WordHunterWoW_QuestEN = WordHunterWoW_QuestEN or {}
WordHunterWoW_QuestEN[25749] = { title = "Not Entirely Unprepared", description = "I overheard your conversation with the Admiral. I know what we're doing sounds insane, but we really don't have much choice. There are people back at that cave that are depending on us.\n\nI've stationed lookouts on various ledges in the immediate area. They're burning ammo fast on the scattered naga scouts. Can you bring them more crossbow bolts to buy us some extra time?", objectives = "" }
WordHunterWoW_QuestEN[25751] = { title = "Properly Inspired", description = "Hello! I've been scrambling, scrambling to prepare for the Admiral's assault. He's got high hopes and high plans to blow all kinds of things sky high! ...or water high? That would do.\n\nBlowing things high takes EXPLOSIVES! I don't have explosives. It's saddening. Very saddening.\n\nI've been properly inspired to improvise though, and the solution has become apparent. The bulbs on the seaweed hanging from the ruins contain a surprisingly volatile gas. Maybe you might gather some for me? Pretty Please?", objectives = "" }
WordHunterWoW_QuestEN[25752] = { title = "Swift Action", description = "We have everything we need to begin the attack.\n\nIf your claims were correct, you would do well to make sure you cling tight to your mount as we make the attack. Anyone who gets caught in the open water isn't likely to out-swim a naga.\n\nKill as many as you can as we make the attack run and we'll rendezvous on the broken ledge of the terrace above once we've expended our explosives. Hopefully by that point there will be few enough that we can finish them off the old-fashioned way.", objectives = "" }
WordHunterWoW_QuestEN[25753] = { title = "Fallen But Not Forgotten", description = "That was a disaster! Most of our men went down to spears before making it anywhere near the rendezvous.\n\nWe're only going to be able to hold this position for so long before the naga overrun us. We need to get out there to the southwest and save as many of the men as we can find - do anything you can.\n\nThey won't last long. Please hurry!", objectives = "" }
WordHunterWoW_QuestEN[25754] = { title = "Gauging Success", description = "Vicious louts... they did a lot of damage with those spears.\n\n<The admiral winces slightly as he clutches a wound on his side.>\n\nWe'll hold here as long as we can for all the men to make it. I need someone to scout their numbers to see how much damage we did.\n\nOne of the biggest groups of them was around the corner on the northwest portion of this round terrace, and the other was a bit farther to the north in the small tunnel, also on this middle level of the ruins.\n\nUp for some scouting?", objectives = "" }
WordHunterWoW_QuestEN[25755] = { title = "Visions of the Past: The Slaughter of Biel'aran Ridge", description = "Look, I know this is asking a lot during a time like this, but I need you to tear yourself away from this defeat for a moment.\n\nI will tend to these soldiers - you need to find the location of that battle with the Kvaldir General to the west that you told me about. You should be able to glimpse more of the Battlemaiden's experiences from there. I have a strong feeling that the key to defeating these naga will lie with that Battlemaiden.\n\nPlease hurry - I will do everything I can to buy you time.", objectives = "" }
WordHunterWoW_QuestEN[25756] = { title = "Get Zherin!", description = "If we're going to get those oil drilling rights, we need to know what the Horde is offering. How can we win if we can't do them one better?!\n\nTheir negotiator, Trackmaster Zherin, is up there talking with one of their khans right now. Why don't you head up and persuade him to hand over the Horde's proposal?\n\nYou don't have to kill him... we're not savages! Just rough him up a bit.", objectives = "" }
WordHunterWoW_QuestEN[25757] = { title = "Get Koalbeard!", description = "If we're going to get those oil drilling rights, we need to know what the Alliance is offering. How can we win if we can't do them one better?!\n\nTheir negotiator, Kravel Koalbeard, is up there talking with one of their khans right now. Why don't you head up and persuade him to hand over the Alliance's proposal?\n\nYou don't have to kill him... we're not savages! Just rough him up a bit.", objectives = "" }
WordHunterWoW_QuestEN[25758] = { title = "A Gap in Their Armor", description = "Do you see what they're doing here? They're affixing armored plates onto the Dragonkin. A page out of Deathwing's book, I suppose.\n\nThose Twilight Juggernauts look like they'll be invincible once they're complete. There's got to be a way around that armor plating!\n\nRun out there and fetch some of the Twilight armor plates that are waiting to be installed. We'll figure out how to beat this.", objectives = "" }
WordHunterWoW_QuestEN[25760] = { title = "Visions of the Past: The Invasion of Vashj'ir", description = "The shard you recovered looks to be of naga origin. I had hoped to find a strong focal object like this for a spell I've been working on that would allow us to glimpse into the recent past.\n\nI've enchanted the blade, but you'll have to take it to a place where we know its owner was. I want you to travel back to the site where you found it and use the blade.\n\nPerhaps we can uncover more behind what the naga are doing here. Or even better, maybe we'll uncover a weakness that will give us a better chance.", objectives = "" }
WordHunterWoW_QuestEN[25761] = { title = "Disassembly", description = "We have to stop these juggernauts before they're completely encased in armor. Right now they're vulnerable, but only if we pry aside the plates and hack at the marred flesh beneath.\n\nTake my shiv, and jam it between the plates of armored juggernauts to deprive them of their armor.\n\nOnce they break from their trance, you're in for a tough fight - keep prying loose that armor and stop those juggernauts!", objectives = "" }
WordHunterWoW_QuestEN[25762] = { title = "The Ancient Brazier", description = "What do we have here? A {race}? Come to steal our land with your honeyed tongue and promises?\n\nYou do not fool me. I have lived a long time, and I know what dealing with your kind means. But the khans do not listen to their elders like they used to.\n\nSince you are here, I will put you to use. When the waters rushed in, the great water spirit, Aquarian, doused the Ancient Brazier deep inside of Splithoof Hold.\n\nUse this brand to reignite the brazier. Aquarian is sure to come. Bring me the Sacred Flame.", objectives = "" }
WordHunterWoW_QuestEN[25763] = { title = "The Codex of Shadows", description = "<This elaborate book contains hundreds of vellum pages bound within a slate cover. It's written in many languages, most unfamiliar. Carefully inked illustrations depict sorcerers or even entire buildings vanishing into curtains of shadow.>\n\n<Many illustrations depict magical artifices like those you see around camp. You suspect the dragon Sethria is trying to keep something hidden. Thisalee will want to hear about this!>  ", objectives = "" }
WordHunterWoW_QuestEN[25764] = { title = "Egg Hunt", description = "Skylord Omnuron wants us to find Aviana's Egg, and I can almost guarantee you it's cloaked by one of Sethria's shadow devices.\n\nSearch around the camp for shadow cloak generators and shut those things down until you find the egg.\n\nOnce you've unveiled it, I'll call out to the other druids. Defend that egg until we can carry it off to safety.\n\nGo get that egg, {name}!", objectives = "" }
WordHunterWoW_QuestEN[25765] = { title = "Tell 'Em Koko Sent You", description = "Northwatch could really use a powerful {race} like you. We're taking a beating in the Southern Barrens and need your help! Are you interested in lending the Alliance a hand?\n\nThe bomb? Yea, it's a problem, but Stonetalon isn't exactly prime real estate. This place was a dump before the Horde sunk their claws into it!\n\nI'll leave the choice in your hands. If you want to help us out in the Barrens, take my horse, Blue Steel. He's grazing at the crossroads south of here. He'll get you past the orc blockade.", objectives = "" }
WordHunterWoW_QuestEN[25766] = { title = "Arcane Legacy", description = "The rage of the elements has unearthed a hidden Highborne city in the heart of Stonetalon Mountains.\n\nDirectly southwest of here, through Sishir Canyon, you will find the Ruins of Eldre'thar. Within the ruins lie treasures untouched by mortals for ten thousand years!\n\nTake this device and use it on the Highborne ghosts that inhabit the ruins. It will... put their souls to rest and also collect valuable data which I may peruse at a later date.", objectives = "" }
WordHunterWoW_QuestEN[25767] = { title = "Capturing Memories", description = "The great cataclysm has unearthed a forgotten Highborne city within Stonetalon Mountains. You must venture southwest to the Ruins of Eldre'thar. Once you are there, search the area for ancient relics. Return the relics to me so that I may study them, {name}.\n\nGo! Lest we keep the arcanist waiting!", objectives = "" }
WordHunterWoW_QuestEN[25768] = { title = "Bombs Away: Mirkfallon Post!", description = "Scout Commander Barus, stationed at Mirkfallon Post, to the northwest, has spotted the Horde bomb. The Krom'gar hot air balloon, with bomb attached, is currently at the new goblin fueling station at Mirkfallon Lake. This might be the opportunity we need to take that thing out once and for all.\n\nGather your things, {name}, and move out! Scout Commander Barus awaits your arrival at Mirkfallon Post.\n\nAnd {name}, your tenacity is a testament to the strength and fortitude of the Alliance!\n\nGlory be unto you!", objectives = "" }
WordHunterWoW_QuestEN[25769] = { title = "Fallowmere Beckons", description = "You're still here? What are you waiting for, a personal engraved invitation? Lord Fallowmere beckons, fool! Go to him now!", objectives = "" }
WordHunterWoW_QuestEN[25770] = { title = "Keg Run", description = "Alright. We need to get this ale to where it's going right away!\n\nIronforge has sent out an expedition of surveyors to check the damage done to the wetlands when the dam burst. Forba Slabchisel's the one leading it...and believe me, you don't want to get on her bad side!\n\nShowing up with an armful of ale will help with that. Go and take this ahead to her, and she might even ask you to stick around for some work.", objectives = "" }
WordHunterWoW_QuestEN[25773] = { title = "A Natural Occurrence", description = "This shard is all that is left from the rift that stood here before.  The connection between the shard and the rift is unknown, but perhaps someone more versed in the elements would know more.\n\nSeek out an Earthen Ring Emissary at any capital city.  This could be exactly what they are looking for.", objectives = "" }
WordHunterWoW_QuestEN[25774] = { title = "Fool's Gold", description = "We definitely DO NOT have the kind of gold that the Horde is offering. {name}, we have to do something or we're not going to be able to get those drilling rights!\n\nWait a minute! There was this report from an underwater survey that we did right after the Cataclysm struck. Something about some gold-looking ore that was pushed up from underground. That's it!\n\nHead west to the old stomping grounds of the centaur, Splithoof Crag and Splithoof Hold, and dig some up.", objectives = "" }
WordHunterWoW_QuestEN[25775] = { title = "Fool's Gold", description = "We definitely DO NOT have the kind of gold that the Alliance is offering. {name}, we have to do something or we're not going to be able to get those drilling rights!\n\nWait a minute! There was this report from an underwater survey that we did right after the Cataclysm struck. Something about some gold-looking ore that was pushed up from underground. That's it!\n\nHead west to the old stomping grounds of the centaur, Splithoof Crag and Splithoof Hold, and dig some up.", objectives = "" }
WordHunterWoW_QuestEN[25776] = { title = "Sethria's Demise", description = "While you've been raiding Sethria's nest, messages have been flying back and forth between here and the shrine. Skylord Omnuron was at first reluctant, but I've persuaded my fellow druids to risk a direct assault on Sethria herself.\n\nEveryone agreed to my plan... provided YOU spearhead the attack.\n\nTake this signal rocket and engage Sethria on the far ridge. When she reveals her true colors and shifts to her dragon form, fire the rocket and backup will arrive to help you!", objectives = "" }
WordHunterWoW_QuestEN[25777] = { title = "Onwards to Menethil", description = "This news needs to get to Menethil as soon as possible. I'll send you along on my fastest ram, {name}.\n\nHe knows the way, just make sure you're steady in the saddle and hold on tight.\n\nDon't dawdle around the camp. We've got to send word quickly!", objectives = "" }
WordHunterWoW_QuestEN[25778] = { title = "Fake Gold for Black Gold", description = "Now that the \"gold\" is ready, I want you to take it up to Khan Ablinh. He'll be so overwhelmed, I bet he'll offer to help us setup the drilling rigs. We could use the horsepower.\n\nHaha, get it? Horsepower?", objectives = "" }
WordHunterWoW_QuestEN[25779] = { title = "Fake Gold for Black Gold", description = "Now that the \"gold\" is ready, I want you to take it up to Khan Blizh. He'll be so overwhelmed, I bet he'll offer to help us setup the drilling rigs. We could use the horsepower.\n\nHaha, get it? Horsepower?", objectives = "" }
WordHunterWoW_QuestEN[25780] = { title = "Assault on Menethil Keep", description = "We'd barely pulled ourselves together after the flood when the Dark Iron hit the town. My men and I all rushed to defend the townsfolk, but the crazed fools retreated right into the keep itself.\n\nThey're holed up good, and we can't destroy the keep. Not with half the town in ruins already.\n\nTake my place, {name}. I'd take the leader on myself if he hadn't dealt me this blow. Enter the keep, slay Horghast, and bring this to an end!", objectives = "" }
WordHunterWoW_QuestEN[25790] = { title = "Back to Crazzle", description = "I am NOT stupid!\n\nGo back to your master and tell him that there will be NO deal! That is, if you can survive to make it back to him.", objectives = "" }
WordHunterWoW_QuestEN[25791] = { title = "Back to Riznek", description = "I am NOT stupid!\n\nGo back to your master and tell him that there will be NO deal! That is, if you can survive to make it back to him.", objectives = "" }
WordHunterWoW_QuestEN[25792] = { title = "Pushing Forward", description = "Most of the mountaineers and steam tanks in Dun Morogh are battling along the Frostmane Front, which is approaching us from the southeast. We can barely hold the trolls back, let alone advance into their village and take on their leader.\n\nThey've blocked our path of approach with mysterious totems that choke mountaineers who come in range, leaving the victims helpless against their enemies. This stone is inscribed with a rune of fire; it should be able to destroy the totems and free our mountaineers.", objectives = "" }
WordHunterWoW_QuestEN[25793] = { title = "The Deep Reaches", description = "The purpose of this base was to establish a foothold in Stonetalon for Theramore and to open up a supply line to the night elves. The Horde, unfortunately, has given us one hell of a fight. Hellscream's armies are mighty and unrelenting. I haven't seen this type of ferocity from the Horde since the second war.\n\nNow it would appear that the mine the Explorers' League dug out is being used by the Horde to \"backdoor\" us. We need to seal that thing off!", objectives = "" }
WordHunterWoW_QuestEN[25794] = { title = "Undersea Sanctuary", description = "I believe I've located the author of your note, friend.\n\nIt would seem that he is in desperate need of attention if he is to survive.\n\nI shall attune one of my scrying orbs, that you might see him for yourself.", objectives = "" }
WordHunterWoW_QuestEN[25795] = { title = "Return to the Shrine", description = "Aviana's Egg should have arrived safely back at the Shrine. You should go check on it! Choluna should know how to handle this.\n\nI'll finish the last of our business here and catch up with you later.", objectives = "" }
WordHunterWoW_QuestEN[25796] = { title = "Eminent Domain", description = "It is our destiny to take this oil. Unfortunate that the centaur retreated to here when the sea rushed in.\n\nUnfortunate for them, that is.\n\nThey've spit in our faces, {name}. We made them a generous offer and they made the mistake of not accepting. Now we... you, will show them the error of their ways.\n\nClear the centaur off of the Splithoof Heights. The oil must flow!", objectives = "" }
WordHunterWoW_QuestEN[25797] = { title = "Eminent Domain", description = "It is our destiny to take this oil. Unfortunate that the centaur retreated to here when the sea rushed in.\n\nUnfortunate for them, that is.\n\nThey've spit in our faces, {name}. We made them a generous offer and they made the mistake of not accepting. Now we... you, will show them the error of their ways.\n\nClear the centaur off of the Splithoof Heights. The oil must flow!", objectives = "" }
WordHunterWoW_QuestEN[25798] = { title = "Defend the Drill", description = "I'm not leaving here empty-handed! Are you?\n\nI bet you were wondering what's in the giant crate. Well, wait no longer. I want you to take one of our drilling rigs to the oil pools and pump us up some crude.\n\nOf course, you should expect the centaurs to attack. Just defend the drill long enough for us to get a barrel or two out of the ground.", objectives = "" }
WordHunterWoW_QuestEN[25799] = { title = "Defend the Drill", description = "I'm not leaving here empty-handed! Are you?\n\nI bet you were wondering what's in the giant crate. Well, wait no longer. I want you to take one of our drilling rigs to the oil pools and pump us up some crude.\n\nOf course, you should expect the centaurs to attack. Just defend the drill long enough for us to get a barrel or two out of the ground.", objectives = "" }
WordHunterWoW_QuestEN[25800] = { title = "When Life Gives You Crabs", description = "There's a lot to do here, {class}, but we need to keep an eye out for the gifts of fate.\n\nWhen the flood rolled in, right over our houses, it swept a good number of ocean dwellers with it. Menethil Bay's full of crabs now, large and ripe for the picking.\n\nWhen life gives you crabs, go crab fishing, I say. Bring me back the largest, meatiest claws you can find and I'll pay you.", objectives = "" }
WordHunterWoW_QuestEN[25801] = { title = "Claws from the Deep", description = "Murlocs are crawling out from the deep waters and building their villages on the coastline.  They are harassing our fishers and merchants and must be stopped.\n\nOne of these murlocs, Gobbler, skulks with other bluegill murlocs and harries merchants along the road, always then retreating to the safety of the nearby murloc hovels.  Our merchants are in jeopardy, and we will pay to secure them.\n\nGobbler prowls the river inlet north of here.  Find him, slay his kin, and bring me his head.", objectives = "" }
WordHunterWoW_QuestEN[25802] = { title = "Reclaiming Goods", description = "Not long ago a merchant vessel, the Blind Princess, was raided by murlocs.  Although the ship escaped intact, much of its cargo was dragged overboard by the creatures, including a very valuable statuette of Terenas Menethil.  We want that statuette recovered.\n\nSearch the coastal murloc hovels for crates, barrels and other evidence of lost cargo.  Find the Menethil statuette and return it to me.", objectives = "" }
WordHunterWoW_QuestEN[25803] = { title = "The Search Continues", description = "You thoroughly search this cluster of murloc hovels, and find no trace of the Menethil statuette.\n\nPerhaps one of the two nearby hovels to the north and northeast will have more clues.", objectives = "" }
WordHunterWoW_QuestEN[25804] = { title = "Search More Hovels", description = "This grouping of murloc hovels, after a thorough inspection, reveals nothing.\n\n...but you're certain that the next clue you find will be fruitful.\n\nOne of the hovels to the north must have the Menethil statuette!", objectives = "" }
WordHunterWoW_QuestEN[25805] = { title = "Return the Statuette", description = "<After pulling the barrel free from the muck and opening it, a silvery figurine is found packed in fine straw. It depicts a young, long-haired paladin with hammer upraised.\n\nThis must be the Menethil statuette! You must now return it to Karl Boran in Menethil Harbor.>", objectives = "" }
WordHunterWoW_QuestEN[25806] = { title = "They Put the Assass in... Never Mind", description = "Ah, the Explorers' League - such a profound group of morons. Not only do we have tauren ghosts up our butts, the Explorers' League has also managed to open up a backdoor to the primary Horde base in Stonetalon, Krom'gar Fortress.\n\nNow we've got Krom'gar assassins silently executing everyone in the mine.\n\nI need you to head in there and clean house.\n\nI almost forgot to give you these goggles. Put them on immediately. They'll make all the stealthed assassins in the mine plainly visible.", objectives = "" }
WordHunterWoW_QuestEN[25807] = { title = "An Ancient Reborn", description = "I'm convinced that YOU are the herald of Aviana, {name}. It was you who first saw her and rescued her essence from the claws of a dragon.\n\nYes, I believe Aviana is to be reborn into our world. And you shall have the honor of ushering her over the threshold.\n\nTake this incense and burn it before Aviana's egg in the room just above me.\n\nThe ancient awaits, {name}. Our deliverance is here!", objectives = "" }
WordHunterWoW_QuestEN[25808] = { title = "Is This Thing On?", description = "<The Gnomecorder crackles with energy. You can hear Lieutenant Paulson on the other end.>\n\nStupid gnome junk... Is ANYBODY there? {name}, are you there?\n\nMaybe he's dead.\n\nListen, if you can still hear me, we just got word that a Horde master assassin is in the mines, directing the other assassins. Find her, kill her, report back to me.\n\nPaulson, out.", objectives = "" }
WordHunterWoW_QuestEN[25809] = { title = "Leave No Man Behind!", description = "Horde monsters!\n\n<Corporal Wocard spits.>\n\nLook at this place! They've wiped out innocents! Civilians!\n\nListen, {name}, you've got to help us. Go into the Deep Reaches and look for surviving miners. If any are still alive they're probably scared witless! Check in the nooks and crannies of the mine. Maybe in mine carts! There are bound to be some left alive and in hiding.", objectives = "" }
WordHunterWoW_QuestEN[25810] = { title = "The Hatchery Must Burn", description = "{name}! Choluna spoke true: the goddess has returned! A miracle in our midst.\n\nWhile you were able to kill the twilight dragon Sethria, we have not yet located all of the eggs that the harpies had delivered to her. Thisalee and I have tracked them to a great hatchery constructed within the Firelands. It is not of this realm, so Aviana cannot accompany you.\n\nFly south and enter the flamegate in the center of the valley. Farden Talonshrike has been sent ahead and will be waiting for you within.", objectives = "" }
WordHunterWoW_QuestEN[25811] = { title = "Shuttin Her Down", description = "To bring this mine down you're gonna need to blow up her support beams. I can provide you with the explosives you'll need, but you're gonna have to trudge through Krom'gar assassins to get to all of the beams.\n\nThe good news, if any exists, is that we always mark our support beams with a big 'X.' Look for the markers and plant this dynamite near 'em. Once you've planted all the dynamite come on back up here and I'll activate the explosives.\n\nKaboom!", objectives = "" }
WordHunterWoW_QuestEN[25812] = { title = "Spelunking", description = "Hurry, {name}!\n\nMake your way to that cavern at once.\n\nWe shall go behind you to ensure that you are not followed.", objectives = "" }
WordHunterWoW_QuestEN[25813] = { title = "Go Blow that Horn", description = "That old, bitter centaur, Skycaller Vrakthris, mentioned a great air spirit that the centaur worship. To secure the Heights, the last step is for us to deal with this thing.\n\nI've seen them blow the giant horn at the top of the hill up there and an air elemental came down. It gave them orders and then dissipated.\n\nGo blow that horn, {name}.", objectives = "" }
WordHunterWoW_QuestEN[25814] = { title = "Go Blow that Horn", description = "That old, bitter centaur, Skycaller Vrakthris, mentioned a great air spirit that the centaur worship. To secure the Heights, the last step is for us to deal with this thing.\n\nI've seen them blow the giant horn at the top of the hill up there and an air elemental came down. It gave them orders and then dissipated.\n\nGo blow that horn, {name}.", objectives = "" }
WordHunterWoW_QuestEN[25815] = { title = "The Third Fleet", description = "I was once First Mate on the Wave Mistress, ship-of-the-line in the Kul Tiras Third Fleet.  The Doomed Fleet.  Doomed, for on its last voyage the fleet was attacked by red dragons.  Dragons controlled by orcs!\n\nWe didn't stand a chance against that dragonfire...and our fleet was burned and sunk off this here coast.  I'm the sole survivor of those poor vessels...\n\n...Bring me my mead, {class}. It's down in the cellar of the inn. As far away as I put it from me, I can't go without it in the end.", objectives = "" }
WordHunterWoW_QuestEN[25816] = { title = "Cursed to Roam", description = "<Bolstered, Fitzsimmons continues his tale...>\n\nI am the sole survivor of the ill-fated Third Fleet of Kul Tiras, wrecked off the coast to the north. On one of our ships was hidden a great, and terrible treasure, and the eerie power of it keeps the souls of my brothers trapped within the ships' rotting hulls.\n\nI'm haunted by them day and night. First Mate Snellig calls for me! He's supposed to be dead! Please, {name}, look for him near the shipwrecks and just...tell him to leave me alone!", objectives = "" }
WordHunterWoW_QuestEN[25817] = { title = "The Cursed Crew", description = "The sailors of the Third Fleet are damned, forever cursed to wander these shores in agony. Fitzsimmons' anguish is tied to us; so long as we suffer, there can be no rest for him, either.\n\nYou must end the suffering of my crewmates' spirits. Purge their ghosts from this plane, and return to me.", objectives = "" }
WordHunterWoW_QuestEN[25818] = { title = "Lifting the Curse", description = "To break the curse, there must be a reckoning. Captain Halyndor damned us all to covet a forbidden artifact; the Eye of Paleth. His spirit still covets it, standing guard over the strongbox of his old ship, the Intrepid.\n\nVanquish the soul of the one who cursed us so, {class}. Defeat the Captain, claim his key, and spirit the Eye of Paleth far from this place.", objectives = "" }
WordHunterWoW_QuestEN[25819] = { title = "The Eye of Paleth", description = "Opening the chest reveals a blackened orb, pulsing with an eerie light. This must be the foul Eye of Paleth that damned these sailors' souls.\n\nSuch corruption should be purged. Perhaps a priest in Menethil Harbor could help you.", objectives = "" }
WordHunterWoW_QuestEN[25820] = { title = "A Mother's Worries", description = "My son Gimlok's the light of my life. It warms my heart to see him playin' with the other children.\n\nI can't help but worry, though. There's sharks not but a few feet away in the bay. If it's deep enough for one to swim its way here...\n\nI can't bear it! Please, you're clearly one {race} that's seen tougher situations than us townsfolk. Would you get rid of those nasty sharks for me? At least a few?", objectives = "" }
WordHunterWoW_QuestEN[25821] = { title = "A Special Kind of Job", description = "You've done an admirable job down here, {name}. Force Commander Valen has taken notice and requested that you see him immediately. He's got a special mission lined up for you - one that'll hopefully put a cold stop on the Horde's incursion into Stonetalon.", objectives = "" }
WordHunterWoW_QuestEN[25822] = { title = "Armaments for War", description = "I am going to need to put you in harm's way once more, {name}. To the east you will find a mineral rich excavation site that was recently overrun by the Horde. At that site are crates of our weaponry, scattered about all over the place. The Horde has only recently taken over, so it is unlikely that they've found all of our supplies.\n\nGet in there and get our Grimtotem friends some weapons!", objectives = "" }
WordHunterWoW_QuestEN[25823] = { title = "The Unrelenting Horde", description = "While it is of utmost importance that you secure weapon crates immediately, we need the Unearthed Grounds to the east clear of Horde. If we are to open a supply line for our Grimtotem allies, we're going to need full access to the dig site.\n\nKill all Horde that you come across at the Unearthed Grounds, {name}. For the glory of the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[25824] = { title = "Debriefing", description = "This soldier was near death, but I fear we do not have the time to await his full recovery. He has information we desperately need to know.\n\nBe patient with him, but keep him talking until we've learned all that we can.\n\nWith luck we might discover just what we're up against...", objectives = "" }
WordHunterWoW_QuestEN[25825] = { title = "Deliver the Goods", description = "Alright, {name}, I need you to get this oil back to Fizzle on the Speedbarge, and let him know the good news!", objectives = "" }
WordHunterWoW_QuestEN[25826] = { title = "Deliver the Goods", description = "Alright, {name}, I need you to get this oil back to Pozzik on the Speedbarge, and let him know the good news!", objectives = "" }
WordHunterWoW_QuestEN[25830] = { title = "The Last Living Lorekeeper", description = "You have awakened the ancients, {name}, but the wilderness spirit Aessina remains silent. With her help, we can turn the tide of this attack and undo the damage Twilight's Hammer has done.\n\nThere may be one who can help us. The oldest of the trees, Nordu, stood in the center of what is now the Flamewake for thousands of years. His wisdom is as old as this mountain. If that old tree still lives, perhaps he can awaken Aessina... seek him out.", objectives = "" }
WordHunterWoW_QuestEN[25832] = { title = "Return to Aviana", description = "{name}, you've done all you can here. This whole cavern is about to collapse in on itself!\n\nI'll gather up the last of our feathered steeds and ensure that the flamegate is sealed behind me.\n\nYou should go on ahead and let Aviana know that this abominable hatchery is no more!", objectives = "" }
WordHunterWoW_QuestEN[25834] = { title = "Death by Proxy", description = "Can you hear them fighting down below, {name}? It would appear that the Grimtotem tauren are no longer in the good graces of the Horde. I don't know what happened, but we can turn this to our advantage.\n\nI will arrange a meeting with an ambassador from the Grimtotem. What I need you to do is put together a peaceful offering.\n\n<Force Commander Valen points to Cookie.>\n\nTalk to \"Cookie,\" {name}. He's already been briefed on what we need to do.", objectives = "" }
WordHunterWoW_QuestEN[25835] = { title = "Free Freewind Post", description = "Alas, it's time for you to leave. How quickly the chicks fall from the nest. Or, something.\n\nAnyway, you've done solid work here, my friend, but Quentin and the night elves have been crying that they urgently need your help with the Grimtotem at Freewind Post to the northwest.\n\nIf you ask me, it's a lost cause, but who knows... maybe with your help they'll actually succeed?", objectives = "" }
WordHunterWoW_QuestEN[25836] = { title = "Free Freewind Post", description = "Well, it looks like it's time for us to part ways, at least for a while. To the northwest, the tauren of Freewind Post are in desperate need of your assistance in pushing back the Grimtotem clan!\n\nYou know, you've been such a great help around here, I bet you're going to be their hero in no-time!", objectives = "" }
WordHunterWoW_QuestEN[25837] = { title = "A Proper Peace Offerin'", description = "To make the perfect peace offerin', I be needing the following ingredients:\n\nKalimdor eagle eggs, obtained from Kalimdor eagle nests. They be scattered about the forest to the west.\n\nRam haunches! You'll find ram haunches on Stonetalon rams.\n\nThe last ingredient be a little tougher to come by, but we be needin' it to make the ramlette. Head southwest to Boulderslide Canyon and find the kobold caves. Kill the kobolds and take their special cheese.\n\nBring it all back and I'll cook up a masterpiece!", objectives = "" }
WordHunterWoW_QuestEN[25838] = { title = "Help from Steelgrill's Depot", description = "With your help, we've managed to push toward Frostmane Retreat. Our forces will soon be in position to dwindle down the Frostmane trolls' reserves, leaving their village open to attack.\n\nThat's where the Gnomeregan covert ops team comes in. Their technicians have figured out a way to deploy operatives behind enemy lines without alerting the Frostmanes to our presence. Head to Steelgrill's Depot, just northeast of town, and speak with Delber Cranktoggle. He'll tell you more about it.", objectives = "" }
WordHunterWoW_QuestEN[25839] = { title = "The Ultrasafe Personnel Launcher", description = "The cataclysm has brought our enemies closer to home, so the chief of Gnomeregan covert operations asked me to build a device to dispatch personnel quickly and quietly to any corner of Dun Morogh.\n\nBehold, the ultrasafe personnel launcher!\n\nWith a jolt of electricity and the benefit of a VLD parachute system, uh, that's 'very late deployment' for you laymen, this baby'll get you to the front in no time. Just hop aboard and prepare for flight! Slamp Wobblecog will be waiting for you in the drop zone.", objectives = "" }
WordHunterWoW_QuestEN[25840] = { title = "Eliminate the Resistance", description = "The Frostmane chieftain died in the initial trogg onslaught, but they've been led by a well-respected warrior ever since. Battok the Berserker was the one who organized the Frostmane retreat, the construction of the new village, and the strikes against Kharanos and the mountaineers.\n\nIf we remove Battok, the Frostmanes' organization should crumble, leaving the mountaineers free to pick off the survivors. Battok will be in the village, just east of here.", objectives = "" }
WordHunterWoW_QuestEN[25841] = { title = "Strike From Above", description = "Delber's technicians have been up day and night helping us prepare for this strike. Aside from building and tuning the personnel launcher, his men have prepared the covert operations air wing for a strike on Frostmane Retreat. They'll be waiting for a signal to begin their strikes.\n\nTake this flare with you, and set it off near the cluster of buildings at the northern end of the village, and the buildings at the southern end of the village. The flying machines will make a quick strike at each site.", objectives = "" }
WordHunterWoW_QuestEN[25842] = { title = "Firefight", description = "It is... too late for me. Burned to all but the core. I have lived eons ... yet still my end seems sudden.\n\nNew life can spring from old. I still have wisdom to pass on. Please... do not let them take me before my work is done.\n\nKeep the tormentors at bay... just a little longer, {class}.\n\nGive me minutes, and I will give you a thousand lifetimes.", objectives = "" }
WordHunterWoW_QuestEN[25843] = { title = "Tortolla's Revenge", description = "The mountain blooms again! If we act quickly, we can press our advantage.\n\nOur old friend Tortolla, the turtle ancient, is already on the move. At his own pace, of course...\n\nFind Tortolla east of here, at the head of the path leading down into the scorched plains. Our strongholds there fell early in the campaign, but perhaps now we can reclaim them.", objectives = "" }
WordHunterWoW_QuestEN[25844] = { title = "Sating the Savage Beast", description = "You heard the commander, {name}. Deliver me perfect offerin' to the Grimtotem ambassador! Him and his crew be waitin' for you at the bottom of the southeastern path.\n\nThis is sure to put us in the good graces of their chieftain!", objectives = "" }
WordHunterWoW_QuestEN[25845] = { title = "Terms of Service", description = "Grimtotem need weapons! The Horde, empowered by their Warchief and with the help of their new goblin allies, have amassed powerful weaponry. Our armaments are simply no match for their firepower. Supply the Grimtotem with strong weapons and we will work together to destroy the Horde!\n\nThese are our demands! Supply the Grimtotem and we will fight for the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[25846] = { title = "Grundig Darkcloud, Chieftain of the Grimtotem", description = "The Grimtotem chieftain awaits your arrival, {name}. Take the weapon crates with you and head to Grimtotem Post, south of here.\n\nGood luck, {name}. Should anything happen to you I will personally notify your next of kin and let King Wrynn know what you have done for the Alliance.", objectives = "" }
WordHunterWoW_QuestEN[25847] = { title = "Grimtotem Supremacy", description = "Throughout all of Greatwood Vale you will find Grimtotem under attack by the Horde. Hellscream's armies show no mercy and no compassion, killing anything that stands in their way.\n\nBut no more! Take the armaments you brought for us and find Grimtotem in battle with the Horde. Give them the weapons of the Alliance and watch as they destroy their Horde assailants! Go, there is much work to do, ally.", objectives = "" }
WordHunterWoW_QuestEN[25848] = { title = "Downfall", description = "By the time that we received word that Hellscream had sent another mag'har orc to oversee the Horde troops in southern Stonetalon, it was too late. Camp Aparaje was burned to the ground and all Grimtotem in the area incinerated.\n\nNow the Horde have four of their most fearsome generals commanding the battle for Greatwood Vale, including the mag'har, General Glubgok.\n\nYou must travel to the ruins of Camp Aparaje, south of here, and kill the generals. We stop the Horde NOW! Return to me with their mark!", objectives = "" }
WordHunterWoW_QuestEN[25849] = { title = "When Archaeology Attacks", description = "Listen, lad, any good archaeologists know the risks that come with the job. If you don't unearth an ancient evil or get cursed by wicked spirits at least once in your career, you're not digging up anything worthwhile!\n\nNo, the real archaeologists know that a little thing like fossilized bones reanimating into skeletal creatures is no reason to stop working.\n\nI still need those fossil bones. Collect 'em from the fossil monsters roaming around and bring them back to me, and I'll reward you.", objectives = "" }
WordHunterWoW_QuestEN[25850] = { title = "Strike the Earth!", description = "In case you didn't notice, the land here in the Wetlands is pretty messed up. Floods, earthquakes... and on top of it all, even the ground's got a wild hair now.\n\nI never thought we'd be attacked by our own dig site, but sure enough, big chunks of it are now rampaging around trying to flatten any dwarf they see.\n\nYou look like a strong, strapping young {race}... mind going down there and slapping some sense into the clods?", objectives = "" }
WordHunterWoW_QuestEN[25851] = { title = "Dances with Grimtotem", description = "Return now to your leader and tell him all that you have done for the Grimtotem. Tell him that the Alliance may pass freely across our borders.", objectives = "" }
WordHunterWoW_QuestEN[25852] = { title = "All's Clear", description = "Pack up your gear, {name}, it's time to join up with the rest of the Northwatch forces in Southern Barrens. Your first mission in Southern Barrens should be fairly straightforward.\n\nTwo days ago we received a distress signal from Commander Walpole. He and his battalion are pinned down in Stonetalon Pass, just outside of Honor's Stand. They've got Horde all over the place! Get there and help him out. I'll forward news of our alliance with the Grimtotem to Northwatch command.", objectives = "" }
WordHunterWoW_QuestEN[25853] = { title = "Tooling Around", description = "I'm in charge of supplying this dig. It's not that bad, but having to pick up and move out so fast wasn't exactly ideal!\n\nArchaeologists need tools, you know. You can't run around pulling up priceless antiquities with your bare hands. If you're going back to the dig site, can you bring back the tools that got left behind?", objectives = "" }
WordHunterWoW_QuestEN[25854] = { title = "I'll Call Him Bitey", description = "Have you heard some raptors are intelligent enough to be domesticated? It's true! I've seen hunters tame them.\n\nIt gets quite lonely out here, you know, even with Wenna to keep me company... a pet's just what I need to brighten my spirits. A little baby raptor would be the best!\n\nIf you're out there slaughtering the adults, would you mind bringing me back some mature eggs? You can tell if they're ready to hatch by the wobbling.", objectives = "" }
WordHunterWoW_QuestEN[25855] = { title = "Gizmos and Gadgets", description = "I've been coming up short on parts recently for my engineering projects, and the other day I finally saw why: the Mosshide gnolls have been making off with them!\n\nI don't have any idea what they could possibly want them for, but I need those gizmos back. They're probably strewn all over the marsh by now, but if you see any, could you gather them and bring them back?", objectives = "" }
WordHunterWoW_QuestEN[25856] = { title = "Crocolisk Hides", description = "I've skinned crocs in the wetlands for years, {class}. Things have changed though.\n\nYou see, not to bore you with a sob story, but when the cataclysm flooded Menethil Harbor, our house went with it. My wife and kids don't have a place to stay, and I need to make as much money as I can to get us under a roof again.\n\nI've been skinning crocs 'til I was too tired to move, but I still need more skins to sell. If you bring me some croc hides, I'll pay you a bit for them.", objectives = "" }
WordHunterWoW_QuestEN[25857] = { title = "Hunting Horrorjaw", description = "I've been tempted to go after the big kill... the largest crocolisk out there, Horrorjaw. His hide alone would be enough to get my family out of this hole.\n\nBut I'm no fool. One mistake and I could lose a leg, or my life, and then where would my wife and kids be? Still homeless and without a father to care for them.\n\nIt's not my proudest moment, but I'll pick my family's safety over pride any day. Please, {class}... hunt Horrorjaw for me. You'll find him in his shady pool to the north, lurking.", objectives = "" }
WordHunterWoW_QuestEN[25858] = { title = "By Her Lady's Word", description = "Lady Sira'kess has begun preparations for the ritual of summoning, but the Crucible of Nazsharin has been stolen from us. The Kvaldir have surely taken it with them as they retreated to shallower waters.\n\nSpeak to the caste leaders to secure a war party, and then lead them in retrieving the artifact from Biel'aran Ridge to the east.\n\nI trust you my Battlemaiden, for you have never failed in any task that I have given you. As I am revered to the Queen, so are you revered to me. Go with my blessings.", objectives = "" }
WordHunterWoW_QuestEN[25859] = { title = "No Trespass Forgiven", description = "I know that you, like our revered lady, have unfortunate streaks of mercy that you succumb to at times. I would advise against such kindnesses this day. The Kvaldir are proud, and they will strike back if we do not cripple them completely. Kill all that you find.\n\nSadly, I have the inglorious task of making sure none return to the city, so you can go have all of the fun. I will cheer you on though, of course.", objectives = "" }
WordHunterWoW_QuestEN[25860] = { title = "At All Costs", description = "We are to begin the ritual immediately, and you are to see to it that we are not interrupted.\n\nSlaughter any Kvaldir that enter the temple. See to it that my priestesses live to see their task complete, no matter the cost.", objectives = "" }
WordHunterWoW_QuestEN[25861] = { title = "Setting An Example", description = "The High-Shaman are in the buildings nearby, chanting and taunting, but not daring to approach me. These Kvaldir find their courage and strength only in the mist. They are a pitiful nuisance beneath the waves.\n\nI came bearing a message. If your ladyship has the time, bring a high-shaman to my feet that I might deliver this message to him and his people.", objectives = "" }
WordHunterWoW_QuestEN[25862] = { title = "Stolen Property", description = "Our revered lady has sent me to aid you in your task. She wants you to retrieve the stolen Crucible of Nazsharin and bring it back here as soon as you can.\n\nShe grows impatient to start the ritual of summoning so that we might fully begin our preparations for war.", objectives = "" }
WordHunterWoW_QuestEN[25863] = { title = "Chosen Burden", description = "With the Crucible of Nazsharin, all that remains is to inform Lady Naz'jar of your success.", objectives = "" }
WordHunterWoW_QuestEN[25864] = { title = "Dinosaur Crisis", description = "We've been getting more and more reports of raptor attacks in the area. I'm seeing to it that this place is safe enough for more settlement to start occuring, so I've put a bounty on the buggers.\n\nA lot have been cleared out already, but the Highland raptors to the north have been growing in number. That won't be true for long, now will it?\n\nClear out a good deal of Highland raptors, and I'll have a nice reward for you.", objectives = "" }
WordHunterWoW_QuestEN[25865] = { title = "The Mosshide Job", description = "You seem trustworthy enough to help me out with my real problem, {name}. I was sent here by Ironforge to recover a shipment of gold ingots.\n\nThe ingots are part of the Ironforge Royal Treasury, stamped with the royal seal... only an idiot would steal them for profit, far too easy to trace. Oddly enough, this area is full of idiots: Mosshide gnolls.\n\nI don't know how many gnolls you've fought before, but they're foul and brutal beasts, and dangerous. I need you to slay them and recover the missing ingots.", objectives = "" }
WordHunterWoW_QuestEN[25866] = { title = "Dark Iron Trappers", description = "You may have seen them while you were out, but the Dark Iron clan has been spotted in this area. They're never up to any good, and it looks like they're kidnapping the Mosshide gnolls for some reason.\n\nI don't know what their game is, but we're putting a stop to this before more foul play occurs. Go and stop them.\n\nAnd if you're worried about fairness, try askin' them politely first and see how far that gets you.", objectives = "" }
WordHunterWoW_QuestEN[25867] = { title = "Gnoll Escape", description = "I know we were just attacking the gnolls ourselves, but I'm not about to let the Dark Iron capture them as slaves. For one, we found the thieves and took back what was missing, so justice is served; for another, whatever work the Dark Iron will be putting them to isn't something I want to allow.\n\nEither way, the gnolls need to be freed. The trappers should have keys on them, so use those to open the cages.", objectives = "" }
WordHunterWoW_QuestEN[25868] = { title = "Yorla Darksnare", description = "I've found out who's pulling the strings on this operation here. Yorla Darksnare is directing the Dark Iron dwarves from a camp to the east, and it might've been orders to have the gnolls steal Ironforge's gold in the first place.\n\nWhat's more, she's a wanted criminal... she's been inciting rebellion and attacks against Ironforge since Magni was still alive.\n\nShe can't slip through our fingers this time, {name}. Go and get her!", objectives = "" }
WordHunterWoW_QuestEN[25869] = { title = "Grimtotem in the Post", description = "The journey ahead must begin with you killing the Grimtotem invaders at Freewind Post. If you can't stop them here, we won't be able to move into their territory.", objectives = "" }
WordHunterWoW_QuestEN[25870] = { title = "Grimtotem in the Post", description = "You must do away with the Grimtotem invaders at Freewind Post. They brought it on themselves, the cowards!\n\nWe can't take the fight to their territory with our back to them. Please help us take back our home, {class}.", objectives = "" }
WordHunterWoW_QuestEN[25871] = { title = "Save the Sentinel", description = "<Brienna waves a note around with Taur-ahe markings on it.>\n\nThose monsters have captured one of our sentinels! They're threatening to kill her if we don't pull back!\n\nWe don't negotiate with cowardly beasts! Please, if you can, rescue her before it's too late, {class}.", objectives = "" }
WordHunterWoW_QuestEN[25872] = { title = "The Brave and the Bold", description = "<Rau dismissively waves a note around with Taur-ahe markings on it.>\n\nThose mongrels have captured one of our braves! They're threatening to kill him if we don't pull back!\n\nWe'll never allow those Grimtotem cowards to keep Freewind Post! Please, rescue him before it's too late, {class}.", objectives = "" }
WordHunterWoW_QuestEN[25873] = { title = "Horn of the Traitor", description = "Here lies the broken body of the Freewind Post lorekeeper, Montarr. The aged tauren's body is broken, lying in a pool of his own blood.\n\nA trail of droplets leads back to the inn....", objectives = "" }
WordHunterWoW_QuestEN[25874] = { title = "Horn of the Traitor", description = "Here lies the broken body of the Freewind Post lorekeeper, Montarr. The aged tauren's body is broken, lying in a pool of his own blood.\n\nA trail of droplets leads back to the inn....", objectives = "" }
WordHunterWoW_QuestEN[25875] = { title = "Gnome on the Inside", description = "Mirkfallon Lake is crawling with Horde. The goblins have set up shop and they aren't going to leave until all the oil under Stonetalon is sucked dry.\n\nThankfully I have a gnome on the inside that's been collecting information for us. If anyone knows what's going on with that bomb, it's my inside gnome.\n\nMake your way to the Sludgewerks, north of here, and find Minx. She'll be disguised as a \"goblin\" pump controller.", objectives = "" }
WordHunterWoW_QuestEN[25876] = { title = "It's Up There!", description = "Listen, I've been tracking this bomb since you rescued me in Ashenvale. Whatever they're doing with it is going to happen real soon.\n\nAt the top of the large oil rig is a control room. Inside that control room you'll find a Krom'gar log book. That log book is the key to where this bomb is heading. Get up there and get the log book! Bring it back here and I'll decipher it for you.", objectives = "" }
WordHunterWoW_QuestEN[25877] = { title = "No Time for Goodbyes!", description = "RUN! Get out of here, {name}. Get back to Barus and inform him of what you've discovered. He'll arrange for you to get safely across Battlescar Valley to Thal'darah Overlook.\n\nIt's not too late to save those young druids!", objectives = "" }
WordHunterWoW_QuestEN[25878] = { title = "Schemin' That Sabotage", description = "Goblins... What would this world be without goblins? I'll tell you what: CLEAN!\n\nThose filthy little scum suckers have planted their oil pumps all over the lake with the hope of extracting every last drop of oil that exists in Stonetalon. At each oil pump they've stationed an oil pump controller whose sole job it is to watch the pump and make sure nothing goes wrong.\n\nSomething is about to go wrong.\n\nTake out the goblin pump controllers and take their pump controls. Use 'em to overload the pumps!", objectives = "" }
WordHunterWoW_QuestEN[25879] = { title = "The Lumbering Oaf Problem", description = "Ever seen a hobgoblin? They're another vile goblin creation. Take a goblin, make it even uglier, fatter, bigger and stupider and you have a hobgoblin. Add to all of that a nasty mean streak and we've got a problem.\n\nThese lumbering oafs wander the Sludgewerks and Mirkfallon Lake, acting as muscle to the goblins.\n\nGet out there and thin 'em out. Permanently.", objectives = "" }
WordHunterWoW_QuestEN[25880] = { title = "Warn Master Thal'darah", description = "There are dozens of students at Thal'darah Grove. Most of them have no means of defending themselves, ripe for the slaughter.\n\nYou must get word to Master Thal'darah of the Horde's plans. He will direct you in what you must do next.\n\nFiora Moonsoar has granted you the use of her fastest hippogryph. Take it now to Thal'darah Overlook! Don't look back, {name}! The Horde must be stopped!", objectives = "" }
WordHunterWoW_QuestEN[25881] = { title = "Lost Wardens", description = "We held out as long as we could, {class}. But the flames... the heat... We lost the whole town.\n\nCaptain Irontree refused to pull back when the flames engulfed us. Our forces are scattered. Maybe some of the others survived? We can mount a counter-attack!\n\nGo into the Scorched Plain and rescue any lost wardens that got separated from the group. Then find Captain Irontree - he's probably taken up a fortified position in the middle of the fighting. ", objectives = "" }
WordHunterWoW_QuestEN[25882] = { title = "A Hand at the Ranch", description = "Captain Tharran asked me to pass along his thanks for your help and congratulations on a successful mission. He and his men are cleaning up the last of the trolls and tending to the wounded.\n\nHe also wanted me to ask you to check out reports about troll raids on the Amberstill Ranch to the north. Ask for Sergeant Flinthammer when you arrive.", objectives = "" }
WordHunterWoW_QuestEN[25883] = { title = "How Disarming", description = "Naga weapons...\n\nAs you cast your vision on the naga Holding Pens, you see dozens of similar stacks of tridents positioned strategically.\n\nDestroying their weapons could only hamper whatever wicked designs they are carrying out in this region...", objectives = "" }
WordHunterWoW_QuestEN[25884] = { title = "Come Hell or High Water", description = "Oh fer the love of...\n\nI know our survivor friend here means well, but the lad's been severely traumatized.\n\nThere only be one way ta deal with these accursed beasts, an' that be a fine dwarven axe buried hilt-deep in the noggin.\n\nPile up enough o' their corpses an' they'll think twice before fiddlin' with yer tasty bits.\n\nMark me words laddie, them buggers don't like the sight o' their own blood any more than you or I.\n\nNow git out there an' give 'em what fer!", objectives = "" }
WordHunterWoW_QuestEN[25885] = { title = "What? What? In My Gut...?", description = "Wha...what IS this!?\n\nThere's great pain growing... from deep in my bowels.\n\nI think... ugh... they must have poisoned me!\n\nThey fed us strangely glowing seaweed that they grow around their stronghold...\n\nI think these cramps will worsen if I don't get more soon...\n\nPlease, {race}. Try to find me some!", objectives = "" }
WordHunterWoW_QuestEN[25886] = { title = "Pressing the Advantage", description = "It looks like most of the Twilight's Hammer has fallen back to regroup for another assault. Their most dedicated are staying behind to hold the line. This is our chance to whittle away at their leadership.\n\nRange out along the Scorched Plain and crush the Twilight Field Captains. We'll remove them from the equation!", objectives = "" }
WordHunterWoW_QuestEN[25887] = { title = "Wake of Destruction", description = "Our time here draws to a close. I must somehow follow the trail of these naga captives if we are to discover their purposes in this region.\n\nBut before I move on, I would see the destruction of this operation!\n\nNevermind their numbers, I have a plan that has the potential to even the odds.\n\nOutside this cave, famished great sharks, displaced by these naga, seek food.\n\nIn their weakened state, they will be susceptible to suggestion. Use this orb to subdue them, then direct them against our enemy.", objectives = "" }
WordHunterWoW_QuestEN[25888] = { title = "Decompression", description = "I simply cannot bear the thought of so many others like this soldier imprisoned, surrounded by naga.\n\nSomething must be done to rescue them!\n\nTry this, {name}. Use it on the prison cells to make them buoyant.\n\nIf we can get them to the surface, at least they stand a chance at being rescued.", objectives = "" }
WordHunterWoW_QuestEN[25889] = { title = "Save the Children!", description = "My poor, defenseless young students are stranded at Thal'darah Grove. With the battle raging across Battlescar Valley, they have no means of escaping. We must save the children before the Horde drops their bomb!\n\nTake my hippogryph and use it to rescue the young druids of Thal'darah Grove. Drop them off at the hippogryph post here in town.\n\nSave them all, {name}! You truly are our only hope.", objectives = "" }
WordHunterWoW_QuestEN[25890] = { title = "Nespirah", description = "It is clear to me at this point what must be done, {name}.\n\nThe naga can only be obtaining these pearls from one place: Nespirah, the ancient, shelled creature that rests outside of this cave.  Why Nespirah would submit to the naga, however, is beyond my understanding.\n\nWe can enter Nespirah's body cavity through a small tube near the exit to this cave.  I must first fetch my master, then we can meet you on the inside.  We will convene in Nespirah's northwestern entrance.", objectives = "" }
WordHunterWoW_QuestEN[25891] = { title = "Last Ditch Effort", description = "The Horde have signaled a retreat. Look now, they fall back from the field of battle - portends of disaster.\n\nWe must make one final descent into Thal'darah Grove. I could not live with myself if any of our young druids were left behind.\n\nAssist me, hero. I will take the reins. You search for any druids that might be left behind.\n\nWe will go when you are ready. ", objectives = "" }
WordHunterWoW_QuestEN[25892] = { title = "Losing Ground", description = "You'll have to catch me up more later. Right now, we need to get out of here before more naga push in. Make your way back to the forward post on the level below us.\n\nTake my sea horse. We will meet you back there shortly.", objectives = "" }
WordHunterWoW_QuestEN[25893] = { title = "Desperate Plan", description = "Jorlan and Hexascrub left to find a way to contact help. The trade lanes aren't far, so there might be a chance of success, but I'm wary to let anyone get their hopes up.\n\nIn truth, we don't have any other options. We're not likely to last much longer here. The naga will find us eventually, and... well... you saw how many of them there were.\n\nYou should go find the two of them on Biel'aran Ridge to the southeast. I'll keep everyone here safe as long as I can.", objectives = "" }
WordHunterWoW_QuestEN[25894] = { title = "Hostile Waters", description = "Hexascrub came out here with a balloon of some sort that he retrieved from one of our ships. He tried to float it to the top, but those Muckskin Scroungers came out of nowhere and swarmed the thing.\n\nHe's got an idea for another balloon, but we need to make sure that the past doesn't repeat itself. I need you to kill off those gill goblins. Or at the very least, enough of them to make them a bit more wary of us.", objectives = "" }
WordHunterWoW_QuestEN[25895] = { title = "Come Prepared", description = "We must always come prepared. Prepared with gear. Prepared with plans. Prepared with gear plans!\n\nAll of the ships in all of the Alliance fleets stow a survival kit. A lot of our tools came from a survival kit. My balloon came from a survival kit too! But now it's gone. I need another survival kit!\n\nThere's a ship to the southeastish. Let's hope that the survivors were dumb and didn't take the survival kit. More survival kit for us!", objectives = "" }
WordHunterWoW_QuestEN[25896] = { title = "Devout Assembly", description = "Ah, Battlemaiden. You carry with you the word and the will of our Lady. I might ask a favor of you...\n\nI need Fathom-Caller Azrajar and my Tide Priestesses to return so that we can begin the ritual. Can you carry my will to them as such? You should find them spread upon the temple terrace. Azrajar will be at the stairs to the north.", objectives = "" }
WordHunterWoW_QuestEN[25897] = { title = "Unfurling Plan", description = "Survival kits never have any rope. It makes no sense! No sense at all.\n\nI bet those Kvaldir have rope. They're always riding around in boats, tying knots, dressing in nets. Go take some rope from them! I must have it for our plan to work. Absolutely must.", objectives = "" }
WordHunterWoW_QuestEN[25898] = { title = "Honor and Privilege", description = "All done! I'm confident it will work. And not a scrounger in sight to pop a hole in it this time! Fortuitous.\n\nJorlan already swam up to catch it. Swam up and stopped to wait for it. He said you'd get the honors though. Jorlan's nice like that.\n\nGo to the top with the balloon, take the flare gun from the crate, and scan the horizon for Alliance ships. If you see any, fire the flare towards them. That's it! All there is to it.\n\nSwim. Float. Flare. Rescue! That last part's my favorite.", objectives = "" }
WordHunterWoW_QuestEN[25899] = { title = "Breakthrough", description = "The fiery army that caused so much devastation up the hill has retreated east of here. Only the Scorchlords remain in action. If we can punch a hole through their lines to regroup with Captain Irontree's forces, the whole offensive may collapse.\n\n{class}, I'm in no shape to continue fighting, but you look like you can do some damage. Slay those Scorchlords and regroup with Captain Irontree!", objectives = "" }
WordHunterWoW_QuestEN[25900] = { title = "Making Contact", description = "I can't believe that Nespirah would willingly allow these naga to take residence inside her shell.  As I see it, one of two things has happened: they have convinced her to willingly join their cause, or they have weakened her to a point where she cannot fight back.  Either one is bad.\n\nHere in this chamber, I should be able to communicate directly with Nespirah.  Let us find out for ourselves.  Speak to me when you are prepared, {class}.", objectives = "" }
WordHunterWoW_QuestEN[25901] = { title = "Hyjal Recycling Program", description = "Reinforcements! I thought we were going to fight this out to the bitter end.\n\nVery few of the Guardians of Hyjal remain, and our supplies are running out. The battlefield around our holdout here must be littered with serviceable arrows.\n\nI know it's beneath your abilities, but can you gather up our spent ammunition? It's the only way we can replenish our supplies!", objectives = "" }
WordHunterWoW_QuestEN[25904] = { title = "The Hammer and the Key", description = "My Nemesis. Still lives.\nThe servants of fire still come.\nWe must pursue. Into their den.\n\nThe ogres know the way.\nSlay the Field Captains.\nRecover the Glyph of Opening.\n\nThis is the way.", objectives = "" }
WordHunterWoW_QuestEN[25905] = { title = "Rams on the Lam", description = "The rams we raise and train here at Amberstill ranch have long been the mounts of choice for Dun Morogh's mountaineers. Aye, there're a few here, but not enough to guard my family and all the animals.\n\nA few brave Frostmane raiders have taken to stealing our rams under the cover of night, taking them south into the Tundrid Hills. Would you be willing to help return them? You'll need to get fairly close to them and give a sharp whistle to get their attention. Their training will take over from there.", objectives = "" }
WordHunterWoW_QuestEN[25906] = { title = "The Third Flamegate", description = "Memorize the glyph.\nTake it within yourself.\n\nDraw it on the ground before the flamegate.\nEast of here.\nEnter the Firelands.\n\nI cannot come with you.\nBut my children await. Inside.\n\nFind Garunda Mountainpeak within the realm of flame.", objectives = "" }
WordHunterWoW_QuestEN[25907] = { title = "Slave Labor", description = "It will take me some time to break through this barrier and communicate with Nespirah.  In the meantime, you can save some of those men that the naga have enslaved in the pits below.\n\n<Duarn produces a length of rope from within his robes.>\n\nThis should come in handy.", objectives = "" }
WordHunterWoW_QuestEN[25908] = { title = "Stick it to Them", description = "I may be unable to communicate directly with the beast Nespirah, but I can still feel some things indirectly.  For example, I can clearly sense that Nespirah is not happy about the naga's presence here.\n\nWhen we first entered Nespirah's body, I saw dozens of sentinels and enchantresses patrolling the central chamber floor.  Perhaps some of the ancient one's pain will be alleviated if you remove them.", objectives = "" }
WordHunterWoW_QuestEN[25909] = { title = "Capture the Crab", description = "Everything in my body tells me that Nespirah is trying to speak with me, but I cannot hear her.  Perhaps the naga have done something to her voice.\n\n<Duarn thinks to himself for a moment.>\n\nNespirah's voice may be suppressed... that means... we need to find a voice for her!\n\nI've got it!  The Idra'kess have been known to train deepseeker crabs as battle companions.  Use this net to capture a crab, and bring it to me.  You will likely find them prowling the chamber's outer edges.", objectives = "" }
WordHunterWoW_QuestEN[25910] = { title = "The Time for Mercy has Passed", description = "This cavern is an abomination, {name}. And it's filled with horrors from the depths.\n\nI don't want any of these - things - getting through the portal to the outside world. Slay everything!", objectives = "" }
WordHunterWoW_QuestEN[25911] = { title = "Welcome News", description = "They'll probably send a skiff over, which may take a bit. I'll stay here to make contact.\n\nYou need to return to the cave immediately and let them know that rescue is on its way. We can only hope that the naga have not found them yet.\n\nGo. Swim fast, {name}. ", objectives = "" }
WordHunterWoW_QuestEN[25912] = { title = "Seen Better Days", description = "The world is unraveling around us, {name}. Old enemies seek to destroy us from one end, while ancient forces close in on the other.\n\n<Elder Sareth'na sighs.>\n\nI have seen better days - brighter days, and I long for them...\n\nAcross Stonetalon Peak lies the ruins of our old outpost - now overrun with darkness. If you happen to go that way, could you search for my sketch book? It holds many happy memories. I would reward you well for its return.", objectives = "" }
WordHunterWoW_QuestEN[25913] = { title = "Putting Them to Rest", description = "As the Horde were marching upon Stonetalon, I noticed that some of the sentinels had fallen ill. Not long after, they started acting strangely. When the first tentacle burst from the ground the ill sentinels began attacking us. We lost the outpost shortly after...\n\nThe sentinels in the peak are now nothing more than shells - husks for something far more sinister. I want you to put the sentinels to rest and retrieve their glaives. Each glaive returned can identify a fallen sister.", objectives = "" }
WordHunterWoW_QuestEN[25914] = { title = "Back to the Depths!", description = "Tendrils are bursting forth from the earth and terrorizing Stonetalon Peak. My sentinels are hardly making a dent in their numbers.\n\nI suspect that there is a force at the heart of Stonetalon Peak that controls the tendrils. Perhaps if we can put a stop to that force, the tendrils will return to the depths from whence they came!", objectives = "" }
WordHunterWoW_QuestEN[25915] = { title = "The Strength of Tortolla", description = "The dark usurper Nemesis fled here when the fires of Hyjal receded. We are not yet strong enough to defeat Nemesis, {name}, but we may be able to turn his own strength against him.\n\nI will send a child of Tortolla with you, one of the children you freed earlier from the Twilight's corruption.\n\nSearch the depths of this cave for a Nemesis Crystal, and allow the young turtle to examine it.\n\nSee me if you lose your companion!", objectives = "" }
WordHunterWoW_QuestEN[25916] = { title = "Breaking Through", description = "A trained shaman has the ability to communicate with the four elements of earth, fire, air and water.  This is known.\n\nWhat is not as widely known, however, is the presence of a fifth element.  This element is not as clearly described as the other four, but it has to do with the shared... commonality between all living creatures.\n\nMy theory is that the crab, as a creature of the sea, is close enough to Nespirah that, with the elements' coaxing, we can convince it to act as Nespirah's mouthpiece.", objectives = "" }
WordHunterWoW_QuestEN[25917] = { title = "We Are Not Alone", description = "<Duarn closes his eyes, pauses, and nods.>\n\nNespirah has just informed me that we are not the only people fighting inside of this shell.  A small group of Alliance slaves has escaped and is currently fighting off the naga on the other side of the shell, up on the ledge that overlooks Nespirah's heart.\n\nGo find them, {name}, and see what help they can lend us.  With their aid, we may be able to rouse Nespirah from her torpor.\n\nI will remain here, should you need anything.", objectives = "" }
WordHunterWoW_QuestEN[25918] = { title = "Hopelessly Gearless", description = "I honestly don't know how we've survived this long.  The naga took my armor and weapons, and left me with rags and a mining pick... and THAT snapped in half long ago.\n\nIf we're to stand any hope of turning the tide, I'm going to need something to fight with... as will my companions, though they may be too proud to admit it.\n\nI've seen weapon racks in the naga storage areas nearby.  I'm not accustomed to fighting with a trident, but it'll sure be better than fighting with my fists.", objectives = "" }
WordHunterWoW_QuestEN[25919] = { title = "Body Blows", description = "<Captain Taylor listens intently to your recount of Duarn and Nespirah's conversation.>\n\nI see.  So the creature wants our help waking it up, is that it?\n\nWith hundreds of slaves already picking away at her pearls, the beast seems to be a pretty heavy sleeper.  You might have better luck, though.\n\nMy suggestion?  Look around the creature's flesh for signs of weakness.  Maybe that weapon of yours will find a ticklish spot and force the beast to come to its senses.", objectives = "" }
WordHunterWoW_QuestEN[25920] = { title = "Still Valuable", description = "My time in the pearl pits, however short, has made me curious about the naga's goals.  Yes, I now know that the naga want to use Nespirah as an engine of war, but if that's the case, then why are they enslaving men to mine her pearls?\n\nAssuming we escape this creature's hull, I would very much like to study these objects.  The pearls we found in the pits were much too large to carry, but I've seen the warlords and prophets occasionally carrying around smaller ones.", objectives = "" }
WordHunterWoW_QuestEN[25921] = { title = "Overseer Idra'kess", description = "My men are flagging, {name}.  We won't last much longer against these naga, I'm afraid.  With the Idra'kess' weapons, and Nespirah's pearls, we should be ready to bust out of here.\n\nFollow the wall to the southeast, and look for a ramp to the upper chamber.  I assume their leader is in there, or perhaps the key to Nespirah's awakening.  Hopefully both.\n\nIf you feel strong enough, head up to the top of the shell and look for some answers.", objectives = "" }
WordHunterWoW_QuestEN[25922] = { title = "Waking the Beast", description = "Thanks to you and the Captain, Nespirah has full control of her body... but most of the naga don't know this yet.  Once we make our escape, she will activate her biological defenses and destroy the naga from within.\n\nMake yourself ready... I will now tell Nespirah to begin the countdown.", objectives = "" }
WordHunterWoW_QuestEN[25923] = { title = "Finish Nemesis", description = "Your turtle companion can use this newfound power to render the two of you invulnerable for a short period of time. You can \"turtle up\" to avoid the worst of Nemesis and his fury. To do so, simply invoke this totem.\n\nThis is all I can do for you. Together, you and a Child of Tortolla must defeat Nemesis, once and for all. Finish the Usurper!\n\nReturn to me if you lose your turtle friend.", objectives = "" }
WordHunterWoW_QuestEN[25924] = { title = "Call of Duty", description = "Listen up, {race}!\n\nA new landmass has emerged off the coast of Eastern Kingdoms and we are engaged in a critical battle for control of the island!\n\nVictory there will leave Stormwind completely defenseless!\n\nNow is the time to strike!\n\nReport to the docks at once for transport to the battle.\n\nEvery warship is engaged, so you'll be boarding a mercenary vessel commissioned by the Warchief himself.", objectives = "" }
WordHunterWoW_QuestEN[25925] = { title = "Thal'darah's Vengeance", description = "We must attempt to establish communication with Farwatcher Glen, to the south. Our Darnassian glaive throwers are at your disposal, {name}. Use them to cut a swath through the encroaching Horde forces and clear a path to Farwatcher Glen.\n\nI only hope we're not too late to save the Glen. Should Farwatcher Glen be intact, find Hierophant Malyk and inform him of our status.", objectives = "" }
WordHunterWoW_QuestEN[25926] = { title = "Mired in Hatred", description = "The mirebeasts to the west are not my brethren... they are symptoms of the earth's disturbance, a foulness of rot given form.\n\nYou would not understand... they take the shape of my kind, infested within with decaying spores, forcing out flourished life in the swamp. They take all and leave only rot. Nothing left, nothing left!\n\nSoothe my mind, {race}. Slay the mirebeasts, cleanse the land, and perhaps my mind will settle.", objectives = "" }
WordHunterWoW_QuestEN[25927] = { title = "The Threat of Flame", description = "Flame has threatened me for far too long... far too long... but it is no longer the little ones, no longer mere gnats...\n\nThe fields burn! The hills and highlands scream, {race}, they scream. The elementals brought here consume all life in their wake.\n\nThey cannot stand, they cannot stand. Stop them. STOP THEM! Destroy the bringers of flame...", objectives = "" }
WordHunterWoW_QuestEN[25928] = { title = "Tortolla's Triumph", description = "I'll escort the children of Tortolla out of here and seal up this accursed portal.\n\nI'll leave it to you to inform Tortolla of our victory. Simply step back through the flamegate. The ancient will be pleased!", objectives = "" }
WordHunterWoW_QuestEN[25929] = { title = "Sea Legs", description = "Greetings, {class}. I am Erunak, a fellow survivor of this savagery.\n\nI'm afraid your travails have only just begun. The naga have been scouring these waters, attacking anyone that still lives.\n\nYou are not yet equipped to survive here, but I can remedy that.\n\nJust outside this ship live a special breed of starfish. Bring me some of them along with a conch shell. I'll prepare an enchantment that should help you grow accustomed to your environment.", objectives = "" }
WordHunterWoW_QuestEN[25930] = { title = "Ascending the Vale", description = "I am told that before the great upheaval the Charred Vale was a valley, closed off to the sea. One has merely to look to the south to see that the Charred Vale is no longer a valley and in fact has become an area of great volcanic activity.\n\nSalsbury here has configured a device that will allow us to ascend the volcano. Use it to get to the top and assess the goings on.\n\nI will keep in touch with this Gnomecorder device, which Salsbury has so kindly gifted upon me.", objectives = "" }
WordHunterWoW_QuestEN[25931] = { title = "Brood of Seldarria", description = "<The Gnomecorder buzzes.>\n\nBe very careful, {name}. You do not want to rouse that black dragon.\n\nNow, look around you. If this is a nest then there must be black dragon eggs nearby. Search the premises for eggs and destroy any that you see.\n\nReturn to me should you find and destroy Seldarria's eggs.\n\nGoldrinn watch over you.", objectives = "" }
WordHunterWoW_QuestEN[25932] = { title = "It's Raid Night Every Night", description = "The reports I'm sending Captain Tharran can't really convey the amount of trouble the Frostmanes have created for us. Your assault on the village has started to relieve some of the pressure. The raids are still frequent, but the trolls don't have the numbers they once did.\n\nEven so, my men are tired and their morale is flagging. Would you help us keep watch for the Frostmane raiders? They could turn up at any time.", objectives = "" }
WordHunterWoW_QuestEN[25933] = { title = "Help for the Quarry", description = "Thank you again for all your help here, {name}.\n\nI have a cousin who used to work in the mines beneath the Gol'Bolar Quarry, but he hasn't been able to work since troggs flooded into the mines and took control. The quarry and its camp are just to the southeast of the ranch. Would you be willing to check in with the foreman there and see if there's anything to be done?", objectives = "" }
WordHunterWoW_QuestEN[25934] = { title = "World First: Gnomegen", description = "Good day, citizen, allow me to introduce myself. I am Salsbury, soon to be the world's first gnomegen. Malyk has assured me that as soon as my work here is complete he will grant me the gift of the worgen.\n\nSo with the introduction out of the way, I've a request!\n\nWithin the Charred Vale, south of here, roam newly created fire elementals. I desperately need a rare blazing heart of fire from one of the fiends. Get it for me and you bring me one step closer to becoming a gnomegen!", objectives = "" }
WordHunterWoW_QuestEN[25935] = { title = "Hungry Pups", description = "Ah, a new arrival! Good that you're here lad! The pups are hungry and we're completely out of food.\n\nThankfully they love dragon meat, which fortuitously exists in abundance within the Charred Vale, south of here.\n\nBe a good boy and fetch me several pounds of black dragon whelp filet.", objectives = "" }
WordHunterWoW_QuestEN[25936] = { title = "Pay It Forward", description = "You are now able to move about this realm more freely and without fear of drowning.\n\nThis is where our work begins.\n\nFirst, you have many allies nearby who are drowning as we speak. As I saved you, you must save them.\n\nI have enchanted the shell you brought me. Use it to rescue your friends.\n\nHurry now!", objectives = "" }
WordHunterWoW_QuestEN[25937] = { title = "Priceless Treasures", description = "Mining wasn't the only thing going on in the quarry, you know. I led a team of Explorers' League excavators recovering priceless ancient artifacts.\n\nI managed to escape, but my colleagues were much deeper in the mine and didn't survive the initial trogg attack.\n\nThey took great pride in their work and they risked their lives to learn more of our history. If you're going into the mines, take this pick with you and see if you can find anything in the digs the prospectors started.", objectives = "" }
WordHunterWoW_QuestEN[25938] = { title = "Help for Desolace", description = "I've received a disturbing message from Nijel's Point in Desolace. It would seem as if the great upheaval has created some new problems for them, which they are ill-equipped to handle. I was given no further information.\n\nReport to Office Jankie in Desolace. She will direct you to Nijel's Point.\n\nGood luck, {name}.", objectives = "" }
WordHunterWoW_QuestEN[25939] = { title = "For Peat's Sake", description = "The elementals rampaging across Direforge Hill are setting the very land beneath them ablaze. In a marsh such as this, fire can find many places to smoulder through the deep moss and peat.\n\nYou must quench the fires before they spread further. Take this flower... blessed by nature's rain, it will let you douse the fires.\n\nThe blossom may also prove useful against the elementals themselves.", objectives = "" }
WordHunterWoW_QuestEN[25940] = { title = "Last Stand at Whistling Grove", description = "We might have a chance to beat these flames back thanks to your work in the Inferno.\n\nStill, more wildlife is threatened. Keeper Taldros ran north through the flames, to Whistling Grove.\n\nSee if you can help him!", objectives = "" }
WordHunterWoW_QuestEN[25941] = { title = "Rest For the Weary", description = "You have done well, {race}, but there is much more to do and I grow weary.\n\nI have expended a great deal of energy sending a distress message to Earthen Ring leadership, pleading for their help.\n\nI must rest if I am to be of further use to us here.\n\nSpeak to the leader of the men you've saved and do what you can to help them prepare for battle.\n\nThe naga are scouring the waters for us. It is but a matter of time before they return - and they will surely come in even greater force.", objectives = "" }
WordHunterWoW_QuestEN[25942] = { title = "Buy Us Some Time", description = "Many good warriors have been lost today.\n\nIf what the shaman says is true, then we must act swiftly or we will add to their numbers.\n\nThe naga are out there, scouring these waters looking for survivors.\n\nWe are not yet ready to fight, {race}. You must buy us time to make preparations.\n\nFind the naga that hunt us and delay their efforts.", objectives = "" }
WordHunterWoW_QuestEN[25943] = { title = "Traveling on Our Stomachs", description = "I'll need your help if I am to get these orcs ready for battle.\n\nAny worthy leader knows that his warriors travel and fight on their stomachs. No food, no victory.\n\nThese warriors are weary from their struggle out there. They need food before they're ready to overcome a naga attack.\n\nSpeaking of traveling on stomachs, I saw plenty of crabs out on the sea floor...", objectives = "" }
WordHunterWoW_QuestEN[25944] = { title = "Girding Our Loins", description = "As we struggled not to drown, my orcs and I were forced to abandon our weapons and much of our armor.\n\nErunak says to expect a major attack from the naga soon and I believe him.\n\nIf we're going to be victorious, we'll need your help to recover our lost equipment.\n\nYou should find it scattered around the sea floor near our shipwrecks here and to the north.\n\nMake haste, {race}. The enemy could arrive at any moment.", objectives = "" }
WordHunterWoW_QuestEN[25945] = { title = "We're Here to Do One Thing, Maybe Two...", description = "You're in Hellscream's army now, {name}, and in Hellscream's army we kick butt and take names. Gone are the days of our people starving in the streets of Orgrimmar as we sign treaties with elves. We take what we need now. Kalimdor belongs to the Horde!\n\nThe Alliance attempts to stop our expansion every chance they get. Unsatisfied with owning most of the Eastern Kingdoms, those pig-lickers want it all!\n\nOverlord Krom'gar has called for more troops in Stonetalon. Get on the caravan west of here and go!", objectives = "" }
WordHunterWoW_QuestEN[25946] = { title = "Helm's Deep", description = "This helm and its associated components are marked with the seal of Stormwind. It was no doubt cast off from an Alliance ship that suffered a similar fate to yours.\n\nLooking closer, this seems far too intricate and sturdy to be everyday diving equipment. Perhaps Nazgrim can make some sense of this...", objectives = "" }
WordHunterWoW_QuestEN[25947] = { title = "Finders, Keepers", description = "I recognize this helm, {race}. You were wise to bring it to me.\n\nThe Alliance have a special unit, trained and equipped to explore and fight beneath the sea.\n\nIt would seem that they are in this region to do more than just defend against our attack.\n\nThere must be more of these down here, and if you can find them it could turn things around for the Vanguard.", objectives = "" }
WordHunterWoW_QuestEN[25948] = { title = "Bring It On!", description = "It is time, {class}.\n\nWe are as ready as we ever will be!\n\nI shall address the Vanguard, and then we shall swim into the sea to meet our fate.", objectives = "" }
WordHunterWoW_QuestEN[25949] = { title = "Blood and Thunder!", description = "The time has come to make our stand, {race}.\n\nWe'll defend this ship to our last breath, and make these naga scum think twice before approaching it again!\n\nFor the Horde!", objectives = "" }
WordHunterWoW_QuestEN[25950] = { title = "Sira'kess Slaying", description = "You're the {name} everyone's been talking about? Good to meet ya, love. Let's have a butcher's hook.\n\nWell, enough rabbit, right? Let's get down to it. I need you to swim out northwest to the Sira'kess Front and read and write them snakes something quick.\n\nNothing fancy. They're looking for a bother, and we'll give 'em a right good one in the ol' boat race.", objectives = "" }
WordHunterWoW_QuestEN[25951] = { title = "Final Judgment", description = "Get to the bridge on the east, quickly. Lady Naz'jar and the Fathom-Lord should be there with whatever forces remain.\n\nFollow our Lady's direction, as always. Hold the bridge until we can complete the ritual.\n\nOnce our allies arrive, the Kvaldir will be doomed.", objectives = "" }
WordHunterWoW_QuestEN[25952] = { title = "Caught Off-Guard", description = "Our escape from the shell can't have gone unnoticed, but either the naga at these ruins weren't informed or they don't consider us a threat. I don't intend to take the opportunity for granted - we strike now.\n\nI need you to slip into the lower level of the ruins to our west and take out as many of their patrols as you can. We cannot risk any of those patrols finding out about our occupation of this cave - make sure none escape.", objectives = "" }
WordHunterWoW_QuestEN[25953] = { title = "Swift Approach", description = "I've taken the liberty of performing some preliminary scouting. The naga may not be aware of our position, but they are not entirely unprepared for intruders.\n\nBeyond their patrols, they have set up magical sentry devices that will warn them of unwelcome guests. Fortunately, they seem to have sacrificed quality for quantity, and there is definitely a window in which the devices can be destroyed before their alarms are answered.\n\nI trust that you can see to this before our other soldiers arrive.", objectives = "" }
WordHunterWoW_QuestEN[25954] = { title = "An Occupation of Time", description = "Look--{name} is it?--I need your help. I know most everyone in this cave thinks that we're not in a position to be worrying about anything but our own hides right now, but I cannot dismiss my ancestors so readily.\n\nThis was one of the royal cities of the elves in the days when Azshara was queen. In this city lie the keys to lore long lost and artifacts of unimaginable historical value. All I want from you, while you're out in the city proper, is to keep a watchful eye out for objects of significance.", objectives = "" }
WordHunterWoW_QuestEN[25955] = { title = "A Better Vantage", description = "This cave is our only refuge. There's no help on the way. Whatever happens, this cave must remain safe or we are all sure to die down here.\n\nWe need a forward post to launch our attacks from. Something defensible.\n\nIn the eastern portion of the ruins on the lowest level, scout the north end of the gardens, the passage leading under the main structure just west of the gardens, and the cluster of buildings at the southeast corner of the ruins, under the bridges.\n\nBring me back any information you can.", objectives = "" }
WordHunterWoW_QuestEN[25956] = { title = "Upon the Scene of Battle", description = "All around you lie the remnants of a fierce battle. The naga skeletons are no surprise, but the weapons and remains of their apparent opponents are somewhat more unexpected.\n\nAmidst the bones, you spot a strangely prominent piece of metal jutting out from one of the skulls. It's difficult to tell what sort of weapon it might have once been part of, but it stands out sufficiently to prompt you to retrieve it as evidence.\n\nSurely someone back at the cave would be interested in this revelation.", objectives = "" }
WordHunterWoW_QuestEN[25957] = { title = "Visions of the Past: The Invasion of Vashj'ir", description = "The shard you recovered looks to be of naga origin. I had hoped to find a strong focal object like this for a spell I've been working on that would allow us to glimpse into the recent past.\n\nI've enchanted the blade, but you'll have to take it to a place where we know its owner was. I want you to travel back to the site where you found it and use the blade.\n\nPerhaps we can uncover more behind what the naga are doing here. Or even better, maybe we'll uncover a weakness that will give us a better chance.", objectives = "" }
WordHunterWoW_QuestEN[25958] = { title = "Looking Forward", description = "The Captain used the information you gathered for him to make a forward post under the terrace to our west. He's been preparing there for some kind of attack against the naga.\n\nYou should go to him immediately and inform him of the scope of what you've witnessed. Our force is small, and I fear for our soldiers if we charge in too recklessly.\n\nTake my sea horse. It knows the way.", objectives = "" }
WordHunterWoW_QuestEN[25959] = { title = "Clear Goals", description = "I see. The news you bring is grim, but I was not entirely unprepared for such possibilities. Without any effective scouting of naga numbers, I knew our plan was risky, but that's why we established this forward post.\n\nLet me put it to you plainly, {class}. If we do not keep the naga off-balance, they will bring the fight to us. We do not have the structures or the men to mount a defense, so that is not an option.\n\nWe need more time. Can you thin their numbers to the south, under the far terrace?", objectives = "" }
WordHunterWoW_QuestEN[25960] = { title = "Not Entirely Unprepared", description = "I overheard your conversation with the Captain. I know what we're doing sounds insane, but we really don't have much choice. There are people back at that cave that are depending on us.\n\nI've stationed lookouts on various ledges in the immediate area. They're burning ammo fast on the scattered naga scouts. Bring them more crossbow bolts to buy us some extra time.", objectives = "" }
WordHunterWoW_QuestEN[25962] = { title = "Properly Inspired", description = "Been all over the place. Blown all kinds of things up. I thought I might have some trouble carrying on the trend, what with the water and all, but it's all just a matter of inspiration.\n\nI found something volatile enough to make bombs out of! There's a bunch of kelp hanging under the terrace to the southwest. Normally kelp stores gas that makes it float - this kelp produces a different kind of heavy gas. It keeps it hanging, but also makes for great explosions.\n\nGather me some?", objectives = "" }
WordHunterWoW_QuestEN[25963] = { title = "Swift Action", description = "We have everything we need to begin the attack.\n\nIf your claims were correct, you would do well to make sure you cling tight to your mount as we make the run. Anyone who gets caught in the open water isn't likely to out-swim a naga.\n\nKill as many as you can as we make the attack run and we'll rendezvous on the broken ledge of the southern terrace above once we've expended our explosives. Hopefully by that point there will be few enough that we can finish them off the old-fashioned way.", objectives = "" }
WordHunterWoW_QuestEN[25964] = { title = "Fallen But Not Forgotten", description = "That was a disaster! Most of our men went down to spears before making it anywhere near the rendezvous.\n\nWe're only going to be able to hold this position for so long before the naga overrun us. We need to get out there to the southwest and save as many of the men as we can find - do anything you can.\n\nThey won't last long. Please hurry!", objectives = "" }
WordHunterWoW_QuestEN[25965] = { title = "Gauging Success", description = "Vicious louts... they did a lot of damage with those spears.\n\n<The captain winces slightly as he clutches a wound on his side.>\n\nWe'll hold here as long as we can for all the men to make it. I need someone to scout their numbers to see how much damage we did.\n\nOne of the biggest groups of them was around the corner on the northwest portion of this round terrace, and the other was a bit farther to the north in the small tunnel, also on this middle level of the ruins.\n\nUp for some scouting?", objectives = "" }
WordHunterWoW_QuestEN[25966] = { title = "Visions of the Past: The Slaughter of Biel'aran Ridge", description = "Look, I know this is asking a lot during a time like this, but I need you to tear yourself away from this defeat for a moment.\n\nI will tend to these soldiers - you need to find the location of that battle with the Kvaldir General to the west that you told me about. You should be able to glimpse more of the Battlemaiden's experiences from there. I have a strong feeling that the key to defeating these naga will lie with that Battlemaiden.\n\nPlease hurry - I will do everything I can to buy you time.", objectives = "" }
WordHunterWoW_QuestEN[25967] = { title = "Losing Ground", description = "You'll have to catch me up more later. Right now, we need to get out of here before more naga push in. Make your way back to the forward post on the level below us.\n\nTake my sea horse. We will meet you back there shortly.", objectives = "" }
WordHunterWoW_QuestEN[25968] = { title = "Desperate Plan", description = "Toldrek and Fiasco left to find a way to contact help. The trade lanes aren't far, so there might be a chance of success, but I'm wary to let anyone get their hopes up.\n\nIn truth, we don't have any other options. We're not likely to last much longer here. The naga will find us eventually, and... well... you saw how many of them there were.\n\nYou should go find the two of them on Biel'aran Ridge to the southeast. I'll keep everyone here safe as long as I can.", objectives = "" }
WordHunterWoW_QuestEN[25969] = { title = "Hostile Waters", description = "Fiasco came out here with a balloon of some sort that he retrieved from one of our ships. He tried to float it to the top, but those Muckskin Scroungers came out of nowhere and swarmed the thing.\n\nHe's got an idea for another balloon, but we need to make sure that the past doesn't repeat itself. I need you to kill off those giblins. Or at the very least, enough of them to make them fear us.", objectives = "" }
WordHunterWoW_QuestEN[25970] = { title = "Come Prepared", description = "It's a short swim to the top. Not much trouble really. Hard to get any supplies up there though. Too heavy.\n\nAll of the ships in all of the Horde fleets stow a survival kit. I had a balloon from the old survival kit, but it fell on hard times recently. I need another survival kit.\n\nThere's a ship to the southeastish. Let's hope that the survivors were dumb and didn't take the survival kit. More survival kit for us.", objectives = "" }
WordHunterWoW_QuestEN[25971] = { title = "Unfurling Plan", description = "Survival kits never have any rope. It makes no sense! Rope and bombs, that's all they should store. The rest of this stuff is just a waste of space.\n\nExcept maybe the balloon. That's coming in handy right now.\n\nI bet those Kvaldir have rope. They're always riding around in boats, tying knots, dressing in nets. Go take some rope from them! I must have it for our plan to work. It is non-optional.", objectives = "" }
WordHunterWoW_QuestEN[25972] = { title = "Honor and Privilege", description = "All done! I'm confident it will work. And not a scrounger in sight to pop a hole in it this time! Well played.\n\nToldrek already swam up to catch it, all concerned about currents and what not. He said you'd get the honors though. Nice guy - don't know how he lasts.\n\nGo to the top with the balloon, take the flare gun from the crate, and scan the horizon for Horde ships. If you see any, fire the flare towards them. That's it! All there is to it.\n\nSwim. Float. Flare. Rescue! That last part's my favorite.", objectives = "" }
WordHunterWoW_QuestEN[25973] = { title = "Welcome News", description = "They'll probably send a skiff over, which may take a bit. I'll stay here to make contact.\n\nYou need to return to the cave immediately and let them know that rescue is on its way. We can only hope that the naga have not found them yet.\n\nGo. Swim fast, {name}. ", objectives = "" }
WordHunterWoW_QuestEN[25974] = { title = "Sira'kess Slaying", description = "So, you're the {name} everyone's been talking about? It's good to finally meet you.\n\nWell, enough talk, right? Let's get down to it. I need you to swim out northwest to the Sira'kess Front and kill those naga real quick.\n\nNothing fancy. They're looking for a fight, and we'll give them one! Well, you will.", objectives = "" }
WordHunterWoW_QuestEN[25975] = { title = "Treasure Reclamation", description = "We've got our reinforcements, but we still need to find a way to pay them. That kind of action doesn't come cheap.\n\nUp on Deepfin Ridge to the northwest, the slimy gilblin have stolen all sorts of treasure. I think that it's time to reclaim some of it for the cause.", objectives = "" }
WordHunterWoW_QuestEN[25976] = { title = "Treasure Reclamation", description = "Blood and thunder! We have our reinforcements, but they still need to be paid. They won't be cheap.\n\nUp on Deepfin Ridge to the northwest, the slimy gilblin have stolen all sorts of treasure. It's time to reclaim some of it for the Horde.\n\nHellscream's eyes are upon you, {name}!", objectives = "" }
WordHunterWoW_QuestEN[25977] = { title = "A Standard Day for Azrajar", description = "{name}, the snakes are after our daft and barmy. Go back northwest to Deepfin Ridge and plant some do me good in that pot and pan pitch and toss of theirs.\n\nThey'll kick and prance away with their alderman's nails tucked between their nutmegs when they see that. Not that they've got any nutmegs mind you.", objectives = "" }
WordHunterWoW_QuestEN[25978] = { title = "Entombed in Ice", description = "Khurgorn tells me the cataclysm upset the balance of the elements all over the world. Helm's Bed Lake, to the south, used to be beautiful and tranquil, but it is now overrun with agitated water elementals. When they started to leave the confines of the lake, I sent my troops in to keep them busy, but most have been frozen in blocks of ice.\n\nIf we can break them free, they have a good chance of recovering. I cannot spare the men for a second expedition out onto the lake. Would you be willing to try?", objectives = "" }
WordHunterWoW_QuestEN[25979] = { title = "Dealing with the Surge", description = "The elements are in turmoil, {class}. The cataclysm stirred up the long-dormant water spirits of Helm's Bed Lake, just to the south. They're angry, confused, and unwilling to hear my pleas.\n\nI have tried everything I know to calm them, to persuade them to stop lashing out and attacking the sergeant's mountaineers.\n\nIt pains me to say this, but no other options remain -- we must kill the elementals.", objectives = "" }
WordHunterWoW_QuestEN[25980] = { title = "A Standard Day for Azrajar", description = "{name}, the naga are after our forces. I need you to go back northwest to Deepfin Ridge and stick our standard in their general, Fathom-Caller Azrajar.\n\nThey'll swim away with their tails tucked between their... er. Well, I guess they don't have any legs, now do they?", objectives = "" }
WordHunterWoW_QuestEN[25981] = { title = "Those Aren't Masks", description = "{name}, there are these demon squid-things out there that are eating gilblins' heads and then taking them over! That's one way to get slaves.\n\nThink you could swim out northwest onto Deepfin Ridge or into the Sira'kess Front and bring me back some of those Merciless things?", objectives = "" }
WordHunterWoW_QuestEN[25982] = { title = "Those Aren't Masks", description = "{name}, there are demon squids out there that are eating gilblins' heads and then taking them over! They better not come in here!\n\nThink you could swim out northwest onto Deepfin Ridge or into the Sira'kess Front and bring me back some of those Merciless things? Preferably dead, I think.", objectives = "" }
WordHunterWoW_QuestEN[25983] = { title = "Promontory Point", description = "We need to get this information up to Captain Taylor on Promontory Point! He's out there to the northwest with Erunak Stonespeaker and the Earthen Ring.", objectives = "" }
WordHunterWoW_QuestEN[25984] = { title = "Promontory Point", description = "{name}, I need you to get this information to Legionnaire Nazgrim on Promontory Point. He's up there to the northwest with Erunak Stonespeaker and those Earthen Ring people.", objectives = "" }
WordHunterWoW_QuestEN[25985] = { title = "Wings Over Mount Hyjal", description = "{name}, is it true you're going to try to commune with the ancients?\n\nSouthwest of here is the Shrine of Aviana, the matron of all flying creatures. It's the home of my favorite instructor, Choluna. I've never encountered one who was so deeply in touch with the spirits of this world. You could learn a lot from her!\n\nThe recent attacks have isolated the shrine. But it's easily accessible from the air - look for the second biggest tree on Hyjal. Good luck!", objectives = "" }
WordHunterWoW_QuestEN[25986] = { title = "Trouble at the Lake", description = "You've been a great help in securing the mines and rescuing the trapped miners.\n\nThe Senate will be heartened to hear that you and Captain Tharran's mountaineers have made progress in securing Dun Morogh.\n\nWhat worries me is that I haven't seen any reports from Sergeant Bahrum and his detachment. They were sent east, along the road toward Helm's Bed Lake, and ordered to set up a small outpost. Would you go to Bahrum's Post and check in on the sergeant?", objectives = "" }
WordHunterWoW_QuestEN[25987] = { title = "Put It On", description = "Hey, {name}, I've got an idea for a disguise! Take one of these merciless whatchamacallits and put it on your head.\n\nWhat could possibly go wrong?\n\nReady to put it on?", objectives = "" }
WordHunterWoW_QuestEN[25988] = { title = "Put It On", description = "I've got an idea for a sweet disguise, but I'm going to need your help, {name}! Take one of these merciless corpses and put it on your head.\n\nI know, I know, but it's dead, so what could possibly go wrong other than you smelling bad for a day or two?\n\nReady to put it on?", objectives = "" }
WordHunterWoW_QuestEN[25989] = { title = "Capture the Crab", description = "Everything in my body tells me that Nespirah is trying to speak with me, but I cannot hear her.  Perhaps the naga have done something to her voice.\n\n<Duarn thinks to himself for a moment.>\n\nNespirah's voice may be suppressed... that means... we need to find a voice for her!\n\nI've got it!  The Idra'kess have been known to train deepseeker crabs as battle companions.  Use this net to capture a crab, and bring it to me.  You will likely find them prowling the chamber's outer edges.", objectives = "" }
WordHunterWoW_QuestEN[25990] = { title = "Breaking Through", description = "A trained shaman has the ability to communicate with the four elements of earth, fire, air and water.  This is known.\n\nWhat is not as widely known, however, is the presence of a fifth element.  This element is not as clearly described as the other four, but it has to do with the shared... commonality between all living creatures.\n\nMy theory is that the crab, as a creature of the sea, is close enough to Nespirah that, with the elements' coaxing, we can convince it to act as Nespirah's mouthpiece.", objectives = "" }
WordHunterWoW_QuestEN[25991] = { title = "We Are Not Alone", description = "<Duarn closes his eyes, pauses, and nods.>\n\nNespirah has just informed me that we are not the only people fighting inside of this shell.  A small group of Horde slaves has escaped and is currently fighting off the naga on the other side of the shell, up on the ledge that overlooks Nespirah's heart.\n\nGo find them, {name}, and see what help they can lend us.  With their aid, we may be able to rouse Nespirah from her torpor.\n\nI will remain here, should you need anything.", objectives = "" }
WordHunterWoW_QuestEN[25992] = { title = "Hopelessly Gearless", description = "I honestly don't know how we've survived this long.  The naga took my armor and weapons, and left me with rags and a mining pick... and THAT snapped in half long ago.\n\nIf we're to stand any hope of turning the tide, I'm going to need something to fight with... as will my companions, though they may be too proud to admit it.\n\nI've seen weapon racks in the naga storage areas nearby.  I'm not accustomed to fighting with a trident, but it'll sure be better than fighting with my fists.", objectives = "" }
WordHunterWoW_QuestEN[25993] = { title = "Body Blows", description = "<Legionnaire Nazgrim listens intently to your recount of Duarn and Nespirah's conversation.>\n\nI see.  So the creature wants our help waking it up, is that it?\n\nWith hundreds of slaves already picking away at her pearls, the beast seems to be a pretty heavy sleeper.  You might have better luck, though.\n\nMy suggestion?  Look around the creature's flesh for signs of weakness.  Maybe that weapon of yours will find a ticklish spot and force the beast to come to its senses.", objectives = "" }
WordHunterWoW_QuestEN[25994] = { title = "Still Valuable", description = "My time in the pearl pits, however short, has made me curious about the naga's goals.  Yes, I now know that the naga want to use Nespirah as an engine of war, but if that's the case, then why are they enslaving men to mine her pearls?\n\nAssuming we escape this creature's hull, I would very much like to study these objects.  The pearls we found in the pits were much too large to carry, but I've seen the warlords and prophets occasionally carrying around smaller ones.", objectives = "" }
WordHunterWoW_QuestEN[25995] = { title = "Overseer Idra'kess", description = "My men are flagging, {name}.  We won't last much longer against these naga, I'm afraid.  With the Idra'kess' weapons, and Nespirah's pearls, we should be ready to bust out of here.\n\nFollow the wall northeast, and look for a ramp to the upper chamber.  I assume their leader is in there, or perhaps the key to Nespirah's awakening.  Hopefully both.\n\nIf you feel strong enough, head up to the top of the shell and look for some answers.  Hellscream's eyes are upon you!", objectives = "" }
WordHunterWoW_QuestEN[25996] = { title = "Waking the Beast", description = "Thanks to you and the Legionnaire, Nespirah has full control of her body... but most of the naga don't know this yet.  Once we make our escape, she will activate her biological defenses and destroy the naga from within.\n\nMake yourself ready... I will now tell Nespirah to begin the countdown.", objectives = "" }
WordHunterWoW_QuestEN[25997] = { title = "Dark Iron Scheming", description = "A cadre of Dark Iron spies have taken over Ironband's Compound to the south, beyond Helm's Bed Lake. The mountaineers are normally able to keep them from getting into Dun Morogh, but everything is in disarray right now.\n\nThe Dark Iron dwarves would be fools if they didn't take advantage of the chaos. We have to find out what they're planning and stop them before they do any damage.\n\nWill you see if you can discover what they're doing down at Ironband's Compound?", objectives = "" }
WordHunterWoW_QuestEN[25998] = { title = "Get to the Airfield", description = "According to the plans you captured, the Dark Irons are planning a large-scale attack on the Ironforge Airfield! The council has moved most of our forces down into Dun Morogh to deal with the instability brought by the cataclysm, leaving our defenses weakened at the airfield.\n\nWe need a way to get you to the airfield quickly. Take the road back west toward Gol'Bolar Quarry and find Mathel Rustwrench. He should have a flying machine you can use. Go!", objectives = "" }
WordHunterWoW_QuestEN[25999] = { title = "Barrier to Entry", description = "Filthy, good-for-nothin' night elves have managed to disarm our entire minefield in Talondeep Pass. Somebody is gonna have to go back up there and re-arm them all! A perfect task for a worthless grunt like you, {name}. Here's to hopin' you don't blow yourself up in the process.\n\nYou'll find our \"Elf Killers\" scattered across Talondeep Pass, directly north of here. Take this wrench and get to work, maggot.", objectives = "" }
WordHunterWoW_QuestEN[26000] = { title = "Spelunking", description = "Hurry, {name}!\n\nMake your way to that cavern at once.\n\nWe shall go behind you to ensure that you are not followed.", objectives = "" }
WordHunterWoW_QuestEN[26001] = { title = "The Missing Blastgineer", description = "It looks like you might not be completely useless after all. Perhaps you can handle something a little more important.\n\nAbout two days ago I sent Blastgineer Fuzzwhistle to Windshear Mine. He was supposed to get there, make sure everything was going according to plan with the bomb, and report back. Two days and nothin'...\n\nHead out to the woods south of here and find him. For his sake, he better be dead.", objectives = "" }
WordHunterWoW_QuestEN[26002] = { title = "Alliance Attack Plans", description = "<You pry the note loose from Fuzzwhistle's hand.>\n\nThey're onto us! They know all about the bomb. Planning an attack on Krom'gar Fortress! I think they sent a search party after me. Won't go out like a chump. They'll get a fight.\n\nI think I hear them coming now! Their leader is a high elf huntress named Davinia. She spoke of attack plans. Avenge me by killing her and getting those plans! Her tent is nearby, to the east.\n\nHellscream's eyes are upon you...", objectives = "" }
WordHunterWoW_QuestEN[26003] = { title = "Lessons from the Lost Isles", description = "There are great dangers in the woods south of here. They are crawling with Darnassian scouts - assassins sent from Darnassus to kill us. Perhaps we can turn the tables on them, eh?\n\nWhen I was marooned on the Lost Isles a goblin gave me these infrared heat focals. They allow the wearer to see heat signatures of certain creatures. Take the focals and use them while in the woods to the south. They will allow you to easily spot the scouts. Kill as many of them as you can! For the Horde!", objectives = "" }
WordHunterWoW_QuestEN[26004] = { title = "Krom'gar Fortress", description = "Our main base of operations in Stonetalon Mountains is Krom'gar Fortress. It is from there that Overlord Krom'gar oversees all Horde military activity in the region. Krom'gar reports everything that happens directly to the Warchief.\n\nThe attack plans you brought back detail an assault that's supposed to take place against Krom'gar Fortress soon. Take the plans and head to the fortress, southwest of here. Give them to the Overlord.\n\nSo long, {name}. Truly, Hellscream's eyes are upon you.", objectives = "" }
WordHunterWoW_QuestEN[26005] = { title = "A Breath of Fresh Air", description = "Captain Taylor and many of the other survivors have already made their way to the surface. I'm sure some are just looking to rid themselves of this place for good, but we still have work to do if we're going to stop the naga from invading the plane of water.\n\nFirst, we need to set eyes on the tentacled fiend that destroyed our ships when we first arrived - we don't want a repeat of that nightmare.\n\nHexascrub left these behind for you. They should speed your trip up a bit.", objectives = "" }
WordHunterWoW_QuestEN[26006] = { title = "A Breath of Fresh Air", description = "Legionnaire Nazgrim and many of the other survivors have already made their way to the surface. I'm sure some are just looking to rid themselves of this place for good, but we still have work to do if we're going to stop the naga from invading the plane of water.\n\nFirst, we need to set eyes on the tentacled fiend that destroyed our ships when we first arrived - we don't want a repeat of that nightmare.\n\nFiasco left these behind for you. They should speed your trip up a bit.", objectives = "" }
WordHunterWoW_QuestEN[26007] = { title = "Debriefing", description = "This warrior was near death, but I fear we do not have the time to await his full recovery. He has information we desperately need to know.\n\nBe patient with him, but keep him talking until we've learned all that we can.\n\nWith luck we might discover just what we're up against...", objectives = "" }
WordHunterWoW_QuestEN[26008] = { title = "Decompression", description = "I simply cannot bear the thought of so many others like this warrior imprisoned, surrounded by naga.\n\nSomething must be done to rescue them!\n\nTry this, {name}. Use  it on the prison cells to make them buoyant.\n\nIf we can get them to the surface, at least they stand a chance at being rescued.", objectives = "" }
WordHunterWoW_QuestEN[26009] = { title = "Seek and Destroy", description = "The Alliance encroaches upon our territories within Stonetalon. The forces of Northwatch have broken through our blockade in the south and occupy Windshear Valley, to our west. From the northern front comes an onslaught of night elf soldiers. All must be stopped!\n\nVenture forth into Stonetalon and destroy all Alliance soldiers that cross your path. Let their deaths serve as a message.\n\nStonetalon belongs to the Horde!", objectives = "" }
WordHunterWoW_QuestEN[26010] = { title = "Ashes to Ashes", description = "The Alliance have grown bold. Just west of here, in Windshear Valley, Northwatch troops have set up camp. No doubt they are preparing for the assault you warned us of, {name}. They will never get the chance!\n\nTake this flame thrower. It is the same flame thrower my incinerators use to burn our enemies out of hiding in the forests. Use it to destroy the Northwatch tents. Leave only ashes in your wake!", objectives = "" }
WordHunterWoW_QuestEN[26011] = { title = "Enemy of the Horde: Marshal Paltrow", description = "My scouts have tracked the cause of this latest fiasco to one man: Marshal Paltrow. He commands the Northwatch forward camp that has established itself in Windshear Valley, west of here. Take him out and you remove a powerful Alliance field commander from the equation.\n\nPaltrow must die, {name}.", objectives = "" }
WordHunterWoW_QuestEN[26012] = { title = "Trouble at Wyrmrest", description = "My old friend Krasus sends word of dire happenings at Wyrmrest, in Dragonblight. His missive was brief, but it seems that there has been some sort of attack on the Ruby Sanctum beneath the Temple.\n\nPressing business here in Dalaran keeps me from attending to the matter personally, but I have heard word of your exploits in the Lich King's Citadel and you are doubtless up to the task -- perhaps you could assist Krasus in my stead?", objectives = "" }
WordHunterWoW_QuestEN[26013] = { title = "Assault on the Sanctum", description = "{race}, something terrible has transpired within the Ruby Sanctum beneath the Temple.\n\nThe entry to the Sanctum is in ruins, and its guardians violently slain. We sent scouts to investigate, but they have not returned. I cannot help but fear the worst.\n\nEnter the Ruby Sanctum and discover what has befallen the home of my flight. Once we have more information, we can plan our next steps accordingly.", objectives = "" }
WordHunterWoW_QuestEN[26014] = { title = "The Brothers Digsong", description = "Private {name}, at attention!  Ve are havink a small problem!\n\nVe have sent Humphrey and Oskar Digsong out to Underlight Canyon, to the northvest, but they are not comink back.  They vere supposed to scout out the area, but ve have lost all contact with them.\n\nYour assignment, Private {name}, is to locate our comrades and, if they live, bring them back to me!", objectives = "" }
WordHunterWoW_QuestEN[26015] = { title = "Phosphora Hunting", description = "Oskar's last wish, before he floated up into that great-eel's gullet, was to bring back food for the captain, so that's what we'll do.\n\nMy brother had a genius plan.  He saw those murlocs luring fish out of the reeds with a phosphorescent antenna, and devised a way to make one of his own.  All ya need is something that glows.\n\nKill the crabs and groupers that roam the canyon's floor.  They aren't edible themselves, but their phosphora is far more valuable than their meat.", objectives = "" }
WordHunterWoW_QuestEN[26017] = { title = "A Lure", description = "Stick this device on your head, then swim through the kelp and coral along the canyon's edge.  There should be all kinds of little fish in there that find your new antenna irresistible.\n\nWhen we return to Darkbreak Cove, we'll have armfuls of fish for everyone!", objectives = "" }
WordHunterWoW_QuestEN[26018] = { title = "Coldlights Out", description = "Oh yeah!  I was supposed to put together a report!  I'd almost forgotten!\n\nLooks like mostly harmless wildlife around here... 'cept for those blasted eels... and a few murlocs.  Cap'n will be more interested in the murlocs, I think.\n\nGo engage a few of 'em in combat and see what kinda moves they got.  From what I've seen, the big ones hunt for fish in the kelp, and the little ones practice some kind o' magic or another... but that's all I know.", objectives = "" }
WordHunterWoW_QuestEN[26019] = { title = "Enormous Eel Egg", description = "<This appears to be an egg from one of the devious great-eels that float up above the canyon.  You wonder whether or not Humphrey might be interested in something like this.>", objectives = "" }
WordHunterWoW_QuestEN[26020] = { title = "Report to Bombgutz", description = "We must prepare for the impending attack. I will have our soldiers prepare the bomb for transport. I want you to report to Chief Blastgineer Bombgutz. She has been working to fix our anti-air cannons, but has thus far failed. Make sure that she is properly motivated to repair our guns, {name}.", objectives = "" }
WordHunterWoW_QuestEN[26021] = { title = "The Brothers Digsong 2: Eel-Egg-Trick Boogaloo", description = "Those eels ate my brother.  My brother, {name}!  It's time someone showed 'em who's boss.\n\n<Humphrey removes several sticks of dynamite from his vest and shoves them through the egg's outer membrane.>\n\nThe great-eels to the south are too tough to fight one-on-one, but with this egg, we should be able to even the odds.  Place it near one of those creatures, then... kablooie!\n\nIf the bomb doesn't kill the eel outright, it should be near enough to death for you to finish it off.", objectives = "" }
WordHunterWoW_QuestEN[26022] = { title = "First Blood", description = "Be prepared, {name}. You will cast the first blood upon this land for us.\n\nThe Syndicate, as they call themselves, are cowardly humans who betray even their own kind. Their isolation will make them easy prey.\n\nTravel north, slay any Syndicate members you find, and claim Northfold Manor in the name of the Forsaken. Bring me the Bloodstone Amulets they wear as proof of your conquest. ", objectives = "" }
WordHunterWoW_QuestEN[26023] = { title = "The Forsaken Trollbane", description = "Let me tell you a story.\n\nOnce, there was a foolish troll named Zengu. He was tasked to find the sword Trol'kalar, the legendary blade of the human Trollbane line. He succeeded, and thinking his task done, went to leave Arathi by himself. There he was cut down by the humans, and the sword simply reclaimed.\n\nWe will not be so foolish. Our apothecaries have given us the perfect guide to reobtain Trol'kalar: the prince who once held it.\n\nHe stands ready to guide you, {name}. Speak with him.", objectives = "" }
WordHunterWoW_QuestEN[26024] = { title = "Wanted!  Marez Cowl", description = "A bounty has been placed on the head of Marez Cowl, a high-level advisor and operative of the Syndicate.  She was last seen within the Syndicate controlled territory of Stromgarde.\n\nBounty may be collected from Captain Nials.\n\nBe warned: Marez is a skilled and cunning warlock, known for her trafficking with demons.  Extreme caution is advised when hunting her.", objectives = "" }
WordHunterWoW_QuestEN[26025] = { title = "The Traitor Orc", description = "There is no doubt in my mind that a powerful warlock resides within the walls of Stromgarde. From time to time, using an arcane magical relic, this warlock has summoned forth terrible demons in large numbers. We must remove the source of her energy.\n\nFind the warlock and kill her. Bring me whatever magical object you find on her person, and I will take steps to destroy it and see that its power is not used to taint this land any longer.", objectives = "" }
WordHunterWoW_QuestEN[26026] = { title = "Dream of a Better Tomorrow", description = "Mr. D is sick, mister. Won't you help him? All you have to do is find his hat and batteries and he'll be all better. I'd go get them myself, but I can't leave Mr. D alone!\n\nHis hat was stolen by the meanies in the Venture Co. over at the water wheel and his batteries are hidden around Windshear Crag. You'll just have to look real hard for those!\n\nWould you kindly bring Mr. D's stuff back so he can teach those baddies in the Alliance a lesson?", objectives = "" }
WordHunterWoW_QuestEN[26027] = { title = "Call to Arms", description = "Our next strike against the ogres will bring you further east to Stromgarde. The living consider these gutted ruins worth clinging to. Their sentimentality is disgusting!\n\nAll that Stromgarde holds for us is a foul den of more ogres, waiting to be struck down. Travel there and slay their shamans and lords, and ensure what passes for leadership among the ogres is snuffed out.", objectives = "" }
WordHunterWoW_QuestEN[26028] = { title = "Mr. D's Wild Ride", description = "Now Mr. D just needs an angel to help him navigate. Will you be that angel, mister? With you helping we can go out into the crag and kill bunches and bunches of Alliance! Waddya say? Come on, mister! PRETTY PLEASE WITH SUGAR ON TOP?\n\nIf we kill enough Alliance Mr. Krom'gar will buy us all ice cream!", objectives = "" }
WordHunterWoW_QuestEN[26029] = { title = "The Real Threat", description = "Or'Kalar leads the ogres here. He has evaded slaughter for years. His very presence is an affront to the Dark Lady; Mug'thol, traitor to the Forsaken, commands him from afar!\n\nWe do not suffer ogres or traitors on Forsaken land. Bring me this ogre's head and I will make sure it's burned properly this time.", objectives = "" }
WordHunterWoW_QuestEN[26030] = { title = "Sigil of Strom", description = "In ancient times, Lord Ignaeus of Strom, named Trollbane, led the first human civilization of Arathor in war against the trolls. His blade was Trol'kalar--troll slayer, in their ancient tongue.\n\nI was one of the last of his line, sworn with guarding Trol'kalar...a duty in which I failed. But now, we will obtain it once more, for my new master.\n\nThe sword is bound by three sigils. The first is held by the Syndicate traitors that lurk the ruins of Stromgarde. Slay them, and return the sigil to me.", objectives = "" }
WordHunterWoW_QuestEN[26031] = { title = "Sigil of Thoradin", description = "In life, I divided the sigil of Thoradin into five pieces to protect it, spreading it among my most loyal men. This too failed, but my successor will have done the same.\n\nThe defenders of Stromgarde hold the pieces of the sigil yet again. Slay them, and bring the shards to me; I will reassemble them.", objectives = "" }
WordHunterWoW_QuestEN[26032] = { title = "Sigil of Arathor", description = "I entrusted the sigil of Arathor to Lieutenant Valorcall, leader of my cavalry. He barely escaped with his life when it was taken.\n\nIt is unlikely he will do so again. Valorcall patrols the road between Stromgarde Keep and Refuge Point. Find him, and take the sigil from him once more.", objectives = "" }
WordHunterWoW_QuestEN[26033] = { title = "Trol'kalar", description = "The last sigil is mine...and with it, the four combine to the Sigil of Trollbane, key to the tomb. We are ready.\n\nTrol'kalar lies sealed with its master's remains, within Trollbane's tomb in the catacombs of Stromgarde. It will be defended heavily...but my presence before you is proof enough that the defenders can be overcome.\n\nEnter the tomb, retrieve Trol'kalar, and bring it here.", objectives = "" }
WordHunterWoW_QuestEN[26034] = { title = "The Twilight Destroyer", description = "This was no reckless attack, but rather a carefully orchestrated strike against the heart of the Red Dragonflight.\n\nZarithrian, on the bluff over there, is overseeing the assault, but the true leader of this force is a brash and powerful Twilight dragon named Halion. Not since Dargonax has a full-grown spawn of Sinestra's twisted experiments been seen.\n\nSlay him, {name}, and then when the invasion has been fully repelled, report to Krasus regarding all you have seen here.", objectives = "" }
WordHunterWoW_QuestEN[26035] = { title = "Worth Its Weight in Gold", description = "Archmage Malin sent me here to collect reagents for him. I was at a loss as to how I was going to collect the items, but now that you're here, I think my problem's solved.\n\nI need Witherbark tusks and Witherbark medicine pouches.\n\nCould you find those for me? The Witherbark live to the southeast of Arathi.", objectives = "" }
WordHunterWoW_QuestEN[26036] = { title = "Wand over Fist", description = "Hey, {name}. Sorry to be so short with ye earlier... and no, that ain't a pun.\n\nI figured out where Trelane's first item ended up: Kor'gresh has it in Boulderfist Hall. An' by the way he was throwing down blasts of ice at his kin to keep them in line, he must be close to figurin' out how to use all of its powers.\n\nBoulderfist Hall's south of here an' then east of Thandol Span. Find the ogre an' get back that wand.\n\nWhile you're gone, I'll figure out what we're gonna do about Stromgarde.", objectives = "" }
WordHunterWoW_QuestEN[26037] = { title = "Trelane's Defenses", description = "All rested?\n\nHere's our next step: there're ogres all around the Tower of Arathor in Stromgarde. We're gonna need to ward you against the tower's defenses. To do that, we're gonna need some gems the Boulderfist shaman have taken a liking to. They took 'em from the tower, but they're not gonna stay in their possession for long.\n\nGet one of them gems an' bring 'em to Kryten--he knows the spell to enchant it.", objectives = "" }
WordHunterWoW_QuestEN[26038] = { title = "Attack on the Tower", description = "Here's what you're looking for: Trelane's phylactery, Trelane's orb, and Trelane's ember agate.\n\nAll three should be in chests within the tower.  You shouldn't have a problem opening the chests on your own; you just have to be careful of the ogres.\n\nYou'll need to have your weapons at the ready. Those ogres find out you're there and stealing from them, and they'll be sure to put the hurt on you.\n\nBe careful, and good luck.", objectives = "" }
WordHunterWoW_QuestEN[26039] = { title = "The Princess Trapped", description = "My name is Myzrael.  I am a princess of the earth, and my captors, the giants, have trapped me deep beneath the Arathi Highlands.  These crystal shards are the only way I can speak with the surface world.\n\nPlease help me.  Allies of the giants, the Drywhisker kobolds, have a shard like this one in their Drywhisker Gorge, to the east.  To power the cluster, you must gather motes of Myzrael from the kobolds and apply them to it.\n\nI beg you, {name}, aid me!", objectives = "" }
WordHunterWoW_QuestEN[26040] = { title = "What? What? In My Gut...?", description = "Wha...what IS this!?\n\nThere's great pain growing... from deep in my bowels.\n\nI think... ugh... they must have poisoned me!\n\nThey fed us strangely glowing seaweed that they grow around their stronghold...\n\nI think these cramps will worsen if I don't get more soon...\n\nPlease, {race}. Try to find me some!", objectives = "" }
WordHunterWoW_QuestEN[26041] = { title = "Stones of Binding", description = "Four Stones of Binding are scattered throughout Arathi.  These stones keep me pinned beneath the earth.\n\nTo unlock them you must unlock the strongest: the Stone of Inner Binding.  And to do that, you must gather keys from the other three.\n\nThese stones are watched by guardians, but if you are clever, or lucky, you may find ways to banish them.", objectives = "" }
WordHunterWoW_QuestEN[26042] = { title = "Breaking the Keystone", description = "Opening the Stones of Binding loosened much of my confinement, but a lock still holds me chained.  It is the Keystone you see among this circle of stones.  And the key is held by one of my captors, the stone watcher Fozruk.\n\nYou must obtain that key, which the stone watchers call the Rod of Order, from Fozruk and use it to open the Keystone.\n\n{name}, you have done so much to aid me.  Just a little more...and my gratitude will shake the very foundations of the earth!", objectives = "" }
WordHunterWoW_QuestEN[26043] = { title = "BEWARE OF CRAGJAW!", description = "By order of Overlord Krom'gar, Cragpool Lake is OFF LIMITS!\n\nThe ferocious beast known as Cragjaw has made the lake a death trap. Should you dispatch of Cragjaw, take his huge tooth as a trophy and return it to Spy-Mistress Anara for a reward.", objectives = "" }
WordHunterWoW_QuestEN[26044] = { title = "Where Are the Parts?", description = "I've been waiting on parts for these guns for days! I sent one of my best blastgineers and two dozen miners into the Deep Reaches five days ago for the parts. After not hearing from anybody for three days I began to get a little worried. The Overlord sent two of his best orcs in to see what was going on. We've received no reports since then...\n\nHead into the Deep Reaches, directly below this fortress, and find out what's going on! I need parts!", objectives = "" }
WordHunterWoW_QuestEN[26045] = { title = "I Got Your Parts Right Here...", description = "Here's the dilemma: I could do one of two things, get killed down here like everyone else or get killed up at Krom'gar Fortress when Krom'gar realizes we've lost the mine. I'm choosing the third option, do nothing. So far, so good.\n\nYou need parts? Plenty from the left over junk scattered about in this mine. You just gotta go get 'em.\n\nGood luck! Maybe if you get those parts we might be able to show our faces at Krom'gar Fortress.", objectives = "" }
WordHunterWoW_QuestEN[26046] = { title = "Between a Rock and a Hard Place", description = "Dontrag can explain it better than me. Basically, we're stuck between a rock and a hard place. Can't do anything down here due to all of the things that can kill us and can't go back to the base due to all of the things that can kill us - you know?\n\nPerhaps if we worked together we might be able to get this mess sorted out. How about you get started by clearing out some of these elementals that have apparently killed everything in the mine, ok?", objectives = "" }
WordHunterWoW_QuestEN[26047] = { title = "And That's Why They Call Them Peons...", description = "These two are USELESS! When they first arrived I thought we were saved. Not so! Instead, Dontrag and Utvoch took one look at the mine and concocted some idiotic plan that involved standing here until... until we all died, I guess. \n\nYou don't look nearly as useless. How about you lend a hand, friend? I've got dozens of peons, scared out of their gourds, hiding in the Deep Reaches. Find them and get them out!", objectives = "" }
WordHunterWoW_QuestEN[26048] = { title = "Spare Parts Up In Here!", description = "Whew, that was tough. I didn't think we'd make it, {name}. We better get these parts back to Chief Blastgineer Bombgutz. I think I hear the gnome flying machines buzzing outside. We haven't got a minute to lose!", objectives = "" }
WordHunterWoW_QuestEN[26049] = { title = "The Princess Unleashed", description = "Myzrael's no innocent princess. She's a terribly dangerous force, and the giants had every reason to chain her down there. I'm afraid you've been had.\n\nAccording to Gerrig, you have to summon her at the Shards of Myzrael where you first spoke with her.  Defeat her and gather her Eldritch Shackles, then bind them to the Shards.\n\nHere's the scroll you'll need. Be careful with it; I risked a few teeth to get it. Good luck, {name}.", objectives = "" }
WordHunterWoW_QuestEN[26050] = { title = "Goggle Boggle", description = "Now that we are full-fledged Blackwater Raiders it is our job to help Mr. O'Breen locate the lost elven treasure.\n\nIt is next to impossible to find the gems in the dark sea without aid. The doctor has constructed some goggles that will help. He needs the goggles charged with the energy derived from the enchanted stone in the cave just up the hill.\n\nBut the cave is cursed! When we get close, we get ambushed. Defend me and I can harness the energy from the stone into the goggles.", objectives = "" }
WordHunterWoW_QuestEN[26051] = { title = "Sunken Treasure", description = "The treasure has been on the sea floor so long that the gems have calcified into thick stone. But the power harnessed in these goggles will allow you to locate them easily.\n\nA little gnomish ingenuity goes a long way!\n\nSo borrow the Goggles of Gem Hunting, {name}, and see if you can collect some of the lost treasure for Captain O'Breen.\n\nI'd swim down there myself but...um...well, I have important scientific business to tend to up on the safe, dry land....er, yeah.", objectives = "" }
WordHunterWoW_QuestEN[26052] = { title = "Speak to Shakes", description = "Let's not leave Captain O'Breen waiting. He'll want to see these gems first hand. After all, that's why we're here!\n\nAnd after a few weeks of consorting with these pirates, the professor and I have realized the last thing that's good for our health is to be caught hanging on to their treasure.\n\nHere, {name}, take these to O'Breen.", objectives = "" }
WordHunterWoW_QuestEN[26053] = { title = "Clearing the Highlands", description = "No threat here will go overlooked. If we are to secure these lands under the Dark Lady's rule, we will tear from them everything living, inch by inch, piece by piece.\n\nTo the northeast, not a stone's throw away from this camp is an ogre mound. The Boulderfist ogres that dwell in it must be eradicated, {class}.\n\nThey are in the way. Show no mercy or hesitation.", objectives = "" }
WordHunterWoW_QuestEN[26054] = { title = "Water They Up To?", description = "Sandfury trolls working with the Twilight's Hammer?!\n\nNo matter. That foul witch won't be sending her monster to MY city.\n\nCome, brave ones! We'll slick the sand with their gore and return home triumphant. Tell General Marcus Jonathan what's happened here when we've gotten back; I'll need to oversee the return of the citizenry, repairs, and so on.", objectives = "" }
WordHunterWoW_QuestEN[26055] = { title = "Drowned Sorrows", description = "Argh, 'tis a horrible life. I should be in a watery grave right now, not sittin' here by the fire, breathin' fresh air.\n\nThe crew tried so hard to save my beautiful Maiden's Folly. Bless the boys, bless their hearts.\n\nO'Breen made it to shore safely but we weren't so lucky. The seas just sank on us, I swear.\n\nOne second we're afloat and the next water is rushin' in. And those beasts! Killed all the survivors. Horrible naga scum. I went black and ended up here, saved.\n\nI want those beasts dead.", objectives = "" }
WordHunterWoW_QuestEN[26056] = { title = "The Wavespeaker", description = "One of the Earthen Ring, Wavespeaker Valoren, swam down into the Nightmare Depths to the northeast. We haven't heard from her in awhile.\n\nSwim out there and see if you can find her.", objectives = "" }
WordHunterWoW_QuestEN[26057] = { title = "The Wavespeaker", description = "One of the Earthen Ring, Wavespeaker Valoren, swam down into the Nightmare Depths to the northeast. We haven't heard from her in awhile.\n\nSwim out there and see if you can find her.", objectives = "" }
WordHunterWoW_QuestEN[26058] = { title = "In Defense of Krom'gar Fortress", description = "There's no time left. Here they come! Take control of a heavy gun and shoot the gnomes out of the sky! If that bomb takes too many hits it will blow, taking us all with it!\n\nDefend the base, {name}! You're our only hope!\n\nIf we somehow make it out of this in one piece, report to Overlord Krom'gar.", objectives = "" }
WordHunterWoW_QuestEN[26059] = { title = "Eyes and Ears: Malaka'jin", description = "Honor's Stand has been lost. The Horde's grip on the Barrens shattered along with the land itself. I now receive reports that we are at risk of losing Malaka'jin to a concerted attack by the Alliance and the Grimtotem. If Malaka'jin falls, half of Stonetalon falls with it!\n\nYou have proven yourself a capable soldier of the Horde. Will you be my eyes and ears at Malaka'jin? Witch Doctor Jin'Zil awaits your arrival.\n\nMalaka'jin is located far to the south.", objectives = "" }
WordHunterWoW_QuestEN[26060] = { title = "Da Voodoo: Stormer Heart", description = "With voodoo, our troops might have a chance at beating back the Grimtotem assault. With that said, I need several ingredients if I am to invoke black magic.\n\nThe first ingredient on my list is a heart from a cliff stormer. The beasts have nearly been hunted to extinction, but a few still exist around these parts. Find one and recover its beating heart!", objectives = "" }
WordHunterWoW_QuestEN[26061] = { title = "Da Voodoo: Ram Horns", description = "If I am to invoke voodoo, I will need several special reagents. Bring me horns from the Stonetalon rams of the region, {name}! Without the horns we are done for!", objectives = "" }
WordHunterWoW_QuestEN[26062] = { title = "Da Voodoo: Resonite Crystal", description = "The final ingredient for the voodoo ritual is a special type of crystal called resonite. It can only be found in the Boulderslide caverns, west of here. Beware the kobolds! They guard the resonite with their lives!", objectives = "" }
WordHunterWoW_QuestEN[26063] = { title = "The Queen and Her Court", description = "<Darn grunts.>\n\nHrmph.\n\nThings falling apart. Darn not happy. Now Darn's mate killed by spiders at Webwinder Hollow. Darn demands vengeance!\n\nHelp Darn? Kill Queen Silith and her little spiderlings? For Darn? For Darn's mate!\n\nWebwinder Hollow is northwest of here, up the path. Go!", objectives = "" }
WordHunterWoW_QuestEN[26064] = { title = "Fight On Their Stomachs", description = "The troops are hungry, {name}. With our supply lines cut off, we're steadily running out of food. I can cook the soldiers a feast if you can get me some ingredients.\n\nHead into the woods west of here and look for Kalimdor eagle nests. Steal the eggs from the nests and bring them back to me.", objectives = "" }
WordHunterWoW_QuestEN[26065] = { title = "Free Wil'hai", description = "Those tentacle horrors rising from the depths have trapped that poor beast. Please, {name}, can you save it by destroying those things?\n\nWill you free Wil'hai?\n\nHere, take my totem and plant it near the tentacles. The cold it emanates will cause major shrinkage on those monsters and then you'll be able to destroy them.", objectives = "" }
WordHunterWoW_QuestEN[26066] = { title = "Reinforcements...", description = "It would appear as if we are running out of big, stupid orcs to send at the enemy. This is a problem. Thankfully, I may have a solution.\n\nTake this whip and head west to Boulderslide Cavern. Within the cave you will find a filthy nest of kobolds. Use my whip to subdue the beasts. Once subdued they will do whatever we ask them to do.\n\nReturn to me when you have amassed a sizable army of kobolds.", objectives = "" }
WordHunterWoW_QuestEN[26067] = { title = "Jin'Zil's Blessing", description = "Ah, it is done! Now to test it out.\n\nTravel to the main point of conflict within Greatwood Vale and use my voodoo stick on the Krom'gar marauders battling the Grimtotem. My voodoo magic should renew their vigor and allow them to crush our enemies!\n\nGo now, {name}!", objectives = "" }
WordHunterWoW_QuestEN[26068] = { title = "Kobold Fury!", description = "We now command the kobold armies of Stonetalon! It almost sounds impressive. Almost.\n\n<Devo sighs.>\n\nThe Alliance base camp north of here is tightly guarded. It is nigh impregnable, save for the entry point by the Unearthed Grounds, northeast of here. Take this kobold war horn and head towards the Unearthed Grounds. Enter from the east, {name}! Once there, head west until you arrive at the location I have marked upon your map. Use the horn there to unleash kobold fury upon the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[26069] = { title = "Nura Pathfinder", description = "Southern Barrens is under attack by the Alliance. The tauren have sent out a call for help that we simply cannot ignore. All able bodied soldiers of the Horde should assist.\n\nIf you wish to help, take the path to the High Road, located in the village. Seek out Nura Pathfinder. ", objectives = "" }
WordHunterWoW_QuestEN[26070] = { title = "Clearing the Defiled", description = "Our Earthen Ring friends here are wondering if we can lend them a hand. There are faceless down below in the Scalding Chasm that are defiling all of the wildlife.\n\nCan you take care of that for me?", objectives = "" }
WordHunterWoW_QuestEN[26071] = { title = "Clearing the Defiled", description = "These Earthen Ring want us to do their killing for them. There are faceless down below in the Scalding Chasm that are defiling all of the wildlife.\n\nSwim down there and take care of it.", objectives = "" }
WordHunterWoW_QuestEN[26072] = { title = "Into the Totem", description = "You must take my totem down into the Scalding Chasm. Use it to capture the energies of the faceless as they die. The totem will keep them from returning from whence they came.\n\nWhen the totem is full, bring it back to me and we will use it to lure their leader up from deep down below.", objectives = "" }
WordHunterWoW_QuestEN[26073] = { title = "All's Quiet on the Southern Front", description = "Return now to Overlord Krom'gar, {name}. Inform him of our status and of what you have done to ensure that Malaka'jin does not fall.\n\nWe thank you for all that you have done. Perhaps some day soon you will have your own region to command.", objectives = "" }
WordHunterWoW_QuestEN[26074] = { title = "Beginning of the End", description = "Champion, we have acquired a new target. Our scouts in Battlescar Valley report that the night elves are preparing their own weapon of mass destruction and hiding it within an ancient tree. They will never be given the chance to use their weapon against us.\n\nYou are to escort the bomb to the Sludgewerks for refueling and then to Cliffwalker Post, from which we will detonate the bomb and kill all of our enemies.\n\nGo now, {name}. Report to Jibbly Rakit when you arrive at the Sludgewerks. ", objectives = "" }
WordHunterWoW_QuestEN[26075] = { title = "The Turd Problem", description = "We have a little problem...\n\n<Jibbly points to the large turds covering the base.>\n\nWe built the Sludgewerks near a wyvern habitat. Now our initial blueprints for the Sludgewerks were drawn up so as not to disturb the wyvern habitat as the beasts are apparently sacred to tauren and orcs. Do you know what's sacred to me? Not getting pooped on, that's what!\n\nBetween you, me and the wall, the wyvern must die!", objectives = "" }
WordHunterWoW_QuestEN[26076] = { title = "Spy Infestation", description = "We've got another problem, {name}. Alliance spies are all over the place! You haven't seen any? That's because they're invisible! Cloaked! I have a solution, but I need muscle like you to go out there and follow through with my plan.\n\nUse this gas bomb on the cloaked spies and it will reveal them. Once revealed, send them back to their maker.\n\nYou'll know a cloaked spy by the effect they leave in the air. Look closely!", objectives = "" }
WordHunterWoW_QuestEN[26077] = { title = "Final Delivery", description = "Overlord Krom'gar sends word from the base. You are to get back on the Krom'gar hot air balloon and take it to Cliffwalker Post. From there, the plan is to unleash the payload on the Alliance at Battlescar Valley.\n\nYou better get going, {name}. It's not wise to keep Krom'gar waiting.\n\nSpeak to General Grebo when you arrive at your destination. He'll be able to brief you on the next course of action.", objectives = "" }
WordHunterWoW_QuestEN[26078] = { title = "Extinguish the Fires", description = "The Dark Iron attack took us by surprise. Their saboteurs managed to damage most of our aircraft, steam tanks, and supplies. We were only able to get a few of our bombers airborne.\n\nEvery technician, recruit, and guard I can spare is  scrambling to get the others repaired and flight-ready. Our infantry can only hold out for so long. Take this equipment and help extinguish the burning bombers.", objectives = "" }
WordHunterWoW_QuestEN[26079] = { title = "Wanted!  Otto and Falconcrest", description = "The Stromgarde Militia has placed bounties on the heads of Lord Falconcrest, and his bodyguard Otto.  Falconcrest heads the Syndicate's efforts in the Arathi Highlands, and his death would cause a major disruption in those efforts.\n\nHis bodyguard Otto, although not a strategic target, is a fierce opponent and has killed dozens of our defenders.\n\nTheir bounties may be collected from Captain Nials.", objectives = "" }
WordHunterWoW_QuestEN[26080] = { title = "One Last Favor", description = "{name}, I'm gonna need ya to bring this back to Captain Glovaal.  With my condition, it'll take me a week to get back to Darkbreak Cove, and we don't have any time to waste.", objectives = "" }
WordHunterWoW_QuestEN[26081] = { title = "Alina's Reward", description = "The tale of Trol'kalar ends here, then. It will be a weapon to bring death to the living, in the name of the Dark Lady.\n\nLeave me now, {name}. My job is once again to guard the blade. Tell Alina of your victory, I'm sure she will have a reward for you.", objectives = "" }
WordHunterWoW_QuestEN[26082] = { title = "To Battlescar!", description = "I will allow this old fool time to plead his case. He has assured me that he will bring back proof that the night elves do not harbor a weapon of mass destruction. We shall see.\n\nWhile we await this proof, you will assist our army in the valley. We have prepared a large number of siege tanks for this purpose. Our demolishers are poised for attack.\n\nTake the elevator down to the base of the outpost and take control of a Krom'gar demolisher. Use it to lay waste to our enemies in Battlescar Valley.", objectives = "" }
WordHunterWoW_QuestEN[26083] = { title = "Hello Lolo", description = "Goutgut get sent scouting. Look at many things. Big adventure!\n\nGoutgut found secret pirate ship. Pirates all scared, run away. But ogre Lolo not run. Lolo make friend with Goutgut!\n\nGoutgut have to leave, but miss Lolo. You go say hello to Lolo for Goutgut.", objectives = "" }
WordHunterWoW_QuestEN[26084] = { title = "Hammerfall", description = "You have served us well here, {name}. Now that we've made our mark, the next phase of our conquest will occur over months rather than minutes.\n\nThere is much work yet to be done, and I will spare you the tedium of waiting for our fortifications to trickle in. Travel to the east, to Hammerfall. The orcs there will no doubt have use of your aid.", objectives = "" }
WordHunterWoW_QuestEN[26085] = { title = "Rallying the Defenders", description = "While our engineers work on getting the bombers ready to fly again, our guards and mountaineers continue to fight the invaders.\n\nThey've been out there since the incursion began, without so much as a chance to catch some sleep or have a meal. Ironforge's defenders are among the best on Azeroth, but even they have limits.\n\nTake these banners and plant them in banks of loose snow. Remind the men what they are fighting for and help keep their morale high.", objectives = "" }
WordHunterWoW_QuestEN[26086] = { title = "Orako", description = "<Captain Verne looks down at his watch.>\n\nWhere is that hunter?  I sent Orako to Underlight Canyon to prepare a recon report a week ago!  Sure, he's a handful, and I didn't mind getting him out of my hair, but I need his report.\n\nSay, what's your name?  {name}?  Would you be willing to go track him down?  It seems strange to send a {class} to find a hunter, but I'm running out of options.", objectives = "" }
WordHunterWoW_QuestEN[26087] = { title = "\"Glow-Juice\"", description = "Shooting fish in a barrel is easy.  Shooting fish in an ocean is a little harder.\n\nHave you seen the murlocs down in the canyon, {class}?  They don't shoot at all!  They have little balls full of glow-juice on their heads that make the fish come to THEM.  Hey, we should try that!\n\nGo south, and kill the crabs and groupers in the canyon.  They have lots of glow-juice in their skin.  I've seen it!", objectives = "" }
WordHunterWoW_QuestEN[26088] = { title = "Here Fishie Fishie", description = "<Orako rolls the glow-juice into a ball, then attaches it to a device that he's clearly been working on for a long time.>\n\nHere, I got you this hat.  It has a light on it, and it will make fish follow you.  Just like the murlocs!\n\nThe murlocs like to hunt in the kelp and coral along the sides of the canyon.  If you put on this hat and swim in that kelp, you might catch some fish like they do.", objectives = "" }
WordHunterWoW_QuestEN[26089] = { title = "Die Fishman Die", description = "A fish ate my wolf, and murlocs look like fish.  I'm going to make those murlocs pay!\n\nHead back down to the canyon and kill the fishmen!  My wolf will be avenged!", objectives = "" }
WordHunterWoW_QuestEN[26090] = { title = "I Brought You This Egg", description = "<This appears to be an egg from one of the devious great-eels that float up above the canyon.  You wonder whether or not Orako might be interested in something like this.>", objectives = "" }
WordHunterWoW_QuestEN[26091] = { title = "Here Fishie Fishie 2: Eel-Egg-Trick Boogaloo", description = "<Orako removes an explosive trap from his sack and shoves it through the egg's outer membrane.>\n\nThis will make the egg explode.  Place the egg down next to one of those giant eels, and wait for them to come close.  When the egg explodes, the big fish will be almost dead, and you can finish killing it.\n\nSave my wolf!  With this egg, you can do it.", objectives = "" }
WordHunterWoW_QuestEN[26092] = { title = "Orako's Report", description = "<You remind Orako that he was supposed to send a report back to Captain Verne.>\n\nRight, a report.  All that I've seen here is fish.  Lots and lots of fish.\n\n<Orako looks over at the sack of fish that you brought for him.>\n\nBring this back to the captain.  This is my report.", objectives = "" }
WordHunterWoW_QuestEN[26093] = { title = "Northfold Manor", description = "We are fighting a war for Stromgarde, and we are losing.  The ogres, the Syndicate and we have divided our once great city, and each faction battles the other into a bloody stalemate.\n\nBut our forces dwindle while our enemy grows.\n\nThough Southshore has fallen, we must not let any further ground be yielded to our enemies.\n\nGo to the Syndicate base in Northfold Manor and slay them. We must reclaim the land for ourselves before the Horde has a chance to creep further.", objectives = "" }
WordHunterWoW_QuestEN[26094] = { title = "Striking Back", description = "My chief engineer tells me that he's managed to get one of the bombers repaired and airworthy. Take these bombs with you, and look for the repaired bomber at the start of the runway.\n\nOnce you're airborne, use the bombs to do as much damage to the attacking Dark Iron dwarves as you can. I've heard rumors that they're preparing to deploy a new kind of war golem. Keep your eyes peeled for those golems and make them your highest priority targets.", objectives = "" }
WordHunterWoW_QuestEN[26095] = { title = "Stromgarde Badges", description = "The Syndicate in Stromgarde do battle with our contingent of militia there. In order to urge the rabble to fight our more disciplined troops, the Syndicate leaders have placed a bounty on our soldiers, awarding gold for each Stromgarde Badge gathered off killed militiamen.\n\nWe want those badges retrieved - we cannot allow the cutthroats to take trophies from our brave fallen!\n\nEnter the Syndicate-controlled area of Stromgarde and hunt them for our badges.", objectives = "" }
WordHunterWoW_QuestEN[26096] = { title = "Scalding Shrooms", description = "We think that we have a use for the merciless ones that your friend from the cave delivered to us. But I need a preservative for it.\n\nDown below in the Scalding Chasm are some mushrooms with the properties that I need. Bring some back up to me and I'll see what I can do.", objectives = "" }
WordHunterWoW_QuestEN[26097] = { title = "Proof of Lies", description = "At the heart of Battlescar Valley stands an ancient tree - a tree that has withstood the force of ages and has served as a place of peace and learning for generations. My kin have studied druidism at the grove, alongside the night elves, for as long as I can recall. Now I am to believe that the tree holds within it an Alliance weapon of mass destruction?\n\nKrom'gar is wrong and I will prove it!\n\nI have sent my son, Orthus, to Thal'darah Grove in search of this weapon. Go there now and meet him.", objectives = "" }
WordHunterWoW_QuestEN[26098] = { title = "Betrayal at the Grove", description = "Druid corpses litter the room. Something seems amiss, as you see no signs of a struggle.  Bloody drag marks lead in from the doorway.\n\nYou pry Orthus' death grip open to find something disturbing in his hand: a Krom'gar General's insignia.\n\nTake the Krom'gar General's insignia back to High Chieftain Cliffwalker.", objectives = "" }
WordHunterWoW_QuestEN[26099] = { title = "Is This Justice?", description = "He was a good boy, {name}. Young, loving. He would have never killed any of the young druids. They were his friends! No... Not Orthus.\n\nThe General must be called to answer for this crime. I will have justice!", objectives = "" }
WordHunterWoW_QuestEN[26100] = { title = "The General is Dead", description = "Perhaps if you spoke to Overlord Krom'gar, {name}. Maybe he would listen to what you had to say? You are a Champion in his army, after all. You saw everything. Please help us, {name}. We simply wish to be left alone - in peace.\n\nTalk to Overlord Krom'gar and try to help him see that we did not mean for any of this to happen.", objectives = "" }
WordHunterWoW_QuestEN[26101] = { title = "Might Makes Right", description = "You have done well to report this crime. The perpetrators of this heinous act will be punished. There will be blood.\n\nI will need a new General now that Grebo is dead. You shall take his place.\n\nMeet me at Cliffwalker Post, General. Together we will end this nonsense.", objectives = "" }
WordHunterWoW_QuestEN[26102] = { title = "Grimaxe's Demise", description = "With you leading the way, we've finally broken the momentum of the Dark Iron attack. General Grimaxe, the Dark Iron leader, is attempting to rally his troops from the center of their lines on the frozen lake to the south.\n\nHe stands atop one of their new dark iron golems, shouting orders to his men. If he succeeds in rallying them, they may still be able to overpower us. You must prevent that, {name}. Destroy the golem guarding him, then kill General Grimaxe himself. He is the key to our victory.", objectives = "" }
WordHunterWoW_QuestEN[26103] = { title = "Bio-Fuel", description = "Submarine fuel is expensive!\n\nThe powers-that-be in Gnomeregan were generous enough to deliver several fuel barrels, but we're burning through it faster than expected.  That means we're going to need to improvise.\n\nIt's a well-known fact that sea creatures are full of all kinds of interesting chemicals... like oil.  Take this device up to Kothrun's End and stick it into the corpses of terrapins, remoras, and hammerhead sharks.  If we don't get more submarine fuel, their oil might be our only hope.", objectives = "" }
WordHunterWoW_QuestEN[26105] = { title = "Claim Korthun's End", description = "The Horde has spies in this area?  Darkbreak Cove is nearby, and inside lies the Pincer X2!  The Horde must not be allowed anywhere nearby!\n\nSomeone in Darkbreak Cove will want to hear of this... after you finish slaying some more of these dirty Horde spies.", objectives = "" }
WordHunterWoW_QuestEN[26106] = { title = "Fuel-ology 101", description = "How much do you know about fuel, {name}?  Constructing the perfect fuel is a tricky job, as there's plenty of factors to balance: chrono-pyroxidation parameters, tempero-incendiary variables, conflagrational siltification criteria... and that's only naming a few.\n\nHopefully the samples you brought me can be combined in the right proportions to create... the perfect bio-fuel.  Use that table over there and try combining some samples!  Bring the result to me when you're done.", objectives = "" }
WordHunterWoW_QuestEN[26107] = { title = "Raising Spirits", description = "Our race's gift of shamanism stirred me from a years-long lethargy. Now I provide for all here, crafting the same boons that gave me newfound strength.\n\nThe Highland raptors are cunning and fierce beasts. Their spirits can grant our warriors great strength. Bring me raptor eyes, so I may make the amulets as Tor'gan taught me.", objectives = "" }
WordHunterWoW_QuestEN[26108] = { title = "Guile of the Raptor", description = "The highland fleshstalkers to the south are even fiercer than the others of their kind. They possess not just strength, but true cunning.\n\nWhen I was trapped by lethargy, even the amulets of strength failed to move me. But Tor'gan used the hearts of the fleshstalkers to imbue me with spirits that conquered my doubt, freeing me.\n\nOur soldiers deserve the guile of the raptor. Collect the fleshstalker hearts for me, {name}.", objectives = "" }
WordHunterWoW_QuestEN[26110] = { title = "Just Like Old Times", description = "It's funny. Kin and I have been through so much together, and here we find ourselves back in Arathi, like so many years ago.\n\nWe broke up a plot to create a new plague right here, her and I. It doesn't look like the Horde learned their lesson, because they're all over this farm yet again.\n\nTheir undead courier is shuffling around as obvious as daylight. If you want to help, find the courier and bring back whatever they're carrying.", objectives = "" }
WordHunterWoW_QuestEN[26111] = { title = "... It Will Come", description = "I now imbue you with the energies of the corrupting faceless.\n\nSwim down to my luring totem in the trench to the northeast. Release the energies through it. Bring back the brain of their leader.\n\nCall forth to Ick'thys the Unfathomable... it will come!", objectives = "" }
WordHunterWoW_QuestEN[26112] = { title = "Demanding Answers", description = "So just how did all those Dark Iron warriors end up here, on the doorstep of Ironforge, on the verge of invading our city?\n\nDoes not 'Empress' Moira, a member of our esteemed Council of Three Hammers, rule the Dark Iron? This cannot have happened without her knowledge and consent. This was no ragtag band of rebel dwarves, but a well-organized and fully equipped invasion force.\n\nI have prepared a report on the battle for the airfield. Take it to Ironforge, to the High Seat and confront her!", objectives = "" }
WordHunterWoW_QuestEN[26113] = { title = "Quae and Kinelory", description = "The Horde have held Go'shek Farm to the east for a long time; it's never been of much concern compared to the rest of our problems here. But there's been reports of undead activity in the area.\n\nAnything more alarming than shuffling peons over there warrants investigation. This isn't the first time the undead have been up to no good at the farm, so I've sent my best scouts there to check it out. Report to Quae and Kinelory and they'll fill you in.", objectives = "" }
WordHunterWoW_QuestEN[26114] = { title = "Quae Trusts You", description = "<Quae begins to go through the folder.>\n\nExpansion...control of territory... these undead aren't cooking up anything new, but they're planning to roll over all of Arathi. We need to disrupt their plans.\n\nI'll keep a lookout from up here. You go with Kin, and get those invasion plans. We're not going to let these walking corpses even know what day it is out here.\n\nAnd keep her safe, you hear me?", objectives = "" }
WordHunterWoW_QuestEN[26115] = { title = "To Be Horde...", description = "Stand by me, {name}, and watch as our mighty weapon destroys our enemies!\n\nLearn what it means to be Horde!", objectives = "" }
WordHunterWoW_QuestEN[26116] = { title = "Kinelory Strikes", description = "All right, {name}. I'm ready if you are.\n\nShall we?", objectives = "" }
WordHunterWoW_QuestEN[26117] = { title = "For Southshore", description = "I've seen Kinelory look way worse after a night in the tavern than she does now. You obviously did a good job protecting her.\n\nRefuge Pointe will want to know of our success. I'm going to stay here with Kin and let her catch her breath. Go on ahead without us.", objectives = "" }
WordHunterWoW_QuestEN[26118] = { title = "Seize the Ambassador", description = "The ambassador's betrayal will long haunt me. You must arrest him before he can do further harm, or worse, before he can escape and start planning the next attack. Ironforge is not safe with Ambassador Slaghammer free inside the city.\n\nTake these manacles and go to the Dark Iron embassy. It's just to the north of the High Seat, around the rim of the Great Forge. Arrest Ambassador Slaghammer and return with him.", objectives = "" }
WordHunterWoW_QuestEN[26120] = { title = "The Crazed Dragonmaw", description = "The Dragonmaw orcs nearby are fast becoming a nuisance. Their suicidal attacks on the grove are merely annoying, though they provide my sentinels with some needed practice.\n\nMy scouts, however, have seen them rounding up black dragon whelps in nets. The last thing these lands need is a crude revival of dragon-taming. Strike out to the east, {class}, and cut down the whelpstealers; make sure their folly does not come back to haunt us later.", objectives = "" }
WordHunterWoW_QuestEN[26121] = { title = "Claim Korthun's End", description = "You are seeink spies up above?  This is not good... not good at all, comrade.\n\nReturn to Korthun's End and destroy them, my friend.", objectives = "" }
WordHunterWoW_QuestEN[26122] = { title = "Environmental Awareness", description = "Have you ever smelled submarine fuel, {name}?  It's nasty stuff.  Unfortunately, we need to burn huge amounts of it to get the Verne to move, and it's both bad-smelling AND deadly to the local wildlife.  We need to be more environmentally conscious.\n\nThe sea creatures nearby have particularly oily flesh.  Take this device up to Seabrush - just above this cave - and use it on the corpses of terrapins, remoras, and hammerhead sharks.  Their oil might save the lives of hundreds of other sea creatures.", objectives = "" }
WordHunterWoW_QuestEN[26124] = { title = "Secure Seabrush", description = "The Alliance has spies in this area?  Tenebrous Cavern is nearby, and inside lies the Horde's new submarine, the Verne!  The Alliance must not be allowed anywhere nearby!\n\nSomeone in the cavern will want to hear of this incursion... after you finish slaying some more of these scheming Alliance spies.", objectives = "" }
WordHunterWoW_QuestEN[26125] = { title = "Secure Seabrush", description = "You saw spies up above?  This is not good... I won't have it.\n\nReturn to Seabrush and get rid of them before they start trickling into our hideout.", objectives = "" }
WordHunterWoW_QuestEN[26126] = { title = "The Perfect Fuel", description = "How much do you know about fuel, {name}?  Constructing the perfect fuel is a tricky job, as there's plenty of factors to balance: chrono-pyroxidation parameters, tempero-incendiary variables, conflagrational siltification criteria... and that's only naming a few.\n\nHopefully the samples you brought me can be combined in the right proportions to create... the perfect bio-fuel.  Use that table over there and try combining some samples!  Bring the result to me when you're done.", objectives = "" }
WordHunterWoW_QuestEN[26127] = { title = "The Twilight's Hammer Revealed", description = "I and everyone else thought these fools were just Dark Iron up to no good, but these nutters are fullblown cultists!\n\nThe Twilight's Hammer wants nothing short of the destruction of the entire world. They've thrown their lot in with Deathwing and Ragnaros, and they've got a history with the Dark Iron.\n\nBut it doesn't matter who they are, what matters is they're in Dun Modr and they need to get out! I'll not let any past here. You get in there and crack some skulls!", objectives = "" }
WordHunterWoW_QuestEN[26128] = { title = "The Battle of Thandol Span", description = "I've defended the Thandol Span from being destroyed before, against the Dark Iron themselves. And so did my father, and his father before him...\n\nThe only Dark Iron that managed to give me the slip ran straight for the bridge. Something's amiss, and I'm betting when we get there we'll be waltzing right into an ugly trap.\n\nI could use your help, {name}, for Ironforge. Are you with me?", objectives = "" }
WordHunterWoW_QuestEN[26129] = { title = "Brothers In Arms", description = "Listen, {name}.  For the first time since the civil war I agree with Greymane.  Now is the time to put aside our quarrel.\n\nIt sure doesn't look like these beasts care much whether you're a rebel or a royal.\n\nSend word back to Greymane.  My men will join his.\n\nThere's a safehouse not far from here, in Josiah's cellar.  My lads stashed some heavy artillery there.\n\nTell our king that my arsenals are now at his disposal.", objectives = "" }
WordHunterWoW_QuestEN[26130] = { title = "Unplug L'ghorek", description = "L'ghorek is the ancient that rests upon the shelf across from us. It is being controlled and its life energies slowly consumed by something immense beneath us.\n\nThere is a cave known as the Undershell down below L'ghorek. In that cave are three powerful ogre magi that are maintaining a ritual connecting the thing below with the ancient. You must kill these three to disconnect L'ghorek.", objectives = "" }
WordHunterWoW_QuestEN[26131] = { title = "Reinforcements for Loch Modan", description = "I've been waiting for the council to hear my plea for hours, and it's not looking good. Moira's greatest desire seems to be to paralyze the council.\n\nMeanwhile, Loch Modan suffers. Our enemies are many and our resources are few. Please, {name}, perhaps you will hear me if the council will not. Speak to Gryth Thurden, Ironforge's gryphon master. He's in the eastern part of the Great Forge. He'll provide a free flight to the South Gate Pass. Introduce yourself to Pilot Hammerfoot once you arrive.", objectives = "" }
WordHunterWoW_QuestEN[26132] = { title = "Fiends from the Netherworld", description = "The ogre magi within the Undershell have summoned protectors for themselves: fleshling fiends from the netherworld.\n\nWe cannot risk these aberrations from being later used against our forces. While you are in there, I want you to destroy as many of those things as you can.", objectives = "" }
WordHunterWoW_QuestEN[26133] = { title = "Fiends from the Netherworld", description = "Those ogre magi inside the Undershell have summoned defenders: fleshling fiends from the netherworld.\n\nI do not want to see these aberrations used against our forces. While you are in there, destroy all of them!", objectives = "" }
WordHunterWoW_QuestEN[26134] = { title = "Nothing Left for You Here", description = "There is nothing left for you here, {name}. As for me, I must lay Masha's body to rest. Once I have done that I will go to the bombing site and begin the process of regrowth. Perhaps one day a new grove will bloom - a grove infused with the spirit of my child and the fallen night elf youths.\n\nIf you wish to travel to Desolace, I hear word of a blood elf named Furien seeking adventuring partners. Perhaps you should seek him out.\n\nFarewell, friend, I will never forget you.", objectives = "" }
WordHunterWoW_QuestEN[26135] = { title = "Visions of the Past: Rise from the Deep", description = "What you told me of the naga before has been plaguing my mind. Who are these allies they're summoning? Do they really think they can defeat the Tidehunter?\n\nEscaping this cave brings a degree of relief, but our purpose here remains. I'm hoping you will be willing to seek answers from the Battlemaiden one last time.\n\nThere's only one place that I can think of where they would have taken the artifact - the temple atop the ruins. It's sure to be well guarded. Proceed carefully.", objectives = "" }
WordHunterWoW_QuestEN[26137] = { title = "Checking on the Boys", description = "I'm sure you've seen just how bad the damage to the Loch is by now. The damage spreads further than that, I'm afraid; all that water had to go somewhere, and it went down into the Wetlands.\n\nThere's a lot of fine dwarves down there trying to help out, and they need supplies. That's why I sent two of my mountaineers ahead with a cask of ale along the path into the Wetlands.\n\nI haven't heard back from them since they set off down the road to Dun Algaz. Would you mind checking up on them?", objectives = "" }
WordHunterWoW_QuestEN[26139] = { title = "Into Arathi", description = "You should go on ahead and warn the other side of the span about this, {name}.\n\nOver the bridge to the north you'll find Refuge Pointe, the stronghold of the Alliance in Arathi. Tell Captain Nials to keep an eye out for these Twilight's Hammer curs.", objectives = "" }
WordHunterWoW_QuestEN[26140] = { title = "Communing with the Ancient", description = "Place the dead merciless one upon your head to pose as one of their slaves.\n\nEnter L'ghorek. Commune with the ancient.", objectives = "" }
WordHunterWoW_QuestEN[26141] = { title = "Runestones of Binding", description = "ON THE OTHER... SIDE OF... MY CHAMBER THERE... ARE... CANDIDATES FOR ASCENSION.\n\nWE WILL NEED... THEIR... RUNESTONES OF BINDING... TO CREATE A... MEANS OF CONTROLLING... A BOUND ELEMENTAL.", objectives = "" }
WordHunterWoW_QuestEN[26142] = { title = "Ascend No More!", description = "TO STOP... THEIR... RITUALS OF ASCENSION... YOU MUST DESTROY... THE ANCIENT CONDUITS.\n\nTHEY USE... THE CONDUITS TO... SIPHON... MY ENERGIES AWAY... AND MAKE... ASCENDANTS.\n\nA FIGHT WITH... NEPTULON IS IMMINENT. THE TWILIGHT'S HAMMER... MUST BE DENIED... THESE CREATURES.", objectives = "" }
WordHunterWoW_QuestEN[26143] = { title = "All that Rises", description = "<The voice of the ancient presses against your mind.>\n\nNOW THAT... YOU HAVE STOLEN... THE ENERGIES OF... THE FAITHFUL, ENTER... THE TEMPLE AND... DESTROY... HALLAZEAL THE ASCENDED!", objectives = "" }
WordHunterWoW_QuestEN[26144] = { title = "Prisoners", description = "The Twilight cultist dropped this key. Use it to free the Alliance prisoners in the cages inside of L'ghorek.\n\nHurry before the prisoners become sacrifices to whatever lurks below!", objectives = "" }
WordHunterWoW_QuestEN[26145] = { title = "The Trogg Threat", description = "{class}, you may or may not be aware of the trogg threat looming over dwarven lands.  With the Ironforge Reserve called up to the Alliance Front, we're left with a fraction of the defense forces needed to keep these lands safe.  My regiment is assigned to watch over the town here and we cannot leave our post for fear of invasion.\n\nBut we need some pressure put on those damned troggs lurking in the hills.  If you're up to the task, wage an assault on the troggs.  Bring me back eight trogg stone teeth as proof.", objectives = "" }
WordHunterWoW_QuestEN[26146] = { title = "In Defense of the King's Lands", description = "We need to protect the Loch, {name}! With so many of the King's soldiers fighting valiantly on remote battlefields, we've become overwhelmed on the home front. Troggs are tunneling up from every crevice! The trogg infestation poses the largest threat to Ironforge.\n\nWe need you, brave adventurer, to venture forth and lay waste to the trogg threat. Slay twelve Stonesplinter troggs and venture back.", objectives = "" }
WordHunterWoW_QuestEN[26147] = { title = "Bigger and Uglier", description = "The Mountaineers tell me you are quite brave and capable, {name}.  We need a {race} like you around here.  The Trogg problem isn't getting any better.  The reserves have been called to the front and we're all alone out here.  But now that we have a seasoned {class} here, let's see what you can do.\n\nGo out and kill 8 Stonesplinter Shaman and 8 Stonesplinter Bonesnappers. You should find them in and around the caves in the southern mountains.\n\nLet's see if you live up to your reputation, Trogg-Slayer.", objectives = "" }
WordHunterWoW_QuestEN[26148] = { title = "A Decisive Strike", description = "It appears that these beasts in Loch Modan are following the lead of a chieftain named Grawmug. He's the biggest of all the troggs here, lurking deep within the darkness of the caves to the north.\n\nIf you feel yourself worthy, {name}, I want you to lead the assassination mission on Grawmug.", objectives = "" }
WordHunterWoW_QuestEN[26149] = { title = "Prisoners", description = "The Twilight cultist dropped this key. Use it to free the Horde prisoners in the cages inside of L'ghorek.\n\nHurry before the prisoners become sacrifices to whatever lurks below!", objectives = "" }
WordHunterWoW_QuestEN[26150] = { title = "A Visit With Maybell", description = "You seem like the helpful type, {name}. How about doing an old man a favor?\n\nThe last time I was over at the Maclure Vineyards I overheard Maybell crying in her cottage. Would you be so kind as to go check up on her? I'm a little worried.", objectives = "" }
WordHunterWoW_QuestEN[26152] = { title = "WANTED: James Clark", description = "By decree of the Stormwind Army, a bounty has been placed on the head of James Clark.\n\nClark is wanted for robbery, burglary, arson, and murder. He is also a suspect in the kidnapping and disappearance of the Brackwell's prized pig, Princess.\n\nJames Clark was last seen heading towards Eastvale Logging Camp.\n\nBring James Clark to justice and report to Marshal Patterson at Eastvale Logging Camp.", objectives = "" }
WordHunterWoW_QuestEN[26153] = { title = "Penny's Pumpkin Pancakes", description = "My daughter Penny loves pumpkin pancakes but we have had a shortage of pumpkins here in Elwynn from the frostbite last season.  I have heard of a new pumpkin patch north of Stormwind that might be ripe for the picking now though.  Head out and harvest a few of those ripe pumpkins for me and let's see what we can do.", objectives = "" }
WordHunterWoW_QuestEN[26154] = { title = "Twilight Extermination", description = "NOW, TAKE... THE ATTUNED RUNESTONE... AND USE... IT TO POSSESS... ONE OF... THE BOUND TORRENTS... AT... THE CENTRAL TEMPLE. THEY WILL IGNORE... YOU. YOU ARE BENEATH... THEIR NOTICE.\n\nUSE... THE ELEMENTAL'S POWERS... TO DESTROY... THE TWILIGHT DEVOTEES... AND... THEIR... FACELESS OVERSEERS.", objectives = "" }
WordHunterWoW_QuestEN[26157] = { title = "Kasim Sharim", description = "I need you to pass on a message for me.\n\nKasim Sharim is an old blood mage that knows a great deal about the demons of the Blasted Lands.  Though you wouldn't know from looking at him, he's quite old, and very powerful... if a little eccentric.  As of late, he spends his days in the back of the Serpent's Coil, a cave not far from where you killed those cultists.\n\nPlease, deliver this message to him.  He will know what it means.", objectives = "" }
WordHunterWoW_QuestEN[26158] = { title = "Attune the Bloodstone", description = "Did you have fun fighting your way to the back of this cave?  I admit, I haven't picked the most... convenient of spots to perform my studies, especially for passing adventurers who wish to enter and leave at will.\n\nHowever, I can allow you to attune yourself to my bloodstone teleporters.  Simply place your hands on the stone in the back corner, and you will be teleported outside of the cave.  Then use the stone outside to teleport back!", objectives = "" }
WordHunterWoW_QuestEN[26159] = { title = "The First Step", description = "Like any good bloodmage, I perform my magic with blood.  All blood is different, and the Blasted Lands has several useful flavors, if you know where to look.\n\nFor our purposes?  Basilisks and hyenas, even amounts.  We're going to need plenty of it.  Head west, to the center of the Blasted Lands.  And don't forget... you can use that teleporter!", objectives = "" }
WordHunterWoW_QuestEN[26160] = { title = "Blood Ritual", description = "I suppose you want to know what we're doing.  Here's the short version - a version at which I happen to be an expert:\n\nThe Shadowsworn cultists wish to summon the demon, Razelikh, back to the Blasted Lands.  We cannot allow this to happen.  So we're going to summon him ourselves, and then kill him.  A task not as simple as it sounds...\n\nLet me know when you are ready to begin the blood ritual, and then stand back.", objectives = "" }
WordHunterWoW_QuestEN[26161] = { title = "Not Just Any Body", description = "We need Loramus Thalipedes, the demon hunter.  He knows Razelikh's true name, and as you know: if you know the name of the demon, you have power over it.  The problem is that Loramus has been killed, and his body torn apart.\n\nIf you bring me the pieces, we still have a recourse.  All three pieces are in the west... the Dreadmaul ogres hide them in their caves.  Move quickly, for much like Grimeo, Loramus also owes me a debt...", objectives = "" }
WordHunterWoW_QuestEN[26162] = { title = "The Altar of Storms", description = "Up on the bluffs to the west lies a powerful altar.  A powerful DEMONIC altar, guarded by cultists, but powerful nonetheless.  If you can reach it, you can use it to bring Loramus back to us.\n\nThe altar will likely resist your efforts, so you'll have to protect Loramus' body while the ritual completes.  Bring the demon hunter back to me afterwards.", objectives = "" }
WordHunterWoW_QuestEN[26163] = { title = "Time is Short", description = "Razelikh plans to return to the Blasted Lands and overwhelm Azeroth with his demons.  Even now, he is preparing to summon his legions to eliminate us.  With these three amulets, we have the method to summon him... but no way to destroy him.\n\n<The gnome quickly draws a rune in the air, then hands it to you.>\n\nDeliver this to Grimeo at the Dark Portal, to the southeast.  He will guide you.  Quickly!  Time is short!  And so am I!", objectives = "" }
WordHunterWoW_QuestEN[26164] = { title = "The Charred Granite of the Dark Portal", description = "Kasim wants you to gather granite chips from these chunks of rock around the Dark Portal.  I don't know what he'd want rocks for, but I have my suspicions, and they're not pleasant ones.\n\nUse this pick and look for small outcroppings of rock along the edge of the portal's blast radius.", objectives = "" }
WordHunterWoW_QuestEN[26165] = { title = "The Vile Blood of Demons", description = "Sharim wants demon blood.  Speaking personally, the stuff does not even seem like blood to me - more like liquid rot - but that is of no consequence.\n\nLuckily for you, the area around the Dark Portal is crawling with demons.  Infernals, felhounds, felguards... they've all got what you need, in copious, pustulent amounts.", objectives = "" }
WordHunterWoW_QuestEN[26166] = { title = "Enhancing the Stone", description = "<Grimeo finishes packing the materials up in a neatly-wrapped package.>\n\nThat's all that the gnome asked of us.  When you see him, make sure you let him know that this task ends my debt.  I will not suffer his requests any longer.", objectives = "" }
WordHunterWoW_QuestEN[26167] = { title = "The Amulet of Allistarj", description = "To summon our demon, we need three amulets, and the first is the Amulet of Allistarj.\n\nAllistarj himself is dead, but he locked his amulet up in a trove inside this very cave.  Along with the other amulets, this relic will give us access to Razelikh's perch.\n\n<Kasim concentrates for a moment.>\n\nThe amulet is close to the entrance.  I recommend using the teleporter.", objectives = "" }
WordHunterWoW_QuestEN[26168] = { title = "The Amulet of Sevine", description = "The second amulet, Sevine's amulet, is in the hands of a murloc, far to the south, on a shelf that overlooks the Shattershore.  How it ended up in that murloc's possession, I cannot say, but I can state with certainty that you will find it there.\n\nBring her amulet to me, along with the rest.", objectives = "" }
WordHunterWoW_QuestEN[26169] = { title = "The Amulet of Grol", description = "Grol... the ogre.\n\n<Kasim laughs.>\n\nIt would seem that Grol's body no longer rests with the ogres.  His body, along with his amulet of power, is in a wrecked ship off the Shattershore, to the east.  His amulet is the last... once combined, the three will give us access to Razelikh, and therein lies our chance to stop his madness.", objectives = "" }
WordHunterWoW_QuestEN[26170] = { title = "The Final Ritual", description = "The knife is ready.  Loramus is present, and he knows what he must do.  I must now take the three amulets and use their enchantment to grant you access to Razelikh, the amulets' creator.\n\nI am prepared to perform the ritual on you and Loramus.  Speak with me when you are both ready.", objectives = "" }
WordHunterWoW_QuestEN[26171] = { title = "You Are Rakh'likh, Demon", description = "Hero, listen well.\n\nFirst, we must travel to the Deathly Usher, who waits at the northern foot of the Rise of the Defiler, to our northwest.  The usher will take us to the top of the rise.  Once there, you will help me defeat Razelikh, for I fear I am not strong enough to defeat him alone.\n\nMost importantly, I need you to hold the stone knife, and do not use it until I tell you to.  The knife will trap Razelikh's soul within its new, eternal prison.\n\nIf we succeed, speak with Grimeo, the draenei.", objectives = "" }
WordHunterWoW_QuestEN[26172] = { title = "A Bloodmage's Gotta Eat Too", description = "Contrary to popular belief, ancient and powerful bloodmages do NOT drink blood.  We eat normal food like everybody else - something which can be hard to come by in the recesses of a hostile cultist stronghold.\n\nThe ashmane boars in the central valley of the Blasted Lands are, if nothing else, convenient for eating, as their meat does not require any cooking.  Would you hunt these boars and help me replenish my ever-dwindling foodstores?", objectives = "" }
WordHunterWoW_QuestEN[26173] = { title = "Protecting Our Rear", description = "The only reason you see me standing aside Horde soldiers is because our duty outweighs our enmity... however slightly.  We have been charged with protecting the Dark Portal from unauthorized travel, and with the recent cataclysm, we are particularly susceptible to an attack.  We've already heard reports of black dragons in the area...\n\nWith my men focused on their duty, we need someone to keep the area demons in check.  Around the portal you will find three demon lieutenants.  Slay them.", objectives = "" }
WordHunterWoW_QuestEN[26174] = { title = "Watching Our Back", description = "<Watch Commander Relthorn Netherwane speaks in hushed tones.>\n\nI have orders from... higher up... that you would be suitable for.  I've seen the Horde periodically referring to a stack of papers on that barrel over there.  I'd like you to take a look at those papers and find out what it is that they're plotting.  My duty and station prevent me from such a questionable task, but a newcomer like you might be able to slip in unnoticed...", objectives = "" }
WordHunterWoW_QuestEN[26175] = { title = "Surwich", description = "Other than what you've seen, the Portal's been surprisingly quiet.  There isn't much more work I can give to you, I'm afraid.\n\nIf you're looking for trouble, you might try the Gilnean fishing village to the southwest.  Surwich, I think it was.\n\nI know we're supposed to be friends with the Gilneans, but really?  Worgen?  I had enough trouble getting used to the draenei.", objectives = "" }
WordHunterWoW_QuestEN[26176] = { title = "Onward to Thelsamar", description = "You've helped us quite a bit here. If you're leaving, I'd ask you to take this status report up to Thelsamar.\n\nFollow the road just north, and you can't miss it. Mountaineer Kadrell will want the report.", objectives = "" }
WordHunterWoW_QuestEN[26177] = { title = "Feeling Crabby?", description = "Fresh crab legs have always been one of the King's favorite foods.  We have had good luck catching fresh crabs in the canals over the past few weeks.  Do you think you can lend me a hand and catch a few of them for me?  Be sure to catch them alive, they are no good to me dead, the King requires the freshest catch we can muster.", objectives = "" }
WordHunterWoW_QuestEN[26179] = { title = "The Venture Co.", description = "This explains the buildup of Venture Co. employees and equipment we've seen in Mulgore. Those goblins... their company is expanding too quickly for their own good. It's how they say, show a goblin something, and you can hear the scales in the background.\n\nGreedy little things, they are. Unfortunately for their business enterprise, we tauren cannot allow them to conduct their operations in our lands. Go to their mine northeast of the ravaged caravan and send them a message.", objectives = "" }
WordHunterWoW_QuestEN[26180] = { title = "Supervisor Fizsprocket", description = "According to the documents you salvaged from the caravan, the Venture Co. created many plans to attempt to drive us from our lands here, so that they could have free reign to plunder our lands.\n\nThe depths that they would sink to accomplish their goals disgusts and appalls me. I want the mastermind behind their plans killed. His name is Supervisor Fizsprocket, you will find him at the Venture Co. mine east of the ravaged caravan. Bring me his clipboard, we shall see if we find out anything useful.", objectives = "" }
WordHunterWoW_QuestEN[26181] = { title = "Back to Darkbreak Cove", description = "YOU MUST RETURN... TO... THE DARKBREAK COVE. ERUNAK STONESPEAKER AWAITS... YOU WITHIN.\n\nI DIE NOW....", objectives = "" }
WordHunterWoW_QuestEN[26182] = { title = "Back to the Tenebrous Cavern", description = "YOU MUST RETURN... TO... THE TENEBROUS CAVERN. ERUNAK STONESPEAKER AWAITS... YOU WITHIN.\n\nI DIE NOW....", objectives = "" }
WordHunterWoW_QuestEN[26183] = { title = "The King's Cider", description = "I am forever in debt to our King for all that he has done for us.  One thing I can do for him is make his favorite drink!  Lucky for us, the ingredients we need to make this wonderful drink are located right here in Stormwind City.  Apple trees can be found in every district of Stormwind.  These trees are too tall to pick the fruit from, but lucky for us the apples have fallen to the ground and are easy to retrieve.", objectives = "" }
WordHunterWoW_QuestEN[26184] = { title = "Wormthorn's Dream", description = "Not surprisingly, most of our citizens in Surwich did not come to the Blasted Lands for the pleasant atmosphere.  They came following the dream of an idealistic druid: Marl Wormthorn.  Wormthorn believed that the Tainted Scar could be healed, and attempted to grow it back.\n\nIt looks like he was wrong.  He grew his forest, but the land is still plagued by demons, and his great-tree is twisted and gnarled.\n\nI'm still hopeful.  Maybe if we head into the Tainted Forest and clear out some of the taint...", objectives = "" }
WordHunterWoW_QuestEN[26185] = { title = "Advice from the Cenarion Circle", description = "I believe that the taint of the Blasted Lands has finally exerted its influence over my friend Wormthorn.  His experiment has failed, and his great-tree now only serves as a focus for the demons to rally around.\n\nThe tree must come down, and Wormthorn with it.  Speak with the Cenarion Observer on the other side of town; she should have some idea how to proceed.\n\n{name}: the act we are about to commit must not be made known to the townspeople of Surwich.  Morale is low enough as-is.", objectives = "" }
WordHunterWoW_QuestEN[26186] = { title = "Demoniac Vessel", description = "We need a way to get Wormthorn's attention.  Something to break him out of his trance.  Something that's guaranteed to work.\n\nThe few types of wildlife that managed to make a foothold in the Tainted Forest are, without a doubt, affected by the land's latent energies.  Your task is to collect their body parts and find a way to combine them into a vessel.  If Wormthorn's trance is druidic, or even if it is demonic, a large enough vessel of tainted animal flesh should be able to break it.", objectives = "" }
WordHunterWoW_QuestEN[26187] = { title = "The Downfall of Marl Wormthorn", description = "When word gets out about what we've done... there's no saying what the citizens of Surwich will do.  They cling so closely to Wormthorn's dream...\n\n...but still, it must be done.  Take the demoniac vessel and use it on Marl Wormthorn to pull him from his trance.  Return to me when he is no more.", objectives = "" }
WordHunterWoW_QuestEN[26188] = { title = "Mazzranache", description = "My grandfather told me stories about his battles with a strider named Mazzranache. He told me of its demonic red eyes, razor-sharp talons and venomous bite.\n\nAs fortune would have it, while traveling across the plains, I encountered it, and it took a nasty bite from my shoulder. He was as terrible as my grandfather described. I have gathered all the parts of the remedy I need to cure myself... except a flatland cougar femur.\n\nI grow weaker by the moment... please, help me.", objectives = "" }
WordHunterWoW_QuestEN[26189] = { title = "The Angerfang Menace", description = "When we hauled up here to get away from the raptors, we put ourselves right next to a whole slew of Dragonmaw orcs!\n\nI've heard the stories in Menethil, how the Dragonmaw are even cruder barbarians than other orcs, how they strangle black dragons with their bare hands... I don't know how much of it's true, but I know we can't just let 'em sit up here in the hills.\n\nYou've got the chops for it, {name}. Head east to the Angerfang Encampment, take care of those orcs, and make sure you get their leader!", objectives = "" }
WordHunterWoW_QuestEN[26190] = { title = "A Fisherman's Feast", description = "If there is one meal I know the King likes, it's fresh catfish.  Catfish are easy to prepare but hard to catch.  That's where you come in!  We have a good population of Gigantic Catfish here in the waters of Stormwind but the competition to catch them is intense to say the least.  I need you to figure out a way to \"acquire\" some of these fine catfish for our King.  You will find fisherman at the small canal docks around town.  You should be able to figure out the rest of the plan on your own.", objectives = "" }
WordHunterWoW_QuestEN[26191] = { title = "The Culmination of Our Efforts", description = "", objectives = "" }
WordHunterWoW_QuestEN[26192] = { title = "Orphans Like Cookies Too!", description = "The orphans of Stormwind are often forgotten, but not today my friend.  The king has requested a special batch of cookies be baked and sent immediately over to the orphanage.  I was almost finished with the final batch when I ran out of confectioners' sugar.  Can you run out and get some more for me?  You should be able to find it at any of the general stores or inns inside of Stormwind.", objectives = "" }
WordHunterWoW_QuestEN[26193] = { title = "Defending the Rift", description = "The whispers of the elements are crowding my thoughts, {name}...\n\nThe Throne of Tides is under siege!\n\nI cannot stand idly by while the naga threaten Neptulon's realm. We must find a way to join forces with him.\n\nCaptain Taylor will escort me to the depths where I can commune directly with Neptulon.\n\nI must ask you to take a more violent path. Keep the enemy forces distracted until I arrive safely at entrance to the Throne of Tides.\n\nMay the spirits see us through, {name}.", objectives = "" }
WordHunterWoW_QuestEN[26194] = { title = "Defending the Rift", description = "The whispers of the elements are crowding my thoughts, {name}...\n\nThe Throne of Tides is under siege!\n\nI cannot stand idly by while the naga threaten Neptulon's realm. We must find a way to join forces with him.\n\nNazgrim will escort me to the depths where I can commune directly with Neptulon.\n\nI must ask you to take a more violent path. Keep the enemy forces distracted until I arrive safely at entrance to the Throne of Tides.\n\nMay the spirits see us through, {name}.", objectives = "" }
WordHunterWoW_QuestEN[26195] = { title = "Who Wards The Greenwarden", description = "The greenwarden was a local legend. Many thought him a myth... the plant-man, protector of the wetlands. The night elves came here just to find him, and after they succeeded they ended up settling down to the east.\n\nThey've got a whole grove over there to watch over the greenwarden, and I've heard he's been acting up, enraged by the flooding and damage to the land.\n\nThe elves are good people. They could use the help of someone like you. If you get a chance, go tell the head druid what you've done here.", objectives = "" }
WordHunterWoW_QuestEN[26196] = { title = "Longbraid the Grim", description = "The dwarves of Dun Modr fight day and night against the Dark Iron that have invaded their old home. While we cannot yet send our sentinels to risk their lives for them, we do send much needed supplies that they may sustain their vigil.\n\nIf you would, bring this package to Longbraid the Grim, north of here. His men must certainly need its contents.", objectives = "" }
WordHunterWoW_QuestEN[26197] = { title = "The Future of Gnomeregan", description = "It's a victory for us every time we're able to help another survivor escape from the contaminated halls of Gnomeregan. {class}s like you will play an important part in the future of Gnomeregan. To that end, our leader, High Tinker Mekkatorque has assembled a team of trainers to help you learn your arts.\n\nBipsi Frostflinger will help oversee your training and adjustment to life on the surface. She's waiting for you outside the tall building to the northeast.", objectives = "" }
WordHunterWoW_QuestEN[26199] = { title = "The Future of Gnomeregan", description = "It's a victory for us every time we're able to help another survivor escape from the contaminated halls of Gnomeregan. {class}s like you will play an important part in the future of Gnomeregan. To that end, our leader, High Tinker Mekkatorque, has assembled a team of trainers to help you learn your arts.\n\n\"Doc\" Cogspin will help oversee your training and adjustment to life on the surface. She's waiting for you near the cluster of buildings to the north.", objectives = "" }
WordHunterWoW_QuestEN[26202] = { title = "The Future of Gnomeregan", description = "It's a victory for us every time we're able to help another survivor escape from the contaminated halls of Gnomeregan. We're going to need all the help we can get to reclaim our home and rid ourselves of the troggs and irradiated gnomes. To that end, our leader, High Tinker Mekkatorque, has assembled a team of trainers to help you learn your, uh, \"arts\".\n\nAlamar Grimm has taken up residence in the building just west of this one. He possesses powers similar to yours and can help you get adjusted.", objectives = "" }
WordHunterWoW_QuestEN[26203] = { title = "The Future of Gnomeregan", description = "It's a victory for us every time we're able to help another survivor escape from the contaminated halls of Gnomeregan. {class}s like you will play an important part in the future of Gnomeregan. To that end, our leader, High Tinker Mekkatorque, has assembled a team of trainers to help you learn your arts.\n\nDrill Sergeant Steamcrank will help oversee your training and adjustment to life on the surface. He's waiting for you on the small practice field across the road.", objectives = "" }
WordHunterWoW_QuestEN[26205] = { title = "A Job for the Multi-Bot", description = "If the multi-bot works, it will help us do all kinds of jobs that are unpleasant or dangerous for us gnomes!\n\nAfter Thermaplugg detonated his irradiator at the end of Operation: Gnomeregan, toxic clouds and ooze began bubbling up at the old airfield south of town.\n\nIf we don't get it under control, the contamination could spread to the rest of our lands. Take the multi-bot with you, and bring it close to the geysers in the green pools at the Toxic Airfield. Your bot should spring into action!", objectives = "" }
WordHunterWoW_QuestEN[26206] = { title = "The Future of Gnomeregan", description = "It's a victory for us every time we're able to help another survivor escape from the contaminated halls of Gnomeregan. {class}s like you will play an important part in the future of Gnomeregan. To that end, our leader, High Tinker Mekkatorque, has assembled a team of trainers to help you learn your arts.\n\nKelsey Steelspark, a key member of Gnomeregan Covert Ops, will help oversee your training and adjustment to life on the surface. She should be in the council tent to the northwest.", objectives = "" }
WordHunterWoW_QuestEN[26208] = { title = "The Fight Continues", description = "The dwarves of Ironforge kindly took us in when the trogg invasion and radiation forced us to leave Gnomeregan for the first time. But even the kindness of friends can't quell the longing for home.\n\nI sent out a call for brave gnomes and other members of the Alliance to help us regain control of Gnomeregan and defeat the usurper Thermaplugg once and for all.\n\nWe weren't able to achieve everything Operation: Gnomeregan set out to do, but Thermaplugg is on the run and we're closer to home than ever.", objectives = "" }
WordHunterWoW_QuestEN[26209] = { title = "Murder Was The Case That They Gave Me", description = "Here's the deal, kid, we've got a full-blown murder on our hands. Double homicide... Single horse... icide.\n\nWorse yet, we're in Westfall. I could throw a rock behind me and hit a dozen hobos with motive enough to want to wipe these people (and horse) out.\n\nNow I don't know who did this and I sure don't appreciate having to come to this dump to investigate the deaths of a couple of squatters, but I'll be damned if I don't find the perp. You want to help? Go talk to some bums. The hobo... knows.", objectives = "" }
WordHunterWoW_QuestEN[26210] = { title = "Gammerita, Mon!", description = "Yo! There be a turtle out there not like the others. She be the Gammerita, leader of the saltwater snapjaws - a downright dirty thievin' reptile.\n\nMon, she stole my best lure. Snapped it right off my line! Since then, the fish just aren't biting the same.\n\nFind Gammerita and get my lure out of her stomach.", objectives = "" }
WordHunterWoW_QuestEN[26211] = { title = "Snapjaws, Mon!", description = "Don't let their big eyes fool you, mon! Those saltwater snapjaws be a menace. I can't fish for five minutes without getting a broken line from one of those oversized fish vacuums stealing my bait.\n\nDo me and the people of Revantusk Village a service and kill em, mon.\n\nKill the whole lot of em!", objectives = "" }
WordHunterWoW_QuestEN[26212] = { title = "Lard Lost His Lunch", description = "Lard was at secret special spot having picnic when ugly mean Vilebranch hit Lard wit da big stick. Lard run back to Revantusk but forget Lard lunch. Lard hungry. Maybe you go back to secret special spot and get Lard lunch? Lard scared. Go nort! Island der to da nort is da secret special spot.", objectives = "" }
WordHunterWoW_QuestEN[26213] = { title = "Hot On the Trail: The Riverpaw Clan", description = "Seeing as how we have no other leads, we may as well chase down the information you got.\n\nThere are a couple of Riverpaw gnoll camps in the area. Track them down and search for clues. Bring back anything that you might find. Isolate your search to the Riverpaw gnolls and scouts.", objectives = "" }
WordHunterWoW_QuestEN[26214] = { title = "Hot On the Trail: Murlocs", description = "As pointless as I think that this is going to be, we need to investigate all of our leads.\n\nI need you to head out to the Longshore, west of here, on the coast, and shake up some murlocs. Try to find a clue or some info that can help shed some light on the murders.\n\nReturn to me if you get lucky, rookie.", objectives = "" }
WordHunterWoW_QuestEN[26215] = { title = "Meet Two-Shoed Lou", description = "Looks like we got ourselves a real \"whodunit\" here, rookie. Unfortunately, it looks like the locals aren't willing to talk and the clues you got off the gnolls and murlocs are damn near worthless. We're going to have to initiate plan... be on the lookout for Two-Shoed Lou.\n\nTwo-Shoed Lou is an old confidential informant of mine who, ironically, makes his home at the Furlbrow's old pumpkin farm. Head west to the farm and find out what Lou knows.\n\nIf he gives you any guff tell him that Horatio sent you.", objectives = "" }
WordHunterWoW_QuestEN[26219] = { title = "Full Circle", description = "We've located the beast that destroyed our ships. It makes its lair in Darkbreak Cove, a giant underwater cavern bordering the abyss.\n\nThis time we're ready. The gnomes have been engineering a beauty for us back at Stormwind, and it's packing firepower that'll make that fiend wet itself.\n\nWhen the Pincer X2 pulls up to dock beside the ship, make your way on board and help out however you can. We'll be right behind you.", objectives = "" }
WordHunterWoW_QuestEN[26220] = { title = "Everything Is Better with Bacon", description = "Feeding a hungry orc army is never an easy task.  Luckily for us, we have a good supply of mature swine meat from the pig farms and surrounding areas south of Orgrimmar.  Do me a favor and slaughter some of those pigs for their delicious belly meat.  I will slice it up and make bacon for the troops' breakfast.", objectives = "" }
WordHunterWoW_QuestEN[26221] = { title = "Full Circle", description = "We've located the beast that destroyed our ships. It makes its lair in Tenebrous Cavern, a giant underwater cave bordering the Abyssal Breach.\n\nThis time we're ready. The goblins have been proving their worth by making a vicious machine for us back at Bilgewater Harbor, and it's packing firepower that'll make that fiend wet itself.\n\nWhen the Verne pulls up to dock beside the ship, make your way on board and find a way to make yourself useful. We'll be right behind you.", objectives = "" }
WordHunterWoW_QuestEN[26222] = { title = "Scrounging for Parts", description = "There's just too much to do around here, and too few gnomes on their feet to help! The high tinker has asked me to start converting some of our old bots and parts from Operation: Gnomeregan. I hope to have a new line of multi-bots ready for a field test soon!\n\nI don't suppose you'd have some time to help, do you? There are all kinds of parts scattered around. Pick up anything you find and bring it back to me. You never know what could turn out to be useful!", objectives = "" }
WordHunterWoW_QuestEN[26223] = { title = "Stalking the Stalkers", description = "Many brave trolls have been lost to the harsh wilds of the Hinterlands, {race}. The Silvermane wolves are one of the biggest threats to our hunters. They lay in wait, hiding amongst the bushes and landscape, then strike out when the opportunity presents itself.\n\nThis type of ferocity will not go unchecked!\n\nYou must think like the Silvermane. Stalk the stalkers! Slay them all!", objectives = "" }
WordHunterWoW_QuestEN[26224] = { title = "Hunt the Savages", description = "Among the more ornery of the wildlife of the Hinterlands are the savage owlbeasts. Many a good Revantusk warrior has been lost to the ferocious claws and beak of the beasts.\n\nKill every savage owlbeast you see, {race}. Return to me when you can stand no more bloodshed. Your contribution will then be weighed, measured, and judged.", objectives = "" }
WordHunterWoW_QuestEN[26225] = { title = "Pupellyverbos Port", description = "You there! Did you know that strewn across the northern beach are tens, if not hundreds, of bottles of fine wine?\n\n...well, now you do!\n\nI'd be out there gathering them by the armload, if those turtles weren't out to get me. They crave my blood, I swear.\n\nSo I'll pay you then. Bring me 12 bottles of Pupellyverbos Port and I'll \"purchase\" it from you, {class}.", objectives = "" }
WordHunterWoW_QuestEN[26226] = { title = "Crawfish Creole", description = "There are a number of small lakes scattered around Orgrimmar.  These lakes fill up with crawfish every year.  That's where you come in, {name}.  I need you to catch some of those delicious crustaceans and return to me when you are done.  Assuming your catch is successful, our Horde army will feast tonight.", objectives = "" }
WordHunterWoW_QuestEN[26227] = { title = "Careful, This Fruit Bites Back", description = "Sometimes the troops want something sweet to eat.  I don't always give them what they want but this time, I am going to make an exception.  I am sure you have seen the local cactus that grows here in Orgrimmar.  These cactus produce a tasty treat called prickly pear fruit.  The trouble is the fruit are covered in spines!  Watch your hands and bring me back a handful of that fruit.", objectives = "" }
WordHunterWoW_QuestEN[26228] = { title = "Livin' the Life", description = "Listen, I really shouldn't be talkin' to you, but I owe Horatio a favor or two. I don't really know nothin' about what happened to the Furlbrows, but I might be able to point you in the right direction.\n\n<Lou hands you a large crate.>\n\nThat crate used to be my home before I struck it rich. Now I'm livin' the life every hobo dreams of!\n\nRight, so you take that there livin' crate and head to the Jangolode Mine, southwest of here. Head to the back of the mine and once there, hide in the crate. ", objectives = "" }
WordHunterWoW_QuestEN[26229] = { title = "\"I TAKE Candle!\"", description = "Back before those damned kobolds gave me a permanent limp I used to be William Pestle's number one candle supplier. Hell, I even came up with the line \"I TAKE CANDLE!\" Yea, that was me. Kobold would say \"You no take candle!\" and I'd just respond \"I TAKE CANDLE!\" and then bash their brains in!\n\n<Jimb drifts off for a second.>\n\nGood times... The best times.\n\nNow? Can't even use the bathroom without assistance. You want to help me? Kill me some kobolds. You'll find a good load of 'em in the nearby mine.", objectives = "" }
WordHunterWoW_QuestEN[26230] = { title = "Feast or Famine", description = "Life in Westfall's hard, sonny! Every day is a struggle. We can sometimes go weeks without a decent meal. That's why it's important that we all help each other out. Maybe you can lend a hand, eh? I'm making dirt pies and need some ingredients.\n\nGet me some fresh dirt from the pumpkin patch out front and a bundle of coyote tails. You'll find coyotes wandering around in the wilds of Westfall.\n\nGet moving! We got mouths to feed.", objectives = "" }
WordHunterWoW_QuestEN[26232] = { title = "Lou's Parting Thoughts", description = "A couple of thugs recently showed up at the farm, causin' all kinds of trouble. I don't know where they came from or who they're working for, but I KNOW they're bad news. I may have overheard 'em talkin' 'bout subjects that might interest you.\n\nIf you're interested, you'll find the thugs back behind the farmhouse. If you get caught or killed, I don't know you. Never seen ya!\n\nGood luck, kid.", objectives = "" }
WordHunterWoW_QuestEN[26233] = { title = "Stealing From Our Own", description = "As you know, {name}, Garrosh has relegated the trolls of Orgrimmar to the western outskirts of the city.  Fortunately, that means that we have easy access to their supplies.  I am working on a large batch of jambalaya for the infantry and I need as much rice as possible.  Lucky for us, the trolls keep it stored in barrels near their structures.  Retrieve these barrels of Darkspear rice for me and I should be able to finish up. ", objectives = "" }
WordHunterWoW_QuestEN[26234] = { title = "Stealing From Our Own", description = "As you know, {name}, Garrosh has relegated the goblins of Orgrimmar to the western outskirts of the city.  Fortunately, that means that we have easy access to their supplies.  I am working on a large batch of jambalaya for the infantry and I need as much rice as possible.  Lucky for us, the goblins keep it stored in barrels near their structures.  Retrieve these barrels of Kezan rice for me and I should be able to finish up. ", objectives = "" }
WordHunterWoW_QuestEN[26235] = { title = "Even Thieves Get Hungry", description = "We have had a problem with thieves stealing our infantry rations here in Orgrimmar for the last couple of weeks.  I recently received some intelligence of where these crimes are taking place.  Anywhere you see piles of crates and supplies, there are likely to be thieves nearby.  I need you to hunt these thieves down and recover the stolen rations.  Return to me when you are done.", objectives = "" }
WordHunterWoW_QuestEN[26236] = { title = "Shakedown at the Saldean's", description = "So what do we know so far? We need to follow the clues.\n\nOver at the Jansen Stead you found a water-soaked letter and some scraps of red cloth. Here at the Furlbrow's you overheard a conversation between some shadowy figure and an ogre mage. You also got a confession to the murder from a bunch of thugs - whom you then killed.\n\nSomething isn't adding up, rookie.\n\nThere's an old couple, southeast of here, at the Saldean's Farm. Head over there and speak with Farmer Saldean. Find out what he knows.", objectives = "" }
WordHunterWoW_QuestEN[26237] = { title = "Times are Tough", description = "Times are tough, brother. With the downtrodden masses of Stormwind migrating into Westfall, resources are stretched as thin as they've ever been. The people are restless and in need of help.\n\nOur own farmhouse has been serving as a halfway house for years. Salma does the best that she can to keep our guests alive, but sometimes the watchers get 'em. Watchers are those twisted abominations roaming my fields - a little present left behind by the Defias, before they were driven off. Help us!", objectives = "" }
WordHunterWoW_QuestEN[26238] = { title = "The Savage Dwarves", description = "The Horde has done much for us Revantusk, and we're no freeloaders. With the other forest troll tribes pushed back, we're striking out to claim more land in the name of the Horde.\n\nBut now the Wildhammer dwarves are getting in our way. If it's a war they want, it's a war they'll get... and I don't plan to lose a war to creatures half my height.\n\nGet out there and kill me some dwarves.", objectives = "" }
WordHunterWoW_QuestEN[26240] = { title = "Stomp To My Beat", description = "Our warriors are out there fightin' hard to kill them nasty Wildhammer dwarves, so we can be safe back here at the village. It's only right we do what we can to support them.\n\nA good beat's what every troll needs to do his best in a fight. The poundin' rhythm of the drums drivin' you to hit harder, callin' the spirits to watch over you. Take my drums to the battlefield wit' ya. Play 'em for our warriors, and let 'em show the Wildhammer who owns these lands!", objectives = "" }
WordHunterWoW_QuestEN[26241] = { title = "Westfall Stew", description = "Hello, dear. Welcome to our home. Hmm, you don't look like you're homeless. Have you come to help us? If so, you're just in time! I'm planning dinner for the young ones and need a few simple ingredients.\n\nIf you could get me some okra, goretusk flanks and stringy fleshripper meat I can make my famous Westfall stew! You'll find all of the ingredients near our farm. Just be careful of the harvest watchers. They are merciless killers.", objectives = "" }
WordHunterWoW_QuestEN[26243] = { title = "The World Pillar", description = "The pillar in this room holds up more than just the Temple of Earth.\n\nThis entire plane of existence will soon collapse into our world if we fail to restore it.\n\nThe time to act will come soon, {name}.  But first you must listen to what I have to tell you.", objectives = "" }
WordHunterWoW_QuestEN[26244] = { title = "The Earth Claims All", description = "We're in the plane of earth, {name}.  Everything is absorbed by the land eventually.\n\nThe Storm's Fury will soon be turned to dust and we won't be able to gain any insight from its remains.\n\nGo and destroy the elementals that are dismantling the ship.  We're only delaying the inevitable, but we need to buy ourselves some time if we're to track down all the pieces of the World Pillar.", objectives = "" }
WordHunterWoW_QuestEN[26245] = { title = "Gunship Down", description = "The Archstone was being transported inside a flying Horde gunship called the Storm's Fury.\n\nThe airship crashed south of here and our scrying has revealed the Archstone's no longer on it.\n\nSearch the ship for clues related to what might've happened.", objectives = "" }
WordHunterWoW_QuestEN[26246] = { title = "Captain's Log", description = "<You leaf to the final, interrupted entry.>\n\n...approaching the Temple of Earth at 300 knots and commencing landing maneuvers according to new route.  We've made note of a low pressure system in the north and redrawn our...\n\nBLOOD AND THUNDER!  ALLIANCE SCUM APPROACH!!", objectives = "" }
WordHunterWoW_QuestEN[26247] = { title = "Diplomacy First", description = "The Earthen Ring is a neutral organization, {name}.  We cannot pick sides in the war between the Horde and the Alliance.\n\nLook around you -- our members come from all backgrounds.  Our mission would be compromised should racial tensions be put above our goal.  Let's try to keep this under wraps until we have more information.\n\nWe must not jump to conclusions just yet.  I'll send you and one of our new members to look for the Alliance gunship.\n\nFind out what you can without dragging us into the conflict.", objectives = "" }
WordHunterWoW_QuestEN[26248] = { title = "All Our Friends Are Dead", description = "Something's wrong here, {name}.\n\nThe ship's crew has been slain.  Yet there is no bloodshed or damage to the ship's structure.\n\nThis was not the Horde's doing.\n\nWe will find the answers we seek by speaking to the spirits of the dead.  They have not yet left this world.\n\nTake this totem and place it near the corpses of the fallen.  You will have a few seconds to listen to their last few thoughts.\n\nBeware, however!  There is no telling how the spirits of the dead will react to our prodding.", objectives = "" }
WordHunterWoW_QuestEN[26249] = { title = "The Admiral's Cabin", description = "It's possible we'll find further clues inside the admiral's cabin. You will find it directly below us.\n\nSee if there are any survivors or information that will lead us closer to the World Pillar fragment.  Be careful, {name}.  Whoever got the crew might still be out there.", objectives = "" }
WordHunterWoW_QuestEN[26250] = { title = "On Second Thought, Take One Prisoner", description = "It's not too late, {name}.  The cultists are probably still here.\n\nGo below decks, find out who's in charge and subdue them.\n\nWe will obtain answers to our questions, one way or another.", objectives = "" }
WordHunterWoW_QuestEN[26251] = { title = "Take No Prisoners", description = "It looks like the Twilight's Hammer's still on the ship.  Go below decks and take them out.\n\nBe careful, {name}.  I've a feeling they're not here for a spiritual retreat, if you know what I mean.", objectives = "" }
WordHunterWoW_QuestEN[26252] = { title = "Heart of the Watcher", description = "You have found what appears to be the heart of a harvest watcher.\n\nFrom the sound being emitted by the device you can tell that it's still fully functional. Perhaps you should return it to Farmer Saldean.", objectives = "" }
WordHunterWoW_QuestEN[26254] = { title = "Some Spraining to Do", description = "Hop on, {name}.  Let's see what Mr. Ogreface has to say for himself.\n\nDon't be shy, Stormbeak's only ever dropped a passenger a couple of times before.", objectives = "" }
WordHunterWoW_QuestEN[26255] = { title = "Return to the Temple of Earth", description = "You must get word back to the others at the temple.  Chances are, the fragment is already getting moved to a more secure location.\n\nTell Maruut what you know.  I'm going to do a little investigating about this Twilight Council in the meantime.", objectives = "" }
WordHunterWoW_QuestEN[26256] = { title = "Bleed the Bloodshaper", description = "The Twilight's Hammer are wielding foul magic here, {name}.  They animate and energize the remains of Deathwing's blood, so that instead of drying out and disappearing it thrives and becomes more abundant.\n\nTake out one of the bloodshapers, see if they have any clues as to where we can find this \"forgemaster.\"", objectives = "" }
WordHunterWoW_QuestEN[26257] = { title = "It's Alive!", description = "From what I've heard, all you really need to do is find a suitable harvest golem and drop in the heart. Once you've done that you should be able to take full control of the creature.\n\nI think there's a whole field of overloaded harvest golems west of here, at the Molsen Farm. Look for the arcs of electricity.\n\nShould you manage to get it working, use the golem to destroy the energized harvest reapers at the old Molsen farm. Those monsters are much more destructive than the ones on our farm.", objectives = "" }
WordHunterWoW_QuestEN[26258] = { title = "Deathwing's Fall", description = "The Twilight's Hammer involvement in the disappearance of the World Pillar fragment makes complete sense.  Let us hope that we can act swiftly enough to recover it.\n\n<Maruut places his hand on your shoulder.>\n\nI've established a spiritual bond with you.  We should be able to communicate while you remain in Deepholm.\n\nGo to Deathwing's Fall to the southeast and investigate the Twilight's Hammer operation there.", objectives = "" }
WordHunterWoW_QuestEN[26259] = { title = "Blood of the Earthwarder", description = "When Deathwing escaped to Deepholm, his corruption was extreme, but perhaps not yet absolute.\n\nThe cultists at Deathwing's Fall harvest and shape the corrupted blood he left behind into living organisms to draw from their power.\n\nWhat if a trace of the Earthwarder's essence remains?  After all, Neltharion was the aspect of earth before he was the aspect of death.\n\nGather samples from the living blood the cultists have created and we'll see if any trace of the Earthwarder remains.", objectives = "" }
WordHunterWoW_QuestEN[26260] = { title = "The Forgemaster's Log", description = "Go to the tower the slave spoke of.  You should find it on the northeastern end of the camp.\n\nIf we can act fast enough we might be able to eavesdrop on the forgemaster's meeting.", objectives = "" }
WordHunterWoW_QuestEN[26261] = { title = "Question the Slaves", description = "According to the orders you found, there is a key inside the tent in the southeastern end of Deathwing's Fall.\n\nObtain it and free the slaves in the quarry to the south.", objectives = "" }
WordHunterWoW_QuestEN[26263] = { title = "Thornar Thunderclash", description = "We've been trying to take out the commander of the Wildhammer encroaching on our lands, but we've had no luck.\n\nThornar Thunderclash sits in the safety of his command post, his voice booming across the battlefield to rally the dwarves. We're thinking he needs to be quieted.\n\nCut Thornar down and we can clean up the rest of this skirmish with no problem.", objectives = "" }
WordHunterWoW_QuestEN[26264] = { title = "What's Left Behind", description = "Most of us have seen the sickly and deranged gnomes suffering from exposure to the poisons and radiation of Gnomeregan. Eventually, they will devolve further, until they become mindless, but mostly harmless, puddles of toxic sludge.\n\nMy research suggests that we may even be able to restore them from this state. Go to the Toxic Airfield to the south, subdue the toxic sludge I told you about, and bring back the possessions of the gnomes they once were.", objectives = "" }
WordHunterWoW_QuestEN[26265] = { title = "Dealing with the Fallout", description = "Tock Sprysprocket has some crazy theory about these toxic sludges being the last remnants of gnomes, so my men have orders not to engage them for now.\n\nHowever, the Toxic Airfield, just south of us, is teeming with living contamination. They are elementals composed of contaminated water and other toxic materials. Left unchecked, they'll overrun the town. Will you help us dispose of them?", objectives = "" }
WordHunterWoW_QuestEN[26266] = { title = "Hope for the People", description = "About four years ago, in the dead of the night, a little girl walked right into our farmhouse and collapsed on the floor. Nobody had a clue as to her identity. The poor little thing had no recollection of who she was or where she came from - truly a lost soul.\n\nSoon after, we adopted the little girl and named her Hope - for that is what she represented.\n\nShe is now a young lady, caring for the destitute and homeless of Westfall. Take my Westfall stew to her at Sentinel Hill, south of here.", objectives = "" }
WordHunterWoW_QuestEN[26267] = { title = "Skulk Rock Clean-Up", description = "Years ago, there used to be a Horde base deep within Skulk Rock. It's been abandoned since then, but it's still prime territory, worth reclaiming.\n\nThe problem is, it's full of oozes by now. They're nasty things... mindless, corrosive, eat anything they find.\n\nI need someone brave to go to Skulk Rock and get rid of those slimes. Are you brave enough, {name}?", objectives = "" }
WordHunterWoW_QuestEN[26268] = { title = "Skulk Rock Supplies", description = "I was at Skulk Rock during the second war. I was young, years before I met my mate, and I still remember the chaos when the Alliance attacked us. We fled with the orcs, without any time to gather our belongings.\n\nIt was all left behind. Skulk Rock is still full of our old supplies. We could use them here at the village... and more importantly, the Wildhammer shouldn't get their filthy hands on them.", objectives = "" }
WordHunterWoW_QuestEN[26269] = { title = "The Green Hills of Stranglethorn", description = "One page!  I only need one more page!\n\nMaster Nesingwary's novel ran into a bit of an... accident <Barnil shoots an accusing glance over at Spanks>... and we misplaced some of the pages.\n\nI've been asking your fellow adventurers to look for the missing pages, and they've been quite helpful, but one page still eludes me.\n\nI'm sure you're awfully busy with other matters, but while you're out in the jungle, would you mind looking for it?", objectives = "" }
WordHunterWoW_QuestEN[26270] = { title = "You Have Our Thanks", description = "It's been many years since anyone has offered to lend us aid, {name}. Had you not come along, we might not have made it through the coming winter. You have proven yourself to be a selfless individual - a person that we can trust. I only wish we had something of value to offer you.\n\nWhile I have no information to assist you in your crusade to bring the Furlbrow's murderer to justice, perhaps my wife can help. Speak to Salma inside and she will tell you what you need to know before you leave.", objectives = "" }
WordHunterWoW_QuestEN[26271] = { title = "Feeding the Hungry and the Hopeless", description = "Yes, I heard about the Furlbrow murders. It is very tragic, but such tragedy is a way of life in Westfall. There are many people here who simply no longer have the means or inclination to keep themselves fed. They have given up hope. Do you understand what it means to be left so hopeless as to stop caring about life? We must work together to show them that there is hope. That with the dawning day a better life comes.\n\nTake my mother's Westfall stew and help feed the homeless around Sentinel Hill.", objectives = "" }
WordHunterWoW_QuestEN[26272] = { title = "The Rise of the Darkspear", description = "Tha Darkspear tribe have long been victims. Outcasts. We found ourselves fleein' our homes time 'n time again... but dis time, it's not fleein' dat drives us here.\n\nVol'jin has offered us leadership through wisdom, and it has kept us alive dis long. Now dat same wisdom offers portents of a chaotic future for tha Horde unda Garrosh Hellscream.\n\nNo, dis time we not fleein'. Dis time, we are fightin' for a home dat will last.\n\nIt's time to begin ya trainin', {name}. Speak with Voldreka to the east.", objectives = "" }
WordHunterWoW_QuestEN[26273] = { title = "The Basics: Hitting Things", description = "Alright, mon. We start simple. I need ta know dat you know the basics of the dark arts.\n\nGo thrash dose tiki targets. Take it slowly. Natural-like. I'll watch how you form your casts and we'll go from dere.", objectives = "" }
WordHunterWoW_QuestEN[26275] = { title = "A Rough Start", description = "Lets put dose skills ta use. I'll start ya off easy, mon.\n\nThere be cats killing our boars. Dat food ain't for sharin'. Dose boars are gonna need ta be alive if ya be wanting food tonight.\n\nDey're all over the island. Bring me some cat pelts.", objectives = "" }
WordHunterWoW_QuestEN[26276] = { title = "Proving Pit", description = "Ya done quite well for ya'self, {class}. I'm sure I could teach ya a trick or two here and dere, but I not be wastin' ya time on tiki targets no longer.\n\nl put one last trial before ya den, mon. Head over to da provin' pit in the middle of dis area and fight a real baddy - one dat wants ta kill ya back. Just let the jailor by the pit know when ya ready.", objectives = "" }
WordHunterWoW_QuestEN[26277] = { title = "More Than Expected", description = "Ya definitely more den expected, mon. I'm sure dere's more important stuff we can be usin' ya talents on now. Ya don't need ta hang out with da newbloods no more.\n\nHead down to da village to da southeast and make yaself known. Lend a hand here and there and I'm sure ya make yer way up to sometin' more prestigious quick enough.", objectives = "" }
WordHunterWoW_QuestEN[26278] = { title = "The Defense of Grom'gol: Raptor Risk", description = "Throm'ka, {class}!\n\nYour arrival at Grom'gol is timely, indeed.  Our mission to provide a safe chain of supply to Stonard is being hampered by some of the local inhabitants.\n\nI am putting you in charge of eliminating the raptor population outside of Grom'gol, just to the north.  Don't worry about the raptors themselves... those wretched Nesingwary hunters will take care of them.\n\nI want you to destroy their eggs.", objectives = "" }
WordHunterWoW_QuestEN[26279] = { title = "The Defense of Grom'gol: Ogre Oppression", description = "When we first arrived in this jungle we did not intend to wage war on the local tribes.  Our mission to supply Stonard is of the highest priority.  But complications have arisen.  A local band of ogres has occupied the Mizjah Ruins to the southeast of Grom'gol.  Despite warnings, they continue to ambush our supply caravans.\n\nI am putting you in charge of dealing with these uncooperative ogres.\n\nTravel to the ruins and attempt to drive them from the area.  At the very least it will send a firm message.", objectives = "" }
WordHunterWoW_QuestEN[26280] = { title = "The Defense of Grom'gol: Murloc Menace", description = "The Murkgill murlocs have been pushed out of the ocean by the Saltscale murlocs, so they make their refuge in the Kal'ai ruins to our northeast.  This was acceptable in the past, but no longer.\n\nSeparated from the sea, the Murkgill have grown restless, and they send their foragers to attack my supply caravans.  Send them a message: this behavior will NOT be tolerated by Hellscream's Horde.", objectives = "" }
WordHunterWoW_QuestEN[26281] = { title = "The Defense of Grom'gol: Trollish Thievery", description = "The trolls leave us well enough alone here in Grom'gol.  Most trolls know that the Horde can easily crush them when angered, and the trolls here in Stranglethorn are no exception.\n\nThe Bloodscalp have been more active lately, however.  As lately as last week, they sent a party into Grom'gol and stole several cases of rations.\n\nStealing food is the most forgivable type of theft, but I still can't let it happen under my watch.  Head north, to the Bal'lal ruins, and return our property.", objectives = "" }
WordHunterWoW_QuestEN[26283] = { title = "Prime Slime", description = "I've become very interested in the slimes inhabiting Skulk Rock. No matter how many times they're cleared out, they seem to return, yet it doesn't seem they're capable of reproducing from a single slime.\n\nI think something's growing in there. There's a source where all the slimes come from, and I want to study it. Find this source, and bring me back a sample.", objectives = "" }
WordHunterWoW_QuestEN[26284] = { title = "Missing in Action", description = "Fer a job like this, I normally bring me whole crew o' demolitionists. With some help in settin' up th' powder, th' charges, and th' rest o' th' gear, the job gets done a lot faster.\n\nThose blasted troggs have me men caged all around Frostmane Hold. Now I'm 'ere all alone without th' personnel I need to finish th' job.\n\nYou look like a capable {class}, though. Would you find th' demolitionists th' troggs captured and break them out o' their cages?", objectives = "" }
WordHunterWoW_QuestEN[26285] = { title = "Get Me Explosives Back!", description = "It's gonna take a lot of powder ta collapse those caves. I don't know whether th' damnable troggs understood that when they stole me supplies and kidnapped me demolitionists! But th' outcome's th' same.\n\nAin't gonna be able ta blow nothin' up until I've got that powder back.\n\nGo south to Frostmane Hold and kill any o' those troggs you find. Any one o' 'em could be carryin' me kegs o' powder.", objectives = "" }
WordHunterWoW_QuestEN[26286] = { title = "In Defense of Westfall", description = "After my tour of duty was over in Grizzly Hills, I returned to Westfall, only to find the land in worse condition than when I left.\n\nThe price of our war left thousands of citizens homeless. They now migrate here and squat upon the deserted farmhouses and towns of the region.\n\nTo make matters worse, we are now under attack by the gnolls. The Westfall Brigade needs your help, {name}. Slay the attacking gnolls and recover their orders. Someone is pulling their strings and we need to find out whom!", objectives = "" }
WordHunterWoW_QuestEN[26287] = { title = "The Westfall Brigade", description = "We were once known as the People's Militia. These days, though, we fight under the banner of Stormwind, with the full support of King Anduin Wrynn. Our goals here in Westfall are many: to clean up the mess left behind by the Defias, to expand the reach of the Alliance and to maintain order. So far we are failing on all fronts.\n\nTimes are worse now than when the Defias ran amok. Now with the indigenous gnolls of the region up in arms, we find ourselves backed into a corner. Help us, {name}!", objectives = "" }
WordHunterWoW_QuestEN[26288] = { title = "Jango Spothide", description = "South of here is an area of Westfall known as the Dust Plains. From what we know the gnolls of the region have made the Dust Plains their unofficial capital. As with any capital, there exists a leader at the heart. If we are to put an end to these attacks, we must track down the gnoll in charge and end him.\n\nVenture forth into the Dust Plains, find the gnoll leader, Jango Spothide, and kill him. Take out any other gnolls that get in your way.", objectives = "" }
WordHunterWoW_QuestEN[26289] = { title = "Find Agent Kearnen", description = "SI: 7 has been tracking Helix Gearbreaker since he entered Alliance territory two weeks ago. The letter I received from Mathias Shaw explained that he sent an agent by the name of Kearnen to Westfall to shadow Helix. Find Agent Kearnen and you'll find Helix Gearbreaker.\n\nKearnen came into town for supplies two days ago. She mentioned that she would be near Mortwake's Tower, southeast of here, on the Dust Plains.\n\nGet going, {name}.", objectives = "" }
WordHunterWoW_QuestEN[26290] = { title = "Secrets of the Tower", description = "Helix has got himself holed up inside Klaven Mortwake's old tower. I won't lie to you, {name}, it's heavily guarded. I count six armed mercenaries just on the outside. There's no way you're getting inside that tower by yourself. Lucky for you, Claire and I are here.\n\n<Kearnen pats her sniper rifle.>\n\nI'll cover your entry.\n\nTake this shrouding potion, you'll need it once you get inside. Use it as soon as you enter the tower and head upstairs. Find out what Helix is hiding up there!", objectives = "" }
WordHunterWoW_QuestEN[26291] = { title = "Big Trouble in Moonbrook", description = "I'll be filling out my report and heading back to Stormwind shortly. SI: 7 must be informed of the happenings in Westfall. I would recommend you do the same and report back to Gryan.", objectives = "" }
WordHunterWoW_QuestEN[26292] = { title = "To Moonbrook!", description = "We have had a camp near Moonbrook for quite some time now, {name}. One of my best soldiers works the area along with a company of Sentinel Hill troopers. Report to Captain Alpert now and find out if he has any news about the happenings in Moonbrook.\n\nAnother ally of mine is also at the Moonbrook camp. His name is Thoralius. I met Thoralius in Northrend during my time in Valgarde. He is a wise and powerful shaman. Perhaps his abilities could help us solve this mystery.", objectives = "" }
WordHunterWoW_QuestEN[26293] = { title = "Machines of War", description = "Far to the east the \"Worldbreakers\" lay hidden in the Twilight Highlands. We must end their threat and we will do it with the most powerful army ever!\n\nOur new allies, the goblins, are making us new machines of war but I hear that there are problems with the quality. We can't fight with broken war machines. Speak to Foreman Glibbs and make sure our machines are ready for battle.", objectives = "" }
WordHunterWoW_QuestEN[26294] = { title = "Weapons of Mass Dysfunction", description = "<Glibbs mops sweat from his brow with a greasy handkerchief.>\n\nSaurfang isn't happy with our work? This is very bad. My boys need to step it up.\n\nMaybe you can help set an example. A set of Hellscream Demolishers just rolled off the blocks and are ready for inspection. Give them a thorough going-over, and if you find any problems, give the Chief Engineer a good thrashing. Remind them that the Horde is depending upon them!", objectives = "" }
WordHunterWoW_QuestEN[26295] = { title = "Propaganda", description = "We've noticed a rise in violent acts amongst the homeless of the area. Something or someone is getting them all riled up. Now whoever is behind all this is getting more organized. Just recently a group of thugs came through here handing out pamphlets.\n\nEnter Moonbrook and look for evidence. Propaganda, leaflets, whatever... Bring whatever you find back to me. Maybe we can find the source through the writings.", objectives = "" }
WordHunterWoW_QuestEN[26296] = { title = "Evidence Collection", description = "The material of this bandana is identical to the material found at the Furlbrow murder scene. You should collect more red bandanas as evidence and return what you find to Captain Alpert.", objectives = "" }
WordHunterWoW_QuestEN[26297] = { title = "The Dawning of a New Day", description = "It looks like the meeting the shadowy figure spoke of is starting soon. The homeless are starting to mobilize. I need you to attend the rally and gather information, {name}.\n\nGo to the center of Moonbrook and listen in on the rally. Return to me with whatever you find out.", objectives = "" }
WordHunterWoW_QuestEN[26298] = { title = "Hunt for Yenniku", description = "A doom, there is.  A doom on my chief's youngest son, Yenniku.  As is a custom with our people, he was given to the Gurubashi Trolls of Zul'Gurub, but after my tribe, the Darkspear tribe, left with the orc Thrall, poor Yenniku was lost to us.  I was sent from distant Orgrimmar, back to Stranglethorn, to search for my chief's son.\n\nAnd I believe the Bloodscalp tribe has him.\n\nIf you would help me, then hunt the Bloodscalps.  You may find them to the north.  Gather their tusks and return to me.", objectives = "" }
WordHunterWoW_QuestEN[26299] = { title = "Headhunting", description = "We must find if Yenniku is dead.\n\nSlay the Bloodscalps of Zuuldaia and take from them their shrunken heads.  You must gather many, many heads, and I will inspect them to make sure Yenniku's head is not among them.\n\nAnd if Yenniku was killed by the Bloodscalps, then may a 600-year curse fall on the spirit of their chief, Gan'zulah!\n\nGo, {name}.  You will find the heads at the ruins of Zuuldaia, along the coast to the north.", objectives = "" }
WordHunterWoW_QuestEN[26300] = { title = "Nezzliok Will Know", description = "Yenniku was not among the heads, and I thank the Great Serpent for it.  But we are no closer to finding him.\n\nWe must know the truth, and I fear that only the Bloodscalp witchdoctor will know it.  He is an enemy of the Darkspear tribe and will not speak freely, so we must force the truth from his dead lips!\n\nBring me the head of Nezzliok the Dire and place it within this cauldron.\n\nHe is deep within Zul'Kunda.  Bring his head...we will then make it talk.", objectives = "" }
WordHunterWoW_QuestEN[26301] = { title = "Speaking with Nezzliok", description = "<The head of Nezzliok speaks.>\n\nIt is true.  I know where the child of the Darkspears was taken.  You have bested me and bound my spirit, but I will say nothing without appeasement!\n\nThe Bloodscalps war with the Skullsplitters.  To gain my favor, steal two of their most-prized trophy skulls from the Skullsplitters across the river to the east.  Place them here with us, so that my spirit will have slaves in the Nether.  One skull must be from their trophy pile in Balia'mah, the other from Ziata'jai.", objectives = "" }
WordHunterWoW_QuestEN[26302] = { title = "Chasing Yenniku's Fate", description = "<Nezzliok speaks.>\n\nYou have appeased myself and my chief, so I will tell you that which you seek to discover...\n\nYoung Yenniku is lost to his clan.\n\nHe was taken by the witchdoctor Zanzil the Outcast.  Now Zanzil controls him, body and soul, and only the most potent magic could set him free.\n\nA magic that you do not have, {class}.\n\nPerhaps your Darkspear allies at Bambala in the east can offer a hope of Yenniku's salvation.  But that, I doubt.", objectives = "" }
WordHunterWoW_QuestEN[26303] = { title = "The Mind's Eye", description = "The Mind's Eye is held by an ogre mage, in the Mosh'Ogg ogre mound just to the south.  His name is Mai'Zoth.  I know him from when the Darkspears dwelt in Stranglethorn - he is vicious, and his magic is strong.\n\nAnd if he has the Mind's Eye, then his magic will be stronger still.\n\nYou must face Mai'Zoth and wrest from him the Mind's Eye.  It is a perilous task, but it is the only hope we have of saving Yenniku.", objectives = "" }
WordHunterWoW_QuestEN[26304] = { title = "Nighttime in the Jungle", description = "One year ago, my mother - that is, the troll who took care of me - was taken by the Skullsplitters of Zul'Mamwe.  Young and headstrong, I ran in after her, only to see her being pushed toward a burning brazier by a dozen of their warriors.  I hid behind a tree and watched as they grabbed her and... and...\n\n<Kil'karil looks away.>\n\nAt nighttime, the lights from their braziers reflect off the treetops and keep me awake.  Please, {name}... travel south into Zul'Mamwe and put them out.", objectives = "" }
WordHunterWoW_QuestEN[26305] = { title = "Saving Yenniku", description = "I have reshaped the Mind's Eye into a Soul Gem.  Its purpose is twofold: you must use it to stun Yenniku, and once stunned place it upon his head to entrap his soul.\n\nMy suspicions that I spoke of earlier were correct: the spirits tell me that Yenniku dwells not with Zanzil the Outcast, but within the Ruins of Zul'Mamwe, to the southwest.  Once you have freed Yenniku's spirit, return to Nimboya at Grom'gol.", objectives = "" }
WordHunterWoW_QuestEN[26306] = { title = "Start Taking Back", description = "Today we make the first strike at the heart of the savage Vilebranch tribe. Show no mercy, {name}; this is no longer just a spat between trolls. Every victory of the Revantusk is a victory for the Horde!\n\nThe Vilebranch headhunters and witch doctors will be the first to go. Make your strike against the lower terraces and report back to me with blood on your weapons.", objectives = "" }
WordHunterWoW_QuestEN[26307] = { title = "Death to the Vilebranch", description = "We won't give them a chance to react. You must re-enter Jintha'Alor and charge all the way to the upper tiers.\n\nThe Vilebranch berserkers and shadowcasters are dangerous enemies, {name}. When the others see their bodies thrown across the walls, they'll know we mean business.\n\nDon't leave any Vilebranch hearts beating!", objectives = "" }
WordHunterWoW_QuestEN[26308] = { title = "It's Ours Now", description = "Only the strongest and foulest Vilebranch are left now. The soul eaters and blood drinkers, foul worshippers of the evil god Hakkar.\n\nThey are FOOLS! They cling to old, defeated beliefs. I won't tolerate their crimes against the Revantusk any longer.\n\nStrike the final blow. Claim Jintha'Alor for the Revantusk... claim it for the Horde!", objectives = "" }
WordHunterWoW_QuestEN[26309] = { title = "Dark Vessels", description = "The Vilebranch trolls here used to drink the corrupted blood of the god Hakkar himself for power. They boiled it in crude pots before drinking, dark vessels full of unholy strength.\n\nHakkar was killed long ago, of course. But the interesting thing... I still see some cauldrons bubbling up there. Bring me back a few and we'll see just what they've got cooking.", objectives = "" }
WordHunterWoW_QuestEN[26310] = { title = "All That Skitters", description = "A moment if you're going up there, {class}...\n\nI've got a few brokers quite interested in potent toxins. I couldn't help but notice the spiders scurrying around near here... not giant ones, about the size of your hand.\n\nThe skitterlings are a hue I've never seen before in this area. Could you collect a few for me and bring them back?", objectives = "" }
WordHunterWoW_QuestEN[26311] = { title = "Unfamiliar Waters", description = "The Warchief has designs to launch an all-out assault on the Twilight Highlands. Once there we hope to ally with the Dragonmaw orcs.\n\nThrough my own sources I've discovered that a Dragonmaw orc resides here, in Orgrimmar. He is known as Herezegor Flametusk, and once he commanded legions of their warriors.\n\nHis insider knowledge is precious to us. Find Flametusk and obtain for us a chart of the Twilight Highlands waterways.\n\nLast I hear, Flametusk was washed up at a bar in the Valley of Honor...", objectives = "" }
WordHunterWoW_QuestEN[26312] = { title = "Crumbling Defenses", description = "When da attack started, we pushed out to take da field as quickly as we could. Dere forces were deep and endless... we underestimated dem. Now some of our best shaman be stranded out dere, exhausted, far from our defenses.\n\nMake your way out and take da pressure off of our stranded brothas. Even a small break in battle be a chance to get much needed room ta breathe.\n\nBe swift, {class}.", objectives = "" }
WordHunterWoW_QuestEN[26313] = { title = "Core of Our Troubles", description = "Elementals are chaotic by nature, but dis kind of organized aggression is out of character. More so down here where dere deaths be a bit more permanent. I suspect dis is Therazane the Stonemother's doin', but I have to be sure.\n\nDestroy da Irestone Rumblers and bring me their cores. We'll be settlin' here and now if dis is da Stonemother's hatred brought down on us.", objectives = "" }
WordHunterWoW_QuestEN[26314] = { title = "On Even Ground", description = "We're fortunate dat those giants be havin' such bad aim. Luck is sure to be favorin' dem eventually though.\n\nWe need to get dem off da battlefield, but I don't tink takin' dem head on would be very smart.\n\nTake dis grapplin' line, get a good hold on one of their ankles and pull their legs out from under dem. Once dey are on da ground, dey should be easy ta be finishin' off.", objectives = "" }
WordHunterWoW_QuestEN[26315] = { title = "Imposing Confrontation", description = "Have ya seen the looming giant in the distance to the northeast? Dat is Boden the Imposing, one of Therazane the Stonemother's Stone Lords.\n\nWe be knowin' little of da Stone Lords, but Boden is not known ta be very level-headed. Sadly, he seems to be da one leadin' dis assault, so he's the one we must be confrontin'.\n\nTake dis proclamation to him and read it aloud on behalf of da Earthen Ring. I know it be a bit of a stretch to think words will settle dis, but we have to try. Be cautious.", objectives = "" }
WordHunterWoW_QuestEN[26316] = { title = "What's Keeping Kharmarn?", description = "The cataclysm tore open deep caves beneath Frostmane Hold and troggs flooded out of their warrens. They succeeded in displacing the trolls who used to live there and they stand to drive us out if we do not act.\n\nHigh Tinker Mekkatorque hired the renowned demolitionist, Kharmarn Palegrip, to close the caves and stem the trogg advance. We've received no word about whether he was able to stop the troggs. Would you look for him at his camp near Frostmane Hold, to the south beyond the Toxic Airfield?", objectives = "" }
WordHunterWoW_QuestEN[26317] = { title = "A Lashtail Hatchling", description = "Upon dealing the final blow to the lashtail eggs, you look down to see a newborn hatchling looking back up at you.  You can see it studying you, learning your features and following your movements.\n\nThe lashtail hatchling has formed a bond with you.\n\nYour original assignment was to thin out the raptors, but you have fulfilled your egg quota, and this one is an innocent newborn.  Perhaps someone back at Grom'gol Base Camp will know what to do with a raptor hatchling.", objectives = "" }
WordHunterWoW_QuestEN[26318] = { title = "Finishin' the Job", description = "My team has finished settin' up th' powder kegs and th' detonator at the bottom o' th' cave in th' western part of Frostmane Hold. All you need to do is venture down there and activate th' detonator to explode the powder and collapse those tunnels.\n\nThat'll stop th' flow of troggs from th' deep parts of th' earth. Mekkatorque'll have an easier time of dealin' with the remainin' troggs if you can take out their leader, who calls 'imself Boss Bruggor. Good luck, {name}.", objectives = "" }
WordHunterWoW_QuestEN[26319] = { title = "Secrets Revealed", description = "There is a shaman here, Thoralius, who might be able to aid us. He is a friend of Gryan's who has recently come to Westfall to study the elemental devastation that has befallen us.\n\nSpeak to Thoralius and see if there is something that he can do to shed some light on the identity of this shadowy figure.", objectives = "" }
WordHunterWoW_QuestEN[26320] = { title = "A Vision of the Past", description = "This incense will put your body and mind in a deep meditative state. Once the trance begins you will be pulled into the spirit world. Do not fight the trance once it has begun, {name}. Allow the spirits to show you what they know.\n\nYou must leave now. Go to the Deadmines, a place which I am told holds great significance in the history of Westfall. Once inside, use the incense.\n\nYou may enter the Deadmines through the old farmhouse south of here. Follow the homeless. \n\nReturn to Gryan with your discovery.", objectives = "" }
WordHunterWoW_QuestEN[26321] = { title = "I Think She's Hungry", description = "It looks like your young raptor is hungry.  If you're looking to keep her, why don't you find something for her to eat?  The lashtail often attack the camp of the Murkgill murlocs, just to our north.\n\nShe probably isn't strong enough to hunt on her own yet, but I'm sure she will eat freshly killed murloc meat.", objectives = "" }
WordHunterWoW_QuestEN[26322] = { title = "Rise of the Brotherhood", description = "I had no idea that VanCleef had a daughter, {name}. If there was one thing that man was exceptionally skilled at, it was keeping secrets.\n\nHow tragic. Poor thing witnessed a horrible act. Had I only known.\n\nWhat was that? Did you hear something? It seems as if the gnolls are pulling back... where are my guards?\n\nON GUARD, {name}!", objectives = "" }
WordHunterWoW_QuestEN[26323] = { title = "Favored Skull", description = "Your pet raptor seems to have found a new toy: a skull, from a nearby troll skull pile.\n\nWhat sets this skull apart from the rest is beyond you, but for some reason, she won't put it down.\n\nNimboya at Grom'gol Base Camp seems to be somewhat of a skull expert, judging by the skull piles he keeps.  Maybe he'll have some idea what makes this one so special.", objectives = "" }
WordHunterWoW_QuestEN[26324] = { title = "Where Is My Warfleet?", description = "The Highlands are the home of the Dragonmaw orcs. If we show them our might they would ally with us against the Twilight's Hammer. I am certain!\n\nThe fleet is gathering at Bilgewater Port in Azshara but there are reports of delays.\nYou did good getting the goblins to work, I need your skills here too.\nFind Warlord Krogg in Azshara and see what is taking so long.", objectives = "" }
WordHunterWoW_QuestEN[26325] = { title = "A Nose for This Sort of Thing", description = "<The skull speaks to you.>\n\nI live?  No, I do not... but I can.\n\nThat raptor you have is wise to have found my skull among what must have been so many.  In life, I was strong, powerful, a lord among trolls.  With your help, I can be a lord once more.\n\nThe Bloodscalps at Zuuldaia hoard magical fetishes that can help me return.  They hide these artifacts under the sand.  Use your hatchling to find these artifacts, {name}... then throw them in the pot.", objectives = "" }
WordHunterWoW_QuestEN[26326] = { title = "The Very Earth Beneath Our Feet", description = "Only one piece of the World Pillar remains, and it is in the hands of the Stonemother herself. Worse, the temple has come under siege by elementals and giants. It's not a terrible leap of logic to assume they're acting by her will.\n\nGo out and meet the elementals in battle to the northwest. Work with Torunscar and Norsala to find a way to communicate with their leaders and seek out the World Pillar. We would prefer such be done peacefully, but we will do whatever we must to seal the rift.", objectives = "" }
WordHunterWoW_QuestEN[26327] = { title = "Anvilmar the Hero", description = "You don't want to waste your time talking to me right now, lad. Thargas Anvilmar himself is just on the other side of these wagons.\n\nSurely you've heard of him? He fought to defend the Thandol Span from the Dark Iron alongside the King of Stormwind! He's one of the finest heroes of Ironforge.\n\nRight now though, he's in the thick of it! Go out there and let him know you're ready to help. Just keep a good distance, he swings wide.", objectives = "" }
WordHunterWoW_QuestEN[26328] = { title = "Rocky Relations", description = "<Norsala reaches to the ground in an attempt to discern Diamant's location, but jumps back in shock after a moment's contact.>\n\nMy! Dat was unexpected. Diamant ain't far at all. When I reached out ta him, he spoke back wit me and told me where we could be finin' him. Head towards tha northeastern edge of the Jagged Wastes - Diamant will be expectin' ya.\n\n{name}, be careful. It may be unlike an earth bein' to lay an ambush, but it was unlike dem to siege the temple in da first place.", objectives = "" }
WordHunterWoW_QuestEN[26329] = { title = "One More Thing", description = "Well, it's time to start packin' up and movin' on to the next job. There's always somethin' else to blow up out there. Somewhere, there's a mountain needs movin' or a gorge that needs carvin', and I'll be there to do it.\n\nI don't suppose you'd do me one more favor? Would you take this report back to High Tinker Mekkatorque in New Tinkertown? He needs to know that th' troggs won't be botherin' his people again anytime soon.", objectives = "" }
WordHunterWoW_QuestEN[26330] = { title = "Who's a Big Troll?", description = "<The skull speaks once more.>\n\nMy soul is ready, but my body is not.  The Bloodscalps desecrated my old body long ago.  The horrors that they inflicted upon me... my spirit watched on while they tore my body apart and, and... I can't go on.\n\nTheir chief, Gan'zulah, presided over the gruesome acts.  In fact, if memory serves, he was a strong, powerful troll... about the same size as I was.  What a fine coincidence.\n\nYou know what to do, {race}.  Make it quick.", objectives = "" }
WordHunterWoW_QuestEN[26331] = { title = "Crushcog's Minions", description = "Our old enemy, Thermaplugg, is doing his best to keep us from rebuilding and finishing our reclamation of Gnomeregan. He's sent one of his most loyal henchmen, Razlo Crushcog, and a force of irradiated gnomes to harry us.\n\nThey've taken over an old arsenal up the road to the north, and Crushcog's technicians are repairing those weapons. We have to stop them before they're able to get those mechano-tanks back online. Go to Crushcog's Arsenal and eliminate as many of the technicians as you can.", objectives = "" }
WordHunterWoW_QuestEN[26332] = { title = "Skullsplitter Mojo", description = "<The skull speaks again.>\n\nI have my body, thanks to you, your raptor, and Gan'zulah.  Now, if I remember correctly, you and your witch doctor friend will need some mojo to complete this ritual.\n\nThe Bloodscalps keep mojo in Zul'Kunda, but it is weak.  Your Darkspears' mojo will not work either.  No... you want to take from the Skullsplitter trolls, across the river to the east.\n\nHurry back, {race}.  I will be watching...", objectives = "" }
WordHunterWoW_QuestEN[26333] = { title = "No Tanks!", description = "We've lost more than a couple scouts trying to find out what exactly Razlo Crushcog plans to do with all those mechano-tanks his irradiated technicians are repairing.\n\nWe can't afford to take it slowly anymore. We must act before Crushcog turns his followers and his weapons on us.\n\nThis techno-grenade packs enough explosive power to destroy the mechano-tanks and deny Crushcog their use. Take it north with you along the road to Crushcog's Arsenal and take out those tanks!", objectives = "" }
WordHunterWoW_QuestEN[26334] = { title = "Bloodlord Mandokir", description = "{race}.  {race}, {race}, {race}... you didn't think I was a friend, did you, {race}?  Ah, ha ha haaaa!\n\nYou've served your purpose.  I've returned to the realm of the living, and it's all thanks to you.  So, instead of killing you, I'm going to make you a deal instead.\n\nGive me the raptor.\n\nYou must already know that she's no normal raptor, and I need a replacement for Ohgan.  Do it, or both you and the witch doctor will taste my rage.", objectives = "" }
WordHunterWoW_QuestEN[26335] = { title = "Ready the Navy", description = "Hellscream expects an armada of ships for his invasion, but the docks here are weeks behind schedule. Costs are rampant and quality is poor. Corruption is the problem, {name}! And I need you to root it out.\n\nThe Foebreaker, a warship berthed at the northwest pier, should have been outfitted days ago. Something reeks. Go there and oversee the construction yourself.\n\nFind out who's disrupting our naval preparations and deal with them!", objectives = "" }
WordHunterWoW_QuestEN[26336] = { title = "Shakes O'Breen", description = "You're all right, {name}. It's not every day you come across a so-called hero that has a clue what they're doing once they get this far from home, so I'll let you in on some more work.\n\nI've a friend by the name of Shakes O'Breen. He's the captain of a crew of pirates, the Blackwater Raiders; good men, respectable as pirates go. They dock at Faldir's Cove, hidden along the southern shore.\n\nI'm sure O'Breen will have lucrative jobs for you if you're interested.", objectives = "" }
WordHunterWoW_QuestEN[26337] = { title = "Beating the Market", description = "<It's not hard to see why the Foebreaker is behind schedule. Every other day, a foreman comes in and changes the blueprints.>\n\n<Most troubling are the recent alterations. The workers have been ordered to remove rivets to save on costs!>\n\n<You'd better track down one of the Bilgewater foremen responsible for this and make an example out of him, before any Horde lives are lost in a faulty ship.>", objectives = "" }
WordHunterWoW_QuestEN[26338] = { title = "Population Con-Troll", description = "I understand you may be headed to Zul'Kunda soon.  While you are there, I have a small task for you.\n\nThe trolls are outgrowing Stranglethorn.  The Bloodscalp in the West, the Skullsplitters in the East... they pour out of their ruins and into the jungle, disrupting the natural balance of the region.  It is time we restored that balance.\n\nZul'Kunda is the Bloodscalp capital.  Inside you will find the most high-ranking Bloodscalps.  Reduce their numbers, then return to me.", objectives = "" }
WordHunterWoW_QuestEN[26339] = { title = "Staging in Brewnall", description = "While High Tinker Mekkatorque, his military advisors, and I finalize the plans for the attack on Razlo Crushcog, I've sent my assistant ahead to Brewnall Village to begin preparations.\n\nTo get to Brewnall Village, follow the road southeast out of town. Once you arrive, find Jarvi Shadowstep and see if he needs any help. Our dwarven cousins have dispatched a cadre of mountaineers from Ironforge to join us in the fight against Crushcog.", objectives = "" }
WordHunterWoW_QuestEN[26340] = { title = "The Hunt", description = "Of all the places to end up across Azeroth, I'm stuck here in Grom'gol.  With the marauding wildlife, the caravan raids, and the constant threat of troll attacks, I'm surprised I've survived for this long.\n\nCould be worse, I suppose.  At least here in Grom'gol we have walls and guards.  There's a group of hunters up north that set up camp right in the middle of the jungle!\n\nI see people heading there all the time.  If you're looking for trouble, feel free to head up there.  I'll stick with my Grom'gol.", objectives = "" }
WordHunterWoW_QuestEN[26341] = { title = "The Stone Shards", description = "I've scouted all over these highlands, {name}, and there's one thing I've found I haven't been able to explain.\n\nTo the northeast of here, there's a circle of stones, like the others you'll find everywhere in Arathi... but the largest and most imposing of them, built into the mountainside itself.\n\nJust between you and me, I heard voices while I was there. Whispers of the earth. If you're the curious type, you could go see for yourself...", objectives = "" }
WordHunterWoW_QuestEN[26342] = { title = "Paint it Black", description = "We have reliable intelligence that Razlo Crushcog has taken up a defensive position on the island in the middle of frozen Iceflow Lake. To make matters worse, he's surrounded himself with a network of sentry-bots that will detect any possible attackers.\n\nIf we're to take on Crushcog, we'll need to take out those sentries. This device launches a dark, sticky paint that will coat the optical sensors of Crushcog's sentry-bots. Use it to take out his early warning system.", objectives = "" }
WordHunterWoW_QuestEN[26343] = { title = "Supply and Demand", description = "\"The finest leathercrafter of the South Seas and the worlds old and new.\" That's what they call me. Me! Drizzlik! The finest lea... Ahem. Well.\n\nMy leather goods are known far and wide as the most exquisite, a connoisseur's choice!\n\nI've just received an order from Director Riddlevox of the Tinkers' Union for a dozen of his favorite Excelsior-line boots. Our best sellers, actually.\n\nTo start on the basic shape, I'll need crocolisk skins from the crocs along the river in Northern Stranglethorn.", objectives = "" }
WordHunterWoW_QuestEN[26344] = { title = "Some Assembly Required", description = "Well, I've got the basic shape of the boots worked out, and they're coming along fine, but the skins you brought aren't going to be quite enough for the inner layers.\n\n\"What are we going to do, Drizzlik?\" No doubt the question on your lips, and well, isn't it lucky you're talking to Drizzlik, because he's going to tell you what we're going to do!\n\nThe inner layers will never really be seen, so we'll just get some of the thicker, cheaper skins from the crocs around Lake Nazferiti to fill the boots out.", objectives = "" }
WordHunterWoW_QuestEN[26345] = { title = "Excelsior", description = "With the inside finished, all that's left is to add the outer layer. For this, I use only the best elder croc skins. They are more durable and a better canvas--if you will--for adding the designs and accents that make Drizzlik's Excelsior line.\n\nIt's hard to find that perfect skin though, the only one that fits my plan is the skin of an elder snapjaw crocolisk.  Find them to the south, near the border with the cape.", objectives = "" }
WordHunterWoW_QuestEN[26346] = { title = "Myzrael's Tale", description = "As the stone goes quiet, you're left with a vague sense of unease. Something isn't right.\n\nPerhaps you should tell Skuerto of what you've done so far.", objectives = "" }
WordHunterWoW_QuestEN[26347] = { title = "Keeper of the Flame", description = "The night the Lighthouse Keeper's family died was horrible.  I watched, helpless, as Old Murk-Eye led the attack.  But what's done is done and now my concern is for the lives of the sailors on The Great Sea whose ships come close to the perilous rocks of the coastline.  With no one to keep watch on the flame the responsibility has fallen upon me.\n\nHelp me keep the torch lit by bringing me chasm ooze from the slimes in the Raging Chasm to the northeast.", objectives = "" }
WordHunterWoW_QuestEN[26348] = { title = "The Coast Isn't Clear", description = "You probably noticed all of the shipwrecks along the coast.  The Great Sea is treacherous indeed.  The coast of Westfall needs to be kept clear, so that if sailors find their way to our beaches, they are safe.  The Murlocs are trouble though.\n\nKill murloc tidehunters and oracles and I will see to it that you are rewarded.", objectives = "" }
WordHunterWoW_QuestEN[26349] = { title = "The Coastal Menace", description = "When my life was ended upon the rocks, I had no clue what the afterlife held for me.  The Lighthouse was black that night because Old Murk-Eye had scared the keeper's family off.  They returned and re-lit the flame but Old Murk-Eye coerced the weaker minded murlocs to raid the Lighthouse with him once again.  The second time the family was not so lucky and before my eyes they perished helplessly.\n\nSlay Old Murk-Eye if you see him along the shore and bring me one of his scales and I shall reward you.", objectives = "" }
WordHunterWoW_QuestEN[26350] = { title = "Priestess Hu'rala", description = "Thank you, {name}.  I know you didn't have to save my life, and... well, I am thankful.\n\nThe return of Bloodlord Mandokir is ill news.  He was killed inside Zul'Gurub several years ago, and we thought we had seen the last of him and his kind.  The trolls of Zul'Gurub were attempting to perform a hideous, horrible ritual.  If Mandokir is alive, then it stands to reason that he is not the only one.\n\nThe trolls at Bambala in the east may know more.  Speak with their priestess.", objectives = "" }
WordHunterWoW_QuestEN[26351] = { title = "Mind Vision", description = "To know Mandokir, you must see Mandokir.\n\nTo see Mandokir, you must use eyes of raptor.\n\nYou have formed bond with raptor: Ohgan'aka: daughter of Ohgan.\n\nTo strengthen bond, we need feathers.\n\nYou will go west, and you will find the feathers, yes.", objectives = "" }
WordHunterWoW_QuestEN[26352] = { title = "Cozzle's Plan", description = "I may be of Darkspear birth, but I spent my childhood here, in Stranglethorn Vale.  I've seen everything there is to see here in Stranglethorn, but the most offensive is the devastation that the Venture Company has done to the riverbed.\n\nTo make things worse, Foreman Cozzle and his crew have been increasing their activity, and I suspect they have some new plan.  Succeed where I failed, {name}: Kill Cozzle, obtain his key, and steal the blueprints from his apartment.", objectives = "" }
WordHunterWoW_QuestEN[26353] = { title = "Captain Sanders' Hidden Treasure", description = "If ye be readin' this, it means that Ol' Captain Sanders is in a watery grave.  So my treasure is yours now, ye jest need to follow the clues. \n\nFirst ye need to find me footlocker.  It's probably half-buried in sand by now, along the Western Coast of Westfall near the shipwreck.  There be lots of shipwrecks but only one rusty anchor on the coast.  Find that anchor and you'll find me locker!  Look in there for the next clue.", objectives = "" }
WordHunterWoW_QuestEN[26354] = { title = "Captain Sanders' Hidden Treasure", description = "The clue to the treasure reads: Good work, matey!  Now ye need to head due east.  East up the bluffs, east to the road.  Look for the ol' chimney ruins near the side of the road.  There you'll find an old barrel with your next clue.", objectives = "" }
WordHunterWoW_QuestEN[26355] = { title = "Captain Sanders' Hidden Treasure", description = "Searching through the barrel you discover another piece of parchment.  This one reads:  Now from this here barrel, face ye North.  Straight as the crow flies, keep ye walkin' till you see the empty jug next to the lone windmill on the sea bluffs.  If ye poke around that jug, ye just might find what you're lookin' for.", objectives = "" }
WordHunterWoW_QuestEN[26356] = { title = "Captain Sanders' Hidden Treasure", description = "Sure enough, deep within the Old Jug there is another clue to Sanders' treasure.  The ink has run in some places and the paper smells like whiskey but you can make out some of the text:  Now that ye found me ol' whiskey jug, you're almost to the treasure!  Just face West from the bottle and walk down to the shore.  Once ye get to the water, keep going!  Swim straight west till you find the island with me treasure chest!", objectives = "" }
WordHunterWoW_QuestEN[26357] = { title = "Faces of Evil", description = "The Vilebranch have hung their tiki masks all across the walls of Jintha'Alor. The spirits not gonna be watchin' over them much longer.\n\nTake this torch with ya as ya fight through the Vilebranch, {class}. Set fire to their tiki masks. I'll be watchin' from here as their wards and hexes fade away, an' their heretical dark voodoo goes up in smoke.", objectives = "" }
WordHunterWoW_QuestEN[26358] = { title = "Ready the Air Force", description = "I gave Hellscream my personal guarantee that I'd have his airfleet ready this week, but our flagship - The Spear of Durotar - still doesn't have its primary engines installed.\n\nFleep promised me a dangerously shiny new engine last week. Go to her junkyard behind the bank and find out what the holdup is.\n\nThe airfleet is waiting on us, {name}!", objectives = "" }
WordHunterWoW_QuestEN[26359] = { title = "See Raptor", description = "We have the feathers, yes.\n\nWe have the {class}, yes.\n\nSpeak with Priestess when you are ready.", objectives = "" }
WordHunterWoW_QuestEN[26360] = { title = "Mind Control", description = "Mind Vision is not enough, no.\n\nMind Control, much more powerful magic, yes.\n\nPowerful magic needs powerful reagents, and troll brain is a powerful reagent.\n\nBraddok in Zul'Mamwe, very smart, yes.\n\nHead south, and check out the big brain on Braddok.", objectives = "" }
WordHunterWoW_QuestEN[26361] = { title = "Smoot's Samophlange", description = "It was the Captain who insisted his new engines use an induction samophlange.\n\nThose things hadn't even been invented yet!\n\nI tasked Smoot with creating one based on some stolen Venture Company schematics, and he's finally built a working model.\n\nNow that he's got his samophlange, he's drunk with power. He's running all over town with it like a goblin possessed.\n\nSmack Smoot and snag my samophlange, {name}.", objectives = "" }
WordHunterWoW_QuestEN[26362] = { title = "Be Raptor", description = "Mind Control, very powerful, yes.\n\nWith luck, you can help Ohgan'aka escape from Zul'Gurub.\n\nThen, Ohgan'aka becomes {name}'aka again!\n\nSpeak to Priestess, yes, and help {name}'aka escape.", objectives = "" }
WordHunterWoW_QuestEN[26363] = { title = "Summit of Fate", description = "You've done well cleaving through their warriors, {name}. I'd like you to investigate the summit of Jintha'Alor.\n\nWe were prepared for our fiercest battle there, to storm their dark altar, but it's too quiet. Not a sound. It could be a terrible trap, and someone strong should look into it first instead of all of us rushing in.\n\nAnd if it's not a trap... I'm very interested in finding out what happened up there. Bring me back any clues you can find.", objectives = "" }
WordHunterWoW_QuestEN[26364] = { title = "Down with Crushcog!", description = "Our cousins, the dwarves of Ironforge, have agreed to help us in the battle against Razlo Crushcog. Mountaineer Stonegrind is a veteran who knows Dun Morogh well. He and High Tinker Mekkatorque stand ready on a small snow-covered island in Iceflow Lake to the north. Meet up with them there and let the high tinker know when you are ready to face the traitor Crushcog.\n\nTake this orbital targeting device and use it during the battle. It will help guide the high tinker's special weapons.", objectives = "" }
WordHunterWoW_QuestEN[26365] = { title = "Hero's Call: Redridge Mountains!", description = "While the situation here is dire, other parts of the region are literally quaking from the great upheaval.\n\nI have here a report from Watch Captain Parker of Redridge Mountains, one of our territories east of Elwynn Forest. He is asking for a hero to come to their aid.\n\nWe are spread so thin here that I don't know how we can afford to send anymore military. Would you check on Parker and see what he needs? You will find Watch Captain Parker atop the tower at Three Corners.", objectives = "" }
WordHunterWoW_QuestEN[26366] = { title = "Heads Up", description = "Umboda of the Vilebranch is one of their strongest warriors, and a sick butcher.\n\nHe takes the heads of all he slays as trinkets, rewards...even weapons!  It's his turn to be taken.\n\nFind Umboda \"Three-Heads\", slay him, and bring me HIS head! We'll see how the Vilebranch fight when we throw it back over their walls!", objectives = "" }
WordHunterWoW_QuestEN[26367] = { title = "Ongo'longo's Revenge", description = "Ongo'longo was one of us. What outsiders called a Dire Troll, but he was a Revantusk, and a proud warrior like all of us!\n\nThen the Vilebranch took him. They keep him chained up in a pit at the top of Jintha'Alor, made to dance for their sick amusement.\n\nNo chains can hold Ongo'longo. All you need to do is raise his temper, {name}. Fight him until he's enraged enough to remember his true spirit and break free... and then get out of the way!", objectives = "" }
WordHunterWoW_QuestEN[26368] = { title = "Venomous Secrets", description = "There's more of this curious venom to be had if Shadra's being summoned.\n\nDon't look so surprised... the Forsaken have studied these lands before, and we've encountered the venom queen at least once. Her toxins have proven quite useful in the past.\n\nThey'll prove useful to the Horde once more, too. Be a dear and fetch me as much poison as you can from the spawn of Shadra that lurk in the cave on the summit... I'm sure you'll be covered in it anyway.", objectives = "" }
WordHunterWoW_QuestEN[26369] = { title = "Hunt the Keeper", description = "Kotonga has told me of Shadra. She is the venom queen, the loa of spiders, worshipped in darkness. If the Vilebranch are performing rituals, I'm not going to let them finish.\n\nCheck the cave behind the altar at the top of Jintha'Alor. Deep within it, one of Shadra's keepers might still be lurking. Kill her and take whatever she carries back here so we can know what's going on.", objectives = "" }
WordHunterWoW_QuestEN[26370] = { title = "Return to Sentinel Hill", description = "The Defias Brotherhood are not a force to be taken lightly, {name}. What you witnessed was the birth of a ruthless organization of criminals that will stop at nothing to see Stormwind turned to rubble.\n\nI need you to return to Sentinel Hill and let Gryan know that we are sending him troops. I hope it's not too late.", objectives = "" }
WordHunterWoW_QuestEN[26371] = { title = "The Legend of Captain Grayson", description = "Have you heard of Captain Grayson? Some say that he's the figment of a drunken sailor's imagination, but anyone in Westfall will tell you that Grayson is real! He's a ghost that haunts the Westfall Lighthouse far to the west, off the coast of the Longshore.\n\nDo you dare investigate?", objectives = "" }
WordHunterWoW_QuestEN[26372] = { title = "Pre-Flight Checklist", description = "This new engine is extremely fast. And dangerous. I'd use the word \"volatile.\"\n\nThat's the way the Captain likes it.\n\nRun back up the hill and let him know that I'll install this bad boy right now and that he should meet me at the construction site.", objectives = "" }
WordHunterWoW_QuestEN[26373] = { title = "On to Kharanos", description = "Some of the mountaineers under Stonegrind's command were telling me about the situation out at Kharanos. When the troggs took over Frostmane Hold, it sounds like the surviving trolls fled westward, deep into the heart of the dwarven homeland.\n\nNow, they threaten the dwarven town of Kharanos. It sounds like they're going to need all the help they can get. You should go to Kharanos and introduce yourself to Captain Tharran. Just follow the road east out of Brewnall and keep going until you see the town.", objectives = "" }
WordHunterWoW_QuestEN[26374] = { title = "Ready the Ground Troops", description = "It was a bad idea to muster the troops in this festering goblin metropolis. Every vice that coin can buy is within arm's reach. Our mighty veterans are running rampant, blowing years of Northrend back-pay in a city-wide debacle.\n\nCan you make a sweep through the city and gather up any stragglers that have gone AWOL?\n\nMy axebite warriors are unmatched on the battlefield, but I won't have them disgrace their uniforms while on shore leave.", objectives = "" }
WordHunterWoW_QuestEN[26375] = { title = "Loose Stones", description = "The Twilight Cultists are taking my rocklings among them.  They drain them and torture them.  Strip them of the very essence that animates them from the stone.\n\nPlease, {race}, free my rocklings. Neither Diamant nor I have the delicacy to smash their chains without hurting them as well.  But we do have a tool you might use.\n\nUse this. Break their chains and set them free.", objectives = "" }
WordHunterWoW_QuestEN[26376] = { title = "Hatred Runs Deep", description = "I would apologize for Boden, but stone is stubborn.\n\nIt does not sway from its ways without the wear of time.\n\nThe Stone Lords, Boden and I among them, are charged with retrieving the World Pillar.\n\nIn that, we are at odds.\n\nI would extend my patience upon you, {race}.\n\nProve that you are no ally of the Twilight Cult or Deathwing...\n\nCarry our hatred upon them.\n\nStrike swiftly where we cannot.\n\nSucceed and I will listen.", objectives = "" }
WordHunterWoW_QuestEN[26377] = { title = "Unsolid Ground", description = "The Twilight Cult are mining jade crystals near their camp.\n\nFoolish...\n\nReckless...\n\nGather the mined crystals. Take them to the center of their camp. Shatter them against the ground.\n\nThe reverberations and the powered crystal will bring the tunnelers upon them.\n\nThey will learn respect for the earth...\n\nPiece by piece...\n\nRock by rock...\n\n...with time.", objectives = "" }
WordHunterWoW_QuestEN[26378] = { title = "Hero's Call: Westfall!", description = "Westfall has fallen to hard times, friend. With the threat of the Defias extinguished, the region has become a haven for the homeless and downtrodden. The crime rate of the area has skyrocketed as people fight for shelter and food. Now I hear tale of murder!\n\nIf you are interested in helping the people of the Alliance, Westfall would be a great place to start. Report to Lieutenant Horatio Laine at the Jansen Stead. You'll find Westfall directly west of Elwynn Forest.", objectives = "" }
WordHunterWoW_QuestEN[26379] = { title = "In Aid of the Refugees", description = "You're come to help, I hope? You have no idea what I'm talking about, do you...\n\nI don't have time to fill you in on all of the details, but we had a town in Darkshore, Auberdine, that took some of the worst of the Cataclysm. We're in the process of rescuing some of the survivors, but I need someone with a bit more experience--someone like you--to check in on a refugee camp that we heard about in the south.\n\nLeave things to us up north. Head straight down there and help the refugees however you can.", objectives = "" }
WordHunterWoW_QuestEN[26380] = { title = "Bound for Kharanos", description = "I was supposed to be bringing these casks of ale to the inn in Kharanos. They contain a mysterious new ale produced by an upstart brewery based in Brewnall Village. As I was leaving town, I was attacked by a Frostmane troll raiding party. It's going to take me days to repair the wagon!\n\nI don't suppose you'd be willing to do me a favor, will you? These big kegs aren't going anywhere, but I have some smaller sample casks. Would you bring them to Kharanos for me? Just follow the road to the southeast.", objectives = "" }
WordHunterWoW_QuestEN[26381] = { title = "The Eye of Shadra", description = "Shadra must be summoned, for certain. To allow an opportunity like this to pass us by would be foolish. While the apothecaries can make fine use of the god's venom, they are relatively inexperienced in ritual magic.\n\nFortunately, I am quite familiar with preparing dark convocations. You will bring the scattered parts of Shadra to me, and I will help you bring her to this plane to be taken out.\n\nThe first part is the eye of Shadra, guarded in Agol'watha to the north.", objectives = "" }
WordHunterWoW_QuestEN[26382] = { title = "Can't Make An Omelette Without...", description = "Marnal has been pestering me about this Shadra plot for days. I'm almost upset he actually found the tablet; I was ready for him to shut up about it.\n\nDespite his high talk of ritual magic, he's still going to need my help as much as I need his. I've got to whip up a base medium with similar...\n\n...You know what, I'm not going to bother rambling about the details. Just bring me the Shadraspawn eggs from Agol'watha. There should be quite a few, guarded by the Vilebranch trolls.", objectives = "" }
WordHunterWoW_QuestEN[26383] = { title = "Breaking Waves of Change", description = "You! You look able. And perhaps willing to help?\n\nAuberdine has finally fallen. Though many of its inhabitants departed long ago when the city first suffered the brunt of the Cataclysm, many of the more stubborn residents are yet unaccounted for. And it now appears that the city may have been overrun by water elementals.\n\nMy sisters need help rescuing the survivors. Please, {class}, use the western tree to reach Rut'theran, then speak to Vesprystus to secure a flight to Lor'danel. Be swift!", objectives = "" }
WordHunterWoW_QuestEN[26384] = { title = "Darkcleric Marnal", description = "We can't toss that tablet aside just yet, {name}. We can use it...\n\nYou see, I'm quite taken with the venom of the spiders here. It's clearly magical, probably related to that spider-god the trolls are involved with. And if that tablet will allow someone to summon it...\n\nWell, you can see where this is going. The Horde can't pass up this opportunity. Take the tablet to my fellow Forsaken. They're to the west, at the research station in the Hiri'watha ruins.", objectives = "" }
WordHunterWoW_QuestEN[26385] = { title = "Breaking Waves of Change", description = "It seems you have your first charge. You must travel back down to Rut'theran Village, where we first arrived, and speak to Vesprystus to secure a ride to Lor'danel.\n\nOnce in Lor'danel, aid the night elves in any way that you are able. I am trusting you to treat them with the reverence that they deserve in light of all that they have done for us.\n\nI must travel to the distant city of Stormwind to meet with King Anduin. I hope to see your face again very soon, {name}. Until then, a fond farewell.", objectives = "" }
WordHunterWoW_QuestEN[26386] = { title = "Surkhan", description = "Priestess is not very good at speaking Orcish, no.\n\nMaybe you go speak with Surkhan, upstairs.\n\nTell him about what you've seen inside Zul'Gurub, yes.", objectives = "" }
WordHunterWoW_QuestEN[26387] = { title = "Starvation Diet", description = "The spiders infesting the Creeping Ruin to the east are useless. We're calling them shadraspawn now, and it's clear they're related to the spider god, but that doesn't change the fact that they're more trouble than they're worth. I'd much rather just wipe the little pests out.\n\nWhen you head to the creeping ruin, destroy any cocoons you find. They feed off the bodies inside for days, so depriving them of their meal will be much more effective than trying to squash them all.", objectives = "" }
WordHunterWoW_QuestEN[26388] = { title = "Twilight Skies", description = "Okay, you're all checked in. Wait here for Captain Krazz to bring the zeppelin around, then get on board and accompany the air fleet. Admiral Stonefist will be waiting for you outside of Dragonmaw Port!", objectives = "" }
WordHunterWoW_QuestEN[26389] = { title = "Blackrock Invasion", description = "The orcs have begun burning down the forest, {name}! They have taken over the vineyard to the east and are planning their final assault against us! They must be stopped!\n\nHead east, across the river, and kill the rampaging Blackrock orcs. Collect their weapons as proof of their demise and return to me.\n\nYou're our only hope, {name}!", objectives = "" }
WordHunterWoW_QuestEN[26390] = { title = "Ending the Invasion!", description = "The rampaging orc horde is led by a savage beast known as Kurtok the Slayer! Kurtok is responsible for the recent invasion and must be killed if we are to have peace in the valley.\n\nVenture back east, across the river and through the vineyard, and look for the passage leading into the mountains. Kurtok will be there, preparing for another assault. Kill him and return to me.", objectives = "" }
WordHunterWoW_QuestEN[26391] = { title = "Extinguishing Hope", description = "Times like these make me long for when the Defias were still around. The cataclysm has opened a pathway from the Burning Steppes and now Blackrock orcs pour into Northshire Valley! They have taken over my vineyard and are burning it to the ground! TO THE GROUND!\n\nPlease, {name}, that vineyard is all I have. Take my fire extinguisher and extinguish the flames at the vineyard. There still might be hope for that land!", objectives = "" }
WordHunterWoW_QuestEN[26393] = { title = "A Swift Message", description = "Although we don't get much aid from Stormwind directly, I do have a contact in the city who helps supply us with armor.  His name is Osric Strang.  His shop, Limited Immunity, is in the Old Town of Stormwind.\n\nOur supply of armor dwindles, and I must contact Osric for more.  Can you take him this note?\n\nThe fastest way to Stormwind is through Bartlett the Brave, our gryphon master.  He's just outside of the smithy; bring him my note, and then take a gryphon to Stormwind.", objectives = "" }
WordHunterWoW_QuestEN[26394] = { title = "Continue to Stormwind", description = "For a small fee, you can take a gryphon to Stormwind, so you can deliver Argus' note to Osric.  You won't get there faster any other way.\n\nIf that sounds acceptable, then just speak to me again when you're ready for the ride.  I'll charge you a little, but trust me; it'll be worth it!", objectives = "" }
WordHunterWoW_QuestEN[26395] = { title = "Dungar Longdrink", description = "{name}, I gathered into this crate everything Argus asked for.  Can you take it to him?\n\nIf you've already spoken to Bartlett at Goldshire, then you can take a gryphon back to him.  Dungar Longdrink is our gryphon master, over in the trade district.\n\nSpeak with Dungar, then get this crate to Argus as fast as you can.  We don't want our fighting men and women in Goldshire to go without fresh equipment!", objectives = "" }
WordHunterWoW_QuestEN[26396] = { title = "Return to Argus", description = "The gryphon master in Goldshire is Bartlett.  If you've spoken to him before, then you can take one of my gryphons to him.\n\nThat's a good lesson to know: gryphons are always trained to fly to their capital city, but they'll only take you to a remote gryphon master after you've already been there.\n\nYou've already been to Bartlett, so just speak with me again when you're ready to take a gryphon to Goldshire.  Once there, you can deliver Osric's Crate to Smith Argus.", objectives = "" }
WordHunterWoW_QuestEN[26397] = { title = "Walk With The Earth Mother", description = "Much has changed outside of Mulgore, {name}. The world is torn, and our Horde allies have turned down dark paths. We must guide them. Even in the darkest hour, we will bravely hold our heads high, and honor the Earth Mother in all we do.\n\nYou must go, {name}, and be this example. Go to Orgrimmar. Tell Saurfang how the Grimtotem were driven out. Let him know our pride and discipline, our strength and sorrow.\n\nTal at the Skytower will send you on your way. Go in peace, and never forget your people.", objectives = "" }
WordHunterWoW_QuestEN[26398] = { title = "Walk With The Earth Mother", description = "You have fought bravely alongside me, {name}, and done much for my people. If every {race} could be as noble, the future of the Horde might not disturb me so much.\n\nI would ask you to ease my worries further. Go to Orgrimmar. Tell High Overlord Saurfang how the Grimtotem were driven out. Let him know our pride and discipline, our strength and sorrow.\n\nTal at the Skytower will send you on your way. Go in peace, friend.", objectives = "" }
WordHunterWoW_QuestEN[26399] = { title = "The Mosh'Ogg Bounty", description = "Say... have you heard about the ogres?  I got a hot tip from some fella' named Mok'thardin that some {race} schmuck in a ridiculous {class} getup found this ogre hand, and...\n\n<Skeezy trails off as he looks you over.>\n\nWhat was I just saying?  Oh yes... some SWASHBUCKLING HERO found this ogre hand, and Mok'thardin thinks it means that the ogres have some special artifact.  I've seen them guarding a chest up in some ruins behind their mound.  Care to fetch it for me?", objectives = "" }
WordHunterWoW_QuestEN[26400] = { title = "The Universal Key", description = "We're going to need something even stronger than those beefy {race} hands of yours to open this.  And the Venture Company schlubs to the northwest might have just the thing.\n\nLast time I was over there, I saw shredders walking around with giant rotating blades on their hands.  That's one way to open a box!\n\nIf you can't find any shredders, you might also try the giant sawblade in their lumber mill, by the lake.", objectives = "" }
WordHunterWoW_QuestEN[26401] = { title = "Return to Vestia", description = "The soft glow from the pedestal brightens, and you can see a simple chain left behind. Is this what the apprentice was searching for?", objectives = "" }
WordHunterWoW_QuestEN[26402] = { title = "General Shandris Feathermoon", description = "We druids do not keep very close company with the Sentinel army, but we are always willing to work together to defend our lands. Now that you have assisted me, I would be remiss in not requesting you assist them as well.\n\nShandris Feathermoon, general of the Sentinels, commands the war effort for all of Kalimdor from the newly built Feathermoon Stronghold to the south. Tell her I sent you; I am sure she will have need of your skills.", objectives = "" }
WordHunterWoW_QuestEN[26403] = { title = "Venture Company Mining", description = "Man, I hate the Venture Company.  They have a string of operations through Stranglethorn which keeps hard-working goblins, like me, from making honest gold!\n\nMy way? Theft. The Venture Co. geologists near Lake Nazferiti to the northwest are deeply interested in those strange blue crystals they have been finding in the mines.  Bring me samples of the stone from their geologists.  I don't care what you have to do to get them. ", objectives = "" }
WordHunterWoW_QuestEN[26404] = { title = "Above My Pay Grade", description = "Hey, have you been to Hardwrench Hideaway yet?  Oh, you've GOT to see it.  It's everything a goblin could ever hope for.\n\nTell you what... you look like a stand-up {class}.  Raskha in the vest and the skirt over here can give you a ride, if you don't already know the way.\n\nThe flight's on me.", objectives = "" }
WordHunterWoW_QuestEN[26405] = { title = "Zul'Mamwe Mambo", description = "The Skullsplitters are an embarrassment to the troll empire.  Their petty squabbles with the Bloodscalps have torn Northern Stranglethorn apart.  Where tribes like the Darkspear and the Zandalari thrive, the Skullsplitters fight over ruins.\n\nI have been authorized to issue rewards to mercenaries who are willing to deliver punishment to the Skullsplitters.  I encourage you, and anyone you know, to travel south to Zul'Mamwe and cull their wayward tribe.", objectives = "" }
WordHunterWoW_QuestEN[26406] = { title = "The Fang of Shadra", description = "We'll need the Fang of Shadra next.\n\nIt's kept in the Creeping Ruins to the east, guarded by Shadra's own spawn.  Their venom is strong, {name}... don't get careless.", objectives = "" }
WordHunterWoW_QuestEN[26407] = { title = "Mosh'Ogg Handiwork", description = "This ogre was carrying an unusual item: the severed hand of another ogre, tied to a piece of string, and worn around the neck.  The hand itself is marked heavily with scars that glow a faint purple.\n\nA scar that glows after death is highly unusual, and to find such an item on an ogre is even stranger.  Perhaps someone back at Grom'gol will know what to do with this oddity.", objectives = "" }
WordHunterWoW_QuestEN[26408] = { title = "Ashes in Ashenvale", description = "Darkshore may be battered and broken, but thanks to you, we've achieved some amount of safety here. Some amount of peace. We've much rebuilding to do.\n\nYou should continue on, friend. Garrosh has pressed the full might of his Horde against us in Ashenvale. They will kill all of us and chop the forest clear if we don't step forward to stop them.\n\nIf we are to have any hope of not losing those forests entirely, we'll need your help. Follow the road to the south and find Sentinel Shyela.", objectives = "" }
WordHunterWoW_QuestEN[26409] = { title = "Where's Goldmine?", description = "My goblin initiate has been gone for quite some time. His name is Goldmine.\n\nI sent him out to observe the local rock flayers southwest at the Quartzite Basin. Perhaps you would be willing to find him? When you do, please ask him to come back to the temple.", objectives = "" }
WordHunterWoW_QuestEN[26410] = { title = "Explosive Bonding Compound", description = "This guy's the son of the Earthen leader! He almost made it to the temple when he got ambushed by more rock flayers than I can count!\n\nWe know that the Earthen Stonefather has the middle fragment of the World Pillar. Maybe if we were to heal his son, the Stonefather would give us the fragment?\n\nMy heals won't work on Flint here. But if we were to get some of the quartzite resin off of these monsters, I think I can make an explosive compound that will bond and cauterize his wounds.", objectives = "" }
WordHunterWoW_QuestEN[26411] = { title = "Apply and Flash Dry", description = "Alright, take this and apply it to his wounds. If the cauterizing effect of the flash dry explosion doesn't crack him wide open, it should completely heal him.\n\nI think.", objectives = "" }
WordHunterWoW_QuestEN[26412] = { title = "The Mosh'Ogg Bounty", description = "Say... have you heard about the ogres?  I got a hot tip from some fella' named Mok'thardin that they're hiding some special, magical artifact in their cave.  Skeezy knows better, though.  I can smell money from a Mulgore mile away, and I'll bet that ogre doodad's worth a fortune.\n\nHere's a hint: I've seen them guarding a chest up in some ruins behind their mound.  Care to fetch it for me?", objectives = "" }
WordHunterWoW_QuestEN[26413] = { title = "Take Him to the Earthcaller", description = "He still looks a little loopy to me. His head must still be ringing.\n\nBest get him inside the temple and see what the Earthcaller wants to do with him.\n\nI think I'm going to stay out here a little while longer and \"observe\" these rock flayers.", objectives = "" }
WordHunterWoW_QuestEN[26414] = { title = "Hitting a Walleye", description = "Sometimes, I fish for fun.  Other times to relax, but sometimes I want a challenge.  That's where the hardened walleye comes into the picture.  This prized fish is not caught for us to eat, but for the challenge.  You can find the walleye in Stormwind Lake just north of the city.  Think you are up to the challenge?", objectives = "" }
WordHunterWoW_QuestEN[26416] = { title = "Well, Come to the Jungle", description = "My commander has sent me to scout for potential recruits to assist in the defense of Grom'gol Base Camp in Northern Stranglethorn.  Are you familiar with Stranglethorn?  It's a long way away... across the Great Sea, on the southern tip of the Eastern Kingdoms.  You fit the build he was looking for... interested in leaving Kalimdor for a while?\n\nIf so, then go talk to my cohort Bort in Orgrimmar.  He'll help you board the zeppelin.\n\nAnd tell him I said \"Woozle wozzle.\"  He'll know what it means.", objectives = "" }
WordHunterWoW_QuestEN[26417] = { title = "Northern Stranglethorn: The Fallen Empire", description = "Commander Aggro'gosh is looking for devoted members of the Horde to assist him and his mission in Grom'gol.  If you're interested, just hop on up to the top of that zeppelin tower and board the Grom'gol zeppelin.  It's that easy!\n\nSeriously, Stranglethorn is the place to be right now... there's plenty of action to be found, and not nearly as much cataclysmic damage as, say... Stonetalon Mountains.  I wish I could go with you.", objectives = "" }
WordHunterWoW_QuestEN[26418] = { title = "The Shell of Shadra", description = "We've one last part to collect, and then we'll have everything we need.\n\nThe Shell of Shadra is held by the spider god's last living high priestess, Qiaga the Keeper. She stands atop the Altar of Zul, guarded by other fanatical zealots.\n\nSimple enough, no? Get up the steps of the altar and send her head rolling back down them. Bring the shell to me and we will have Shadra at last.", objectives = "" }
WordHunterWoW_QuestEN[26419] = { title = "Shadra the Venom Queen", description = "<The ground rumbles as the idol sits on the altar, and the lake below roils! Shadra is emerging!>", objectives = "" }
WordHunterWoW_QuestEN[26420] = { title = "Diggin' For Worms", description = "Hey there, Angler!  Arnold here tells me that you have been looking for a new fishing spot and I think I know just the place.  North of Stormwind there is a great little spot called Olivia's Pond.\n\nThe pond is stocked with crystal bass every year but they are hard to catch.  They only bite on a very specific type of bait... overgrown earthworms.  If you search the shore around the pond, you should find plenty of worms to use as bait.", objectives = "" }
WordHunterWoW_QuestEN[26421] = { title = "Meet the High Tinker", description = "I don't know if you'll remember Mekkatorque or not. Nevin tells me that memory loss is pretty common for a Gnomeregan survivor.\n\nMekkatorque, or more properly, the High Tinker Mekkatorque is the leader of all the gnomes. He has made a habit of meeting with every rescued survivor personally. You should introduce yourself to him. He'll be with his war council beneath the tent in the center of town.", objectives = "" }
WordHunterWoW_QuestEN[26422] = { title = "Meet the High Tinker", description = "I don't know if you'll remember Mekkatorque or not. Nevin tells me that memory loss is pretty common for a Gnomeregan survivor.\n\nMekkatorque, or more properly, the High Tinker Mekkatorque is the leader of all the gnomes. He has made a habit of meeting with every rescued survivor personally. You should introduce yourself to him. He'll be with his war council beneath the tent in the center of town.", objectives = "" }
WordHunterWoW_QuestEN[26423] = { title = "Meet the High Tinker", description = "I don't know if you'll remember Mekkatorque or not. Nevin tells me that memory loss is pretty common for a Gnomeregan survivor.\n\nMekkatorque, or more properly, the High Tinker Mekkatorque is the leader of all the gnomes. He has made a habit of meeting with every rescued survivor personally. You should introduce yourself to him. He'll be with his war council beneath the tent in the center of town.", objectives = "" }
WordHunterWoW_QuestEN[26424] = { title = "Meet the High Tinker", description = "I don't know if you'll remember Mekkatorque or not. Nevin tells me that memory loss is pretty common for a Gnomeregan survivor.\n\nMekkatorque, or more properly, the High Tinker Mekkatorque is the leader of all the gnomes. He has made a habit of meeting with every rescued survivor personally. You should introduce yourself to him. He'll be with his war council beneath the tent in the center of town.", objectives = "" }
WordHunterWoW_QuestEN[26425] = { title = "Meet the High Tinker", description = "I don't know if you'll remember Mekkatorque or not. Nevin tells me that memory loss is pretty common for a Gnomeregan survivor.\n\nMekkatorque, or more properly, the High Tinker Mekkatorque is the leader of all the gnomes. He has made a habit of meeting with every rescued survivor personally. You should introduce yourself to him. He'll be with his war council beneath the tent in the center of town.", objectives = "" }
WordHunterWoW_QuestEN[26426] = { title = "Violent Gale", description = "There is a task that I can set before you.\n\nIt is a dangerous task. Completing it will help impress the more stubborn Stone Lords.\n\nTo the northwest is the Scoured Reach. Severe winds batter the rock and hide the true living threat underneath.\n\nWithin the Scoured Reach are Gyreworms. They devour rock and move through it as if it were water. They do the same thing to our rocky skin.\n\nFind Felsen the Enduring. Have him direct you to the Crumbling Depths. I will speak to you once you get that far.", objectives = "" }
WordHunterWoW_QuestEN[26427] = { title = "Without a Captain or Crew", description = "Not sure who you're with, but you don't look like one of... them.\n\nI'm not sure what happened.  I slept through supper and woke up to a ship full of dead people and murderers.\n\nNot sure if you want to kill me or not, but I'll spare you the trouble.\n\n<Moody points to a wound in his stomach.  His insides are not where they should be.>\n\nI can keep steering the ship for a while longer.  You don't die from a gut wound immediately.  Just bring me some rope and some rum... no, whiskey.", objectives = "" }
WordHunterWoW_QuestEN[26428] = { title = "To Steal From Thieves", description = "The harlot! The swine! Kenata still lives; her family healthy and prospering while I suffer. Forsaken indeed!\n\nMy family is gone, taken by the plague. Our estate also forfeit; looted and burned during the war. And after all that, she and her lousy children had the audacity to steal the only precious belongings I had left.\n\nI don't care about the things they stole any more. What I want now are their heads!\n\nKill them for me! Go to the Dabyrie Farmstead in Arathi, northeast of Refuge Point.", objectives = "" }
WordHunterWoW_QuestEN[26429] = { title = "Crush the Witherbark", description = "The Witherbark trolls and Boulderfist ogres of Arathi are working together to rid us from this land, but we shall not meet our fates at their, or anyone else's, hand. We will slay them and show them that we, too, have a home here. \n\nThe trolls turned their backs to us; the ogres would use us for food and bedding if we allowed them to--these things shall not be.\n\nWe start our attack on the Witherbark trolls to the south of here. Slay them in droves, and only return when their camps run thick with blood.", objectives = "" }
WordHunterWoW_QuestEN[26430] = { title = "Revantusk Village", description = "Not all forest trolls are foul nuisances like the Witherbark. North of here in the Hinterlands is Revantusk Village, home to the only forest troll tribe still allied with the Horde.\n\nEven they cannot escape the cruelty of their brethren. The Vilebranch tribe wars with them, distracting them from our battle with the Alliance.\n\nYou have fought well here. Speak with Urda if you wish to fly to Revantusk. Their village will have use of your strength.", objectives = "" }
WordHunterWoW_QuestEN[26432] = { title = "The Fall of Jintha'Alor", description = "We've got more to deal with than just dwarves, mon. While I watch the village, my mate Primal Torntusk has gone to lead our warriors against the wicked Vilebranch tribe.\n\nThey've killed our brothers, and I was even taken prisoner by them once. No more! This time, the city of Jintha'Alor falls to us.\n\nGo to Jintha'Alor and speak with my mate. She's captured a camp near the entrance to the city.", objectives = "" }
WordHunterWoW_QuestEN[26433] = { title = "The Holy Water of Clarity", description = "Skeezy said you'd be coming.  Let's identify this... thing.\n\nTo start out, I'm going to need you to obtain The Holy Water of Clarity.  The nagas to our southeast maintain a hallowed shrine that dispenses a water so clean, so fresh, and so mouthwateringly pure, that when the imbiber quaffs but a mouthful of the sacred stuff, their mind is cleansed and their best path made clear.\n\nSounds good, doesn't it?\n\nObtain it from the Nek'mani Wellspring at the peak of the naga camp.  Good luck!", objectives = "" }
WordHunterWoW_QuestEN[26434] = { title = "Primal Reagents of Power", description = "I see clearly now... the key to identifying this mysterious talisman revolves around obtaining some rare and precious items.  These Primal Reagents of Power, when properly combined, will reveal to us the origin of our treasure.\n\nTravel north, to the western side of the Gurubashi Arena, and hunt the cats that roam the jungle.  Their fleecy furs will lead us to the truth!", objectives = "" }
WordHunterWoW_QuestEN[26435] = { title = "I'm A Huge Liar and a Fraud", description = "I have no idea what this artifact is.  I have no idea where I would even START finding out what it is.\n\nIn fact, I have no idea why anybody expected ME to be able to identify it in the first place.\n\nI asked for water because I was thirsty.  I asked for the jewelry and furs for... well, they're for my girlfriend.\n\nHopefully I can at least point you in the right direction.  Garley Lightrider in Booty Bay is a member of the Reliquary, and might be of more use than me.\n\nSorry.", objectives = "" }
WordHunterWoW_QuestEN[26436] = { title = "Entrenched", description = "Your intentions appear true.\n\nI will impress upon the other Stone Lords my wary trust.\n\nWith this, they should speak to you.\n\nMore importantly, they should listen.\n\nEarning their favor may take time. Earning the Stonemother's favor may take more time. Time is a potent offering, so be generous with it.\n\nAmong the Shuddering Spires far to the northwest, you shall find Kor the Immovable. He is evenly tempered. His situation lends itself well to seeking outside aid.\n\nGo to him.", objectives = "" }
WordHunterWoW_QuestEN[26437] = { title = "Making Things Crystal Clear", description = "Among the Shuddering Spires are crystals. White, chalky crystals. We can absorb these crystals into our skin. To cleanse us. Purify us.\n\nI do not stride among the stones any longer. I am one with the earth. This carries many boons, but I can no longer retrieve the crystals for myself.\n\nBring me the crystals that I might be stronger. Carry them away from the flayers. Away from my sons. This honor should be mine.", objectives = "" }
WordHunterWoW_QuestEN[26438] = { title = "Intervention", description = "The flayers have gone crazy with hunger. Their digging was once tempered and moderate. Now their hunger cannot be quenched. They grow murderously violent.\n\nThe flayers have turned on my sons. They overwhelm them. Kill them. It must stop.\n\nKill the flayers. They serve no purpose to the earth. Their passing will not be missed. Save my sons. Slaughter any flayers you find.", objectives = "" }
WordHunterWoW_QuestEN[26439] = { title = "Putting the Pieces Together", description = "{race}. If you act in the service of the Stone Lords, there are those that might aid you.\n\nWatch for the Stonebound. They lie dormant all around the Shuddering Spires. It should not take much prompting to rebind them to service against the flayers.", objectives = "" }
WordHunterWoW_QuestEN[26440] = { title = "Clingy", description = "<A miniscule elemental seems to have taken a liking to you.>\n\nCaris... carstr... crystal? <Pebble looks up at you expectantly.>\n\n<You did notice a very large crystal formation towards the middle of the Shuddering Spires. Perhaps you should take him there?>", objectives = "" }
WordHunterWoW_QuestEN[26441] = { title = "So Big, So Round...", description = "<Pebble looks around, excited by something. After a few seconds of confusion, he stops and stares up at you with big, glowy gem eyes.>\n\nHug-nery... hungry...\n\n<Try as you might, there's no resisting those eyes. Maybe Kor knows what mini-mentals like to eat?>", objectives = "" }
WordHunterWoW_QuestEN[26442] = { title = "Rock Lobster", description = "If I could choose my last meal, it would definitely be fresh lobster tail.  Something about that tasty crustacean is just irresistible!  We recently started trapping lobsters here in Stormwind.  Would you mind heading out and checking the traps for me?\n\nOne more thing, watch out for the sharks.  They can be vicious down there.", objectives = "" }
WordHunterWoW_QuestEN[26443] = { title = "Diabolical Plans", description = "The demon dropped this parchment, which is amazingly written in the Common tongue!  The ones mentioned in it, Diathorus and Gorgannon, are the two infamous dreadlords that control the demons hereabouts.\n\nThe plans detail preparations for a demonic attack on Forest Song to the north, the location where a new draenei settlement is being established.\n\nPerhaps Vindicator Vedaar at the Warsong Lumber Camp would be interested in these?", objectives = "" }
WordHunterWoW_QuestEN[26444] = { title = "Destroy the Legion", description = "I will not tolerate their existence on this world! The Burning Legion all but destroyed our race and we fell back to settle a new home on a new world. Then they came again and we retreated, over and over.\n\nNo more!\n\nThere is a remnant of the Legion to the south and west in the regions known as Felfire Hill, Demon Fall Canyon and Demon Fall Ridge. They are what is leftover from a force that once long ago invaded this world.\n\nGo and destroy as many as you can before it is too late!", objectives = "" }
WordHunterWoW_QuestEN[26445] = { title = "Never Again!", description = "{name}, it falls to you to see that this attack by the Burning Legion never comes to pass. You must go and slay their leaders.  Without them the demons will be mindless.\n\nYou will find Gorgannon in Demon Fall Canyon south beyond Felfire Hill, near Mannoroth's floating, broken spear.\n\nDiathorus the Seeker resides somewhere in the barrow den atop Demon Fall Ridge. To find the ridge, look for a ramp up from Demon Fall Canyon near the Horde's monument to Grom Hellscream.\n\nBring me their weapons.", objectives = "" }
WordHunterWoW_QuestEN[26446] = { title = "Reclaiming Felfire Hill", description = "Little one, to the southwest is an area of Nightsong Woods that has in recent times come to be called Felfire Hill. It is very sad to see the demons crawling over it, spreading their corruption.\n\nWould you do something to help take back the land?\n\nI have a number of seeds that I have been saving for such a purpose. Take them to Felfire Hill and plant them in the fertile dirt mounds.", objectives = "" }
WordHunterWoW_QuestEN[26447] = { title = "Diabolical Plans", description = "The demon dropped this parchment, which is amazingly written in the Orcish tongue!  The ones mentioned in it, Diathorus and Gorgannon, are the two infamous dreadlords that control the demons hereabouts.\n\nThe plans detail preparations for a demonic attack on Splintertree Post to the northwest.\n\nYou're certain that Valusha at Splintertree Post would be interested in these.", objectives = "" }
WordHunterWoW_QuestEN[26448] = { title = "Destroy the Legion", description = "The remains of the demonic Burning Legion have been a thorn in our side for far too long!\n\nNo more!\n\nThe demons are attacking from the areas known as Felfire Hill, Demon Fall Canyon and Demon Fall Ridge to the east.\n\nGo and destroy as many as you can to bring glory to both yourself and the Horde!", objectives = "" }
WordHunterWoW_QuestEN[26449] = { title = "Never Again!", description = "{name}, you will see to it that this attack by the Burning Legion never comes to pass!  Go and slay these dreadlords!  Without them the rest of the demons are essentially mindless.\n\nYou will find Gorgannon in Demon Fall Canyon south beyond Felfire Hill, near Mannoroth's floating, broken spear.\n\nDiathorus the Seeker resides somewhere in the barrow den atop Demon Fall Ridge.\n\nReturn to me with their weapons as proof of your deeds.", objectives = "" }
WordHunterWoW_QuestEN[26450] = { title = "If They're Just Going to Leave Them Lying Around...", description = "I was just thinking about something, {name}.  Those naga have more than just reeds down there.  They tend to keep little statues lying around on their shrines, in the sand, under their trees.  They don't seem to be USING them.\n\nI could use those statues!  I could... put 'em around the camp, make it feel a little more homey.  Anything's better than a bloody dinosaur corpsepump.  I could sell them as souvenirs.\n\nI could sell them back to the naga!\n\nWhy don't you go grab a couple while I figure this out.", objectives = "" }
WordHunterWoW_QuestEN[26451] = { title = "Gurubashi Challenge: Free-For-All Arena Combat", description = "The arena is a place of battle unlike any other.  Inside, you have no friends.  Alliances that do form are fleeting, as your allies can turn on you in the blink of an eye.  Horde vs. Alliance, Alliance vs. Alliance, Horde vs. Horde... anything goes.\n\nTake this battle standard, {race}, and place it down on the arena floor.  Defeat the summoned combatant, then return to me.\n\nStay on your toes, {race}.  Anything goes inside the Gurubashi Arena.", objectives = "" }
WordHunterWoW_QuestEN[26452] = { title = "Gurubashi Challenge", description = "You've returned, {race}.  That means you've felt the call of the arena once more.  Very well.\n\nTake this battle standard, {race}, and place it down on the arena floor.  Defeat the summoned combatant, then return to me.\n\nStay on your toes, {race}.  Anything goes inside the Gurubashi Arena.", objectives = "" }
WordHunterWoW_QuestEN[26453] = { title = "A Helping Hand", description = "Under the supervision of Architect Nemos and Vindicator Vedaar, my people are revitalizing an old night elf outpost in the eastern part of Ashenvale.\n\nThe task of building won't be easy, {name}, for the challenges and enemies they face are many. I know Architect Nemos and his compatriots at Forest Song would appreciate any help they can get, and he has asked me to send any interested men his way.\n\nSpeak to me again and I will arrange for fast transport for you to their location.", objectives = "" }
WordHunterWoW_QuestEN[26454] = { title = "A Shameful Waste", description = "Welcome to Forest Song, {class}. Where you see tents, there will one day be buildings, but such ambition requires a steady stream of materials. I cannot bring myself to order our workers to fell any of the ancient trees of this grove, but our neighbors to the west have no such reverence for the forest.\n\nWe shall reclaim the tainted wood from Satyrnaar to the west. Take the wood to Gnarl at the Warsong Lumber Camp. He is an Ancient who will purify it for our use.", objectives = "" }
WordHunterWoW_QuestEN[26455] = { title = "The Lost Chalice", description = "The area to our west, now called Satyrnaar, was once a prominent shrine built by my people. It housed a priceless relic, the Chalice of Elune, entrusted to the shrine's keepers by the priests of Elune. Pilgrims once traveled to the shrine to experience the healing powers the chalice was rumored to hold.\n\nThese stories might be nothing but old wives' tales, but if there is any truth to them, the relic may hold the key to rejuvenating the wounded forest. I must know, {name}.", objectives = "" }
WordHunterWoW_QuestEN[26456] = { title = "Report from the Northern Front", description = "The battle against the Horde isn't being waged from Raynewood Tower alone, {name}. There's a more substantial Silverwing Sentinel presence at Silverwing Grove to the southeast, near the border with the Barrens. From the grove, Sentinel Farsong directs our efforts against those who would destroy our lands.\n\nI'm a bit late in sending my latest report to her, but also hesitant to leave the tower unattended.\n\nI am in dire need of your help in getting this report to her as soon as possible!", objectives = "" }
WordHunterWoW_QuestEN[26457] = { title = "Agents of Destruction", description = "The Warsong Lumber Camp is a blight upon an embattled landscape. Every time we make progress in halting their operations, Overseer Gorthak orders his loggers to redouble their efforts!\n\nNow, the orcs are cutting more wood than they can possibly use, leaving it to rot while their blades bite into fresh trees! This is an affront to all we stand for, {name}, and we will show them that we'll not suffer further destruction of our lands!\n\nGo, and do not rest until Overseer Gorthak and his minions are dead!", objectives = "" }
WordHunterWoW_QuestEN[26462] = { title = "The Wicked Revantusk", description = "These Revantusk trolls think they're special for bein' in the Horde. Makes me laugh!\n\nSee, the funny part is, it doesn't matter if they're part of the Horde, or some kinda troll empire, or the bloody Burning Legion for that matter. We've fought trolls in these lands for a few centuries now.\n\nIn fact, I'll be kind enough to let you lend a hand, lad! Grab a weapon and head out to the battlefield and help our boys to the east.", objectives = "" }
WordHunterWoW_QuestEN[26463] = { title = "Finding Teronis", description = "A friend of mine from Astranaar, Raene Wolfrunner, asked me to send a scout west to Lake Falathim. Teronis left days ago, just before the Horde attacked.\n\nHe was searching for an item he thought could slow the furbolg attacks on our people--a rod created by a now-dead, evil wizard.\n\nBefore he left, he mentioned a gem for the rod. Unfortunately, we know that the lake has been invaded by some evil force.\n\nPlease, {name}, find my friend.\n", objectives = "" }
WordHunterWoW_QuestEN[26464] = { title = "The Lost Gem", description = "As you rummage through Teronis' belongings, you find a water-damaged journal.\n\nQuickly flipping through the last legible pages, you read that Teronis makes mention of finding the gem, but then of having lost it in the Falathim area.\n\nThe only thing left to do is find it. Perhaps the tendrils have it...?", objectives = "" }
WordHunterWoW_QuestEN[26465] = { title = "The Ancient Statuettes", description = "I would charge you with a task, {class}.\n\nI was on my boat, skimming over the submerged ruins of Zoram, when naga attacked me, surging from the water and tearing at me with their claws! I fled and the rest, as they say, is history.\n\nI am an archaeologist of sorts, and I am attempting to recover artifacts of the lost city.\n\nWill you head out onto the Zoram Strand to the southwest and recover any ancient statuettes you come across? They are the reason I have braved the dangers of the Zoram Strand.", objectives = "" }
WordHunterWoW_QuestEN[26466] = { title = "Ruuzel", description = "I fear the ancient statuette's secrets will remain forever hidden unless you find the key to their ancient locks.\n\nThat key is a ring, the Ring of Zoram. It belonged to the rulers of this city before the waves of the Sundering drowned it.\n\nFor years the ring was lost, but the naga have recently found it.\n\nTheir leader, Ruuzel, dwells on her isle on the northern edge of the Zoram Strand. Please, {name}, retrieve the ring for me!", objectives = "" }
WordHunterWoW_QuestEN[26467] = { title = "Vile Satyr! Dryads in Danger!", description = "Listen, I don't know who you are, but I need your help. My sisters went to take back the Branch of Cenarius from the satyr. They said they'd be back soon, but it's been two whole days!\n\n{name}, you have to find them! They were looking for the ruins of a night elf temple in Xavian to the northwest. I don't know what to think. Look for Anilia, she was leading them on the search.", objectives = "" }
WordHunterWoW_QuestEN[26468] = { title = "The Branch of Cenarius", description = "Anilia puts her hands on your shoulders and draws you close. Gasping, she points towards the arch to the north, before her eyes close and her last wheezing breath leaves her body. \"He has taken it... Geltharis...\" You know in your heart that Anilia's dying wish is to see the Branch of Cenarius back in dryad hands.", objectives = "" }
WordHunterWoW_QuestEN[26469] = { title = "Satyr Slaying!", description = "I can't believe that Anilia is gone... We used to play together in the forests all the time. I almost feel... sad.\n\nI know something that might make me feel better. Please, slay the satyrs that took Anilia from me! Bring me their horns as proof of your actions and you will forever have my gratitude.", objectives = "" }
WordHunterWoW_QuestEN[26470] = { title = "Retaking Mystral Lake", description = "We could easily have held Silverwind Refuge from the Horde had they not taken control of our water elemental defenders on Mystral Lake.\n\nOne of their shaman summoned in Tideress, an old and angry water spirit of the forest who befouled our elementals and turned them against us. With the lake and the Horde pressing in on us, we had no choice but to retreat to the spire here.\n\nGo east. Take the lake back so that we will have a chance to retake the refuge some day.", objectives = "" }
WordHunterWoW_QuestEN[26472] = { title = "Insane Druids", description = "The druids are dead, killed by their leaders who were driven insane by the Horde tainting the Forest Heart! I can feel the corruption even from here and I dare go no further.\n\nWhile I am too well attuned to Ashenvale and the Forest Heart, you... you could descend into the barrow den and do what must be done. I've laid down breadcrumbs for you in there.\n\nThough it tears me apart, I must ask that you put to rest the druids' once great leaders: Taneel Darkwood, Uthil Mooncall, and Mavoris Cloudsbreak.", objectives = "" }
WordHunterWoW_QuestEN[26473] = { title = "Bathran's Hair", description = "There is a plant that grows in the old ruins of Bathran's Haunt across the road to the east. The plant is called Bathran's Hair and is known to cure ailments of the spirit.\n\nNow the Horde are there harvesting the plant for their own evil schemes.\n\nThere is a sick child in Astranaar, and we believe that her illness is more than just physical. I promised my master that I would help seek a cure, but I am no fighter.\n\nWill you go to Bathran's Haunt and gather the plants?", objectives = "" }
WordHunterWoW_QuestEN[26474] = { title = "Orendil's Cure", description = "{name}, now that it has been bathed in Elune's blessed light, I believe that the concoction will help the afflicted child. Please, take it to Astranaar and give it to the child's parent, Pelturas Whitemoon.\n\nTo reach Astranaar, follow the road south and then east. However, if you'd like to get there more swiftly, speak with Sentinel Avana.", objectives = "" }
WordHunterWoW_QuestEN[26475] = { title = "Elune's Tear", description = "I'd hoped Orendil's cure would save Relara, but I fear it only slowed the disease running through her. We must find more powerful medicine! Thankfully, Orendil spoke to me of further remedies should his first one fail.\n\nElune's Tear is a type of stone that rests in only one place: the remains of Iris Lake, destroyed by the eruption of Thunder Peak, northeast of Astranaar. Orendil said the stone will wash away corruption.\n\nPlease, {name}, bring me Elune's Tear and pray it will end my child's sickness!", objectives = "" }
WordHunterWoW_QuestEN[26476] = { title = "Dryad Delivery", description = "Ah, there you are, {name}. I've pored over the notes Teronis has made and it sounds like your next course of action is to find the other pieces of Dartol's rod.\n\nI would start by heading east along the road to Raynewood Tower.\n\nA dryad there named Shael'dryn is better suited to guide you. Seek her out.\n\nKeep the gem with you--Shael'dryn will need it if she's to help you recreate the rod.", objectives = "" }
WordHunterWoW_QuestEN[26477] = { title = "Search the Bole", description = "I wish your tidings were better.\n\nRaene is correct, I know about Dartol's creation and the treants in the area--at least I did once. They've become corrupted now, their nature twisted.\n\nTo find the next piece of the rod, you'll have to find the key to open the chest it's in.\n\nThe wooden key is on one of the treants northeast of here near the Felwood border, at the Howling Vale. Once you have it, look for a small glade through the tunnel at the vale. The chest should be hidden around there.", objectives = "" }
WordHunterWoW_QuestEN[26478] = { title = "Playing Possum", description = "The last piece of the rod is held by druids of the claw. I asked their leader, Oso Bramblescar, to give it to me, but he and his guardians nearly killed me! Clearly they too were affected by the Horde's corruption of the Forest Heart.\n\nBut, I have an idea for how you can get into Oso's cave and grab the pommel.\n\nEver since I was a faun, I've been pretty good at playing possum. It works great against bears! I can teach you! Go east to the Shady Nook, and if they try to get you, just use my technique.\n", objectives = "" }
WordHunterWoW_QuestEN[26479] = { title = "Return to Raene", description = "I suggest you find Raene and let her know the rod is finished. I'm sure she'll know what your next course should be.\n\nBe careful... I sense a great deal of power within it for both good and ill. I hope that you and Raene know what you are doing.\n\nGood luck, {name}.", objectives = "" }
WordHunterWoW_QuestEN[26480] = { title = "Dartol's Rod", description = "I'm not completely certain what Teronis had in mind next, but if what he said was true about the rod's power, then it will allow you to take on another form altogether, presumably that of a furbolg.\n\nPerhaps he meant to use its powers to get closer to them, but even the uncorrupted creatures would slaughter him were he not careful. Transformed by the rod, Dartol would have to speak to a furbolg who was uncorrupted.\n\nI would start with one known as Krolg. Seek his hut southeast of Mystral Lake.", objectives = "" }
WordHunterWoW_QuestEN[26481] = { title = "A New Adornment", description = "I'm certain that the long-dead wizard, Dartol, intended to use his rod to subjugate and destroy us just as the night elves and orcs have, but I think now we'll put that thing to an unintended use.\n\nRan Bloodtooth is the king of all of the Ashenvale furbolg. His tribe, the Bloodtooth, are the most powerful and keep themselves secluded in a camp just to the east.\n\nKill them all and bring back his skull. Let us see if we can put it to good use.", objectives = "" }
WordHunterWoW_QuestEN[26482] = { title = "True Power of the Rod", description = "Now, take the rod and while using its power, speak with my brother, Ota Wen.\n\nOta is amongst the other furbolg that the orcs have captured and have penned in the giant cage on the north side of Silverwind Refuge. The rod will allow you to convince Ota and the other furbolg to rise up and attack the Horde.\n\nThen you may go wherever your path leads you. Just know that you have found a new friend for that which you have done.", objectives = "" }
WordHunterWoW_QuestEN[26483] = { title = "Gan'dranda", description = "As fun as it is to butt heads with these trolls, we've got other things to do down here. It'd be nice to get this battle over with, aye?\n\nTheir commander, Gan'dranda, sits in the ruined walls to the southeast of the battlefield. Our boys have most of their forces locked up, so I want you to slip in there and take out Gan'dranda. When they see a {race} standin' over the corpse of their biggest hero it should take some of the fight out of 'em!", objectives = "" }
WordHunterWoW_QuestEN[26484] = { title = "To Stonehearth's Aid", description = "The earthen and the stone troggs somehow found their way to Deepholm through Uldum more than fifteen thousand years ago. They've been warring ever since.\n\nIf we're to recover the middle fragment of the World Pillar, the Stonefather must be rescued.\n\nPlease go to Stonehearth and do everything that you can to aid the Earthen in their war against the stone troggs.\n\nYou're our best hope, {name}.", objectives = "" }
WordHunterWoW_QuestEN[26485] = { title = "Snapjaws, Lad!", description = "I've got plans to brew up somethin' special for those pesky trolls. Aye, I said for them... a brew they won't ever forget! A brew that'll have them pickin' their tusks out of the hillsides!\n\nI've got a few ingredients steepin' already, but I could use a hand gatherin' more. At the bottom of the Overlook Cliffs to the east, near the shore, is a whole mess o' snapjaws. I need fresh, whole gizzards from them for my blastbrew.", objectives = "" }
WordHunterWoW_QuestEN[26486] = { title = "99 Bottles of Booze on the Beach", description = "Now, I know we've got a little battle ragin' and all that, but down at the overlook cliffs are some nice lookin' bottles strewn all over the place. I don't want good drink to fall into the hands o' the Horde!\n\nIf you're down that way, collect the bottles for me and bring 'em back here. I'll pay in full for it as if you bottled 'em yourself.", objectives = "" }
WordHunterWoW_QuestEN[26487] = { title = "Akiris by the Bundle", description = "It's not easy running a combination 5-star exotic resort/jungle resource salvaging plant!  That is, it wouldn't be easy, if I didn't have the organizational skills of a trade prince's personal assistant!\n\nThe first trick is multitasking.  For example: the naga explorers to our south carry a valuable ocean reed - Akiris reeds.  We can sell these reeds to our clients overseas, and we can also stuff our visitors' mattresses with them!  Come to think of it, we could probably use some more of that stuff.", objectives = "" }
WordHunterWoW_QuestEN[26488] = { title = "Big Gulp", description = "Arnold and I used to relax down at the moat in the Valley of Heroes.  One day, I lost my locket in the lake and I have never been able to find it.  Rumor has it that huge royal monkfish live in that moat and that they eat anything!  I know it's a long shot, but do you think you could catch a few monkfish and look for my locket?\n\nPlease let me know right away if you find it, it's very precious to me.", objectives = "" }
WordHunterWoW_QuestEN[26489] = { title = "It's You!!", description = "Yes, can I help...\n\n<Sassy's jaw drops to the floor.>\n\n{name}!  Is it really you?!  Look how big and strong you've gotten!  Let me feel that bicep!\n\nMe?  I've been trying to make my gold here in the jungle.  We're mainly in resource acquisition, but we also do tourism.\n\nI know, genius, right?\n\nHey, listen.  I was thinking... the naga explorers to the south carry Akiris reeds, which we could sell, and use to stuff visitor mattresses.  You interested in killing some naga?  It'll be just like old times!", objectives = "" }
WordHunterWoW_QuestEN[26490] = { title = "Prime Slime", description = "Not many dwarves know this, but to get a REAL kick out of my brew I add a wee bit of the oozes around here. Aye, the giant green dwarf-eatin' oozes, those ones.\n\nThis brew's gonna have a HUGE kick to it though, so we need a huge slime! There's one lurkin' down in Skulk Rock that's the mother o' them all, absolutely huge...the Direglob, we call it.\n\nIf you've got what it takes, head down there and take a chunk out of the Direglob for me!", objectives = "" }
WordHunterWoW_QuestEN[26491] = { title = "Skulk Rock Clean-Up", description = "Years ago, there used to be a Horde base deep within Skulk Rock. It's been abandoned since then, but it's still prime territory, worth takin' for our allies!\n\nProblem is, it's full of dwarf-eating slimes and oozes. Those things are slightly less disgustin' than trolls, but they'll still give us a hassle.\n\nWith our boys tied up fightin' the Revantusk, I need you to go to Skulk Rock and clear the place out for me.", objectives = "" }
WordHunterWoW_QuestEN[26492] = { title = "Skulk Rock Supplies", description = "I had a cousin in the second war! He used to tell me all about when they led a raid on Skulk Rock. Swept in there and drove the trolls out like rats from a nest. They chased right after 'em all the way to Alterac!\n\nThe slimes moved in right quick after that, and there's still cratefuls of old Horde goods sittin' in there. I say we don't let the trolls get it back!\n\nBring me back a few crates from Skulk Rock to the northwest.", objectives = "" }
WordHunterWoW_QuestEN[26493] = { title = "There's Somebody Out There Who Wants It", description = "So, while you're already all sweaty from doing all that other stuff, I was thinking I might grab you for one more task.  You don't mind, do you?\n\nThe latest Science and Explosions journal just came in from Bilgewater Harbor, and there's this article about this hot new reagent.  Prices on the reagent are skyrocketing, and we're in prime position to capitalize!\n\n<Sassy leans over and whispers the details into your ear.>\n\nYou got that?  Good.  You can find the basilisks in a cave, far to the east.", objectives = "" }
WordHunterWoW_QuestEN[26494] = { title = "Mixmaster Jasper", description = "Mind giving some of this stuff to Jasper, over by the luxury suites?  I'm sure he can find some use for it.\n\nThanks, {name}!", objectives = "" }
WordHunterWoW_QuestEN[26495] = { title = "Chabal", description = "Chabal, that troll over by the botanical gardens/biological weapons lab, is a special guest.  He's a representative of the Zandalari trolls, and has traveled quite far to stay with us.\n\n<Sassy places some of the items you've collected in a small parcel and hands it to you.>\n\nHere, give this to him.  Tell him that the Zandalari are always welcome at Hardwrench Hideaway!  And mention that referrals are key to maintaining our business!", objectives = "" }
WordHunterWoW_QuestEN[26496] = { title = "Down with the Vilebranch", description = "The Revantusk isn't the only tribe of foul trolls we're here to take care of! The Vilebranch have corrupted this land for years from their stronghold of Jintha'Alor.\n\nWe're done sittin' by in Aerie Peak twiddlin' our thumbs, if you haven't noticed. Doran Steelwing leads the charge against the Vilebranch from a camp the boys took just to the south. Speak with him and join the fight!", objectives = "" }
WordHunterWoW_QuestEN[26497] = { title = "Vilebranch Scum", description = "The Vilebranch are a different tribe from the Revantusk, but the difference is academic. Far as we're concerned the only good troll is a dead troll!\n\nBut make no mistake, the Vilebranch are just as nasty even without the Horde's chain around their neck. They'll poison this whole land unless we take this stand and get rid of them\n\nYou can start with their witchdoctors and headhunters on the lower tier. Let me know when you've killed a fair share of 'em.", objectives = "" }
WordHunterWoW_QuestEN[26498] = { title = "Death to the Vilebranch", description = "We're makin' good progress. Keep pressing on, and don't falter!\n\nThe Vilebranch berserkers fight like savage animals, whipped into a blood frenzy. Their shadowcasters summon foul spirits from beyond this world! This is why we're getting rid of these depraved creatures, {name}, never forget that.\n\nHead to the middle tier and kill the berserkers and shadowcasters!", objectives = "" }
WordHunterWoW_QuestEN[26499] = { title = "Stonefather's Boon", description = "With the Stonefather taken prisoner, our forces are demoralized. Normally any one of mine could take five times his number of stone troggs. But now....\n\nI want you to head out into the field surrounding the town. Plant Stonefather Oremantle's banner near my defenders. Grant them his boon and remind them of that for which they fight.", objectives = "" }
WordHunterWoW_QuestEN[26500] = { title = "We're Surrounded", description = "Our war has been waged for longer than your kind counts time. Let us see if you can make a difference, {race}.\n\nThe stone troggs are a mistake of the titans. On your world they have succumbed to the Curse of Flesh. But here, in Deepholm, you see them in their true form.\n\nWe're surrounded. Maybe you could go out there and break a few troggs down for us. See what they're really made of?", objectives = "" }
WordHunterWoW_QuestEN[26501] = { title = "Sealing the Way", description = "The stone troggs have found a way to burrow up from underneath our homes!\n\nI've sent our geomancers to seal all of the buildings, but they need these reagents and enough time out of battle to properly cast their rockslide rituals.\n\nWhen you're done, report to, Gravel Longslab, just to the north on the Fractured Front.", objectives = "" }
WordHunterWoW_QuestEN[26502] = { title = "Thunder Stones", description = "To the north lies the Fractured Front. That is where most of the heavy fighting is happening.\n\nGo into Stonehearth proper and grab all of the thunder stones that you can. Our engineers need them for the catapults.\n\nWhen you have enough, take them to Clay Mudaxle. Don't mind his tongue. He's old and cranky, and should have gone back into the earth thousands of years ago.", objectives = "" }
WordHunterWoW_QuestEN[26503] = { title = "Still Assessing the Threat", description = "Damned worthless gnolls are up to no good. I can feel it in my bones. Gnoll activity in the area has tripled in the past two weeks. I fear they might be mounting up to make an assault on Lakeshire.\n\nI need you to head to each of the gnoll camps of this area and gather any information that you come across. Check the camps directly north of here, east of here and southeast of here. Bring back whatever you find.", objectives = "" }
WordHunterWoW_QuestEN[26504] = { title = "WANTED: Redridge Gnolls", description = "By order of the Stormwind Royal Guard, all gnolls of the region known as Three Corners in the southwestern corner of Redridge Mountains, are wanted dead.\n\nShould you dispatch of the gnolls of the region, report your victory to Watch Captain Parker at Tower Watch.", objectives = "" }
WordHunterWoW_QuestEN[26505] = { title = "Parker's Report", description = "<Watch Captain Parker hands you a report.>\n\nHere it is, {name}. Take my report to Lakeshire, located north of this tower, and deliver it to Magistrate Solomon. Inform him that we need a more comprehensive solution for dealing with the gnolls. Suggest explosives. Lots of explosives.\n\nAnd stick to the road if you know what's good for you.\n\nWhat's good for you is staying alive, by the way. In case you didn't know what was good for you. You now know... Oh never mind!", objectives = "" }
WordHunterWoW_QuestEN[26506] = { title = "Franks and Beans", description = "I need your help, {race}! Our rations have run out and the guards are getting hungry. They're clamoring for my world famous franks and beans, but I have no ingredients on hand. Would you be a darling and help me out?\n\nI need some goretusk kidneys, condor giblets, and tarantula eyes. You'll find goretusks, condors and tarantulas near this tower. Just look around!", objectives = "" }
WordHunterWoW_QuestEN[26507] = { title = "Petrified Delicacies", description = "Petrified bats.\n\nElementals of that size are picky. You're not likely to find anything better easily.\n\nTo the east are basilisks. They petrify stone bats that fly too close and snack on them when they grow hungry. You may find bats scattered around their territory.\n\nI must warn you... if you show that little elemental too much attention, you're unlikely to be rid of it. It can be very... needy.", objectives = "" }
WordHunterWoW_QuestEN[26508] = { title = "Nida's Necklace", description = "My friend Nida lost her necklace, and we can't find it.  We've been fishing all day right here, and we looked around here already.  The only thing I can think of is that it fell into the lake.  Our parents don't want us to swim in the lake... my mom says there's some mean things underwater, but you look like you aren't scared of mean things.\n\nCould you find it for her, please?", objectives = "" }
WordHunterWoW_QuestEN[26509] = { title = "An Unwelcome Guest", description = "Once again my garden was trampled and pillaged.  And I know the brute who is doing it.  It's that forsaken boar, the one Marshal Marris has taken to calling Bellygrub.\n\nI won't be able to re-plant the daffodils until next season now.  Ruined!  All ruined by that one menacing boar.  Put an end to that pest!  Show me his tusk and I'd be happy to reward you.  He seems to spend his time foraging in the field southwest of Lakeshire but occasionally he roams over here and into my garden.", objectives = "" }
WordHunterWoW_QuestEN[26510] = { title = "We Must Prepare!", description = "More of our citizens go missing every day. We think the gnolls are responsible, but we have no idea where they are taking them! If you are to help us defeat the gnolls and find our people, you must be properly equipped. Unfortunately, we are all out of gnomecorders. Without a gnomecorder, there is no way for us to communicate with you when you are in the field.\n\nOur last good gnomecorder was stolen by marauding murlocs last week. You will have to go to Lake Everstill, east of here, and recover it!", objectives = "" }
WordHunterWoW_QuestEN[26511] = { title = "Lake Everstill Clean Up", description = "Headed out to Lake Everstill? You'll be happy to know that we currently have a bounty on murlocs. Kill as many as you can and be rewarded! Any murloc will do. All you need to do is kill indiscriminately.\n\nYou'll find Lake Everstill directly east of Lakeshire. It's the lake. Has water in it... Any of this ring a bell?", objectives = "" }
WordHunterWoW_QuestEN[26512] = { title = "Tuning the Gnomecorder", description = "The gnomecorder looks to be in working order. I've got you all hooked up, now we just need to tune the gnomecorder for reception.\n\nHead north out of Lakeshire and follow the road up to the graveyard. Once you reach the graveyard I'll attempt to transmit.", objectives = "" }
WordHunterWoW_QuestEN[26513] = { title = "Like a Fart in the Wind", description = "We were raided last night, or perhaps it was the night before. I'm not really sure when it was as I haven't had a wink of sleep in three days. I'm probably delusional at this point.\n\nListen, gnolls raided our supply stores and took off with everything! Just like a fart in the wind, they were in and they were OUT! My soldiers saw them running back towards the canyons, northwest of here. Recover our supplies, {class}!", objectives = "" }
WordHunterWoW_QuestEN[26514] = { title = "Canyon Romp", description = "<The gnomecorder hums.>\n\nThe first order of business is a romp through the Redridge Canyons, directly north of Lakeshire. Kill every gnome that you see... woops, did I say gnome? I meant gnoll. Kill every GNOLL that you see and take their collars as proof of deed.\n\nI must warn you, {name}; while you are out there, watch out for ettins. My scouts have reported seeing huge, bloodthirsty ettins roaming the canyons lately. Stay out of their way if you want to remain alive.\n\nSolomon out. I'll be in touch.", objectives = "" }
WordHunterWoW_QuestEN[26515] = { title = "Ongo'longo's Revenge", description = "I've got a plan to pit troll against troll.\n\nThe Vilebranch have a big ol' dire troll locked up in a pit with some flimsy-lookin' chains. I've seen those things fight, and there's no way those'll hold if that big brute gets swingin' mad!\n\nI want you to find the dire troll and fight him, {name}. Don't kill him... just smack him around til' he's seein' red, then let him break free and get out of his way! He'll be a big pain for the Vilebranch.", objectives = "" }
WordHunterWoW_QuestEN[26516] = { title = "It's Ours Now", description = "Only the strongest and foulest Vilebranch are left now. The soul eaters and blood drinkers, foul worshippers of the evil god Hakkar.\n\nDon't forget you're not just fighting trolls here, {name}. You're fighting dark and evil forces that'll churn this land into ash if we let them live!\n\nShow no mercy!", objectives = "" }
WordHunterWoW_QuestEN[26517] = { title = "Summit of Fate", description = "You have to go to the summit now, {name}. Our warriors won't go past the final gates. They say it's still as a tomb; not a sound, not a breath, not a hint of motion.\n\nThey think it's a trap, but based on what you've brought me, I'm worried it's something even more sinister. Go to the altar, investigate what happened... and bring me back ANY sort of mystical object or dark idol you find! Do you hear me?", objectives = "" }
WordHunterWoW_QuestEN[26518] = { title = "Heads Up", description = "Umboda Three-Heads is one o' the biggest trolls you'll see around. He's a savage butcher, takin' heads for his own collection, dwarf and troll alike! It's time he got what he deserved.\n\nLook for the big brute on the lower terraces, and you take his own head right back here!", objectives = "" }
WordHunterWoW_QuestEN[26519] = { title = "He Who Controls the Ettins", description = "You've stumbled upon a gnoll document. The gnoll that wrote this propaganda is semi-literate:\n\nBROTHERS OF YOWLER, HEAR DIRTPAW! DIRTPAW GIVEN ORB FROM ORCS! DIRTPAW CONTROL ETTIN THINGS! DIRTPAW CRUSH HUMIES! COME GET DIRTPAW PAW-O-GRAPH IN RETHBAN CAVE. CAVE IS WEST, HIDDEN IN CANYON!\n\n<There's a paw print as the signature.>\n\n<There also appears to be a bite taken out of the scroll.>\n\nYou should probably investigate.", objectives = "" }
WordHunterWoW_QuestEN[26520] = { title = "Saving Foreman Oslow", description = "<Upon touching the orb you hear a faint click.>\n\n<You remove the orb from the pedestal.>\n\n<You now control the orb, therefore you now control the ettins. Maybe you can use an ettin to remove the huge boulder currently crushing Foreman Oslow over at Lakeshire. Find an ettin and use the orb on the ettin. Then head over to Lakeshire.>", objectives = "" }
WordHunterWoW_QuestEN[26521] = { title = "Faces of Evil", description = "The Vilebranch have hung their tiki masks all across the walls of Jintha'Alor. We won't tolerate their foul hexes and dark magic.\n\nIt's time to send a message, and tear down their defenses, all at once! Take this torch, {class}. Set fire to their tiki masks and watch 'em burn. They'll know the Wildhammer want them gone when they see their dark idols consumed!", objectives = "" }
WordHunterWoW_QuestEN[26523] = { title = "All That Skitters", description = "There's somethin' I've noticed up there... Jintha'Alor's full of spiders. Small ones about as big as yer hand. Not an unusual sight for the Hinterlands, but somethin's amiss.\n\nTo be honest, I don't trust the trolls to keep pets. They're up to somethin'. I need you to bring me some of those spiders. Keep 'em alive if you can, and we'll see what the spirits tell me...", objectives = "" }
WordHunterWoW_QuestEN[26524] = { title = "Dark Vessels", description = "The Vilebranch trolls here were always worshippers of the foul god Hakkar, the loa of blood. He was a sick and twisted entity that nearly broke through to our world, but he was defeated long ago.\n\nThe Vilebranch are still stirring their dark cauldrons, ones they filled with blood years before. They're either holding onto hope for a long-dead spirit, or they're up to something new and just as sinister.\n\nGet me those vessels, {name}. We need to examine them with the spiders and see just what's going on here!", objectives = "" }
WordHunterWoW_QuestEN[26525] = { title = "Venomous Secrets", description = "If the sacrifice has already been made, Shadra's presence is going to start creepin' into this realm. That cave's probably full of her spawn by now.\n\nDon't let them escape, {name}. Slay any of those vile spiders you find!", objectives = "" }
WordHunterWoW_QuestEN[26526] = { title = "Hunt the Keeper", description = "Shadra the spider loa... the venom queen, a spirit of darkness and death! If there's been a sacrifice, they're trying to bring her forth as a last-ditch effort.\n\nIf the Vilebranch are performing rituals, I'm not going to let them finish.\n\nCheck the cave behind the altar at the top of Jintha'Alor. Deep within it, one of Shadra's keepers might still be lurking. Kill her and take whatever she carries back here so we can know what's going on.", objectives = "" }
WordHunterWoW_QuestEN[26527] = { title = "Gryphon Master Talonaxe", description = "I'd smash this tablet to bits if I had the right, but that's not for me to decide. Gryphonmaster Talonaxe needs to see this.\n\nYou've got to return to Aerie Peak with the tablet. Gryphon Master Talonaxe is in the aviary, tending to the gryphons.\n\nBe swift... and don't let that tablet leave your grasp for a moment!", objectives = "" }
WordHunterWoW_QuestEN[26528] = { title = "The Eye of Shadra", description = "Gryphon Master Talonaxe has sent me here to deal with Shadra, the Venom Queen. The conquest of Jintha'Alor isn't enough... the trolls could regroup and summon this creature later, when we're not expecting it.\n\nWe'll gather the artifacts first, pull Shadra into this world on our own terms, and put our hammers to that foul creature. I'll need you to help find the artifacts, and put a hurt on the rest of the trolls while you're at it.\n\nWe first need the Eye of Shadra, guarded in Agol'watha to the north.", objectives = "" }
WordHunterWoW_QuestEN[26529] = { title = "The Fang of Shadra", description = "We'll need the Fang of Shadra next.\n\nIt's kept in the Creeping Ruins to the east, guarded by Shadra's own spawn. Hideous spiders the size of a dwarf, and twice as strong. Their venom is strong, {name}... don't get careless.", objectives = "" }
WordHunterWoW_QuestEN[26530] = { title = "The Shell of Shadra", description = "The final piece is all we need to burn Shadra out for good.\n\nThe Shell of Shadra is held by the spider god's last living high priestess, Qiaga the Keeper. She stands atop the Altar of Zul, guarded by other fanatical zealots.\n\nYou've got to climb that altar to the top and take her out! She'll have the Shell in her possession. Bring it back here.", objectives = "" }
WordHunterWoW_QuestEN[26531] = { title = "Summoning Shadra", description = "Our best fighters are ready, we've got the idol assembled... it's time, {name}.\n\nHere's what we're gonna do. You'll travel southwest to Shadra'Alor ahead of us with the idol. You'll need to use the idol at each of the three temples, fighting through the trolls guardin' them.\n\nWhen you do that, Shadra will emerge into our world, and we'll be right there waiting for her with fury in our hearts. Talk to my boys on the scene as soon as you've performed the ritual!", objectives = "" }
WordHunterWoW_QuestEN[26532] = { title = "Shadra the Venom Queen", description = "No time to waste, {name}! She's comin' out of the water right now!\n\nGryphon Master Talonaxe is comin' right now with the boys, let's show that bug what for!", objectives = "" }
WordHunterWoW_QuestEN[26533] = { title = "Zanzil's Secret", description = "Years ago, the Gurubashi exiled one of their own from Zul'Gurub: a troll by the name of Zanzil.  The reasons why aren't all that clear, but I'd guess it had something to do with his tendency to administer powerful, behavior-altering drugs to anyone he saw.  Anyhow, the Gurubashi priests and their blood god have been slain, but Zanzil the Outcast remains...\n\n...as do his powerful, behavior-altering drugs.\n\nI'd like to get my hands on some, {race}.  Check the zombies to the southeast.", objectives = "" }
WordHunterWoW_QuestEN[26534] = { title = "Let's See What You've Got, Zanzil", description = "Visitors to Hardwrench Hideaway sign a number of waivers upon arrival, one of which allows us to perform basic tests on them.  I'd say it's about time we invoked that clause again.\n\nActually, let's avoid poisoning our customers this time.  Better for business.\n\n<Jasper fills a pitcher with Zanzil's Mixture and some crushed ice.>\n\nThe Hideaway's southeastern tower serves as a temporary jail.  \"Hardwrench Hoosegow,\" we call it.  Anyways, give the prisoners a drink and tell me what happens.", objectives = "" }
WordHunterWoW_QuestEN[26535] = { title = "Recipe for Disaster", description = "I need Zanzil's recipe, now more than ever.  One of Zanzil's flunkies at the Ruins of Aboraz must have it on him.  Head east, to the other coast of the Cape, and snatch it for me!", objectives = "" }
WordHunterWoW_QuestEN[26536] = { title = "Thunder Falls", description = "Arnold and I have been fishing in and around Stormwind for years now.  That's the kind of time it takes to find a good fishing spot.  One of my favorites is called Thunder Falls.\n\nIt's just south of Stormwind in Elwynn Forest.  Best part about Thunder Falls is the violet perch.  I have never seen them anywhere else, only up there at the falls.  It's a bit of hike for me and Arnold to get out there these days though, do you think you could head up there and fetch some of those perch for us?", objectives = "" }
WordHunterWoW_QuestEN[26537] = { title = "Shatter Them!", description = "I want you to go out there and I want you to finish them.\n\nBerserkers, Earthrenders, Deathriders... I don't care! I want those stone troggs shattered!", objectives = "" }
WordHunterWoW_QuestEN[26538] = { title = "Emergency Aid", description = "Many of our warriors didn't survive the Twilight attack on our air fleet. Those that did are swimming to the remains of the fleet, bleeding and badly burned. I need support from the shore to keep my men alive!\n\nThere should be some sort of doctor or medicine man inside of Dragonmaw Port who would be willing to help his fellow orcs out. Go ashore and see if you can bring some medical supplies back to the fleet!", objectives = "" }
WordHunterWoW_QuestEN[26539] = { title = "Stalled Negotiations", description = "The Warchief's whereabouts are unknown! But we have to keep his plan moving forward. {name}, you look like you can get things done.\n\nOur negotiations with the Dragonmaw have stalled. Their Warchief is... not what we expected. I need you to go in there and get negotiations back on track.\n\nMeet with Ornak on the shore, he'll fill you in.\n\nTalk to Horzog on deck here for quick transportation to the shore.", objectives = "" }
WordHunterWoW_QuestEN[26540] = { title = "Dangerous Compassion", description = "The red dragonflight represents the aspect of life. As such, their blood has healing properties.\n\nThis crate of bandages has been soaked in red dragon blood. It is the last of my supply. May it bring a speedy recovery to your warriors.\n\nWhatever the outcome of your negotiations here, do not forget that you have friends among the Dragonmaw.", objectives = "" }
WordHunterWoW_QuestEN[26542] = { title = "Hero's Call: The Hinterlands!", description = "By order of his royal highness, King Anduin Wrynn, all able-bodied citizens of the Alliance are to report to Gryphon Master Talonaxe at the aviary in Aerie Peak.\n\nOur new brothers in the Alliance need your help to fend off the aggressive Horde offensive in their beloved homeland. Travel north from the Arathi Highlands, through the dwarven mountain pass and follow the road northwest to Aerie Peak.\n\nFor the glory and honor of the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[26543] = { title = "Clammy Hands", description = "Nothing tastes like fresh monstrous clam meat, {name}.  I have been so busy with work these past few weeks that I have not been able to make it out to the local clam spawning grounds.  Think you could run down there and gather some of those tasty treats for me?\n\nThe clams can be found near the shoreline on the eastern coast of Durotar.  Should be plenty right around the Orgrimmar docks.", objectives = "" }
WordHunterWoW_QuestEN[26544] = { title = "They've Wised Up...", description = "<The gnomecorder crackles and pops.>\n\nIt would appear that the Blackrock orcs have finally wised up. I'm getting reports that they're joining forces with the gnolls and planning an attack. I want details, {name}!\n\nI need you to check out Rethban Caverns, located in the western region of Redridge Canyons. Look for orcs with dark skin. Kill any that you encounter and search their corpses for information.\n\nSolomon, out.", objectives = "" }
WordHunterWoW_QuestEN[26545] = { title = "Yowler Must Die!", description = "<The gnomecorder hums.>\n\nYou need to find Yowler, {name}. He'll be located somewhere in the northern region of Redridge Canyons. Kill that mongrel and search his corpse for the Blackrock invasion plans. Should you succeed, bring the plans to me over at the town hall in Lakeshire.\n\nSolomon, out.", objectives = "" }
WordHunterWoW_QuestEN[26546] = { title = "Razorbeak Friends", description = "Our clan reveres the gryphon as a sacred animal. They're majestic creatures of the skies, and more than just beasts; they're intelligent and cunning.\n\nSome say we keep them, but it's more of a friendship. If you want to befriend the Wildhammer here, first befriend our gryphons! Take this bag o' chow, it's nice and fresh. Our trained razorbeak gryphons wander the forests to the south of the aviary. Go on and feed a few of 'em for me, aye?", objectives = "" }
WordHunterWoW_QuestEN[26547] = { title = "A Mangy Threat", description = "We do everything we can to protect our kin and our gryphons. That includes chasin' off predators, whether they be from the forest or from the Horde.\n\nI won't ask you to save us from two-legged monsters just yet. Mangy silvermane prowl the woods to the south where our gryphons range, and they're known to get 'em if they stray too low. Hunt a few of the silvermane and make sure they know our gryphons aren't food.", objectives = "" }
WordHunterWoW_QuestEN[26548] = { title = "Out to the Front", description = "We need your help with somethin' more pressin', {name}.\n\nThe Horde's been gettin' bolder out here. They've moved in on our territory and started attackin' us outright. The Revantusk forest trolls are attackin' Stormfeather Outpost in broad daylight!\n\nI need you to help out. Talk to Guthrum Thunderfist just outside. He'll put you on a gryphon to Stormfeather Outpost. Kerr Ironsight will fill you in when you get there.", objectives = "" }
WordHunterWoW_QuestEN[26549] = { title = "Madness", description = "Our last two negotiators haven't returned from speaking with the Dragonmaw Warchief. I think we might need to flex a little bit of muscle.\n\nThis time, I want YOU to accompany the negotiator. Their Warchief might think twice once he realizes the Horde is full of battle-hardened heroes like yourself.\n\nSimply escort our negotiator into the main hold in the center of Dragonmaw Port and look menacing. ", objectives = "" }
WordHunterWoW_QuestEN[26550] = { title = "Backdoor Dealings", description = "Zanzil the Outcast, an exile from the Gurubashi tribe, is my quarry.  Recently, I have heard tales from my brothers in the north about his planned reentry into society, starting with the emissary he sent to the Skullsplitters.  This is not good news.\n\nI want you to peer into Zanzil's current plans.  Take this incense, and place it in front of the bat totem in the Ruins of Jubuwal, to the east.  Hir'eek will guide you from there.", objectives = "" }
WordHunterWoW_QuestEN[26551] = { title = "Eliminate the Outcast", description = "You are to kill Zanzil.  You rode on Hir'eek's wings and saw through Hir'eek's eyes; you know where Zanzil hides within the Ruins of Aboraz.  Travel there and kill him.\n\nOh, and {race}: if we become separated, you should use this fetish.  It only works within Stranglethorn, but it will transport you back here to me should you need to return swiftly.\n\nGood luck, {race}.  Zanzil is no ordinary opponent.", objectives = "" }
WordHunterWoW_QuestEN[26552] = { title = "Through the Troll Hole", description = "It looks like Zanzil's portal into Zul'Gurub is still open.  Zul'Gurub is a dangerous place, but Chabal entrusted this task to you.\n\nThe portal lies in wait in front of you.", objectives = "" }
WordHunterWoW_QuestEN[26553] = { title = "High Priestess Jeklik", description = "Ahead of you looms a ramp up to one of the city's many terraces.  The bat-shaped totems ahead of you indicate that this is the domain of High Priestess Jeklik, a follower of Hir'eek.\n\nJeklik was one of the Hakkar-worshipping priests that Zanzil was planning to resurrect.  Perhaps if you hurry, you can stop the resurrection!", objectives = "" }
WordHunterWoW_QuestEN[26554] = { title = "Plunging Into Zul'Gurub", description = "Zanzil the Outcast has once again escaped through one of his portals.  Follow him!", objectives = "" }
WordHunterWoW_QuestEN[26555] = { title = "High Priest Venoxis", description = "Venoxis was the second of the two priests that Zanzil planned to bring back from the dead.  You have already succeeded in destroying the body of High Priestess Jeklik... Venoxis must be the next.", objectives = "" }
WordHunterWoW_QuestEN[26556] = { title = "No Dumping Allowed", description = "Ever since those goblins took up refuge in Orgrimmar, they have been dumping all of their waste in our water supply.\n\nI have no idea what effect this is having on our local fishing supply, but I don't think it's good.  I have heard reports of a new mutated fish species spawning in that toxic pool near their camp.  A few specimens would really help me figure out what exactly is going on.\n\nCan you help me out?", objectives = "" }
WordHunterWoW_QuestEN[26557] = { title = "A Staggering Effort", description = "I've fished sandy carp in Orgrimmar's local waters for years now.  Recently, I have noticed my bait is not working as well as it used to.  I suspect it has something to do with all the tauren that moved into the Valley of Wisdom.\n\nI spoke with one of their local fisherman and it just turns out their appetite has changed.  They are biting on stag eyes these days.  You should be able to find plenty of stags north of Orgrimmar, just outside the northern gate.", objectives = "" }
WordHunterWoW_QuestEN[26558] = { title = "Summoning Shadra", description = "The idol is prepared, {name}. I trust that you are as well?\n\nYou will go southwest to Shadra'Alor ahead of us with the idol. You'll need to use the idol at each of the three temples.\n\nWhen you do that, Shadra will be summoned to this realm. The Deathstalkers and I will be along shortly to subdue and harvest her body. Speak with the lookout I've sent ahead once you've performed the ritual, and await my arrival.", objectives = "" }
WordHunterWoW_QuestEN[26560] = { title = "Jorgensen", description = "I don't know where Krakauer or Danforth are, but Jorgensen was being held at Render's Camp, northwest of here. I was in the same crap filled cage with him before they relocated me to Alther's Mill.\n\nIf we're gonna get him out we'll need the key. A stone cold witch from hell known as Utroka the Keymistress holds on tight to that thing. We'll have to kill her if we're going to get Jorgensen's cage key. She's up north in the valley leading to the Burning Steppes.\n\nLet's go, kid.", objectives = "" }
WordHunterWoW_QuestEN[26561] = { title = "Krakauer", description = "Krakauer is up on the chopping block as we speak! The orcs brought in a Gurubashi witch doctor to perform a dark ritual on him. We need to kill that troll to free Krakauer!\n\nLet's go! He's just inside the cave here. Hang a right at the first fork.", objectives = "" }
WordHunterWoW_QuestEN[26562] = { title = "And Last But Not Least... Danforth", description = "Danforth's being tortured on the other side of the cave. There's no telling what state he's in by now! We need to get over there and save him!\n\nOverlord Barbarius has the key to the lever holding Danforth up. We work together as a team and we can kill that bastard, Barbarius. Once Barbarius is dead, we use his key to get Danforth down and get out of here!\n\nReady?", objectives = "" }
WordHunterWoW_QuestEN[26563] = { title = "Return of the Bravo Company", description = "I don't know who you are, mister, but you've earned the respect and admiration of the Bravo Company. You've managed to save all our hides and kill a boatload of orcs in the process. Now we return the favor.\n\nGet back to Lakeshire and report to Colonel Troteman. We'll find Johnny and deliver the good news in person. With the Bravo Company back in action, these orcs don't stand a chance.", objectives = "" }
WordHunterWoW_QuestEN[26564] = { title = "Fixer Upper", description = "<Clay sneers at you and makes a sound much like two stones rubbing against each other.>\n\nThey've smashed all of our catapults. I've been trying to get this one working, but no luck so far.\n\nMaybe you'd like to make yourself useful. Head out onto the front and grab me any spare parts you come across.\n\nYou think you can handle that, flesh bag?", objectives = "" }
WordHunterWoW_QuestEN[26566] = { title = "A Triumph of Gnomish Ingenuity", description = "We will need all the weapons, inventions, and soldiers we can get in order to defeat Razlo Crushcog and his followers.\n\nOver to the northeast, you'll find Engineer Grindspark, one of a new generation of brilliant gnomish minds. Why, he hasn't had an explosion in over three prototypes!\n\nBut enough bragging. Engineer Grindspark is working on a bot that he says will help clean up the toxic airfield. You should introduce yourself to him and see if he needs any help testing it.", objectives = "" }
WordHunterWoW_QuestEN[26567] = { title = "John J. Keeshan", description = "You ever heard of John Keeshan, {name}? I was his commanding officer throughout all three great wars. Let me tell you, that man has killed more orcs than any man alive. If anyone can stop the Blackrock orc invasion, it's JOHN J. KEESHAN. We need to get him to help us or Lakeshire will be nothing more than a mound of rubble and ash after that massive Blackrock army marches through to Elwynn.\n\nI heard he was fighting in the underground fight club at the Lakeshire inn. Find him and tell him everything you know.", objectives = "" }
WordHunterWoW_QuestEN[26568] = { title = "This Ain't My War", description = "They asked me to fight in those wars. I didn't ask them! I did what I had to do to win. So I end up getting captured by those filthy, crap-swilling, maggot orcs and for five long years they used me as a toilet. Finally I break out and head back to my hometown and what do I get? People spitting on me, protesting me, calling me a baby orc killer and all kinds of vile crap!\n\nNo, I don't think I'll be helping you. You go back to Troteman and you tell him that this ain't my war.", objectives = "" }
WordHunterWoW_QuestEN[26569] = { title = "Surveying Equipment", description = "Ah, my savior! I've heard that you're on a mission to save Lakeshire... and my bridge. Yep, worked too damned long on that thing to let it get destroyed by an army of marauding orc monsters!\n\nListen, if you're headed up north towards Render's Camp, would you do me a solid and get me some spyglasses from the Blackrock trackers up there? I could sure use 'em for my new surveying gear.", objectives = "" }
WordHunterWoW_QuestEN[26570] = { title = "Render's Army", description = "Heading up north, eh? How about you wage your own little war against those Blackrock monsters? What do you say, {name}?\n\nKill any Blackrock orc that you see at Alther's Mill or Render's Camp. Kill until your skin turns red from their blood splatter and then come back to me and I'll pay you handsomely.\n\nIt might not stop the Blackrock invasion, but it'll be sure to put a kink in their plans.", objectives = "" }
WordHunterWoW_QuestEN[26571] = { title = "Weapons of War", description = "What I'm about to ask of you isn't going to be easy to accomplish, {name}. Keeshan left everything back there in that orc prison, and I'm not just talking about his soul or his will to live.\n\nIf we're going to get Johnny ready for war, we need to recover his prized possessions. The orcs now hold Keeshan's bow and his survival knife.\n\nHead to Alther's Mill, east of here and look for two orc lieutenants, Murdunk and Homurk. They've got Keeshan's gear. Get it back.\n\nI'll be in touch via gnomecorder.", objectives = "" }
WordHunterWoW_QuestEN[26572] = { title = "A Golden Opportunity", description = "You heard of the golden stonefish, {name}?  The thing with these fish is that they can't be caught by normal means.  They have jaws so strong that they snap right through any hooks or lures you try to use on 'em.\n\nYou can find a number of them in Thunder Ridge, south of Orgrimmar.  That ridge used to be full of thunder lizards, but they all drowned in the flood.\n\nTake my knife, swim down there and cut off their tails.  You should be able to use the tail to zap any stonefish you find.", objectives = "" }
WordHunterWoW_QuestEN[26573] = { title = "His Heart Must Be In It", description = "<The gnomecorder clicks.>\n\nHis gear alone won't be enough, {name}. His heart must also be in this battle. To capture that, we need items of sentimental value. The Blackrock orcs of Render's Camp, located in the north, hold two such items that belong to Keeshan.\n\nGet up there and search their coffers for Keeshan's headband and a jade amulet left to him by his wife - who was brutally killed during a Blackrock orc invasion.\n\nBring them back to me should you succeed.", objectives = "" }
WordHunterWoW_QuestEN[26574] = { title = "Adella's Covert Camp", description = "Lady Shandris has already asked for you to assist us further.\n\nAdella has struck out to the east, among the woodpaw gnolls, and established a foothold south of Camp Mojache. You are to report to her if you wish to assist Lady Shandris and the Alliance further.\n\nDon't stray too close to Camp Mojache... the Horde will not hesitate to attack. Keep to the south and look for our banners.", objectives = "" }
WordHunterWoW_QuestEN[26575] = { title = "Rock Bottom", description = "I've one more favor to ask, fleshling.\n\nThere is a basilisk, much larger and much older than the rest. Though we normally fear nothing from their kind, this one has become so potent as to petrify some of my sons. This shall not be abided.\n\nFind Gorgonite to the east and slay him. He has lived much longer than necessary.", objectives = "" }
WordHunterWoW_QuestEN[26576] = { title = "Steady Hand", description = "Nearby to the north, you will find Terrath the Steady. He has taken upon the task of pulling the stone dragons back into the fold. We find ourselves repeating this trial every few hundred years... the stone dragons are fickle, and bend only to strength.\n\nTerrath is balanced and reasonable, but his goals may not be easily accomplished. Go to him. Appeal to the more balanced side of the Stonemother.", objectives = "" }
WordHunterWoW_QuestEN[26577] = { title = "Rocky Upheaval", description = "To the east, on the Crimson Expanse, you will find Gorsik. He embodies the more unstable and violent nature of our kind. He is neither friendly, nor trusting, but his word carries weight.\n\nProving yourself to Gorsik will go a long way towards proving yourself to the Stonemother.", objectives = "" }
WordHunterWoW_QuestEN[26578] = { title = "Doomshrooms", description = "The rift to your world has poisoned our home. Corrupted it. Polluted it.\n\nThis expanse festers and grows. It becomes difficult to even see the purity of the rock beneath this filth.\n\nIf you are here to lend your aid, then go about cleansing this overgrowth. Look for the brightly glowing mushrooms that are growing faster than the others. They are the worst of the offenders.", objectives = "" }
WordHunterWoW_QuestEN[26579] = { title = "Gone Soft", description = "The fungal behemoths that surround us have succumbed to a weakness very similar to that that affects your kind. Their skin has grown soft. They no longer belong with the stone.\n\nKill them. We do not wish to see this infection spread.", objectives = "" }
WordHunterWoW_QuestEN[26580] = { title = "Familiar Intruders", description = "Fleshling. Some of your kind skitter among the rocks. Too cowardly to approach, too swift to be crushed.\n\nIf you wish my favor, deal with them. I tire of these games.", objectives = "" }
WordHunterWoW_QuestEN[26581] = { title = "A Head Full of Wind", description = "I'm no druid, but some of these mushrooms do not look to be naturally occurring. I know that our Stone Lord friend over there is eager to blame this on exposure to Azeroth, but I suspect more domestic causes.\n\nI saw some clouds of red mist to the northeast, near the water's edge. They seemed to be spurring new growth in their wake. Take one of my wind-devils with you and get me a sample from those clouds. You may have to stay close to the ground to spot them.", objectives = "" }
WordHunterWoW_QuestEN[26582] = { title = "Unnatural Causes", description = "This is most definitely magic in origin. Not even druidic. I suspect one among the stone troggs to the north.\n\nGo to Gorsik and point him in their direction. Hopefully this will help earn his favor.", objectives = "" }
WordHunterWoW_QuestEN[26583] = { title = "Wrath of the Fungalmancer", description = "Their leader hides within his hole ahead. He is the one that has brought the plague upon the crimson expanse.\n\nHe must be killed.\n\nOne of your Earthen Ring companions is already inside. You should speak with her.", objectives = "" }
WordHunterWoW_QuestEN[26584] = { title = "Shaken and Stirred", description = "I have sent my brothers to assault the Verlok village from below. The Verlok will gather on their rocky ledges, as they always do to avoid our ire. When they do, we shall make the earth itself shake them until they fall at our feet below.\n\nThat is where you prove your use. When they fall to the ground amongst my brothers, make sure that they do not rise again.", objectives = "" }
WordHunterWoW_QuestEN[26585] = { title = "Corruption Destruction", description = "If this disgusting growth is truly brought on by the Verlok, then their supplies will be in their village to the north. Bring them to me so that I can verify your claims.", objectives = "" }
WordHunterWoW_QuestEN[26586] = { title = "In Search of Bravo Company", description = "If you and Keeshan are going to defend Lakeshire, we're going to need to find his old battalion. Last I heard all of 'em - Messner, Jorgensen, Krakauer and Danforth - were captured by the Blackrock orcs. Now I don't know where they could possibly be or if they're even alive, but I'd be a damned fool if I didn't ask you to try and find 'em.\n\nSearch Alther's Mill, east of here, for any clues.", objectives = "" }
WordHunterWoW_QuestEN[26587] = { title = "Breaking Out is Hard to Do", description = "The key to this cage is stored in a pouch over at the worg den, just north of our location. The problem is that the pouch is resting safely atop a tree stump amidst a sea of bloodthirsty man-killing worgs.\n\nYou've got one shot to get that key without waking up any of those sleeping worgs. Head to the worg den and find a way into the center. Tread carefully and watch out for the Blackrock worg captain. Get the key and return to me.\n\nIf you got a pet, I'd recommend telling it to stay back!", objectives = "" }
WordHunterWoW_QuestEN[26588] = { title = "A Furious Catch", description = "Are you up for a challenge, {name}?  Good, I was hoping you would be.  The Southfury River flows just west of Orgrimmar and your challenge can be found within its mighty flow.\n\nWe are looking for a giant furious pike.  This esteemed fish used to be prevalent in these areas but ever since the floods hit, the big ones have been much harder to find.  Head out to the river and let's see just how good of an angler you really are.", objectives = "" }
WordHunterWoW_QuestEN[26589] = { title = "The Wilds of Feralas", description = "You are truly brave to help us protect these lands, hero. If you wish to do more for the wilds, there are others in need of your aid.\n\nThe verdant forests of Feralas lie to the south. There, in the shade of the mighty Twin Colossals, you must seek out Konu Runetotem. He has found signs of a disturbing illness.\n\nFollow the road west around the Twin Colossals to find Camp Ataya. Go in peace, {name}, and walk with the Earth Mother.", objectives = "" }
WordHunterWoW_QuestEN[26590] = { title = "The Holy Water of Clarity", description = "Hey, listen.  You don't look like any old tourist, and I'm in a bit of a pickle.  My cousin up north sent me this weird artifact, and I need your help to... ah... identify it.\n\nTo start out, I'm going to need you to obtain The Holy Water of Clarity.  Rumor has it that whoever drinks from this spring is given a vision of clarity.\n\nSounds pretty promising, doesn't it?\n\nObtain it from the Nek'mani Wellspring at the peak of the naga camp.  Good luck!", objectives = "" }
WordHunterWoW_QuestEN[26591] = { title = "Battlefront Triage", description = "You seem quick on your feet, {race}. I need someone to go out into the chaos of the front and patch up our injured.\n\nTake my kit. It's simple enough to use.\n\nHeal them before the stone troggs finish them off for good.", objectives = "" }
WordHunterWoW_QuestEN[26592] = { title = "Diffractory Chromascope", description = "To properly identify this artifact, I will need tools for analysis.  A diffractory chromascope should suffice, I think.\n\nI already have the mithril casing, which surprisingly, is the hardest part to find.  We simply need two other pieces: a ruby and a sapphire.\n\nThere's pirates nearby, just to our south, and a bit farther to the east.  Pirates love treasure... why don't you see if you can find some gems for me?", objectives = "" }
WordHunterWoW_QuestEN[26593] = { title = "Scaring Shaky", description = "If there's one thing I can't stand, it's people who don't pay their gambling debts!  And there are a lot of people who owe me.  Think you can help me collect?\n\nFirst, there's \"Shaky\" Phillipe down by the docks.  He owes me plenty after last week's game and I want my due!  But to get it, we'll have to scare him.\n\nGo out of town and hunt elder mistvale gorillas.  Find a nice selection of giblets, then take them to Shaky.  Don't let on that they're from an animal; let him think the worst.", objectives = "" }
WordHunterWoW_QuestEN[26594] = { title = "Return to MacKinley", description = "Here, take this pouch and give it to Sea Wolf.  And tell him I meant to pay him back!  I swear!!\n\nI just got a little drunk and lost my way, and...you know how things are.  He'll understand - you don't have to get rough!", objectives = "" }
WordHunterWoW_QuestEN[26595] = { title = "Kill-Collect", description = "There's three phases to debt collecting: asking nicely, asking forcefully, and something I like to call \"Phase Three\".\n\nUnfortunately, collecting during Phase Three is something that this old dog can't do any more.  That's why I employ so many cronies, stooges, mooks, goons, and noble adventurers like yourself!\n\nJuntz Fitztittle, Ephram Moonfall, and Maury Wilkins are hiding out on the eastern coast.  You should have no problem visiting them all in one trip... and bringing back their valuables.  ", objectives = "" }
WordHunterWoW_QuestEN[26596] = { title = "The Call of Kalimdor", description = "I've been sent by the good people of Theramore to find loyal members of the Alliance who are willing to help Lady Jaina with some problems in Dustwallow.\n\nYou weren't really here working for the goblins, were you?\n\nThe path back to Dustwallow will take you through Ratchet.  Wait on the end of this pier for the next boat.  Once you get to Ratchet, speak with Gazlowe.  He'll point you in the right direction from there.\n\nUgh, I think I stepped on a fish!  And it flopped!", objectives = "" }
WordHunterWoW_QuestEN[26597] = { title = "Stranglethorn Fever", description = "Sick...so...very s-s-sick... have contracted Stranglethorn Fever....\n\n...technically... CAPE of Stranglethorn Fever....\n\n...deadly v-v-virus....\n\n...only cure... is... is... to eat the heart of M-m-m-m-mokk the Savage... elusive white beast....\n\n...Witch Doctor Unbagwa... only one who can s-s-summon....\n\n...seek Unbagwa in hidden cave on southern cape....\n\n...hurry... dying... dying....", objectives = "" }
WordHunterWoW_QuestEN[26599] = { title = "The Captain's Chest", description = "I used to sail a ship from here all the way to Ratchet, in Kalimdor.  I was a successful captain with a sterling reputation.\n\nUntil...\n\nThose cursed sea giants ruined me!  They smashed my ship, killed my crew, and set me on a lifeboat to Booty Bay.  I will not rest until their corpses pepper the ocean floor!\n\nOne of the giants, Gorlash, stole my captain's chest.  I hear Gorlash wanders the coast east of here.  Find him and get back my chest!  Do that, and you'll have earned a captain's gratitude.", objectives = "" }
WordHunterWoW_QuestEN[26600] = { title = "A Giant's Feast", description = "The next giant on my list is called Negolash.  I remember vividly how he leapt from the seafoam and plucked poor Poop-Deck Paul from the crow's nest.\n\nSwallowed him in one gulp, he did.  And snapped my mizzenmast in two on the way down.\n\nNo man on my crew deserves such a heinous death.  So we're going to use Negolash's appetite against him.  Kelsey Yance should be able to sell you some meat, and Whiskey Slim has enough booze to knock out... well, a sea giant.  You'll find both of them in town.", objectives = "" }
WordHunterWoW_QuestEN[26601] = { title = "Mok'rash the Cleaver", description = "Mok'rash the Cleaver is the last of the lot.  And the largest, by my memory.  Taller than a wave in a windstorm, with a beard like a kelp forest and a hammer like an oak tree.\n\nHe taunts me from Janeiro's Point, the island right off the end of this very pier.  It's because of him that I'm still trapped here, living this lamentable landlubber's life.\n\nIf you can swim, then head out to Janeiro's Point and slay Mok'rash.\n\nTake care, {name}.  Mok'rash will not lay down as easily as his brothers.", objectives = "" }
WordHunterWoW_QuestEN[26602] = { title = "A Dish Best Served Huge", description = "Take this food, and put it in our old lifeboat, southeast of here along the coast.  When Negolash smells all that food, he'll come running!\n\nAnd when he does, there will be a stouthearted {class} ready to knock his corpse back into the briny deep.", objectives = "" }
WordHunterWoW_QuestEN[26603] = { title = "Message in a Bottle", description = "Inside the bottle you find a note which reads, in fairly good handwriting:\n\n<To any that can aid me->\n\n<Please, my need for help is dire. A great beast holds me captive on an island in the South Seas.>\n\n<The stars at night are foreign to me and obscured by the jungle trees, but on the clearest days I see shoreline to the northwest, and what seem to be large sailing ships to the southwest.>\n\n<I beg of you, my would-be savior, please help me.>", objectives = "" }
WordHunterWoW_QuestEN[26604] = { title = "Protecting Her Royal Highness Poobah", description = "These vicious jungle cats have been circling me for some time now.  I watch them as closely as I can, but they seem to just... disappear into the grass.\n\nHow they snarl and hiss!\n\nDon't get me wrong... I still want you to rescue me, but first, clear out some of these cats.  I won't need to be rescued if I end up someone's dinner.", objectives = "" }
WordHunterWoW_QuestEN[26605] = { title = "Grubby Little Paws", description = "I understand that you're anxious to rescue me, but the time is not yet right.  First I'm going to need some of my things.\n\nThe gorillas and the monkeys on the other side of the island have taken most of my possessions.  I'll need my tiara, my scepter, my slippers, and my diary before I'm ready to leave.\n\nWhat?  Stop looking at me like I'm some sort of insane person.  You don't know what it's like being a princess.", objectives = "" }
WordHunterWoW_QuestEN[26606] = { title = "Mukla's Demise", description = "{name}, I now put my faith in you to help free me.  The great Skymane King Mukla is my captor.  He commands the beasts of this island, and they keep me here against my will with the aid of this chain.  If you can slay him and find the key to this shackle, I shall be indebted to you greatly.\n\nI often hear him to the southeast side of the island, but please be careful: he is not to be trifled with.", objectives = "" }
WordHunterWoW_QuestEN[26607] = { title = "They Drew First Blood", description = "Take this bundle of Keeshan's possessions and head back to the Lakeshire inn basement. Bravo Company is already there, talking to Keeshan. Remind him of who drew first blood, {name}. Lakeshire needs Keeshan. The Alliance needs Keeshan.\n\nDismissed, soldier!", objectives = "" }
WordHunterWoW_QuestEN[26608] = { title = "Negotiations Terminated", description = "Go now, go back to your fleet. Tell them what kind of a monster claims authority over the Dragonmaw.\n\nOur \"Warchief\" is a traitor to his blood. Since his return from Outland he reeks of demon and leads what remains of our clan to ruin.\n\nHelp rid the Dragonmaw of Mor'ghor, and those of us with pure blood will be your allies forever. This I can promise.", objectives = "" }
WordHunterWoW_QuestEN[26609] = { title = "The Bloodsail Buccaneers", description = "You sure seem eager to work, matey.  Not sure why some land-loving {race} {class} is offering help to the Blackwater Raiders, but I'm not going to turn you away.\n\nWe've made Booty Bay our happy home away from the high seas, but word has it that the Bloodsail have some new plan cooked up.  All me boys are too busy hitting the grog and looking for ladies!  What I need is a scout.\n\nCheck the cove just north of Booty Bay along the Savage Coast and see what you find.", objectives = "" }
WordHunterWoW_QuestEN[26610] = { title = "Bloodsail Treachery", description = "The map shows Booty Bay with a red \"X\" drawn precisely at the spot at which you are standing.\n\nThe scribbled text reads:\n\n\"Set up your command post here, and bide your time.  The Fleet Master will send out word when it's time to make your move.\"\n\n\"I'm placing Lieutenant Bruce in charge here.  This time will be different.  This time we take Booty Bay once and for all.\"\n\nThe map is held in place with a dagger, placed right through the location of Booty Bay.", objectives = "" }
WordHunterWoW_QuestEN[26611] = { title = "The Baron Must Be Told", description = "Shiver me timbers!  So the Bloodsail Buccaneers are planning some sort of attack on Booty Bay?  Why, the nerve of those scoundrels.  Booty Bay will always be run by the Blackwater Raiders!\n\nThis is bigger than I thought.  Report what you have learned to Baron Revilgaz at once!  You'll find him here in Booty Bay.", objectives = "" }
WordHunterWoW_QuestEN[26612] = { title = "Details of the Attack", description = "I want to know details, {name}.  Our supremacy over the Bloodsail is due largely in part to our stronghold here in Booty Bay, but intelligence also plays a critical role.\n\nThe Bloodsail maintain a few meager camps to the south which they call their \"Southern Command.\"  Well, you're going to raid their excuse for a southern command, find their plans, and slaughter their men.  Return with whatever information you can find.", objectives = "" }
WordHunterWoW_QuestEN[26613] = { title = "Up to Snuff", description = "Ah, the sea life.  I ain't gonna say it's the good life, but it's my life.\n\nWhen I get into port I like to find me a good bottle of grog and some high quality snuff.  Nasty habits but what's a pirate without his vices, right?\n\nSo you can imagine how heartbroken I was to find out the herbalist here in town has gone and sold out of the stuff.  Says his shipment got hijacked by those damned Bloodsail Raiders.\n\nI bet a fearless {class} like you could convince 'em to share the goods, eh?", objectives = "" }
WordHunterWoW_QuestEN[26614] = { title = "Keep An Eye Out", description = "Avast!  Who goes there?\n\nArgh, I am but useless without me special enchanted eye.  Bad enough to have lost me eyes in battle in the first place!  But by some stroke o' luck we docked in Menethil and a traveling wizard enchanted a special glass eye that let me see again.\n\nLast night I ended up gettin' jumped by some Bloodsail Buccaneers on me way out.  Took me eye, they did!  Seems those blokes have found their way to Booty Bay.\n\nHelp an old sea dog out by gettin' me eye back?", objectives = "" }
WordHunterWoW_QuestEN[26616] = { title = "It's Never Over", description = "Those Blackrock orcs are gonna need an army to handle the Bravo Company and you, {name}. When you're ready to go, meet us at the dock facing Lake Everstill and we'll set off on my riverboat for Camp Everstill on the other side of the lake.\n\nSee you there, {name}.", objectives = "" }
WordHunterWoW_QuestEN[26617] = { title = "An Old Sea Dog", description = "This old, weathered coin was found on the body of the pirate \"Good-Boy\" Bruce.  Its front side bears the image of a large, unfamiliar pirate ship; on its back side, the term \"Brashtide Crew\".\n\nSomeone who has been in the piracy business for some time might know what this coin is, or what it means.", objectives = "" }
WordHunterWoW_QuestEN[26618] = { title = "Wolves at Our Heels", description = "The dire wolves are the most common threat to the townsfolk here. They lurk in the forests on all sides of us, though most are along the north bank of the river.\n\nThese aren't the runt dogs you see in Elwynn, or wherever you come from. They're big as a man and twice as vicious.\n\nIf you wish to assist the people of Darkshire, hunt the dire wolves so our streets can be safer.", objectives = "" }
WordHunterWoW_QuestEN[26619] = { title = "You Say You Want a Revolution", description = "If what you say is true, {name}, then we have friends within the Dragonmaw Clan. We can support an insurgency from within their ranks and avoid a lot of bloodshed on both sides.\n\nI can help, but the most dangerous part is up to you.\n\nMy Axebite Warriors will launch an offensive on the shores. During the confusion, I need you to slip behind the lines and speak with your revolutionary contact, Zaela.\n\nWe'll arm the Dragonmaw and overthrow their fel masters! ", objectives = "" }
WordHunterWoW_QuestEN[26620] = { title = "Seasoned Wolf Kabobs", description = "Seasoned wolf kabobs are a house favorite!  Sure, I can make you some.  But first I'll need the supplies.\n\nBring me five wolf skirt steaks.  The dire wolves near the river north of town are good to hunt; I wouldn't stray too far into the woods if I were you.", objectives = "" }
WordHunterWoW_QuestEN[26621] = { title = "Insurrection", description = "The weapons the Horde has supplied us with will be more than enough. The four of us should split up and arm as many Dragonmaw workers and merchants as we can.\n\nDon't underestimate us, {name}. You'll find even our tradesmen are ferocious in battle.\n\nLet's do as much damage as possible. Arm a squad of Dragonmaw and lay waste to the fel enforcers and warlocks that have intimidated my people for so long. Then meet back here to launch our final strike!", objectives = "" }
WordHunterWoW_QuestEN[26622] = { title = "Death to Mor'ghor", description = "The time has come. Mor'ghor dies today.\n\nBe warned, {class}. Demon blood courses through his wretched veins, and he channels unnatural power. He will be destroyed, yes. But it will not be an easy fight.\n\nYou remember where Mor'ghor resides, at the top of the camp. I will meet you there. Finish him!\n\nBe sure to recruit 3 Dragonmaw followers if you are short - you will need our help.", objectives = "" }
WordHunterWoW_QuestEN[26623] = { title = "Dusky Crab Cakes", description = "I'll let you in on a little secret - Dusky \"Crab\" Cakes are really made from spider meat!  I know it's a bit disgusting, but the cakes have a nice, tangy flavor and make great snacks!\n\nIf you want to try some still, I'm afraid I'm out of meat. I need some lump meat to whip up a few more cakes.\n\nVenom Web Spiders are a good source - they nest to the north, between the foothills and the river.", objectives = "" }
WordHunterWoW_QuestEN[26624] = { title = "Getting In With the Bloodsail", description = "These plans are... interesting.  Firallon, you're smarter than this!\n\nLook, he has all three ships devoted to cannon fire, and only a few men coming in through the tunnel.  He can never take Booty Bay with three ships and a dozen footmen.  And he knows that.\n\nNo, they've got something else planned... and you're going to find out what it is.  Speak to Yancey Grillsen, the Bloodsail Recruiter, just to the north of town.\n\nThat's right, {name}.  You'd better hope that they don't recognize your face.", objectives = "" }
WordHunterWoW_QuestEN[26625] = { title = "Troggzor the Earthinator", description = "You have to put an end to this now!\n\nGo back northwest onto the front and kill their battle leader, Troggzor the Earthinator. Bring me his cudgel as proof.", objectives = "" }
WordHunterWoW_QuestEN[26627] = { title = "The Hermit", description = "I've been told there's signs of activity at Beggar's Haunt. People have reported seeing lights in the tower to the east of town.\n\nFew would be bold enough to stay that close to Deadwind Pass. You're the first to report since I've learned about this; go check it out and make sure whatever's in there is human.", objectives = "" }
WordHunterWoW_QuestEN[26628] = { title = "Death From Below", description = "This is bad. It seems the Daggerspines are amassing for an attack.\n\nNaga are known for their ruthlessness in battle. They will keep attacking until I am dead.\n\nI don't value my own life above that of my crew members, but you must help to defend me. The crew will not be able to make it back to Booty Bay without my knowledge of the seas.\n\nThe naga will be coming from the sea. I need you to remain up here with me to fend off the attack. Man the cannon and drive them back.\n\nAre you ready, {name}?", objectives = "" }
WordHunterWoW_QuestEN[26629] = { title = "Seeing Where Your Loyalties Lie", description = "Thar be just one thing...\n\nYancey hears things.  A few o' me hearties were pretty deep in their cups when they told me about some {race} {class} that came a-rollin' through the Southern Command lookin' for charts and orders.  Even ran a couple o' good pirates through, he did.\n\nLike I said, they were up to their eyeballs in grog, but still... a buccaneer's gotta trust his ears.  So I've just got one small task for ye, one sent down from Firallon hisself...\n\nBring me the head of Fleet Master Seahorn.", objectives = "" }
WordHunterWoW_QuestEN[26631] = { title = "Your First Day as a Pirate", description = "Ye may be a slayer of Fleet Masters, but rules is rules and orders is orders.  And MY orders say that all new pirates start out as swabbies.  It's the rule.\n\nYou're to be working for Captain Keelhaul, the commander of the Riptide.  It's the westernmost ship in the fleet, which is parked south of the tip o' the cape.\n\nFind him in his captain's chambers, and bring yer papers.", objectives = "" }
WordHunterWoW_QuestEN[26632] = { title = "Close Escort", description = "Alright, I think I've got it working again. You've got to get the catapult to the stone trogg town, Needlerock Slag, just to the north of the front.\n\nThe driver will go with you. I'll head back and let Gravel know.\n\nThere's no doubt that the stone troggs will try to stop you. You just keep them off of the catapult. It packs a big punch.\n\nLet me know when you're ready, {name}.", objectives = "" }
WordHunterWoW_QuestEN[26633] = { title = "Swabbing Duty", description = "I want the surface of the Riptide t'shine like a star ruby, Swabbie {name}.  I keep a tight ship around here, and it's swabbies like you that make it happen!\n\nWell, what're y'waitin' for, y'cockle-brained bilgerat?  Head updecks and start swabbin'!", objectives = "" }
WordHunterWoW_QuestEN[26634] = { title = "The Bane of Many A Pirate", description = "Gum disease.  It's a real problem, {race}.\n\nI know you're new and all, and probably haven't ever needed your gums cut, but the rest of us pirates have to deal with a little thing called SCURVY.  It's why we keep so many limes around here.\n\nWell... we used to keep limes around here.  Someone made off with our last shipment, but they can't have gone far - maybe to the nearby islands?  Bring them back, and maybe I'll see what I can do to get you promoted from swabbie.", objectives = "" }
WordHunterWoW_QuestEN[26635] = { title = "Cannonball Swim", description = "Help out a fellow swabbie?\n\nKeelhaul asked me to gather up some cannonballs at the bottom of the ocean.  Let me tell you why this doesn't work for me.\n\n- One: I have tiny arms.  Look at them!  Do you really think I can pick up a cannonball, even underwater?\n\n- Two: I have a weak respiratory system.  I start to white out after holding my breath for more than ten seconds.\n\n- Three: There are sharks.\n\nYou gotta help me, {name}!  I've been demoted as far as I can... I don't want to see what comes next!", objectives = "" }
WordHunterWoW_QuestEN[26636] = { title = "Bravo Company Field Kit: Camouflage", description = "We're gonna need some supplies before we take out the Blackrock army and save Redridge. That's where you come in, rookie.\n\nKeeshan put me in charge of getting camouflage together for the Bravo Company field kit. What I need you to do is head south and do a little \"gardening.\" There are two parts to this little adventure that you should know about: (1) Leaves and (2) Fox poop. We need 'em both.\n\nWhat did you think camo was made of?\n\nHead south and gather what I asked for, pal.", objectives = "" }
WordHunterWoW_QuestEN[26637] = { title = "Bravo Company Field Kit: Chloroform", description = "The first part of this mission is all covert ops, {name}. To that end, we need to be able to incapacitate the enemy without making any sounds. To do that we're going to need chloroform.\n\nThe muckdwellers at the bottom of Lake Everstill hold chloroform in their glands. I'm going to need you to go underwater and recover muckdweller glands. Think you can handle it?\n\nCome back to me once you've recovered enough glands.\n\nWhere's the lake you ask? Open your eyes, dummy. Directly west.", objectives = "" }
WordHunterWoW_QuestEN[26638] = { title = "Hunting the Hunters", description = "Just south of here on the Lakeridge Highway are a group of Blackrock orcs that stalk the forests under cover of darkness and ambush the uninitiated. That group is the first line of defense for the Blackrock army. They're scouts, reporting everything they see back to their central command. They need to be taken OUT or our mission here could be compromised.\n\nHead south and kill every Blackrock hunter that you see.", objectives = "" }
WordHunterWoW_QuestEN[26639] = { title = "Point of Contact: Brubaker", description = "Before we do a damned thing we need to get a field kit together. You'll help with that, {name}. There's also a matter of scouting. Thankfully for that we got some help from Stormwind. An old war buddy of mine, Brubaker, was sent here by SI:7 to scout around for us. You're to meet him in the field, just south of here.\n\nMeet up with Brubaker and find out what he knows.", objectives = "" }
WordHunterWoW_QuestEN[26640] = { title = "Unspeakable Atrocities", description = "<You unfold the note and begin reading.>\n\nKeeshan, if you're reading this note, I'm dead. Likely that my position was compromised.\n\nOrcs are committing unspeakable atrocities against their prisoners. Yes, prisoners, Keeshan. They've got cages full of P.O.W's. If you're gonna blow up this valley, you'll need to free the prisoners first.\n\nTell my wife I love her and to take out the damned trash.\n\n-Brubaker\n\nPS - They've got black dragons.\n\nTake Brubaker's report back to Keeshan.", objectives = "" }
WordHunterWoW_QuestEN[26641] = { title = "Can't Make An Omelette Without...", description = "The Vilebranch broodguards to the northeast tend the eggs of Shadra's brood. Even if we kill the Vilebranch, those eggs will still sit there, waiting to hatch and release those horrible creatures further into the wilds.\n\nWe need to take care of this properly. Tear any eggs you see out of the egg sacks and bring them to me. Don't try to destroy them on your own; you might let the little ones out.\n\nWhen you get them back here, I'll see that they're properly disposed of!", objectives = "" }
WordHunterWoW_QuestEN[26642] = { title = "Preserving the Barrens", description = "For years, the Barrens have been the heart of the Horde presence on Kalimdor, a vital link between the orcs of Durotar and the tauren settlements in Mulgore.\n\nIn the chaos of the cataclysm, floods, earthquakes, and even a quilboar invasion threaten to separate us from this vital grassland.\n\nYou look ready for a challenge. Report to Kargal Battlescar at Far Watch Post and ensure the route to the Barrens remains clear! Head west from nearby Razor Hill and cross the Southfury River to find him.", objectives = "" }
WordHunterWoW_QuestEN[26643] = { title = "Starvation Diet", description = "The Creeping Ruin to the east is crawling with fully-grown Shadraspawn spiders. They're large enough to drag off an entire dwarf in the night, and you'll see evidence enough of that when you get there... bodies are cocooned all through the ruins.\n\nThey don't keep them alive for long, {name}, but they feed off the bodies for days. It's too late to save the victims, but we can't let those spiders grow fat and thrive. Make sure you get rid of those cocoons.", objectives = "" }
WordHunterWoW_QuestEN[26644] = { title = "Attracting Attention", description = "Swabbie {name}!  This is a sad day fer ol' Cap'n Keelhaul.  Today I lose m'best swabbie.\n\nA letter's come in from Fleet Master Firallon.  Apparently he's heard about the excellent swabbin' y'been doin', and he wants t'take ye aboard the Crimson Veil as his Jack o' Swords and third mate.  She's moored just next t'the Riptide.\n\nPiracy career-wise, this's a big step fer ye, Swabbie {name}.  I recommend y'take his offer.\n\nDismissed!", objectives = "" }
WordHunterWoW_QuestEN[26645] = { title = "The Night Watch", description = "I'm afraid you're all I've got to help here, {name}. Stormwind's forces are so taxed by greater evils that they can't spare a single footman to protect Darkshire. It's up to me and the rest of the Night Watch to keep our homes safe.\n\nThere's more threats here than just wolves, unfortunately. Rotting horrors roam near Blind Mary's Haunt, on the southeast outskirts. If they're not kept in check, they'll be visiting our homes in the night.\n\nDeal with the undead and report back to me for your bounty.", objectives = "" }
WordHunterWoW_QuestEN[26646] = { title = "Prisoners of War", description = "The Bravo Company field kit is ready, {name}. I'm gonna equip you with it and you're gonna enter Render's Valley, southeast of here, and free our P.O.W.s.  I'm sending Jorgensen with you to watch your back.\n\nNow the prisoners are being held on the northeast side of the valley in a large cage, but the key to the cage is in a cave on the south side of the valley. You'll have to steal the key, create a distraction, and free the citizens.\n\nGood luck, {name}! I'll be in touch through the field kit.", objectives = "" }
WordHunterWoW_QuestEN[26647] = { title = "Ol' Blasty", description = "We've got some work to do.  How much experience have you got with cannons?  Hmm... really?  Well, how about with ancient, fallin'-apart pirate cannons?\n\nWe've got a few cannons updecks that work the old-fashioned way: you load one cannonball in at a time, aim, lock it into place, and fire.  Works well if you're tryin' to hit the side of a three-sailer... not so well for rowboats and the like.\n\nWhy don't you head upstairs and lob a few shots at Smilin' Timmy Sticks?", objectives = "" }
WordHunterWoW_QuestEN[26648] = { title = "Our Mortal Enemies", description = "Hey, new guy, take a look at this.\n\n<The dwarf flips up his eyepatch to reveal a living, functional eyeball.>\n\nI don't wear this patch because of any lost eye.  I wear it because this OTHER eye is so strong, the normal one was just weighin' it down.\n\nThis eye's good for seein' all kinds of things, like those masked hooligans that follow us around.  Fleet Master says that they've been spotted over on Jaguero Isle.  Once you get there, fire this flare gun, and I'll help you spot 'em.", objectives = "" }
WordHunterWoW_QuestEN[26649] = { title = "Drive-By Piracy", description = "Now that you know how to handle our cannons, it's time to hit some real targets!\n\nThe Venture Company has found gold to the north of here... a rare type they call \"Black Gold\".  More like a Black Spot if you ask me.\n\nWe're going to take that gold, but first, we need to get rid of those Venture Company goons.  I've got an oarsman who will take you out there.  Head off the ship down the gangplank and speak with him on the islet's northern shore.", objectives = "" }
WordHunterWoW_QuestEN[26650] = { title = "The Damsel's Luck", description = "I know ye just arrived here on the Crimson Veil, but I need to send ye off on another task.  The Damsel's Luck is the third ship in me fleet, moored over to the east.  Her skipper - Captain Stillwater - is no longer with us.\n\nDamn those masked hoodlums!\n\nAnyhow, Ironpatch told me about yer heroics at sea, and I be runnin' low on quality brigands.  I think yer more than capable for this new duty.\n\nCongratulations, matey.  Ye be the new captain of the Damsel's Luck.", objectives = "" }
WordHunterWoW_QuestEN[26651] = { title = "To Win a War, You Gotta Become War", description = "<The Bravo Company radio beeps.>\n\nDo you understand yet, {name}? Do you now see what we gotta do to win a war against these monsters? YOU GOTTA BECOME WAR! NO MERCY!\n\nWith the P.O.W.s freed you're clear to plant the seaforium. Carefully make your way into each of the structures out there and plant a charge.\n\nPlant a seaforium charge at the Blackrock munitions hut and the Blackrock tower. Once you're done meet up with me and the rest of Bravo Company at Shalewind Canyon, east of Render's Valley.", objectives = "" }
WordHunterWoW_QuestEN[26652] = { title = "Ghost Hair Thread", description = "There is a poor, sad spirit, Blind Mary, who haunts an old farm house in the hills south of Darkshire.\n\nHere, take this Spectral Comb and ask Blind Mary to comb her hair.  Then bring back the comb and I will glean from it the Ghost Hair I'll need for the thread.\n\nAnd take care, for dark things now lurk near that house...", objectives = "" }
WordHunterWoW_QuestEN[26653] = { title = "Supplies from Darkshire", description = "Oh, what is a poor old man to do?  I need some supplies from Darkshire, but the village is so far away and I am so old and feeble...I would never make the trip.\n\nCan you go to Darkshire and bring me back some ghost hair thread?  You can get it from Madame Eva at her home on the Darkshire square.", objectives = "" }
WordHunterWoW_QuestEN[26654] = { title = "Return the Comb", description = "NO!!!!!\n\nTake it, take this comb away from me!\n\nI'm a monster, and no one will ever think me lovely again!", objectives = "" }
WordHunterWoW_QuestEN[26655] = { title = "Deliver the Thread", description = "Here is your thread, {name}.  It has a thousand uses, from binding evil spirits to sewing life into inanimate objects.", objectives = "" }
WordHunterWoW_QuestEN[26656] = { title = "Don't. Stop. Moving.", description = "When Deathwing came, the Stone Dragons flocked to him. In his absence, they are again without purpose. They swarm and feed upon our kin.\n\nI have bound dozens of Opalescent Guardians, but am unable to lead them from the safety of cover. I need someone more swift, as I suspect you might be.\n\nLead them by ground towards Therazane's Throne to the east. Surely, some will not make it, but as long as you keep moving, you should be able to bring several to join our forces there.", objectives = "" }
WordHunterWoW_QuestEN[26657] = { title = "Hard Falls", description = "Stone Dragons bow only to strength. When we have punished them enough, they will bend back to our will.\n\nI have sent many of my strongest giants onto the fields in the west. They will bring the drakes to the ground. You will see to it that they do not take wing again after they fall.", objectives = "" }
WordHunterWoW_QuestEN[26658] = { title = "Fragile Values", description = "It is now time to draw the Broodmother's attention. To do so, we will need a mallet that the troggs use when making offerings to her.\n\nSeek out the Stone Trogg Beast Tamers that are attempting to tame basilisks in the southern portions of the Pale Roost. You will find a mallet on one of their corpses.", objectives = "" }
WordHunterWoW_QuestEN[26659] = { title = "Resonating Blow", description = "On the western edge of the Pale Roost, you will find a resonating crystal. Strike it with the mallet and the broodmother will come.\n\nBe ready for battle. I will be there to aid you, but she will not be easily overcome.", objectives = "" }
WordHunterWoW_QuestEN[26660] = { title = "Zombie Juice", description = "I need a bottle of a certain liquor - Zombie Juice.  Tavernkeep Smitts at the Scarlet Raven Tavern in Darkshire should have some.\n\nAnd please hurry, {name}.  These nights get cold, and I need that drink to put fire in my veins again!", objectives = "" }
WordHunterWoW_QuestEN[26661] = { title = "Gather Rot Blossoms", description = "If you bring me some rot blossoms then I can brew you up a batch of zombie juice.\n\nRot blossoms grow in strange places.  They tend to flourish on dead things, and Duskwood has its fair share of those!\n\nI've seen a few of them growing at Tranquil Gardens Cemetery lately. Check near the graves... but mind the dead that are walking about near there.", objectives = "" }
WordHunterWoW_QuestEN[26662] = { title = "The Brashtide Crew", description = "The charts mention a group called the Brashtide Crew.  This name is new to you, though you've heard about a few other newcomers to the Buccaneers.\n\nMaybe it's time you paid them a visit and found out what they know.", objectives = "" }
WordHunterWoW_QuestEN[26663] = { title = "Sinking From Within", description = "The attack on Booty Bay is looming.  You'll have to return to Booty Bay quickly and inform the Baron.\n\nFirst, however, it might be a good idea to sabotage some of the pirates' supplies while you're still in their favor.  The pirates keep most of their supplies belowdecks, spread out across the entire fleet.", objectives = "" }
WordHunterWoW_QuestEN[26664] = { title = "Making Mutiny", description = "Before returning to Booty Bay, you should do everything you can to weaken the Bloodsail Buccaneers.  Unfortunately, even as captain, you're prohibited from killing other buccaneers in cold blood.  Only a Fleet Master can do that.\n\nYou can, however, put mutineers to the sword... and mutiny can be awfully hard to disprove.\n\nSpeaking of which, those Bloodsail corsairs that hang out on the lowest level of the ships have been acting awfully suspicious...", objectives = "" }
WordHunterWoW_QuestEN[26665] = { title = "Call of Booty", description = "You feel like you've done just about enough damage, and you know the Bloodsail's battle plans.  You've done everything that Baron Revilgaz has asked of you.\n\nIt's time to hang up the pirate hat and return to Booty Bay.  The battle looms near.", objectives = "" }
WordHunterWoW_QuestEN[26666] = { title = "The Legend of Stalvan", description = "I'm here because I received a letter from my brother Stalvan, who I haven't seen in years. On arriving here, I was told he was dead...\n\nThe entire town refuses to offer any further explanation. Any mention of his name is met with terror and suspicion. As if I didn't have enough of that myself!\n\nI'm afraid of what will happen if my frustration and anger grows any further. I beg you, help me get to the bottom of this. Implore Clerk Daltry for any information he may have on my brother.", objectives = "" }
WordHunterWoW_QuestEN[26667] = { title = "The Stolen Letters", description = "You want to know about Stalvan...\n\nYou're not the first, you know. We get outsiders coming through asking about him every so often. Always outsiders. Everyone who lives here knows better.\n\nYou're out of luck, anyway. I'm missing half the archives. Feral worgen broke into the town hall not a few nights ago and tore the place to shreds.\n\nThe documents you'll want are probably strewn all across Brightwood Grove by now, deep in the woods to the west. Not worth it if you ask me.", objectives = "" }
WordHunterWoW_QuestEN[26668] = { title = "Detonation", description = "Those explosives you planted were high yield, {name}. When I push this button on the Bravo Company field kit, that whole valley is gonna be consumed by a massive fireball of death.\n\nYou know, I think you should do the honors. You did all the hard work, after all.\n\nReady?", objectives = "" }
WordHunterWoW_QuestEN[26669] = { title = "In A Dark Corner", description = "If you're that serious about this, I'll help you, {name}. I know where the other documents must be. I'm just too terrified to do anything about it.\n\nThere's only a few places that those horrible Nightbane beasts gather when they're not prowling the forest. One of them's the Rotting Orchard to the south. They use the buildings there as their dens, so if they haven't just eaten the other documents, you might find one there... but you'll have to search their lairs thoroughly, I wager.", objectives = "" }
WordHunterWoW_QuestEN[26670] = { title = "Roland's Doom", description = "This isn't all of it...\n\nYou should let it go, {name}. The only place left to look is Roland's Doom. That's the mine south of town, and the largest lair of worgen in Duskwood. Nobody in Darkshire has ever made it back from that place alive. In fact, some of the records I have here imply that's where the monsters first came from... who knows what evil's lurking in there?\n\nPlease, {name}, just give it up. Let's just forget about this whole thing, and never speak of it again.", objectives = "" }
WordHunterWoW_QuestEN[26671] = { title = "The Fate of Stalvan Mistmantle", description = "You've recovered everything. Everything except the last page...\n\n...which I've got right here. Don't look at me like that. You'll understand when you read it. Some even say it's cursed, you know. In fact, I was relieved when the worgen broke in and made off with these!\n\nTake it. Take all of it, in fact. I thank you for recovering my archives, but I don't want anything to do with this ever again. Please, just leave me be.", objectives = "" }
WordHunterWoW_QuestEN[26672] = { title = "Clawing at the Truth", description = "This can't be. My brother was strong-willed, but such vileness... such sickness and violent, bloody evil...\n\n<Tobias brings a hand to his face, averting his gaze.>\n\nI must have answers. I need to know how I got that letter. I need to know if Stalvan really did this.\n\nI need to know why...\n\nTake my ring, {name}. Bring it to Madame Eva. That woman is a follower of old arts and makes no secret of it... call it madness, but I'll try anything at this point.", objectives = "" }
WordHunterWoW_QuestEN[26674] = { title = "Mistmantle's Revenge", description = "I'm afraid I cannot give Tobias the answers he seeks. But I can help you find the only person who can...\n\nStalvan Mistmantle.\n\nTake the ring into the woods to the north, to Manor Mistmantle, where Stalvan's body was buried. Enter, and hold the ring before you. Let the waning moon pour its light through the ring, and the spirits will answer your call.\n\nTake heed, {name}. The questions of the living can offer more comfort than the answers of the dead.", objectives = "" }
WordHunterWoW_QuestEN[26676] = { title = "Juice Delivery", description = "Here's your Zombie Juice...\n\n...and be careful with this stuff.  It's strong enough to raise the dead!", objectives = "" }
WordHunterWoW_QuestEN[26677] = { title = "Ghoulish Effigy", description = "Out here on the outskirts of town, it's a wonder the walking dead haven't eaten me!  In fact, just yesterday a pack of ghouls was pounding on the walls of my tower!\n\nI want to make an effigy - a kind of \"scarecrow\" for ghouls.  To do that I need some ghoul ribs.  You can find plenty of them on the fetid corpses wandering Manor Mistmantle's grounds, north of Darkshire...\n\nGet the ribs for me, and I will repay you with some coin.", objectives = "" }
WordHunterWoW_QuestEN[26678] = { title = "Doublerum", description = "<Baron Revilgaz sighs.>  Even with all my suspicions about Firallon's plot, we aren't prepared for a full two-front attack between the Bloodsail and the Brashtide.  It's going to take a small miracle to hold Booty Bay today.\n\nI've got a barrel of Doublerum in my chambers.  Take the stairs down three flights, and check the first door on your right.  You can ignore the warnings on the barrel... those should be the least of your worries.", objectives = "" }
WordHunterWoW_QuestEN[26679] = { title = "Return to Revilgaz", description = "Something is happening outside.  Could the Bloodsail already be here?\n\nYou'd better get Revilgaz his doublerum.  Quickly.", objectives = "" }
WordHunterWoW_QuestEN[26680] = { title = "Ogre Thieves", description = "A few weeks ago I was picking herbs far from my house, and a band of ogres attacked me!  I ran, and I was forced to leave behind a crate of precious tools and herbs.\n\nAfter they chased me off, the ogres swaggered back to the ogre mound in southern Duskwood.  I'm sure my crate is somewhere near the mound.\n\nPlease, {name}, retrieve this crate for me for I miss it sorely.", objectives = "" }
WordHunterWoW_QuestEN[26681] = { title = "Note to the Mayor", description = "Take this note to Ello Ebonlocke, the Mayor of Darkshire.\n\nHe and I are old friends...and when he reads it and discovers what you did for me...I'm sure he'll be just as happy as I am!  Hahahaha!", objectives = "" }
WordHunterWoW_QuestEN[26682] = { title = "A Shambling Threat", description = "Dustwallow is Horde territory, {name}. The humans may have their little island and their precious sand bar, but the marsh belongs to us.\n\nIn time, we will surely win this stalemate with the humans. For now, we must master our own territory. The withervine bog beasts to the north rise from the marsh itself to attack any living thing that approaches. If we own this marsh, we must not let our own land fight back against us!\n\nSlay the bog beasts, if you wish to serve the Horde. You will be rewarded.", objectives = "" }
WordHunterWoW_QuestEN[26683] = { title = "Look To The Stars", description = "My gnomish friend, Cog, has promised to help me build a device which will let me peer towards the stars. According to Cog's blueprint, what I need first is a way to reflect light.\n\nI remember a woman by the name of Mary who became well known around these parts for always carrying a looking glass.  Perhaps you can track Mary down and see if she might lend us a reflective surface for this project?  I believe she once resided in southern Duskwood. . .", objectives = "" }
WordHunterWoW_QuestEN[26684] = { title = "The Insane Ghoul", description = "The looking glass was one of my finest treasures until. . .the incident.  After that happened, I discarded it behind the barn.  There was an insane ghoul who used to roam back there.  Perhaps he picked it up.  Rumor has it the devilish beast resides in the Tranquil Gardens Cemetery.", objectives = "" }
WordHunterWoW_QuestEN[26685] = { title = "Classy Glass", description = "Now there is just one more item needed to complete this device.  Cog's blueprint calls for a lens of some sort.  The only lens I know of that would be large enough will be very difficult to acquire.\n\nThere is an ogre by the name of Zzarc'Vul who resides in the mound in southern Duskwood.  If you can, bring to me his monocle and I will use that as our lens!", objectives = "" }
WordHunterWoW_QuestEN[26686] = { title = "Bones That Walk", description = "There's even fouler undead left to deal with, {name}.\n\nTranquil Gardens Cemetery, further south of town, is a place you don't want to be caught in at night. The bones that rise from the ground there are cunning enough to remember how to swing an axe or cast a spell.\n\nI shouldn't need to explain how dangerous that makes them. Proceed with caution, but remember the people of Darkshire that will suffer if you falter.", objectives = "" }
WordHunterWoW_QuestEN[26687] = { title = "Reinforcements From Theramore", description = "Hawthorne dead... my own son murdered... the situation in the Barrens is out of control, {name}.\n\nI'm going to take charge of Fort Triumph and try to lock things down. To do that, I'm going to need reinforcements. Reinforcements that were promised from Theramore weeks ago!\n\nTravel to Theramore in Dustwallow Marsh and give Captain Garran Vimes an earful. What good is that blasted road through the swamp if the men and materiel aren't rolling in?", objectives = "" }
WordHunterWoW_QuestEN[26688] = { title = "Worgen in the Woods", description = "Darkness seems drawn inexorably to Duskwood. Master Carevin's quest is the expulsion of evil and heresy. Through our efforts are the people of Darkshire kept safe.\n\nYou believe yourself worthy to join us?\n\nI once thought as you. Disillusioned by the complacency of the Watch, I joined Master Carevin. If you wish to prove yourself, it will not be through words.\n\nTest your skills against the Nightbane worgen in Brightwood Grove. We'll see if you have what it takes to hunt these monsters.", objectives = "" }
WordHunterWoW_QuestEN[26689] = { title = "The Rotting Orchard", description = "The worgen infestation stretches further than Brightwood Grove. To the south, on the very edges of Darkshire itself, the Rotting Orchard is host to even more of the savage beasts.\n\nThe worgen there are more cunning, {name}, but just as savage and evil. They conjure foul shadows to tear their enemies apart from a distance. Go to the Rotting Orchard, and slay the Shadow Weavers to keep the town safe!", objectives = "" }
WordHunterWoW_QuestEN[26690] = { title = "Vile and Tainted", description = "Your previous accomplishments have convinced me that you are ready to take on the toughest worgen infesting the woods.\n\nOf the worgen that have made their new home here, the Vile Fangs and the Tainted Ones have proven the most dangerous. They've settled down near some of the caves and in the mine to the south.\n\nFrom far away you can even see the light from their bonfires...", objectives = "" }
WordHunterWoW_QuestEN[26691] = { title = "Worgen in the Woods", description = "Here you go, {name}. Bring this message to Master Carevin.\n\n<He quickly removes a piece of faded parchment and offers it to you.>\n\nA few more like you, and we will outnumber the Night Watch! Perhaps then we could complete the work that we few carry on today.", objectives = "" }
WordHunterWoW_QuestEN[26692] = { title = "Shadowhide Extinction", description = "Now that every Blackrock orc south of Lake Everstill is nothing more than ash and cinder, we can turn our attention to the Shadowhide gnoll army of Galardell Valley, directly north of here.\n\nI want you to head out there and kill 'em all, {name}! Initiate Operation: Extinction, soldier. For Bravo Company and for the Alliance!", objectives = "" }
WordHunterWoW_QuestEN[26693] = { title = "The Dark Tower", description = "We got lucky with some vital intelligence from the locals of this valley. Those two behind us, the Ranthals, have informed me that the gnolls in Galardell Valley are being controlled by a powerful magus in the tower of Ilgalar. The problem is that the tower is sealed by a magical force field.\n\nThe first thing we need to do is get the key that will get you inside. The gnoll general, Fangore, has your ticket inside. Kill General Fangore and get the key.\n\nI'll be in touch.", objectives = "" }
WordHunterWoW_QuestEN[26694] = { title = "The Grand Magus Doane", description = "<The Bravo Company field kit vibrates.>\n\nGood work, kid. I've got some vital intel for you. The magus in the tower is a human named Doane. Damned traitor is working for the Blackrock orcs. I want him dead.\n\nUse the key of Ilgalar and get inside that tower. Work your way to the top and show Doane what Bravo Company does with traitors.\n\nRendezvous back at Shalewind Canyon when the deed is done.\n\nKeeshan, over and out.", objectives = "" }
WordHunterWoW_QuestEN[26695] = { title = "Prepare for Takeoff", description = "I've got an idea, but it's going to involve some footwork on your part.  As a goblin cartel, the Blackwater Raiders have a lot of explosives on hand.  In fact, I know for a fact that our old friend Narkk keeps a case in the back of his shop, in the Old Port Authority.\n\nGo grab them and bring them here, if they haven't already exploded.", objectives = "" }
WordHunterWoW_QuestEN[26696] = { title = "The Call of Kalimdor", description = "Say, you haven't seen a fish about this long?  Short fins?  Responds to the name Steve?  He's blue?\n\nNever mind, I'll keep looking.\n\nActually... there was another reason I came here to Booty Bay.  Boss Krog, over in Dustwallow, is looking for new blood.  Someone to help us Stonemaul from getting overrun.  You look strong enough.\n\nWait on the edge of the pier for the next ship, then ride to Ratchet.  Gazlowe should be able to help you from there.\n\nSteve?  Steve!", objectives = "" }
WordHunterWoW_QuestEN[26697] = { title = "The Final Voyage of the Brashtide", description = "We'll never survive this attack with all these worgen pirates pouring into the harbor from the north.  Luckily, it looks like they're not armed with cannons, so if we can get you out of the harbor, you can attack from the skies.\n\nKebok, the Horde flight master's assistant, is right around the corner.  Talk to him and let him know that you're going to need his bravest wind rider.\n\nBring a couple armloads of handbombs with you.  You'll need all of them to stop those attack boats!", objectives = "" }
WordHunterWoW_QuestEN[26698] = { title = "Seeking Seahorn", description = "When the Brashtide pulled in, Seahorn grabbed the nearest weapon he could find and jumped off the ledge here.  You'll find him down below, probably pounding new holes into those worgen's skulls.\n\nHelp him out down there.  I can handle the motivation from up here.", objectives = "" }
WordHunterWoW_QuestEN[26699] = { title = "Turning the Brashtide", description = "The Brashtide are everywhere!  The Baron's Booty Bay Bruisers are no match for their sheer numbers, I'm afraid.\n\nWhile you're down here in the fray, why don't you help me get rid of a few of them?\n\nWhen you're done, don't bother coming back here.  I'll probably be pretty busy.", objectives = "" }
WordHunterWoW_QuestEN[26700] = { title = "The Damsel's (Bad) Luck", description = "I heard that this ship here is the Damsel's Luck.  Didn't you used to be the captain of that thing?  You must know your way around it, then.\n\nThe Brashtide are our main concern, but we still don't want to take an unnecessary pummeling from those cannons of theirs.  Grab this rope behind me and take out some of those angry-looking corsairs.  Check in with the Baron when you're done.", objectives = "" }
WordHunterWoW_QuestEN[26701] = { title = "Flight to Brackenwall", description = "Listen, I got no special love for the Horde... but then again, I got no real hate for you guys either.\n\nYour gold is as good as anyone else's.\n\nThat two-headed ogre and his pet fish left some gold for your travel costs.  I believe the person you're looking for in Dustwallow goes by the name of Krog.  And the best way to get there is to talk to our flight master, Bragok.  He'll fly you there, if you want.  The flight's free, thanks to your friend.", objectives = "" }
WordHunterWoW_QuestEN[26702] = { title = "Flight to Theramore", description = "Listen, I got no special love for the Alliance... but then again, I got no real hate for you guys either.\n\nYour gold is as good as anyone else's.  Sometimes better.\n\nJeyne left some gold for your travel costs.  I believe the person you're looking for in Dustwallow goes by the name of Calia Hastings.  And the best way to get there is to talk to our flight master, Bragok.  He'll fly you there, if you want.  The flight's free, thanks to your friend.", objectives = "" }
WordHunterWoW_QuestEN[26703] = { title = "Bloodsail's End", description = "We've nearly won the day, largely thanks to you.  One task remains, however... kill Fleet Master Firallon.\n\nIt looks like most of Firallon's crew is already dead, but I know that old sea dog well enough to know that he's not done yet.  No, he's cooped up tight in his cabin, ready to go down with his ship.\n\nSpeak with Kebok again to get a wind rider.  I'll try to hold off the cannonfire while you're on board.", objectives = "" }
WordHunterWoW_QuestEN[26706] = { title = "Endgame", description = "We need to get rid of that flying gunship if our people have any chance of escaping.\n\nHere's the plan.  Keel Harbor had its share of rebel sympathizers in the old days.  I've managed to round up a hefty amount of incendiary explosives from one of our storehouses.\n\nWe're going to hit the enemy with a force small enough to fly undetected.  The night elf hippogryphs should do the trick.\n\nTobias will give you the signal when we're ready to go.", objectives = "" }
WordHunterWoW_QuestEN[26707] = { title = "A Deadly Vine", description = "I need large amounts of corpseweed for Master Harris's concoctions. It's difficult to obtain, but we can't let our supply dwindle.\n\nCorpseweed is tough stuff to tangle with... the plant will get you before you get it, if you're not careful! But if you'd like to help out, I'll eagerly pay you for any you gather yourself.\n\nYou'll find plenty of it all over the Yorgen Stead to the southeast.", objectives = "" }
WordHunterWoW_QuestEN[26708] = { title = "AHHHHHHHHHHHH! AHHHHHHHHH!!!", description = "I'm here to help you and Bravo Company end this mess. You're to get in the Bravo Company siege tank and clear a path to Keeshan's Post on the other side of the valley, north of here.\n\nThis is a high alert situation soldier as the Blackrock orcs are now aware of your location and sending a large force to meet you head on. Terminate them all with extreme prejudice.\n\nI'll see you on the other side. May the Light have mercy on your soul.", objectives = "" }
WordHunterWoW_QuestEN[26709] = { title = "The Stone Throne", description = "I am returning to my throne. I've no desire to see any more of these Earthen Ring, but you remain welcome here, {race}. If you wish to help us rebuild our realm, perhaps we can help you in return.\n\nAll things in time.\n", objectives = "" }
WordHunterWoW_QuestEN[26710] = { title = "Lost In The Deeps", description = "Pebble has gotten himself lost again, somewhere deep in the Crumbling Depths.\n\nHe's fortunate that his size makes him unworthy of the effort for those gyreworms, but it's only a matter of time before he stumbles too close to one and gets eaten. Whatever he's so intent on down there is certainly not worth it.\n\nHe seems to like you. Please, go and find him and bring him out of those tunnels to safer playing grounds.", objectives = "" }
WordHunterWoW_QuestEN[26711] = { title = "Off to the Bank", description = "Yo, baby. Wassup? You ready for the party?\n\nNo?! You know I love you, so I don't know how to say this, but check it... I think you need to swing into town to buy a new outfit for the party.\n\nDon't look at me like that... you want to look gooood, right? Don't you want to look super fine for me? I am your contractually-obligated boyfriend after all!\n\nSwing by the bank first and pull out plenty of macaroons. You don't want to buy any of that cheap stuff!", objectives = "" }
WordHunterWoW_QuestEN[26712] = { title = "Off to the Bank", description = "Hi, babe. Are you ready for the party?\n\nNo?! You know I love you, right? I think you need to swing into town and buy a new outfit for the party.\n\nDon't look at me like that... you want to look your best? Don't you want to look good for me? I am your contractually-obligated girlfriend after all!\n\nMake sure you swing by the bank first and pull out plenty of macaroons. Don't buy any of that cheap stuff!", objectives = "" }
WordHunterWoW_QuestEN[26713] = { title = "Showdown at Stonewatch", description = "Only the Blackrock high command remains, {name}. They're all holed up in Stonewatch Keep, directly south of our position here at Keeshan's Post. I want you and the rest of Bravo Company to enter Stonewatch and put an end to the Blackrock orc invasion.\n\n{name}, no survivors.", objectives = "" }
WordHunterWoW_QuestEN[26714] = { title = "Darkblaze, Brood of the Worldbreaker", description = "As Troteman cuts out, the world around you grows eerily silent. In the distance you see a full grown black dragon!", objectives = "" }
WordHunterWoW_QuestEN[26717] = { title = "The Yorgen Worgen", description = "My kinsmen at Raven Hill are concerned with curing the feral worgen in these forests. The condition itself cannot be lifted, but sanity can be restored to those not too far gone.\n\nWhile most here have proven beyond help, we keep an eye out for those that retain vestiges of their minds... attachments to their old lives.\n\nI've seen a lone worgen lurking the Yorgen Farmstead, digging in a pile of dirt between the buildings...could you check out that pile and see if he's left anything?", objectives = "" }
WordHunterWoW_QuestEN[26719] = { title = "Delivery to Master Harris", description = "Master Harris will want to know of this immediately.\n\nHere, take this package of corpseweed down the road to the camp at Raven Hill. Tell him what we saw at the Yorgen Stead.", objectives = "" }
WordHunterWoW_QuestEN[26720] = { title = "A Curse We Cannot Lift", description = "What we do here is not a cure. The transformation cannot be removed once inflicted. But the mind...\n\nThe mind can be restored, through alchemy,  if enough is left intact. This worgen you've encountered sounds like he's fighting to stay aware, {name}. We've got to find him again.\n\nIf he's fled the Yorgen Stead, search the Addle Stead to the south; he may be lurking in one of the buildings.\n\nInject him with this ampule to tranquilize him. You'll need to be quite close.", objectives = "" }
WordHunterWoW_QuestEN[26721] = { title = "The Jitters-Bugs", description = "M-Master Harris requires many reagents for his serums. He has me gather them for him.\n\nMost of it's not so bad... I mean, the corpseweed is pretty bad, but it's not as bad as the widow venom. Have you seen the widows around here? The hatchlings are the size of a man. Even with a gun, I can't stand to go out hunting them!\n\nIt's just too terrifying. If you'll go do it for me, I'll gladly pay you! Just bring me back some widow venom! You'll find them all in the woods to the east, just north of the road.", objectives = "" }
WordHunterWoW_QuestEN[26722] = { title = "Buried Below", description = "<You attach the arch to the rod, and the artifact is nearly complete. A large gap still sits at the center of the holy symbol's head.>\n\n<Once again you feel it tug your arm, urging you towards the hole in the wall and the winding tunnel ahead. The last piece must be through there.>", objectives = "" }
WordHunterWoW_QuestEN[26723] = { title = "The Fate of Morbent Fel", description = "Before I was lost to the woods, the last thing I remember is Morbent Fel. He was a vile necromancer, and the reason this land swarms with so many vile undead.\n\nI asked an adventurer to help me put an end to him. I thought they did! But Sister Elsington tells me the land still crawls with ghouls and spectres ripped from the grave.\n\nMorbent Fel should have breathed his last in the house on Forlorn Rowe, north of Raven Hill Cemetery. Go there and see what's become of him...", objectives = "" }
WordHunterWoW_QuestEN[26724] = { title = "The Lurking Lich", description = "The others here share my suspicion. Morbent Fel lives on in undeath...and may be even more powerful than before. A necromancer was struck down, but a lich may have risen in his place. And now he continues to ruin this land.\n\nI remember Duskwood before all this, {name}. I remember bright skies and peaceful woods. This can't stand! Morbent Fel must be stopped for good.\n\nSpeak to Sister Elsington. Her vision might guide you to where Morbent Fel is, and how he can be defeated.", objectives = "" }
WordHunterWoW_QuestEN[26725] = { title = "Guided by the Light", description = "Sven is correct. I can feel the presence of a powerful evil deep beneath the Raven Hill Cemetery. Evil lurks in its catacombs, and Morbent Fel must be the source.\n\nYou will need the power of the Light to strike him down, {name}. Sven told me the heroes who first slew Morbent Fel wielded an artifact of lightforged iron, imbued with holy power. That artifact is still here!\n\nI can feel it as well, a glimmer of light amidst the darkness. Search Raven Hill for it, and let the Light guide you through it.", objectives = "" }
WordHunterWoW_QuestEN[26726] = { title = "Triumphant Return", description = "Return to Lakeshire and let Solomon know that the Blackrock invasion has been stopped. Make sure he understands the cost at which our freedom came - that we lost five of our finest heroes to save Redridge and ultimately, Stormwind.\n\nYou are the last surviving member of Bravo Company, {name}. It is up to you to keep its legacy alive.\n\nDismissed.", objectives = "" }
WordHunterWoW_QuestEN[26727] = { title = "The Embalmer's Revenge", description = "You're not the first fool to be manipulated by Abercrombie! That doddering old man is known as The Embalmer to us. He's a vile necromancer and a blight upon this town.\n\nAnd now, sewn together and given life by the very materials you brought him, his horrible creation approaches!\n\nThat hideous creature will be upon us in mere moments! If you have any heart, {name}, you'll help the Night Watch drive off the abomination and save our town!", objectives = "" }
WordHunterWoW_QuestEN[26728] = { title = "Hero's Call: Duskwood!", description = "{name}, the citizens of Duskwood are in dire need of your assistance! I have here a letter from Commander Althea Ebonlocke, leader of the Night Watch, pleading for help.\n\nTo reach Darkshire you should travel across the bridge located in the southwest corner of Redridge. Once you cross the bridge you will be in Duskwood. Then you just follow the road to Darkshire. Beware of the savage beasts that stalk the countryside!", objectives = "" }
WordHunterWoW_QuestEN[26729] = { title = "Water Elementals", description = "I arrived in Stranglethorn to study a feature known as the Altar of Naias, but made the unfortunate choice of denying Colonel Kurzen's advances, which earned me several years in that cage.  Now that I'm out, I figure I might as well continue with my original studies.\n\nThe altar is on an island to the west, south of Zul'Kunda.  Gather some of the bracers from the island's water elementals.\n\nOh, and you can use this device when you're finished.  No need to make you walk all the way back here.", objectives = "" }
WordHunterWoW_QuestEN[26730] = { title = "You Can Take the Murloc Out of the Ocean...", description = "I need something to cut into the raw, elemental power of these bracers... something strong and abrasive, but still of the sea.\n\nThe Murkgill murlocs have moved inland from the sea, but they still carry vials of sea salt on them.  What they use it for, I can't be sure, but it will serve for our studies.  You can find the Murkgill in the glade south of the Rebel Camp and east of Bal'lal ruins.", objectives = "" }
WordHunterWoW_QuestEN[26731] = { title = "The Altar of Naias", description = "The salt you brought was sufficient to activate the bracers' innate enchantments.  I have taken these enchantments and combined them into a summoning token... a gift, if you will.\n\nReturn to the Isle of Naias, and place the gift on Naias' altar.  Call me again once you have Naias' heart.", objectives = "" }
WordHunterWoW_QuestEN[26732] = { title = "Bad Medicine", description = "I have a feeling that Kurzen's Medicine Men are distributing more than just medicine.  Kurzen needs some way to quelch insubordination, and an elixir under the guise of \"medicine\" would be the perfect way to do that.\n\nWe need those remedies for research.  Search the Kurzen Compound to the southeast - his medicine men and jungle fighters should carry the remedies on their bodies.", objectives = "" }
WordHunterWoW_QuestEN[26733] = { title = "Control Sample", description = "<Brother Nimetz analyzes the samples you've given him.>\n\nThis... this is just basilisk blood!\n\nNo, it's mostly basilisk blood.  They've added something to it though.  I'll need a control sample to perform a proper comparison.\n\nThey most likely obtained the blood from the crystal spine basilisks, found to the east of their compound.  Bring me back some pure samples, and I'll have this elixir figured out.", objectives = "" }
WordHunterWoW_QuestEN[26734] = { title = "The Source of the Madness", description = "After reducing the basilisk blood out of the elixir, I've uncovered an unusual precipitate.  It appears to be a blue crystal of some sort...\n\n<Brother Nimetz consults his notes.>\n\nIt's not a singing blue crystal... not a pulsing blue shard...\n\n<He flips forward a few pages.>\n\n... not a piece of the Mind's Eye.  Nope, this isn't something we've seen before in Stranglethorn.  If anyone has any more of this substance, I want it.  Check the high-ranking Kurzen troops, in the back of their cave.", objectives = "" }
WordHunterWoW_QuestEN[26735] = { title = "The Fate of Kurzen", description = "Hello, {class}.\n\nWe are soldiers of Stormwind, and rebels from Kurzen's Compound, a large outpost that you'll find just to the southeast of here.  We were under the command of Colonel Kurzen, until he and those close to him started to descend into madness...\n\nWe rebelled, set up camp here, and stood against Kurzen.  Now, my sources are telling me Kurzen has disappeared.  I trust my source, but it would help to hear from a third party.  Please, head into the compound and find some documentation of his fate.", objectives = "" }
WordHunterWoW_QuestEN[26736] = { title = "Spared from Madness", description = "Kurzen's death is a relief, but what's more interesting, and perhaps more immediate, is the sign of some potential allies within the compound.\n\nI don't care what it says on that prison record, I know EXACTLY why those 3 were locked up: refusal to follow orders.  They must have been spared from the madness, much like my fellow rebels here, and incarcerated for speaking up.\n\nFind them, {name}.  Find them, and send them back here.", objectives = "" }
WordHunterWoW_QuestEN[26737] = { title = "Stopping Kurzen's Legacy", description = "Now that our allies have been evacuated, it's time to run a final raid on Kurzen's Compound.  They will never be weaker than they are right now, and with your help, we may be able to weaken them beyond repair.\n\nThose four names that were listed in the Officers' Dossier - Anders, Gaulus, Miranda, and Esquivel - will be the highest-ranking personnel remaining.  Look for them in that cave in the back of their compound.  Removing all four will be devastating to Kurzen's forces.\n\nGo with honor, {name}.", objectives = "" }
WordHunterWoW_QuestEN[26738] = { title = "Just Hatched", description = "While looking through this soldier's possessions, you look down to see a newborn raptor hatchling looking back up at you.  Was it following this Kurzen militiaman the whole time?\n\nYou can see it studying you, learning your features and following your movements.\n\nThe lashtail hatchling has formed a bond with you.\n\nPerhaps someone back at the Rebel Camp will know what to do with a raptor hatchling.", objectives = "" }
WordHunterWoW_QuestEN[26739] = { title = "I Think She's Hungry", description = "It looks like your young raptor is hungry.  If you're looking to keep her, why don't you find something for her to eat?  The lashtail often attack the basilisks of Stranglethorn, which can be found to the east, beyond Kurzen's Compound.\n\nShe probably isn't strong enough to hunt on her own yet, but I'm sure she will eat freshly killed basilisk meat.", objectives = "" }
WordHunterWoW_QuestEN[26740] = { title = "Krazek's Cookery", description = "I do most of the cooking at the camp.  It used to be a lot of work, until I bought a mechanical cooking pot from a goblin merchant.  The pot is a wonder!  It saved me countless hours...until it broke!\n\nCan you take the pot back to the goblin for me so he can fix it?  His name is Krazek.  Last I heard, he was staying with Nesingwary in the hunters' camp just to the south.", objectives = "" }
WordHunterWoW_QuestEN[26742] = { title = "Bloodscalp Insight", description = "I never got to properly thank you for saving me.\n\nThank you, {name}.\n\nI'm still a little fatigued from my captivity, so I thought you might help me with my studies.  As a shaman of the Wildhammer clan, I'm very interested in the shamanic practices of the Bloodscalp tribe.\n\nTheir magic seems to have diverged in an interesting direction.  If I had one of the totems that their shaman use, I could begin my studies.  You'll find them at the Bal'lal ruins, on the coast to the southwest.", objectives = "" }
WordHunterWoW_QuestEN[26743] = { title = "Sacred to the Bloodscalp", description = "Ahh... these must be names of their totemic creatures - the animals that they attribute to the spirits.  Let's see... Mahamba as water, Tsul'Kalu as earth, Pogeyan as... air?  Fire?  I can't make this part out.\n\nI'd like some more information on these spirits of theirs.  The Bloodscalp have a camp close to here, in the Tkashi ruins.  Maybe you can find some details there.", objectives = "" }
WordHunterWoW_QuestEN[26744] = { title = "Deep Roots", description = "On a somewhat unrelated note, I've been putting together a collection of troll stories and legends for a... personal project.  I was just thinking you might be able to help me find some of them.\n\nThe Bloodscalps at the Bal'lal ruins, on the coast to the southwest, maintain a large tablet documenting some of their stories.  Of course, I'll reimburse you if you're able to bring any of these stories back to me.", objectives = "" }
WordHunterWoW_QuestEN[26745] = { title = "Favored Skull", description = "Your pet raptor seems to have found a new toy: a skull, from a nearby troll skull pile.\n\nWhat sets this skull apart from the rest is beyond you, but for some reason, she won't put it down.\n\nOsborn Obnoticus, the gnome you saved from Kurzen's Compound, is an expert in troll history and physiology.  Maybe he'll have some idea what makes this one so special.", objectives = "" }
WordHunterWoW_QuestEN[26746] = { title = "A Nose for This Sort of Thing", description = "<Osborn looks at the skull again.>\n\nIn life, he was strong, powerful, a lord among trolls.  With our help, he can be a lord once more.\n\nThe Bloodscalp scavengers that wander the ruins to the southwest hoard magical fetishes that can help us.  They hide these artifacts under the ground.  Use your hatchling to find these artifacts, {name}... then bring them here.", objectives = "" }
WordHunterWoW_QuestEN[26747] = { title = "A Physical Specimen", description = "The soul is ready, but the body is not.  For a skull as well-formed, as marvelous, as beautiful as this... we will need a suitable body.\n\nThe chief of the Bloodscalps, Gan'zulah, won his throne with brute force.  If he still lives, you'll find him in Zul'Kunda, to the west.\n\nTaking his body won't be easy, but nothing a sturdy {class} like yourself couldn't handle.  Bring it back here when you're done.", objectives = "" }
WordHunterWoW_QuestEN[26748] = { title = "Bloodlord Mandokir", description = "{race}.  You just resurrected your worst nightmare.  You didn't think I was a friend, did you, {race}?  Ah, ha ha haaaa!\n\nYou've served your purpose.  I've returned to the realm of the living, and it's all thanks to you.  So, instead of killing you, I'm going to make you a deal instead.\n\nGive me that raptor.\n\nYou must already know that she's no normal raptor, and I need a replacement for Ohgan.  Do it, or both you and the gnome will taste my rage.", objectives = "" }
WordHunterWoW_QuestEN[26749] = { title = "Priestess Thaalia", description = "Thank you, {name}.  I know you didn't have to save my life.\n\nThe return of Bloodlord Mandokir is ill news.  He was killed inside Zul'Gurub several years ago, and we thought we had seen the last of him and his kind.  The trolls of Zul'Gurub were attempting to perform a hideous, horrible ritual.  If Mandokir is alive, then it stands to reason that he is not the only one.\n\nThe explorers at Fort Livingston, far to the south, may know more.  Speak with their priestess.", objectives = "" }
WordHunterWoW_QuestEN[26750] = { title = "At the Stonemother's Call", description = "It is time. The Stonemother will speak with you. You can find her throne in northern Deepholm, above the Scoured Reach.", objectives = "" }
WordHunterWoW_QuestEN[26751] = { title = "Population Con-Troll", description = "I understand you may be headed to Zul'Kunda soon.  While you are there, I have a small task for you.\n\nThe trolls are outgrowing Stranglethorn.  The Bloodscalp in the West, the Skullsplitters in the East... they pour out of their ruins and into the jungle, disrupting the natural balance of the region.  It is time we restored that balance.\n\nZul'Kunda is the Bloodscalp capital.  Inside you will find the most high-ranking Bloodscalps.  Reduce their numbers, then return to me.", objectives = "" }
WordHunterWoW_QuestEN[26752] = { title = "Audience with the Stonemother", description = "Stay where you are, champion. I have not yet decided what to do with you or your Earthen Ring.", objectives = "" }
WordHunterWoW_QuestEN[26753] = { title = "The Halls of the Dead", description = "<In front of you, the bare earth slopes down towards the dark entrance to the crypts.>\n\n<You can feel the tug of the lightforged artifact urging you towards it. Perhaps the other piece is down there?>", objectives = "" }
WordHunterWoW_QuestEN[26754] = { title = "Morbent's Bane", description = "<The pieces fit, and the holy artifact is restored, gleaming with sacred light. This should let you defeat Morbent Fel's dark magic.>\n\n<Further down the tunnel, away from the direction you came from, a heinous cackle rings out. It's the clattering laugh of a lich. Morbent Fel is just ahead!>", objectives = "" }
WordHunterWoW_QuestEN[26755] = { title = "Keep Them off the Front", description = "Oh good, you brought another catapult with you! Clay might be older than dirt, but he makes a mean war machine.\n\nWell, you didn't bring it all the way out here for your health, flesh bag. Get in one of those things and bombard the fungal terrors and reinforcements streaming out of Needlerock Slag.\n\nWe have to keep them off the front!", objectives = "" }
WordHunterWoW_QuestEN[26760] = { title = "Cry For The Moon", description = "I'm hopeful, but let's remain professional. It's business as usual for this one.\n\nInto the guillotine he goes... and if the alchemy doesn't take, he won't be getting back out of it.\n\nJitters and I will attend to this. Please, just stand back and watch from a safe distance.", objectives = "" }
WordHunterWoW_QuestEN[26761] = { title = "Threat to the Kingdom", description = "There is no doubt that the Defias pose a great threat to the kingdom, but we certainly cannot enter their hideout and hope that everything will work itself out. No, an assault against the Defias is going to take time and planning. I want you to leave the logistics to me. Our kingdom has other threats that must be dealt with immediately!\n\nTravel east through Elwynn to Redridge and report to Magistrate Solomon in Lakeshire. I will call for you when we are ready to attack the Defias.", objectives = "" }
WordHunterWoW_QuestEN[26762] = { title = "Reactivate the Constructs", description = "We sent a number of our war constructs north into Needlerock Slag, but none of them ever returned. We know that the stone trogg mystics have done something to them.\n\nWhat we're concerned about is that the mystics will control and turn them against us, like they have with the fungal giants.\n\n{name}, go into the stone trogg town and reactivate the constructs.", objectives = "" }
WordHunterWoW_QuestEN[26763] = { title = "Venture Company Mining", description = "If I'm going to repair this pot, I'm going to need reagents.  And to get them, you're going to have to do an eensy little bit of killing.  I hope you don't mind.\n\nThose dastardly Venture Company geologists have been collecting some tumbled crystals that will suffice for what I need.  You'll find them around their Base Camp, on the other side of Lake Nazferiti, to the east.\n\nI don't care what you have to do to get them. ", objectives = "" }
WordHunterWoW_QuestEN[26764] = { title = "A New Low", description = "You may notice that the Venture Company has completely clear-cut all the trees around their Base Camp to the east.  Not one to miss out an opportunity for profit, their foreman has enslaved druids, and is forcing them to re-grow the forest so they can chop it down again!\n\nPersonally, I find this abhorrent, and not just because I didn't think of it first.\n\nRelease a few of these druids from their captors.  I'm sure they'll appreciate it.", objectives = "" }
WordHunterWoW_QuestEN[26765] = { title = "Return to Corporal Kaleb", description = "So, this pot is fixed.  I even added an extra steam whistle, and look!  There's a new chopper at the bottom that'll cut through leg bones!\n\nYes yes, Krazek's Crock Pot is a 100% cook pleaser!  I'm sure its owner will be satisfied.", objectives = "" }
WordHunterWoW_QuestEN[26766] = { title = "Big Game, Big Bait", description = "We're only going to get one shot at capturing Abyssion, {name}.  Let's make it count.\n\nWe'll test out the trap on the biggest of the stone dragons in the Alabaster Shelf.\n\nTo lure the stone matriarch, we're going to need to gather sufficient bait.\n\nTake this knife and carve 5 sides of basilisk meat.  That ought to be enough even for her appetite.", objectives = "" }
WordHunterWoW_QuestEN[26767] = { title = "Figuring out how to make quests", description = "Whee!  You get to make a breadcrumb quest!  Now figure out what to do next.", objectives = "" }
WordHunterWoW_QuestEN[26768] = { title = "To Catch a Dragon", description = "Having a dragon guard the fragment was a smart move on the enemy's part.  They can keep moving its location any time we get close to it.\n\nCatching Abyssion will be extremely difficult, but I have a plan that might help.\n\nThe Twilight's Hammer uses magical traps to bind stone drakes to the ground while they drain their energy.\n\nIf we can get our hands on one of these, we might be able to ground the Twilight Dragon for just long enough.\n\nGo east of here, to the Alabaster Shelf, and obtain a trap.", objectives = "" }
WordHunterWoW_QuestEN[26769] = { title = "Raging River Ride", description = "Enjoy your cut of the loot, {name}!\n\nI hate to share, but business is business. And that double-dealer Nozzlepot is guaranteed a 10% cut of this treasure. Can you deliver this to him at his outpost in the north?\n\nHe's got a little research station upstream, along the river. If you travel just northeast of town here, Horton Hornblower can give you a free ride on one of his riverboats. Tell him I sent ya!", objectives = "" }
WordHunterWoW_QuestEN[26770] = { title = "Mystic Masters", description = "The Needlerock mystics have taken control of the fungal giants that have sprouted in their chasm, down below. Now they seek to control our war constructs.\n\nGo north into Needlerock Slag and do something about it! Isn't that what you're here for?", objectives = "" }
WordHunterWoW_QuestEN[26771] = { title = "Testing the Trap", description = "You must set the trap for the matriarch now.\n\nGo to the western end of the Alabaster Shelf and place the trapped basilisk meat in the center of the feeding grounds.", objectives = "" }
WordHunterWoW_QuestEN[26772] = { title = "Mind Vision", description = "To know Mandokir, you must see Mandokir.\n\nTo see Mandokir, you must use eyes of raptor.\n\nYou have formed bond with raptor: Ohgan'aka: daughter of Ohgan.\n\nTo strengthen bond, we need feathers.\n\nYou will go northeast, and you will find the feathers, yes.", objectives = "" }
WordHunterWoW_QuestEN[26773] = { title = "See Raptor", description = "We have the feathers, yes.\n\nWe have the {class}, yes.\n\nSpeak with Priestess when you are ready.", objectives = "" }
WordHunterWoW_QuestEN[26774] = { title = "Mind Control", description = "Mind Vision is not enough, no.\n\nMind Control, much more powerful magic, yes.\n\nPowerful magic needs powerful reagents, and troll brain is a powerful reagent.\n\nBraddok in Zul'Mamwe, very smart, yes.\n\nHead south, and check out the big brain on Braddok.", objectives = "" }
WordHunterWoW_QuestEN[26775] = { title = "Be Raptor", description = "Mind Control, very powerful, yes.\n\nWith luck, you can help Ohgan'aka escape from Zul'Gurub.\n\nThen, Ohgan'aka becomes {name}'aka again!\n\nSpeak to Priestess, yes, and help {name}'aka escape.", objectives = "" }
WordHunterWoW_QuestEN[26776] = { title = "Ghaliri", description = "Priestess is not very good at speaking Common, no.\n\nMaybe you go speak with Ghaliri, in front of that tent.\n\nTell him about what you've seen inside Zul'Gurub, yes.", objectives = "" }
WordHunterWoW_QuestEN[26777] = { title = "Soothing Spirits", description = "This is a tragic land, with a history of violence and despair. While many of the dead roam in the flesh, some are simply lost souls, wandering in confusion.\n\nThey deserve to be put at ease.\n\nMany of these souls gather at the Addle Stead to the south, appearing before travelers. Take this censer of holy incense. Sway it before the forlorn spirits, and let the offering of its gentle scent give them peace.", objectives = "" }
WordHunterWoW_QuestEN[26778] = { title = "The Cries of the Dead", description = "Can you hear them, {name}? There's so many of them. They wander their graves, shuffling across the cold ground on rotting limbs.\n\nThe dead cry out in the still air. They suffer in their own flesh, forced from sleep! Every night I venture to the graveyard to put more of them to rest, but it's never enough.\n\nHelp me, {name}. Put the ghouls that swarm Raven Hill Cemetery out of their misery. Strike down as many as you can.", objectives = "" }
WordHunterWoW_QuestEN[26779] = { title = "Zul'Mamwe Mambo", description = "The Skullsplitters are an embarrassment to the troll empire.  Their petty squabbles with the Bloodscalps have torn Northern Stranglethorn apart.  Where tribes like the Darkspear and the Zandalari thrive, the Skullsplitters fight over ruins.\n\nI have been authorized to issue rewards to mercenaries who are willing to deliver punishment to the Skullsplitters.  I encourage you, and anyone you know, to travel east into Zul'Mamwe and cull their wayward tribe.", objectives = "" }
WordHunterWoW_QuestEN[26780] = { title = "Nighttime in the Jungle", description = "Nighttime in Stranglethorn is a beautiful thing.  The skies fill with stars, and the moon casts its rays right between those leaves, right there.  I could stare at these skies all night.\n\nUnfortunately, the trolls that walk the ruins of Zul'Mamwe are interfering with my astronomy.  They burn braziers, day and night, which rob me of the darkness I need.\n\nPlease, {name}... travel east into Zul'Mamwe and put them out.", objectives = "" }
WordHunterWoW_QuestEN[26781] = { title = "The Mind's Eye", description = "One of the Vale's many treasures lies nearby, on OUR side of the giant whirlpool.  The Mind's Eye is held by an ogre mage, in the Mosh'Ogg ogre mound just to the northeast.  His name is Mai'Zoth.  From what I understand, he is vicious, and his magic is strong.\n\nAnd if he has the Mind's Eye, then his magic will be stronger still.\n\nThus far I've been unable to get near enough to take it from him.  Will you give it a try?", objectives = "" }
WordHunterWoW_QuestEN[26782] = { title = "The Mosh'Ogg Bounty", description = "There's been some activity up north, at the rebel camp.  I just heard from a soldier named Nimetz that some {race} {class} up there found the key to what's been driving them so crazy.  That wasn't you, was it?\n\nAnyhow, he sent a sample to me, and it looks just like the rocks I've been seeing over at the Mosh'Ogg Ogre Mound, to the northeast.\n\nI've heard that the ogres are guarding a chest up in some ruins behind their mound.  I suspect it may be related.  Care to fetch it for me?", objectives = "" }
WordHunterWoW_QuestEN[26783] = { title = "The Mosh'Ogg Bounty", description = "There's been some activity up north, at the rebel camp.  I just heard from a soldier named Nimetz that a {race} {class} up there found the key to what's been driving them so crazy.  That wasn't you, was it?\n\nAnyhow, he sent a sample to me, and it looks just like the rocks I've been seeing over at the Mosh'Ogg Ogre Mound, to the northeast.\n\nI've heard that the ogres are guarding a chest up in some ruins behind their mound.  I suspect it may be related.  Care to fetch it for me?", objectives = "" }
WordHunterWoW_QuestEN[26784] = { title = "Muddied Waters", description = "The elemental powers are strong here in the Highlands, {name}. It is why the Twilight's Hammer chose to build their stronghold here.\n\nIn the right hands, we can channel this energy into something productive... like a portal directly to Orgrimmar.\n\nNorthwest of here, at the Verrall River Delta, water elementals have been stirred up by the actions of our foes upstream. Destroy them and gather 5 whirlpool cores. You'll not only calm the river, you'll power up our portal. ", objectives = "" }
WordHunterWoW_QuestEN[26785] = { title = "Part of the Pack", description = "I've been trying to keep my true self hidden away from the people of Darkshire... they seem to react poorly to worgen. There are more of us here, though, beyond the city.\n\nThe companions I first traveled here with search the woods for wild worgen. They believe some of them, ones with telltale signs, can still be returned to sanity.\n\nI'm not quite ready to rejoin them. Please send word to Apprentice Fess at the crossroads west of town that I'll be staying in Darkshire a while longer.", objectives = "" }
WordHunterWoW_QuestEN[26786] = { title = "Securing the Beach Head", description = "Something troubles me, {name}. The Twilight dragons knew just where and when to strike our airfleet. It's as if they knew our plans.\n\nTwilight spies cower within our midst!\n\nI'm going to take one of our remaining ships back to Orgrimmar to roll some heads. I need you to stay behind and secure this front. The Dragonmaw shaman are powerful; I have asked them to open up a portal to Orgrimmar, and I need you to help.\n\nSo. Start helping!", objectives = "" }
WordHunterWoW_QuestEN[26787] = { title = "Bear In Mind", description = "I'm afraid that... well, I'm just plain afraid, but I'm also sorry to have to ask for another favor.\n\nMaster Harris needs brains. Bear brains. They're part of the serum apparently, or at least a proper substitute.\n\nThere's plenty of black bears in the woods to the west, and along the riverbank, but... I can't do it! I'm too terrified to go out there and face those huge things, even with a rifle. Please, let me pay you to bring back some!", objectives = "" }
WordHunterWoW_QuestEN[26788] = { title = "Cementing Our Victory", description = "Our alliance with the Dragonmaw is secured, but this port is far from combat ready. These flimsy wooden walls are an embarrassment to the Warchief.\n\nWhen water elementals carve their way through rock, as they have in the Verrall River, they create a peculiar kind of muck. It spreads easily and dries harder than the hardest stone. It's the perfect mortar for large-scale construction.\n\nGo to the river delta northwest of here and collect some Verrall River muck. Even a little will go a long way.", objectives = "" }
WordHunterWoW_QuestEN[26791] = { title = "Sprout No More", description = "The stone trogg mystics are creating those fungal monstrosities from the giant mushrooms to the north.\n\nI want you to take a war guardian to help deal with the giants and stone troggs. Make your way to the giant mushrooms and target them. I and my geomancers will sink them into the ground before the mystics have a chance to finish their ritual.", objectives = "" }
WordHunterWoW_QuestEN[26792] = { title = "Fungal Monstrosities", description = "Grab yourself a war guardian, and destroy those fungal monstrosities while you're out there.", objectives = "" }
WordHunterWoW_QuestEN[26793] = { title = "The Weathered Grave", description = "The weathered grave marker reads simply:\n\nMORGAN LADIMORE\n\n<Upon further examination, you notice that dirt over the grave has been recently disturbed, and that a good amount of the dirt seems to have been displaced...>", objectives = "" }
WordHunterWoW_QuestEN[26794] = { title = "Morgan Ladimore", description = "<He searches through the shelves and comes up with a leatherbound book.>\n\nIf you would like to know more, you might ask Althea, she's been the one to handle the... trouble... with him of late.", objectives = "" }
WordHunterWoW_QuestEN[26795] = { title = "Mor'Ladim", description = "From what my scouts tell me, Mor'Ladim wanders throughout Duskwood, following a strange and meandering path through the cemetery. We buried him out past the house on the hill, you know where that is?\n\nThere isn't anything I can do to help you, but I wish you good luck.", objectives = "" }
WordHunterWoW_QuestEN[26796] = { title = "The Daughter Who Lived", description = "I should have told you this earlier...\n\nHow do I put this...\n\nMorgan may have believed that his family was all dead, but, in fact, his daughter Sarah Ladimore is now a Watcher. She's always been troubled by the... circumstances... surrounding her father's death. Perhaps you could go to bring the news to her.", objectives = "" }
WordHunterWoW_QuestEN[26797] = { title = "A Daughter's Love", description = "Here, take this and lay it on his grave. Maybe... somehow, he'll know that I'm okay, and that none of us hold him responsible for what happened.\n\n<There are tears in her eyes now, as she slides a ring from her right hand, and presses it into your hands.>\n\nAnd... thank you, {name}.", objectives = "" }
WordHunterWoW_QuestEN[26798] = { title = "Saurfang Will be Pleased", description = "The portal is ready!\n\nIt's not powerful enough to transport an army, but we can maintain the connection long enough to allow important individuals to pass back and forth.\n\nSaurfang will want to know about our progress here. Walk through the portal to Orgrimmar, then deliver the news him.", objectives = "" }
WordHunterWoW_QuestEN[26799] = { title = "Those That Couldn't Be Saved", description = "The val'kyr raise hundreds of corpses every day.  Agatha raised you just a few moments ago.  Not all are as lucky as you, however.\n\nSome maintain their free will, but live in constant fear and confusion.  They usually run off into the woods, cowering at their own reflections.\n\nOthers lose their minds completely, shambling about aimlessly.  They often turn to violence, and must be destroyed.\n\nThis is your task, {name}.  Destroy them, our former brothers and sisters though they might be.", objectives = "" }
WordHunterWoW_QuestEN[26800] = { title = "Recruitment", description = "We've been shipping in dead bodies from Silverpine, Hillsbrad... hell, anywhere we can get them from.  We can't, however, afford to ignore the bodies which are sitting right on our front doorstep.\n\nThe last vestiges of the Scarlet Crusade roam here in Tirisfal Glades.  While we've managed to push them from Deathknell, several of their bodies litter the buildings to the north and the east.\n\nGo find them... and bring that Darnell fellow with you.  He looks strong enough to carry a few corpses.", objectives = "" }
WordHunterWoW_QuestEN[26801] = { title = "Scourge on our Perimeter", description = "If you're going to be an asset to the Forsaken, you need to learn how to fight.  And there's no better target than the Scourge minions that continue to pester us.\n\nThe wretched ghouls and Rattlecage skeletons that roam the north and to the east are former troopers of the fallen Scourge.  They should prove to be an even match for a fledgling {class} like you.\n\nDo not tarry - when you are done, speak to me again.", objectives = "" }
WordHunterWoW_QuestEN[26802] = { title = "The Damned", description = "First of all, look at your armor.  You're a mess, {class}.\n\nIf you'd like to stay in one piece--and I've no doubt you do--perhaps I can help.  If you can gather some paws and wings from the wolves and bats nearby, maybe I'll find some armor for you.  You'll find the creatures to the north and to the west of here.", objectives = "" }
WordHunterWoW_QuestEN[26803] = { title = "Missing Reports", description = "Saurfang is wise, and his intentions are good. In time, he will grow to see your people as a valuable ally.\n\nI am awaiting reports about recent Alliance activity in Durotar, but they haven't arrived yet. Would you be willing to visit Razor Hill and ask him for the reports in person? The easiest way to get there is by wind rider. Doras, Orgrimmar's wind rider master will let you use one of his wind riders for a small fee. Look for him on the rise north of the Valley of Strength.", objectives = "" }
WordHunterWoW_QuestEN[26804] = { title = "Flight to Razor Hill", description = "When you're ready to take the wind rider down to Razor Hill, simply speak with me again. When you get there, waste no time in finding Gar'Thok. He's the one responsible for preparing reports on recent Alliance activity in Durotar.", objectives = "" }
WordHunterWoW_QuestEN[26805] = { title = "To the Cape!", description = "The Explorers' League is growing, {name}.  Not only have they taken in worgen like me, but they have expanded their range in search of artifacts.  One of our best, Bronwyn Hewstrike, has set up a camp in the south, where he believes an item of titan origin may be hidden.\n\nBronwyn asked me to perform some duties here in the north, one of which was to identify potential recruits.  You seem to be made of the right stuff.  Talk to Robert Rhodes, the flight master, and he'll send you down there.  Bronwyn's treat.", objectives = "" }
WordHunterWoW_QuestEN[26806] = { title = "Reports to Orgrimmar", description = "Eitrigg will have to be happy with the part of the report that I've finished. Tell him to expect more in the future.\n\n<Gar'Thok hands you a stack of roughly folded papers.>\n\nThis should cover the most important details of the increase in Alliance forces working out of Northwatch. Please apologize to Eitrigg for me and let him know that we've had our hands full here, trying to keep Razor Hill secure and supplied. When you're ready to return to Orgrimmar, simply speak to Burok and hire a wind rider.", objectives = "" }
WordHunterWoW_QuestEN[26807] = { title = "Return to Eitrigg", description = "Since you've already spoken to Doras, you'll be able to hire a wind rider to take you right back to Orgrimmar. Each time you arrive in a new town, be sure to speak with the town's flight master. After that, you'll be able to use the flight master's services to travel quickly.\n\nSpeak to me again when you're ready to purchase a return flight to Orgrimmar. Bring those reports to Eitrigg in the Valley of Strength once you've landed.", objectives = "" }
WordHunterWoW_QuestEN[26808] = { title = "Maywiki", description = "<Linzi looks troubled.>\n\nYou know, there's a troll hiding behind that pile of boxes.  She must be awfully sad, if she doesn't want to come out and talk to anyone.\n\n<Linzi places some of the Akiris reeds in a kerchief and ties it together.>\n\nHere, give these to her.  They're very soft, and that maybe they will make her feel a little more comfortable back there.", objectives = "" }
WordHunterWoW_QuestEN[26809] = { title = "Backdoor Dealings", description = "Zanzil the Outcast, an exile from the Gurubashi tribe, is my quarry.  Recently, I have heard tales from my brothers in the north about his planned reentry into society, starting with the emissary he sent to the Skullsplitters.  This is not good news.\n\nI want you to peer into Zanzil's current plans.  Take this incense, and place it in front of the bat totem in the Ruins of Jubuwal, to the north.  Hir'eek will guide you from there.", objectives = "" }
WordHunterWoW_QuestEN[26810] = { title = "Eliminate the Outcast", description = "You are to kill Zanzil.  You rode on Hir'eek's wings and saw through Hir'eek's eyes; you know where Zanzil hides within the Ruins of Aboraz.  Travel there and kill him.\n\nOh, and {race}: if we become separated, you should use this fetish.  It only works within Stranglethorn, but it will transport you back here to me should you need to return swiftly.\n\nGood luck, {race}.  Zanzil is no ordinary opponent.", objectives = "" }
WordHunterWoW_QuestEN[26811] = { title = "Through the Troll Hole", description = "It looks like Zanzil's portal into Zul'Gurub is still open.  Zul'Gurub is a dangerous place, but Maywiki entrusted this task to you.\n\nThe portal lies in wait in front of you.", objectives = "" }
WordHunterWoW_QuestEN[26812] = { title = "High Priestess Jeklik", description = "Ahead of you looms a ramp up to one of the city's many terraces.  The bat-shaped totems ahead of you indicate that this is the domain of High Priestess Jeklik, a follower of Hir'eek.\n\nJeklik was one of the Hakkar-worshipping priests that Zanzil was planning to resurrect.  Perhaps if you hurry, you can stop the resurrection!", objectives = "" }
WordHunterWoW_QuestEN[26813] = { title = "Plunging Into Zul'Gurub", description = "Zanzil the Outcast has once again escaped through one of his portals.  Follow him!", objectives = "" }
WordHunterWoW_QuestEN[26814] = { title = "High Priest Venoxis", description = "Venoxis was the second of the two priests that Zanzil planned to bring back from the dead.  You have already succeeded in destroying the body of High Priestess Jeklik... Venoxis must be the next.", objectives = "" }
WordHunterWoW_QuestEN[26815] = { title = "Zanzil's Secret", description = "Years ago, the Gurubashi exiled one of their own from Zul'Gurub: a troll by the name of Zanzil.  The reasons why aren't all that clear, but I'd guess it had something to do with his tendency to administer powerful, behavior-altering drugs to anyone he saw.  Anyhow, the Gurubashi priests and their blood god have been slain, but Zanzil the Outcast remains...\n\n...as do his powerful, behavior-altering drugs.\n\nI need his mixture for my next test.  Check the zombies to the north.", objectives = "" }
WordHunterWoW_QuestEN[26816] = { title = "Recipe for Disaster", description = "Did you see that explosion I made?  I must have flown 10 inches off the ground!\n\nI've just got to get Zanzil's recipe so I can find out why it did that.  One of Zanzil's flunkies at the Ruins of Aboraz must have it on him.  Head east, to the coast of the Cape, and snatch it for me!", objectives = "" }
WordHunterWoW_QuestEN[26817] = { title = "Perfectly Pure", description = "This humour won't serve on its own.  Too thick.  WAY too thick.\n\nThe nagas to our west maintain a shrine that dispenses the only clean water this side of Duskwood.  For most potions, I'll use river water, but Bronwyn demands accuracy!\n\nObtain it from the Nek'mani Wellspring at the peak of the naga camp.  Good luck!", objectives = "" }
WordHunterWoW_QuestEN[26818] = { title = "Plush Pelts", description = "Hi, I'm the town merchant!  And Bronwyn's my dad!\n\nSorry, I shouldn't get too excited.  Father says it's not professional.\n\nAnyhow, people always come to me asking for heavy leather, or rough hides, but I think they might also like it if I had some soft materials... like tiger fur!  Think you could get some for me?\n\nYou'll find a few panthers nearby, but if you want to see the big tigers, you'll have to go northwest from here... north of that big troll arena.", objectives = "" }
WordHunterWoW_QuestEN[26819] = { title = "Akiris by the Bundle", description = "The naga explorers to our west carry a valuable ocean reed - Akiris reeds.  Traders use them to make medicines and poultices, and craftsmen use them to line armor or even wrap cigars!\n\nIn the evenings, when digging's done, father's been teaching me how to use them... but unfortunately, we ran out.  Would you mind getting us some more?", objectives = "" }
WordHunterWoW_QuestEN[26820] = { title = "If They're Just Going to Leave Them Lying Around...", description = "Father says that a responsible merchant is always keeping an eye out for good deals.  I've been trying to look for deals everywhere I go, and I think I've just found one!\n\nThe naga to the west have dozens of statues that they place on the ground where they live.  They couldn't possibly need all of them... so I was thinking that we'd take some for ourselves!\n\nFree statues!  That's a good deal, right?", objectives = "" }
WordHunterWoW_QuestEN[26821] = { title = "Airwyn Bantamflax", description = "Well, we have no idea what this artifact is.  It's old, older than dirt... but not titan.  I'm completely dumbstruck.\n\nAirwyn Bantamflax in Booty Bay is my direct superior.  Our next step should be to inform her of this find.  Please, would you bring it to her?", objectives = "" }
WordHunterWoW_QuestEN[26822] = { title = "Good-Fer-Nothin' Slither-Dogs", description = "Ahem!  Hrm, hrm...\n\n<The dwarf clears his throat for several seconds.>\n\nYou're lookin' fer somethin' ta do?  And ya come askin' ME?  Lowly ol' Goris?!\n\nWell, ah... this is a first.  Ah, I've got it!\n\nThe vale ta tha north is filled with a bunch o' useless, belly-scrapin' basilisks.  They don't do nothin' for no one, and I hear they turned a guy ta stone once.\n\nIf ya kill 'em, I'll give ya some o' my stuff.", objectives = "" }
WordHunterWoW_QuestEN[26823] = { title = "Too Big For His Britches", description = "Whatever it is you want to do: I've got a recipe that'll do exactly that.  You want an exploding potion?  BOOM!!  You want a lightning potion?  ZAP!!  You want a shrinking potion?  Smeerp.\n\nSo Bronwyn says he wants a carbon-dating potion?  Easy.  I could make that in my sleep.  The thing is... if we want it to be accurate, I need you to get some quality ingredients.\n\nStart with some humour from a basilisk to the north.  It'll need to be a pretty big basilisk...", objectives = "" }
WordHunterWoW_QuestEN[26824] = { title = "Results: Inconclusive", description = "I did all I could, {name}.  I had the right potions... I had the right recipes... but the source of this sample eludes me.  It's tens of thousands of years old, but we've shown that it's not of titan origin.  And it's not saronite, I can tell you just by looking at it.  So... what in Brann's name is it?\n\nTell Bronwyn that I tried my best.  Sorry.", objectives = "" }
WordHunterWoW_QuestEN[26825] = { title = "Dask \"The Flask\" Gobfizzle", description = "Hey - you must be that fella' that Wulfred was talkin' about!  The one who found the ogre artifact, and helped him test out those strange stones from up north.  Welcome to the digsite, {name}!\n\nWe were actually working on identifying those samples right as you got here.  Would you mind bringing the sample over to Dask?  I need him to help me find out how old it is.", objectives = "" }
